[{"s":"القلبية","topics":[{"t":"التظاهرات السريرية","cards":[{"f":"ألم صدري شديد ممزق (Tearing) يهاجر إلى الظهر هو...؟","b":"تسلخ الأبهر (Aortic dissection) حتى يثبت العكس."},{"f":"كل ما يلي يسبب هبوط ضغط انتصابي ما عدا...؟","b":"مقبضات الأوعية (Vasoconstrictors) ومانعات الحمل الفموية — ترفع الضغط ولا تسبب هبوطًا انتصابيًا."},{"f":"في الغشي القلبي العصبي (الوعائي المبهمي) ما الذي يحدث للقلب؟","b":"بطء قلب (Bradycardia) + توسع وعائي — لا تسرع أبدًا."},{"f":"فتاة شابة فقدت الوعي فجأةً بعد خروجها من حمام ساخن ممتد ثم استعادت وعيها سريعًا — التشخيص؟","b":"غشي وعائي مبهمي (Vasovagal syncope): الحرارة سببت توسعًا وعائيًا ونقص العود الوريدي."},{"f":"نوب ارتفاع ضغط شديد + توهج وتعرق + خفقان + صداع نابض — التوجه التشخيصي؟","b":"ورم القواتم (Pheochromocytoma) — ورم لب الكظر المفرز للكاتيكولامينات."},{"f":"كل ما يلي من أسباب الصدمة قلبية المنشأ ما عدا...؟","b":"التسرع الجيبي — استجابة تعويضية للصدمة لا سبب لها. والتهاب التامور البسيط لا يسبب صدمة (الاندحاس هو السبب)."}]},{"t":"قصور القلب","cards":[{"f":"ما الدواء الذي يحسن الأعراض في قصور القلب دون تحسين البقيا؟","b":"الديجوكسين (Digoxin): يحسن الأعراض ويقلل الاستشفاء دون تحسين الوفيات."},{"f":"ما الأدوية المثبتة لتحسين البقيا (الإنذار) في قصور القلب؟","b":"مثبطات ACE (أو ARNI) + حاصرات بيتا + مضادات الألدوستيرون (سبيرونولاكتون) + مثبطات SGLT2."},{"f":"المدر الإسعافي الوريدي لوذمة الرئة الحادة هو...؟","b":"الفوروسيميد الوريدي (IV Furosemide)."},{"f":"الصمة الرئوية الحادة تسبب قصور قلب...؟","b":"قصور القلب الأيمن الحاد (القلب الرئوي الحاد) — لا الأيسر."},{"f":"كل ما يلي من علامات قصور البطين الأيمن ما عدا...؟","b":"الخراخر الناعمة في الساحتين الرئويتين — علامة قصور أيسر (احتقان رئوي). علامات الأيمن: احتقان وداجي + وذمات + ضخامة كبدية."},{"f":"الصوت الثالث S3 (نظم الخبب) يُسمع في...؟","b":"قصور القلب الأيسر (Left heart failure)."},{"f":"ما الواسم الحيوي الذي يرتفع في قصور القلب؟","b":"BNP (الببتيد الدماغي المدر للصوديوم) — يفرز استجابة لارتفاع ضغوط الامتلاء."},{"f":"زلة حادة + تعرق بارد + هياج + سعال منتج لقشع زهري رغوي — التشخيص؟","b":"قصور قلب أيسر حاد (وذمة رئة حادة)."},{"f":"مثبطات ACE تسبب في البوتاسيوم...؟","b":"فرط بوتاسيوم الدم (Hyperkalemia) — لا نقصه."},{"f":"الاختبار المؤكد لتشخيص قصور القلب وقياس الكسر القذفي هو...؟","b":"تصوير القلب بالأمواج فوق الصوتية (الإيكو - Echocardiography)."},{"f":"كل ما يلي يسبب قصور قلب عالي النتاج ما عدا...؟","b":"تضيق الصمام التاجي — يسبب قصورًا منخفض النتاج. العالي: الانسمام الدرقي، فقر الدم الشديد، داء باجيت."},{"f":"لماذا لا تُستخدم حاصرات الكالسيوم في قصور القلب؟","b":"تأثير سلبي على المقوية القلبية (Inotropy) وتسوء الإنذار في قصور القلب بانخفاض الكسر القذفي."},{"f":"فرّق: قصور الدسام الأبهري يسبب حملًا...؟ وتضيق الأبهر يسبب حملًا...؟","b":"القصور الأبهري: حمل حجمي (Volume overload) على الأيسر. التضيق الأبهري: حمل ضغطي (Pressure overload)."},{"f":"قصور القلب المزمن يسبب في الصوديوم...؟","b":"نقص صوديوم تخفيفي (Dilutional hyponatremia) — لا فرط صوديوم."},{"f":"ما الوضعية الصحيحة لمريض وذمة الرئة الحادة؟","b":"وضعية عمودية (جلوس) — الاضطجاع الظهري يزيد العود الوريدي ويفاقم الاحتقان."}]},{"t":"الداء الإكليلي","cards":[{"f":"ما تعريف الخناق الصدري المستقر (Stable angina)؟","b":"ألم ضاغط خلف القص يأتي على الجهد ويخف بالراحة والنتروغليسيرين."},{"f":"اختبار الجهد في الخناق غير المستقر...؟","b":"مضاد استطباب — خطر إحداث احتشاء أو لانظمية قاتلة أثناء الجهد."},{"f":"فرّق: خناق غير مستقر / NSTEMI / STEMI من حيث التروبونين والتخطيط؟","b":"غير مستقر: ألم على الراحة + تروبونين طبيعي. NSTEMI: تروبونين مرتفع دون ارتفاع ST. STEMI: ارتفاع ST (إعادة تروية إسعافية)."},{"f":"الواسم القلبي النوعي في المتلازمة الإكليلية الحادة هو...؟","b":"التروبونين (Troponin I أو T)."},{"f":"ارتفاع ST في V1-V4 يدل على...؟ وفي II وIII وaVF يدل على...؟","b":"V1-V4: احتشاء أمامي حاد. II وIII وaVF: احتشاء سفلي (إكليلية يمنى)."},{"f":"بديل الأسبرين عند عدم التحمل الهضمي هو...؟","b":"الكلوبيدوغريل (Clopidogrel) — مضاد P2Y12."},{"f":"حالّات الخثرة (Thrombolytics) مستطبة في...؟","b":"احتشاء ST المرتفع (STEMI) — لا في NSTEMI ولا الخناق غير المستقر."},{"f":"كل ما يلي من عوامل خطر الداء الإكليلي ما عدا...؟","b":"انخفاض LDL — وقائي لا عامل خطر. عوامل الخطر: التدخين، السكري، ارتفاع الضغط، انخفاض HDL."},{"f":"التهاب التامور التالي للاحتشاء يُعالج بـ...؟","b":"الأسبرين بجرعات عالية (+ كولشيسين) — مضادات الالتهاب غير الأسبرينية تُتجنب بعد الاحتشاء."},{"f":"من اختلاطات الاحتشاء الميكانيكية...؟ وما الذي ليس منها؟","b":"تمزق العضلة الحليمية (قصور تاجي حاد) وتمزق الحاجز (VSD مكتسب). قصور الصمام الأبهري ليس اختلاطًا للاحتشاء."},{"f":"هل يشخص الإيكو تضيق الشرايين الإكليلية؟","b":"لا — الإيكو لا يُظهر لمعة الإكليليات؛ التشخيص بالقثطرة القلبية أو الطبقي الإكليلي."},{"f":"انزياح القطعة PR نحو الأسفل علامة تخطيطية لـ...؟","b":"التهاب التامور (Pericarditis) — لا الداء الإقفاري."},{"f":"من مضادات استطباب حالّات الخثرة...؟ وما الذي ليس منها؟","b":"النزف الدماغي سابقًا، احتشاء دماغي خلال 3 أشهر، جراحة كبيرة حديثة. احتشاء دماغي منذ سنة ليس مضاد استطباب."},{"f":"النترات في الخناق غير المستقر...؟","b":"تخفف الألم لكنها لا تضمن الاستقرار ولا تحسن الإنذار."},{"f":"ألم صدري ضاغط منذ ساعة + تخطيط طبيعي + تروبونين طبيعي — التشخيص؟","b":"خناق صدر غير مستقر (Unstable angina)."},{"f":"نفخة منتصف انبساطية في القمة علامة...؟","b":"تضيق الصمام التاجي (أو أوستن فلنت) — ليست من مظاهر الخناق المستقر."},{"f":"حصار الفرع الأيسر الحديث مع ألم صدري يُعامل كـ...؟","b":"مكافئ احتشاء ST المرتفع (STEMI equivalent) — يستطب إعادة التروية."},{"f":"أقوى عوامل الخطورة القابلة للتعديل للتصلب العصيدي هو...؟","b":"التدخين (Smoking) — أذية بطانية مباشرة وتسريع تمزق اللويحة."}]},{"t":"أمراض الشغاف والصمامات","cards":[{"f":"حرارة منذ شهر + نفخة انقباضية شاملة جديدة في القمة + ضخامة طحال + عقد مؤلمة على الأصابع — التشخيص؟","b":"التهاب شغاف انتاني تحت حاد (Subacute infective endocarditis)."},{"f":"أشيع عقبيل صمامي متأخر للحمى الرثوية هو...؟","b":"تضيق الصمام التاجي (Mitral stenosis)."},{"f":"في معايير جونز: التهاب المفاصل المتنقل والحمى وتطاول PR — كبير أم صغير؟","b":"التهاب المفاصل المتنقل: معيار كبير. الحمى وتطاول PR (حصار AV درجة أولى): معياران صغيران."},{"f":"فرّق بين تضيق التاجي وقصور التاجي إصغائيًا؟","b":"التضيق: دحرجة انبساطية في القمة + اشتداد قبيل انقباضي + طقطقة انفتاح (Opening snap). القصور: انقباضية شاملة في القمة تنتشر للإبط."},{"f":"فرّق بين تضيق الأبهر وقصور الأبهر؟","b":"التضيق: نفخة انقباضية قذفية تنتشر للسباتي + نبض خيطي بطيء. القصور: نفخة انبساطية باكرة متناقصة + نبض قافز (مطرقة مائية) + ضغط نبض واسع."},{"f":"النفخة الانبساطية قد تكون بريئة؟","b":"أبدًا — النفخات البريئة انقباضية دائمًا؛ النفخة الانبساطية عضوية دائمًا."},{"f":"انشطار الصوت الثاني الثابت (لا يتأثر بالتنفس) يميز...؟","b":"الفتحة بين الأذينتين (ASD)."},{"f":"نفخة مستمرة تحت الترقوة اليسرى علامة...؟","b":"بقاء القناة الشريانية (PDA) — نفخة غيبسون (Gibson murmur)."},{"f":"الاستقصاء الأهم في التهاب الشغاف تحت الحاد هو...؟","b":"زرع الدم (Blood cultures) — 3 زرعات قبل بدء الصادات."},{"f":"هل متلازمة وولف-باركنسون-وايت (WPW) عامل خطر لالتهاب الشغاف؟","b":"لا — شذوذ توصيل كهربائي دون آفة بنيوية. وكذلك الـ ASD المعزولة خطرها ضئيل."},{"f":"أشيع عامل مؤهب لالتهاب الشغاف الجرثومي هو...؟","b":"الأمراض الصمامية (Valvular disease) — التنبتات تنمو على أذية شغافية سابقة."},{"f":"اذكر 3 علامات محيطية لالتهاب الشغاف؟","b":"عقد أوسلر المؤلمة (Osler nodes) + بقع جانواي غير المؤلمة (Janeway lesions) + النزوف الشظوية تحت الأظافر."},{"f":"هدف INR في الصمام التاجي الميكانيكي هو...؟","b":"2.5 – 3.5 (أشد من الصمام الأبهري الميكانيكي: 2.0 – 3.0)."},{"f":"الصوت الرابع S4 لا يُسمع في...؟","b":"تضيق التاجي الشديد — يُسمع في تضيق الأبهر الشديد والاعتلال الضخامي والإقفار الحاد."},{"f":"أي آفة صمامية لا تسبب وذمة رئة حادة؟","b":"تضيق الصمام مثلث الشرف — يسبب احتقانًا جهازيًا (أيمن) لا رئويًا."},{"f":"من أسباب القصور الأبهري الحاد...؟","b":"التهاب الشغاف الانتاني (تخرب الوريقات)."},{"f":"الحمى الرثوية تسبب في PR...؟","b":"تطاول PR (حصار أذيني بطيني درجة أولى) — لا قصره."},{"f":"وذمة الرئة الحادة سبب أم نتيجة لقصور التاجي الشديد؟","b":"نتيجة له — لا سببًا."}]},{"t":"اضطرابات النظم والنقل","cards":[{"f":"عدم الانتظام غير المنتظم (Irregularly irregular) + غياب الموجة P = ؟","b":"الرجفان الأذيني (Atrial fibrillation)."},{"f":"أخطر مضاعفات الرجفان الأذيني هي...؟","b":"السكتة الدماغية (Stroke) — خثار أذينة الأذينة اليسرى ينصم دماغيًا."},{"f":"الوقاية من الخثار في الرجفان الأذيني تكون بـ...؟","b":"مضادات التخثر الفموية (وارفارين أو DOACs) — الأسبرين وحده غير كافٍ."},{"f":"لضبط الاستجابة البطينية في الرجفان الأذيني نستخدم...؟ وما الذي لا يفيد؟","b":"حاصرات بيتا، ديلتيازيم، فيراباميل، ديجوكسين. لا يفيد: أميلودبين ونفيدبين (ثنائيات الهيدروبيريدين)."},{"f":"في سلم CHA2DS2-VASc أي جنس يُحتسب نقطة؟","b":"الجنس الأنثوي — الذكري لا يُحتسب."},{"f":"خوارج الانقباض البطينية اللاعرضية عند قلب سليم...؟","b":"لا تُعالج — شائعة ولا تستطب العلاج."},{"f":"العلامة التخطيطية المميزة لنقص البوتاسيوم هي...؟","b":"بروز الموجة U (مع تسطح T)."},{"f":"أشيع اضطراب نظم في التسمم الدرقي؟ وقصور الدرق يسبب...؟","b":"التسمم الدرقي: التسرع الجيبي. قصور الدرق: بطء القلب."},{"f":"أي نظم لا يُصدم في الإنعاش؟ وما علاج الرجفان البطيني؟","b":"اللانبض (Asystole) لا يُصدم — إنعاش وأدرينالين. الرجفان البطيني: صدمة غير متزامنة فورية."},{"f":"حصار القلب من الدرجة الثانية نمط وينكباخ يعطي نبضًا...؟","b":"عدم انتظام منتظم (Regularly irregular) — سقوط دوري لضربة."},{"f":"العلامة الوداجية المميزة للحصار القلبي التام هي...؟","b":"أمواج مدفعية (Cannon waves) — انقباض الأذينة ضد صمام مغلق."},{"f":"كل ما يلي يسبب بطء قلب جيبي ما عدا...؟","b":"الحمى والسالبوتامول — يسببان تسرعًا. البطء: قصور الدرق، حاصرات بيتا، ارتفاع الضغط داخل القحف، اليرقان الركودي."},{"f":"تسرع فوق بطيني غير مستقر (ضغط 90/60) لم يستجب للأدينوزين — الخطوة التالية؟","b":"صدمة كهربائية متزامنة (Synchronized cardioversion) إسعافيًا."}]},{"t":"ارتفاع الضغط الرئوي","cards":[{"f":"ارتفاع التوتر الثانوي يتميز بـ...؟","b":"مقاوم للأدوية (يحتاج عدة أدوية)، يظهر بعمر مبكر، نفخة بطنية توحي بتضيق الشريان الكلوي — وعلاجه بمعالجة السبب."},{"f":"الخافض المأمون في الحمل هو...؟ والممنوعة؟","b":"ألفا ميتيل دوبا (Methyldopa) مأمون. مثبطات ACE وحاصرات ARB ماسخة وممنوعة."},{"f":"في فرط التوتر الإسعافي كيف يُخفض الضغط؟","b":"تدريجيًا (~25% في الساعة الأولى) — لا إلى الحدود الطبيعية خلال ساعات (خطر نقص التروية الدماغية)."},{"f":"ضغط 180/100 دون أعراض — إسعاف أم استعجال؟","b":"استعجال (Urgency) لا إسعاف — الإسعاف يتطلب أذية أعضاء حادة."},{"f":"آثار جانبية: أميلودبين؟ حاصرات بيتا على القصبات؟ مثبطات ACE في الحمل؟","b":"أميلودبين: وذمات كاحلية. حاصرات بيتا: تشنج قصبي (لا توسع). مثبطات ACE: ماسخة."},{"f":"الاستقصاءات الروتينية لكل مريض ارتفاع توتر تشمل...؟ وما المستثنى؟","b":"سكر وشحوم وشوارد وبول وتخطيط قلب. الإيكو ليس روتينيًا — يُطلب عند الشك بضخامة البطين."},{"f":"ارتفاع التوتر الشرياني عامل خطر قوي لـ...؟","b":"الحوادث الدماغية الوعائية (السكتات) — أقوى عوامل خطرها القابلة للتعديل."}]},{"t":"أمراض العضلة القلبية","cards":[{"f":"شاب بغشي جهدي متكرر + نفخة تشتد بالوقوف — التشخيص؟","b":"اعتلال العضلة القلبية الضخامي الساد (HOCM) — الوقوف ينقص العود الوريدي فيشتد الانسداد."},{"f":"هل حاصرات بيتا مضاد استطباب مطلق في الاعتلال التوسعي؟","b":"لا — من أساسيات علاجه وتحسن البقيا (تُوقف فقط في اللا تعويض الحاد)."},{"f":"مريضة تلاسيميا كبرى بنقل دم متكرر + قصور قلب — التشخيص؟","b":"اعتلال عضلة قلبية تحددي (Restrictive) بترسب الحديد (Hemochromatosis)."}]},{"t":"أمراض القلب الخلقية","cards":[{"f":"غياب أو ضعف النبض الفخذي مع ارتفاع توتر الطرفين العلويين علامة...؟","b":"تضيق برزخ الأبهر (Coarctation of aorta)."},{"f":"نفخة مستمرة في الورب الثاني الأيسر تحت الترقوة = ؟","b":"بقاء القناة الشريانية (PDA) — نفخة غيبسون."},{"f":"أي آفة قلبية خلقية لا مزرقة؟ وأي آفات تزيد التوعية الرئوية؟","b":"التضيق الرئوي المعزول: لا مزرقة. الشنتات يسار-يمين (VSD, ASD, PDA) تزيد التوعية الرئوية."}]},{"t":"أمراض التامور","cards":[{"f":"أشيع سبب لالتهاب التامور الحاد؟ وأشيع سبب للتامور العاصر؟","b":"الحاد: الفيروسات (إيكو وكوكساكي B). العاصر: التدرن."},{"f":"صفة الألم الصدري في التهاب التامور؟","b":"يزداد بالاستلقاء والسعال والتنفس، ويتحسن بالجلوس والانحناء للأمام."},{"f":"العلامة التخطيطية لالتهاب التامور هي...؟","b":"انزياح القطعة PR نحو الأسفل (مع ارتفاع ST منتشر)."},{"f":"التهاب التامور التالي للاحتشاء يُعالج بـ...؟","b":"الأسبرين بجرعات عالية (+ كولشيسين) — لا مضادات الالتهاب غير الأسبرينية."}]},{"t":"المداواة القلبية","cards":[{"f":"فرّق: الوارفارين والكلوبيدوغريل والأسبرين؟","b":"الوارفارين: مضاد تخثر (فيتامين K). الكلوبيدوغريل والأسبرين: مضادا صفيحات — الكلوبيدوغريل بديل الأسبرين عند عدم التحمل الهضمي."},{"f":"من مضادات استطباب حالّات الخثرة...؟ وما المستثنى؟","b":"نزف دماغي سابق، احتشاء دماغي خلال 3 أشهر، جراحة كبيرة حديثة. المستثنى: احتشاء منذ سنة، استئصال مرارة منذ 3 أشهر."},{"f":"مضاد الاستطباب المطلق لحاصرات بيتا هو...؟","b":"الربو القصبي والتشنج القصبي (تشنج قصبي قاتل) — أما قصور القلب المستقر فمن استطباباتها."}]},{"t":"جراحة الصدر والأوعية","cards":[{"f":"التمييع (مضادات التخثر) في تسلخ الأبهر...؟","b":"مضاد استطباب — يفاقم النزف داخل الجدار الكاذب وقد يكون قاتلًا."},{"f":"تسلخ الأبهر يرتبط بـ...؟ وما الذي لا يرتبط به؟","b":"متلازمة مارفان، الصمام الأبهري ثنائي الشرف، ارتفاع الضغط الشديد. لا يرتبط بالتضيق التاجي."},{"f":"فرط التوتر الرئوي التالي لتضيق التاجي بعد تبديل الصمام...؟","b":"عكوس ويتحسن عادة بعد تبديل الصمام."}]}]},{"s":"الصدرية (باطنة)","topics":[{"t":"أعراض الأمراض التنفسية","cards":[{"f":"كل ما يلي يسبب نفثًا دمويًا ما عدا...؟","b":"الربو القصبي — النفث من: التوسع القصبي، الخراجة، الاحتشاء الرئوي، السرطان القصبي."},{"f":"مدخن 65 سنة + قشع مدمى + خفوت أصوات فوق كامل الرئة اليمنى — التشخيص؟","b":"سرطان قصبية مركزية يمنى (Central bronchial carcinoma) مع انخماص كامل."},{"f":"من علامات سوء الإنذار في الربو...؟ وما المستثنى؟","b":"الزرقة، تغيم الوعي، الصدر الصامت، التنفس السطحي. المستثنى: السعال."},{"f":"الساركوئيد يتميز بـ...؟ وما علاجه الأساسي؟","b":"ضخامة عقد سرية ثنائية الجانب + حبيبوم غير متجبن + حمامى عقدة. العلاج: الستيروئيدات القشرية حجر الأساس."},{"f":"فرّق بين انصباب الجنب الرشحي والنتحي بالأسباب؟","b":"الرشحي (Transudate): قصور القلب، تشمع الكبد، قصور الدرق. النتحي (Exudate): السل والذات الرئة والذئبة."},{"f":"ألم الصمة الرئوية شبيه بالخناقي؟ وصورة الصدر فيها؟","b":"لا — ألمها جنبي لا عاصر منتشر للذراع. صورة الصدر قد تكون طبيعية تمامًا."},{"f":"الاستقصاء الأكيد لتشخيص الصمة الرئوية هو...؟","b":"الطبقي المحوري الوعائي للصدر (CTPA) — حساسية 83% ونوعية 96%."},{"f":"التنفس القصبي (Bronchial breathing) يُسمع في...؟","b":"ذات الرئة الفصية — نسيج متكثف ناقل للصوت مع قصبات سالكة."},{"f":"في استرواح الصدر نجد بالقرع...؟","b":"فرط وضاحة (رنين مفرط) — لا أصمية؛ مع خفوت/غياب الأصوات."},{"f":"مسن + نفث دم + بحة صوت + تكثف صدري — التشخيص؟","b":"سرطان الرئة — غزو العصب الحنجري الراجع (شلل الحبل الصوتي)."}]},{"t":"الأمراض الرئوية الانسدادية","cards":[{"f":"ما تعريف التهاب القصبات المزمن؟","b":"سعال منتج لمدة 3 أشهر كل سنة ولمدة سنتين متتاليتين."},{"f":"من أسباب السعال المزمن...؟ وما المستثنى؟","b":"التقطير الأنفي الخلفي، القلس المعدي المريئي، مثبطات ACE، الربو السعالي. المستثنى: الصمة الرئوية، حاصرات الكالسيوم."},{"f":"أهم تدبير في COPD على الإطلاق هو...؟","b":"إيقاف التدخين — يبطئ تدهور FEV1 ويخفف السعال والقشع. واللقاحات (إنفلونزا ومكورات رئوية) مستطبة."},{"f":"من العلامات الفيزيائية للـ COPD...؟ وما المستثنى؟","b":"الصدر البرميلي، خفوت الأصوات المعمم، السحب الضلعي. المستثنى: التبقرط (ليس من علاماته)."},{"f":"من أسباب تبقرط الأصابع...؟ وما المستثنى؟","b":"تشمع الكبد، تليف الرئة، سرطان الرئة، التوسع القصبي. المستثنى: الساركوئيد والـ COPD."},{"f":"في نوبة الربو الحادة نستخدم...؟ وما الممنوع؟","b":"سالبوتامول إنشاقي + إبراتروبيوم + ستيروئيد جهازي + أكسجين. الممنوع: حاصرات بيتا، والستيروئيد الإنشاقي وحده لا يكفي."},{"f":"مما يثير هجمة الربو...؟ وما المستثنى؟","b":"الجو البارد، الجهد، الإنتانات الفيروسية، NSAIDs، حاصرات بيتا. المستثنى: الجو الحار."},{"f":"أي دواء ممنوع منعًا باتًا في الربو؟","b":"التيمولول (Timolol) — حاصر بيتا غير انتقائي يحرض التضيق القصبي."},{"f":"هل المونتيلوكاست موسع قصبي؟","b":"لا — مضاد مستقبلات اللوكوترين (دواء مسيطر مضاد للالتهاب)، ولا يُستخدم وحيدًا للسيطرة."},{"f":"في ARDS التهوية الآلية تكون بـ...؟ وما الممنوع؟","b":"حجم جاري منخفض (6 مل/كغ) لحماية الرئة. الممنوع: الحجم الجاري المرتفع، والموسعات القصبية ليست من العلاج."},{"f":"شاب + سعال جاف + حمى خفيفة + ارتشاحات غيمية ثنائية — التشخيص والعلاج الأول؟","b":"ذات رئة بالمفطورات (Mycoplasma) — العلاج الأول: ماكروليد (كلاريثروميسين/أزيثروميسين)."},{"f":"أشيع مسبب لذات الرئة الاستنشاقية هو...؟","b":"اللاهوائيات (Anaerobic bacteria) الفموية."},{"f":"ذات الرئة الفصية النموذجية جرثومية أم فيروسية؟ وأشيع مسبب؟","b":"جرثومية — أشيع مسبب: المكورات العقدية الرئوية (Streptococcus pneumoniae)."},{"f":"الإنفلونزا تؤهب لذات رئة بـ...؟","b":"العنقوديات المذهبة (Staphylococcus aureus)."},{"f":"آثار أدوية السل: بيرازيناميد؟ إيزونيازيد؟ إيتامبوتول؟ ستربتومايسين؟","b":"بيرازيناميد: نقرس (فرط حمض البول). إيزونيازيد: التهاب أعصاب محيطية. إيتامبوتول: التهاب عصب بصري. ستربتومايسين: سمية سمعية."},{"f":"فرّق: لويحات جنبية متليفة تميز...؟","b":"تغبر الأميانت (الأسبستوز) — لا السيليس."},{"f":"معايير لايت (Light) للانصباب النتحي؟","b":"بروتين الجنب/المصل > 0.5، أو LDH الجنب/المصل > 0.6، أو LDH السائل > ثلثي الحد الأعلى للمصل."},{"f":"الحد الأقصى للبزل الجنبي الإفراغي في الجلسة؟ ولماذا؟","b":"1.5 لتر — خطر وذمة الرئة بإعادة التوسع (Re-expansion edema)."},{"f":"من أسباب العقدة الرئوية الوحيدة...؟ وما المستثنى؟","b":"السرطان القصبي، الخراجة، الاحتشاء الرئوي، التدرنوم. المستثنى: تغبر الرئة (عقيدات منتشرة)."}]},{"t":"الأمراض الرئوية الخلالية","cards":[{"f":"التليف الرئوي مجهول السبب مرض سادّ أم حاصر؟ وما علاماته؟","b":"حاصر (Restrictive): زلة مترقية + سعال جاف + خراخر قاعدية + تبقرط + ارتشاحات شبكية."},{"f":"أمراض تسبب إصابة رئوية خلالية...؟ وما المستثنى؟","b":"الساركوئيد، الذئبة، التصلب الجهازي، داء واغنر. المستثنى: التهاب الجيوب الأنفية الحاد."},{"f":"الاختبار النوعي للتحري عن السل الكامن هو...؟","b":"اختبار إطلاق الإنترفيرون-غاما (IGRAs) — أكثر نوعية من السلين ولا يتأثر بلقاح BCG."},{"f":"تحول حديث للسلين دون أعراض أو ظلال شعاعية — التدبير؟","b":"سل كامن — العلاج الوقائي الكيميائي (إيزونيازيد)."},{"f":"الزلة نفسية المنشأ (فرط التهوية) تتميز بـ...؟","b":"خدر الأصابع وحول الفم — من القلاء التنفسي."}]},{"t":"أخماج الجهاز التنفسي","cards":[{"f":"بالفحص في ذات الرئة نجد...؟ وما المستثنى؟","b":"أصمية بالقرع + خراخر + زيادة الاهتزازات + تنفس قصبي. المستثنى: فرط الوضاحة."},{"f":"أشيع مسبب لذات الرئة الفصية؟","b":"المكورات العقدية الرئوية (Streptococcus pneumoniae)."},{"f":"أشيع مسبب لذات الرئة عند مرضى الإيدز؟","b":"المتكيس الرئوي الكاريني (Pneumocystis carinii/jirovecii)."},{"f":"شاب نحيل + سعال ونفث دم ونقص وزن وتعرق ليلي منذ شهرين — التشخيص؟","b":"سل رئوي (Tuberculosis)."},{"f":"النظام الدوائي للسل الرئوي الفعال؟","b":"رباعي RIPE (ريفامبيسين + إيزونيازيد + بيرازيناميد + إيتامبوتول) شهرين، ثم ثنائي RI أربعة أشهر."},{"f":"أي دواء ليس من أدوية السل؟","b":"البيبراسيللين (Piperacillin) — بنسلين واسع الطيف لا يفيد في المتفطرات."},{"f":"التوسع القصبي يتظاهر بـ...؟ وما المستثنى؟","b":"سعال مزمن منتج لقشع قيحي غزير + بخر فموي + تبقرط + نفث دم. المستثنى: السعال الجاف."},{"f":"أسباب التوسع القصبي...؟ وما المستثنى؟","b":"مكتسبة: ذات رئة، جسم أجنبي، سل، ورم. خلقية: تليف كيسي، نقص غاما غلوبيولين. المستثنى: فرط غاما غلوبيولين الدم."},{"f":"علاج الصمة الرئوية يكون بـ...؟ وما المستثنى؟","b":"هيبارين (مجزأ أو غير مجزأ)، وارفارين، حالّات الخثرة في الكتلية. المستثنى: الأسبرين (مضاد صفيحات لا يكفي)."},{"f":"الصمة الرئوية الكبيرة تسبب...؟ وما المستثنى؟","b":"زلة شديدة + ألم صدري مركزي + تسرع قلب + هبوط ضغط. المستثنى: ارتفاع الضغط وبطء القلب."},{"f":"متلازمة هورنر تتألف من...؟ وما المستثنى؟","b":"انسدال الجفن (Ptosis) + تقبض الحدقة (Miosis) + غؤور المقلة + انعدام التعرق بنفس الجانب. المستثنى: توسع القصيب."},{"f":"الساركوئيد يسبب في الكالسيوم...؟","b":"فرط كالسيوم الدم (الحبيبومات تنتج الكالسيتريول) — لا نقصه."},{"f":"مما يزيد خطورة السل الرئوي...؟ وما المستثنى؟","b":"التماس مع إيجابي القشع، السكري، السيليكوز، التدخين. المستثنى: عمر الشباب وحده."},{"f":"تكثف في قمة الرئة عند مدخن — التشخيص؟","b":"ورم بانكوست (Pancoast tumor) — سرطانة الثلم العلوي."},{"f":"من اختلاطات ذات الرئة...؟ وما المستثنى؟","b":"انصباب الجنب، خراجة الرئة، تقيح الجنب (دبيلة)، ARDS. المستثنى: تناذر هورنر وفتق الحجاب الحاجز."},{"f":"الاستقصاء الأفضل لتشخيص COPD هو...؟","b":"اختبار وظائف الرئة (قياس التنفس: FEV1/FVC)."},{"f":"أدوية الربو المسيطرة (Controllers)...؟ وما المستثنى؟","b":"ستيروئيد إنشاقي، مضادات اللوكوترين، بيتا2 طويل المفعول. المستثنى: بيتا2 قصير المفعول (دواء إنقاذ)."},{"f":"الربو يشتد...؟","b":"ليلًا وفي الصباح الباكر — لا مساءً."},{"f":"قصور تنفسي نمط 1 (نقص أكسجة دون احتباس CO2) الحاد تسببه...؟","b":"هجمة الربو، الريح الصدرية، وذمة الرئة، ذات الرئة الشديدة — لا التليف الموضع المزمن."}]},{"t":"أمراض الأوعية الرئوية","cards":[{"f":"من مؤهبات الصمة الرئوية...؟ وما المستثنى؟","b":"الاستلقاء المديد، الخباثات، الحمل، موانع الحمل الفموية، أذيات النخاع. المستثنى: حاصرات الكالسيوم والتهاب شغاف التاجي."},{"f":"سيدة بعد ولادة بأربعة أيام + ألم صدري مع الشهيق + زلة شديدة — التشخيص؟","b":"صمة رئوية — فرط التخثر النفاسي."},{"f":"كسر عنق فخذ + استلقاء + ألم جنبي + زلة مفاجئة + نفث دموي قليل + صورة صدر سوية — التشخيص؟","b":"صمة رئوية — الثلاثية الكلاسيكية مع صورة سوية نموذجية."},{"f":"فرط التوتر الرئوي التالي لتضيق التاجي بعد تبديل الصمام...؟","b":"عكوس ويتحسن عادة بعد تبديل الصمام."},{"f":"فرط التوتر الرئوي البدئي (مجهول السبب) يصيب...؟","b":"الشابات غالبًا — وإنذاره سيء."},{"f":"ما الذي يزيد التوعية الرئوية؟ وما المستثنى؟","b":"الشنتات يسار-يمين (VSD, ASD, PDA). المستثنى: تضيق الصمام الأبهري."},{"f":"في الريح الصدرية الأصوات التنفسية...؟","b":"خافتة أو غائبة — لا محتدة؛ مع بدء مفاجئ وألم ضاغط وزلة."}]},{"t":"أمراض الجنب","cards":[{"f":"التليف الرئوي البدئي يتظاهر بعمر...؟ وما إنذاره؟","b":"بعد 50-60 سنة (لا بعمر 30) — زلة مترقية + سعال جاف + خراخر قاعدية + تبقرط؛ إنذاره غير مؤاتٍ."},{"f":"معايير لايت (Light) للانصباب النتحي؟","b":"بروتين الجنب/المصل > 0.5، أو LDH الجنب/المصل > 0.6، أو LDH السائل > ثلثي الحد الأعلى للمصل."},{"f":"انصباب قصور القلب رشحي أم نتحي؟ وانصباب الذئبة؟","b":"قصور القلب: رشحي (Transudate). الذئبة: نتحي (Exudate) — عملية التهابية."},{"f":"كم الحد الأدنى لرؤية الانصباب بالصورة؟ وحد البزل الإفراغي؟","b":"يُكشف بالصورة من ~200 مل. البزل الإفراغي ≤ 1.5 لتر في الجلسة."},{"f":"من اختلاطات بزل الجنب...؟ وما المستثنى؟","b":"تقيح الجنب، النزف، الريح الصدرية، الصدمة المبهمة. المستثنى: تليف الجنب (اختلاط مزمن للانصبابات المهملة)."},{"f":"من أسباب العقدة الرئوية المفردة...؟ وما الأقل شيوعًا؟","b":"سرطان القصبات، الخراجة، الاحتشاء الرئوي، التدرنوم. الأقل شيوعًا: العقيدة الرثوانية."},{"f":"من مظاهر السل الأولي...؟ وما المستثنى؟","b":"معقد غون (بؤرة رئوية + ضخامة عقد سرية). المستثنى: التوسع القصبي (اختلاط متأخر للتليف)."},{"f":"من المظاهر المهددة للحياة في الربو الحاد الشديد...؟ وما المستثنى؟","b":"ارتفاع PaCO2، انخفاض PEF، الزرقة، هبوط الضغط. المستثنى: الوزيز (قد يغيب في الصدر الصامت)."}]},{"t":"أورام الرئة والقصبات","cards":[{"f":"من التظاهرات نظيرة الورمية لسرطان القصبات...؟ وما المستثنى؟","b":"فرط كالسيوم الدم، نقص صوديوم الدم (SIADH)، تبقرط، لامبرت-إيتون، تثدي. المستثنى: تناذر الأجوف العلوي (تأثير موضعي) ومتلازمة كابلان."},{"f":"تكثف قمة الرئة عند مدخن — التشخيص؟","b":"ورم بانكوست (Pancoast tumor)."},{"f":"العلاج المختار للخراجة الرئوية هو...؟","b":"الكليندامايسين (Clindamycin) — يغطي اللاهوائيات الفموية."},{"f":"ذات الرئة بالعنقوديات المذهبة المكتسبة بالمجتمع تُعالج بـ...؟","b":"فلوكلوكساسيلين + كلاريثرومايسين (تغطية مزدوجة)."},{"f":"من مظاهر التدرن الرئوي...؟ وما المستثنى؟","b":"حمى، تعب، نقص وزن، سعال مع نفث دم. المستثنى: الزرقة."},{"f":"استطبابات الكورتيكوستيروئيدات في السل...؟ وما المستثنى؟","b":"انصباب الجنب السلي، تدرن العقد اللمفاوية، التهاب السحايا السلي. المستثنى: الكهوف السلية."}]}]},{"s":"الخمجية","topics":[{"t":"الحمى المالطية (البروسيلا)","cards":[{"f":"حمى البروسيلا متموجة أم مستمرة؟ ومن أعراضها؟","b":"متموجة (Undulant) — لا مرتفعة مستمرة. الأعراض: عرواءات، تعرق ليلي، آلام مفصلية عضلية، صداع. ما عدا: إسهال مزمن، شح بول."},{"f":"العلاج النوعي للحمى المالطية هو...؟","b":"دوكسيسيكلين + ريفامبيسين لمدة 6 أسابيع (ثنائي لمنع النكس) — لا أمبيسلين ولا أحادي."},{"f":"فرّق: تفاعل رايت (Wright) وتفاعل فيدال (Widal)؟","b":"رايت: تشخيص البروسيلا (المالطية). فيدال: تشخيص الحمى التيفية."},{"f":"البروسيلا مرض حيواني المنشأ أم بشري؟ وطرق انتقالها؟","b":"حيواني المنشأ (Zoonosis) — الإنسان ليس المستودع. الانتقال: حليب غير مبستر، تماس مع أنسجة مصابة؛ الحضانة أسابيع (2-8)."},{"f":"أخطر اختلاط للحمى المالطية؟ وهل تسبب صدمة إنتانية؟","b":"التهاب الشغاف (نادر لكنه الأخطر). لا تسبب صدمة إنتانية — خمج مزمن داخل خلوي."},{"f":"من التظاهرات الهيكلية للبروسيلا...؟ وما المستثنى؟","b":"التهاب الفقار، ذات العظم والنقي، التهاب مفصل أحادي. المستثنى: التهاب مفاصل عديد حاد."},{"f":"البروسيلا جرثوم...؟ وهل الانتقال إنسان-لإنسان شائع؟","b":"سلبي الغرام، داخل خلوي، بطيء النمو. الانتقال إنسان-لإنسان نادر جدًا."}]},{"t":"الحمى التيفية (السالمونيلا التيفية)","cards":[{"f":"ما علامة فاجيت (Faget) في الحمى التيفية؟","b":"افتراق نبضي حروري — بطء قلب نسبي رغم الحمى؛ لا تسرع قلب."},{"f":"المعيار الذهبي لتشخيص الحمى التيفية في الأسبوع الأول؟","b":"زرع الدم (Blood culture) — الجرثومية الدموية في الطور الأول؛ زرع البراز إيجابي في الأسبوعين 2-3."},{"f":"الإنسان مستودع للحمى التيفية؟ وكيف تنتقل؟","b":"الإنسان المستودع الوحيد — لا تنتقل بالتماس مع الحيوانات. الانتقال برازي-فموي (ماء/طعام ملوث)."},{"f":"أخطر اختلاط للحمى التيفية ومتى يحدث؟","b":"النزف والانثقاب المعوي — في الأسبوع الثالث."},{"f":"الخط الأول لعلاج الحمى التيفية عند البالغين؟","b":"الفلوروكينولونات (سيبروفلوكساسين) — أو أزيثروميسين/سيفترياكسون. لا أمينوغليكوزيدات."}]},{"t":"الأخماج الهضمية والإسهالات والتسمم الغذائي","cards":[{"f":"أشيع سبب لإسهال المسافرين؟ وماذا تسبب العنقوديات المذهبة؟","b":"الإشريكية القولونية المنتجة للذيفان المعوي (ETEC). العنقوديات: تسمم غذائي ذيفاني (إقياء خلال 1-6 ساعات) لا إسهال مسافرين."},{"f":"حجر أساس تدبير الكوليرا؟ والعلاج النوعي؟ والممنوع؟","b":"تعويض السوائل والشوارد (حجر الأساس). النوعي: دوكسيسيكلين. الممنوع: اللوبيراميد (مضاد استطباب في الإسهالات الخمجية)."},{"f":"الكوليرا: صفة الإسهال؟ وطريق الانتقال؟ ومن الأكثر عرضة للشدة؟","b":"إسهال مائي غزير (ماء الأرز). الانتقال برازي-فموي — لا رذاذ تنفسي. حاملو الزمرة O أكثر عرضة للإصابة الشديدة."},{"f":"الصادات في EHEC عند تطور HUS...؟","b":"ممنوعة — تزيد خطر متلازمة انحلال الدم اليوريمية (HUS)."},{"f":"من أسباب الإسهال المدمى...؟ وما المستثنى؟","b":"شيغيلا، سالمونيلا غير تيفية، عطيفة (كامبيلوباكتر)، EIEC. المستثنى: العنقوديات المذهبة."},{"f":"أهم سبب لإسهال الأطفال عالميًا؟ وعند البالغين؟","b":"الأطفال: فيروس الروتا (Rotavirus). البالغين: النوروفيروس (Norovirus)."}]},{"t":"الأخماج الفيروسية التنفسية (الإنفلونزا)","cards":[{"f":"العلاج النوعي للإنفلونزا هو...؟ وهل الأسيكلوفير يفيد؟","b":"أوسيلتاميفير (مثبط النورامينيداز) — فعال ضد A وB. الأسيكلوفير لفيروسات الحلأ فقط."},{"f":"الإنفلونزا تؤهب لذات رئة بـ...؟","b":"العنقوديات المذهبة (Staphylococcus aureus) — بعد النزلة الوافدة."},{"f":"لقاح الإنفلونزا يُعطى...؟","b":"سنويًا — لتغير السلالات المستمر."}]},{"t":"الحصبة والنكاف","cards":[{"f":"العلامة الواسمة للحصبة؟ وكيف ينتشر طفحها؟","b":"بقع كوبليك (Koplik spots). الطفح ينتشر تدريجيًا من الوجه نزولًا (cephalocaudal) — لا دفعة واحدة."},{"f":"التهاب الخصية النكافي شائع قبل البلوغ أم بعده؟","b":"بعد البلوغ (20% من المرضى) — يتبع التهاب النكفة بـ4-6 أيام؛ نادر قبل البلوغ."},{"f":"من اختلاطات النكاف...؟ وما المستثنى؟","b":"التهاب الخصية/المبيض، التهاب السحايا والدماغ، التهاب البنكرياس. المستثنى: تشمع الكبد."}]},{"t":"فيروسات الحلأ (الحماق، داء المنطقة، الحلأ البسيط، المضخم للخلايا، وحيدات النوى)","cards":[{"f":"فرّق بين الحماق وداء المنطقة؟","b":"الحماق: الإصابة الأولية بـ VZV. داء المنطقة: تفعيل الفيروس الكامن في العقد العصبية (بعد 50 سنة/مثبطي المناعة) — والمريض مصدر عدوى للمخالطين غير الممنعين."},{"f":"اختبار بول-بونيل (Paul-Bunnell) يشخص...؟","b":"داء وحيدات النوى الخمجي (EBV) — اختبار الأضداد المغايرة."},{"f":"النكس التناسلي غالبًا من...؟ والشفوي من...؟","b":"التناسلي: HSV-2. الشفوي: HSV-1 (يبدأ التعرض في الطفولة، يهجع في عقدة مثلث التوائم)."}]},{"t":"الإيدز وفيروس عوز المناعة البشري","cards":[{"f":"من الأمراض المميزة للإيدز...؟ وما المستثنى؟","b":"مبيضات المري، التدرن، سحايا المستخفيات، المقوسات الدماغية، المتكيسة الرئوية. المستثنى: التهاب الأمعاء بالمتحول الزحاري؛ وتجرثم الدم المتكرر يكون بالسالمونيلا غير التيفية."},{"f":"تعداد خلايا CD4 يُقاس بـ...؟","b":"قياس التدفق الخلوي (Flow cytometry)."},{"f":"الخمج بـ HIV يسبب في الوزن...؟","b":"نقص الوزن والهزال (متلازمة الهزال) — لا زيادته."}]},{"t":"فيروسات أخرى (داء الكلب، بارفوفيروس B19)","cards":[{"f":"أجسام نيغري (Negri bodies) توجد في...؟","b":"العصبونات — الدماغ وقرن آمون؛ لا في مكان العضة."},{"f":"فيروس B19 يسبب...؟ وما المستثنى؟","b":"الحمامى الانتانية (الخد المصفوع)، فقر دم لاتنسجي مع الانحلالي المزمن، التهاب مفاصل صغيرة. المستثنى: التهاب الدماغ الشامل المصلب تحت الحاد (SSPE — للحصبة)."},{"f":"في داء الكلب: الحضانة؟ والتدبير بعد التعرض؟","b":"الحضانة قد تمتد أشهرًا. بعد التعرض: الغلوبولين المناعي البشري + اللقاح."}]},{"t":"التهاب الكبد الفيروسي","cards":[{"f":"فيروس التهاب الكبد A: طريق الانتقال؟ وهل يسبب إزمانًا؟","b":"برازي-فموي (ماء ملوث/محار نيء) — لا يسبب خمجًا مزمنًا أبدًا ولا سرطانًا."},{"f":"من الفيروسات المسرطنة...؟ وما المستثنى؟","b":"EBV (بيركيت)، HBV، HCV، HPV. المستثنى: HAV."},{"f":"HCV ينتقل فمويًا؟ وHDV يحتاج ماذا؟","b":"HCV دموي (إبر/نقل دم) لا فموي. HDV ينتقل بنفس طرق HBV ويحتاج وجوده."}]},{"t":"الاستجابة الالتهابية الحادة والصدمة الإنتانية","cards":[{"f":"الصدمة الإنتانية: توزيعية أم قلبية؟ والمقاومة الوعائية؟","b":"توزيعية (Distributive) — نقص المقاومة الوعائية الجهازية (توسع وعائي) لا زيادتها؛ ليست صدمة قلبية."},{"f":"من علامات الالتهاب الحاد...؟ وماذا يحدث للصفيحات؟","b":"ارتفاع الكريات البيض وESR وCRP. الصفيحات ترتفع تفاعليًا (كثرة صفيحات ثانوية) — لا تنقص."},{"f":"هل تشفى الصدمة الإنتانية عفويًا؟","b":"لا — حالة مهددة للحياة تستلزم التدخل؛ الفشل متعدد الأعضاء مسارها النهائي."}]},{"t":"الحميات واضطرابات الحرارة","cards":[{"f":"ما تعريف الحمى مجهولة السبب (FUO)؟","b":"حرارة > 38.3°م في عدة مناسبات + أكثر من 3 أسابيع رغم أسبوع من التقييم المكثف."},{"f":"من أسباب الحمى مجهولة السبب...؟ وما المستثنى؟","b":"التهاب الشغاف، البروسيلا، اللمفومات والابيضاضات. المستثنى: التهاب السحايا الفيروسي (خمج حاد واضح المعالم)."},{"f":"انخفاض حرارة الجسم يحدث في...؟ وما المستثنى؟","b":"نقص السكر، التسمم بالكحول والباربيتورات، الوهط الدوراني. المستثنى: نقص الكالسيوم (يسبب تكززًا لا انخفاض حرارة)."}]},{"t":"الكزاز (التيتانوس)","cards":[{"f":"تشخيص الكزاز يكون...؟","b":"سريريًا عادةً (Clinical diagnosis) — لا بالزرع ولا بالتخطيط."},{"f":"المطثية الكزازية: إيجابية أم سلبية الغرام؟ والحضانة؟ والبداية؟","b":"عصيات لاهوائية إيجابية الغرام. الحضانة 3-14 يومًا. تبدأ بالضزز (تشنج الماضغة)."},{"f":"أشيع سبب للوفاة في الكزاز؟","b":"ذات الرئة الاستنشاقية (Aspiration pneumonia)."}]},{"t":"الأخماج الجرثومية (ذوات الرئة اللانمطية، المكورات)","cards":[{"f":"أي ذات رئة تتميز بافتراق نبضي حروري؟","b":"ذات الرئة بالليجيونيلا (Legionella) — مع أعراض هضمية ونقص صوديوم أحيانًا."},{"f":"الأزيثرومايسين يعالج...؟ وما المستثنى؟","b":"كلاميديا، ليجيونيلا، عطيفة (كامبيلوباكتر)، برتونيلا. المستثنى: اليرسينيا (تُعالج بأمينوغليكوزيدات)."},{"f":"العقديات المقيحة (المجموعة A) تسبب...؟ وما المستثنى؟","b":"القوباء، الحمى القرمزية، التهاب اللوزات، التهاب كبيبات الكلية، الحمى الرثوية. المستثنى: الحميراء (فيروسية)."}]},{"t":"الأخماج المكتسبة من المستشفى","cards":[{"f":"أشيع مسببات الإنتانات المكتسبة من المشافي؟","b":"العصيات سلبية الغرام (إشريكية قولونية، كلبسيلا، زوائف) — ثم إيجابيات الغرام."},{"f":"مما يساهم في الأخماج المشفوية...؟ وما المستثنى؟","b":"التقارب بين المرضى، انتقال العدوى بين العاملين، الإفراط في الصادات (مقاومة). المستثنى: قلة استخدام الصادات."},{"f":"من أهم أبواب الخمج المشفوي...؟","b":"القثاطر (البولية والوريدية المركزية)، أجهزة التهوية الآلية، الجروح الجراحية."}]},{"t":"الأخماج الفطرية (المبيضات، المستخفيات)","cards":[{"f":"من مؤهبات عدوى المبيضات...؟ وما المستثنى؟","b":"الصادات واسعة الطيف، القثاطر الوريدية المركزية، التثبيط المناعي والستيروئيدات. المستثنى: الإنترفيرون."},{"f":"الغريزوفولفين يفيد في...؟ وهل يفيد في المبيضات؟","b":"الفطور الجلدية (Dermatophytes) فقط — لا يفيد في المبيضات (علاجها: فلوكونازول/أمفوتريسين/إيكينوكاندين)."},{"f":"أرخص وأسهل طريقة لتشخيص الطفيلي المعوي المكوّن للأكياس البيضية (Cryptosporidium)؟","b":"صبغة تسيل-نلسن المعدلة للبراز."}]},{"t":"الأخماج الطفيلية (التوكسوبلاسموز، الليشمانيا، البلهارسيا)","cards":[{"f":"الثوي النهائي لداء المقوسات (التوكسوبلاسموز) هو...؟","b":"القطط (Cats) — لا الكلاب."},{"f":"البلهارسيا البولية تُشخص بـ...؟","b":"كشف البيوض في عينة البول (بيلة دموية)."},{"f":"الليشمانيا الحشوية (كالا-آزار) تسبب في الألبومين والغلوبيولين...؟","b":"نقص الألبومين + فرط غاماغلوبولين الدم (انقلاب النسبة) — والتشخيص برؤية الأماستيغوت في نقي العظم."}]},{"t":"اللقاحات والتمنيع","cards":[{"f":"فرّق بين التمنيع الفاعل والمنفعل؟","b":"الفاعل: لقاح يحفز إنتاج الأضداد — مناعة دائمة. المنفعل: أضداد جاهزة (غلوبولين مناعي) — مناعة مؤقتة."},{"f":"اللقاحات الحية المضعفة (كالحصبة والنكاف والحصبة الألمانية) ممنوعة في...؟","b":"الحوامل ومثبطي المناعة."},{"f":"المعزز (Booster) للقاح الكزاز والدفتيريا كل...؟","b":"كل 10 سنوات."}]}]},{"s":"الهضمية","topics":[{"t":"اضطرابات التغذية","cards":[{"f":"أي مرض لا يدخل في التشخيص التفريقي للقهم العصبي (anorexia nervosa)؟","b":"الداء السكري النمط الثاني (type 2 diabetes) — يترافق مع بدانة عادةً؛ أما الاكتئاب وداء الأمعاء الالتهابي وقصور النخامية وسوء الامتصاص فتسبب نقص وزن وتدخل في التفريقي."},{"f":"قاعدة ذهبية: ما تعريف نقص الوزن المرضي (pathological weight loss)؟","b":"نقص وزن غير مقصود (غير مخطط له) — أما النقص المخطط له فليس مرضيًا."},{"f":"أي مما يلي لا يسبب نقص وزن نموذجيًا: تشمع الكبد، داء الأمعاء الالتهابي، أورام المريء والمعدة، الحصيات المرارية؟","b":"الحصيات المرارية (gallstones) — تسبب مغصًا مراريًا لا نقص وزن؛ البقية من أسباب نقص الوزن المعروفة."}]},{"t":"التظاهرات السريرية والاستقصاءات","cards":[{"f":"متى يتظاهر النزف الهضمي العلوي ببراز مدمى (hematochezia)؟","b":"في النزف الغزير مع مرور هضمي سريع — لا مع بطء المرور. التظاهر النموذجي: إقياء دموي و/أو براز زفتي (melena)."},{"f":"قاعدة ذهبية: رجل بعمر 65 سنة بخروج مدمى مخلوط بالبراز — ما الاستقصاء الأهم؟","b":"ورم قولوني مشتبه حتى يثبت العكس — التنظير الهضمي السفلي (colonoscopy) مع الخزعة هو الاستقصاء الأهم."},{"f":"شابة تتناول مانعات الحمل الفموية + حبن عالي المدروج عالي البروتين + ألم مراق أيمن — التشخيص الأرجح؟","b":"متلازمة بود-كياري (Budd-Chiari syndrome) — انسداد الوريد الكبدي؛ الحبن دون سوابق مرض كبدي يرجّح حدثًا وعائيًا."},{"f":"شابة + ألم بطني مبهم + حرارة مسائية + نقص وزن + حبن منخفض المدروج (SAAG ≈ 0.5) — التشخيص؟","b":"سل البريتوان (peritoneal tuberculosis) — حبن نضحي (exudative) منخفض المدروج."},{"f":"بعد تأكيد الحبن بالأمواج فوق الصوتية، ما الخطوة التالية الإلزامية للتشخيص؟","b":"بزل الحبن التشخيصي (diagnostic paracentesis) — تحليل البروتين وSAAG وتعداد الخلايا والفحص الخلوي والجرثومي."},{"f":"أي دواء يسبب إمساكًا لا إسهالًا: مضادات الاكتئاب ثلاثية الحلقة (TCAs)؟","b":"نعم — بتأثيرها المضاد للكولين (anticholinergic) تسبب إمساكًا؛ وكذلك حاصرات الكالسيوم. أما الصادات وPPIs وNSAIDs وسامات الخلايا فتسبب إسهالًا."},{"f":"الديجوكسين (digoxin): هل يسبب إسهالًا نموذجيًا؟","b":"لا — يسبب غثيانًا وإقياءً وقهمًا واضطرابات نظم؛ الإسهال ليس من آثاره النموذجية."},{"f":"قاعدة ذهبية: الإمساك يترافق مع فرط كلس الدم أم نقصه؟","b":"فرط كلس الدم (hypercalcemia) — نقص الكالسيوم لا يسبب إمساكًا."},{"f":"ما العلامات المنذرة (alarm features) في الأمراض الهضمية؟","b":"عسرة البلع، البراز الزفتي (melena)، القيء المدمى، نقص الوزن، فقر الدم — أما الألم الشرسوفي المعزول وتطبل البطن فليسا منذرين."},{"f":"أشيع سبب للإسهال عند الأطفال في العالم؟","b":"فيروس الروتا (Rotavirus)."},{"f":"فرّق: داء الرتوج (diverticulosis) — سبب لنزف علوي أم سفلي؟","b":"سفلي — وهو أشيع سبب للنزف الهضمي السفلي الحاد الشديد."}]},{"t":"أمراض المريء","cards":[{"f":"العلاج الأكثر فعالية وفائدة في القلس المعدي المريئي (GERD)؟","b":"مثبطات مضخة البروتون (PPIs) مثل بانتوبرازول — حاصرات H2 أقل فعالية."},{"f":"ما علاقة القلس المعدي المريئي بالألم الصدري غير القلبي (NCCP)؟","b":"سبب رئيسي له — وتجربة مثبط مضخة البروتون تشخيصية وعلاجية معًا."},{"f":"المعيار الذهبي لتشخيص GERD؟ وهل التنظير السوي ينفي الإصابة؟","b":"قياس حموضة المريء (pH monitoring) — والتنظير السوي لا ينفي الإصابة (NERD: قلس دون التهاب مريء تنظيري)."},{"f":"فرّق: البلع المؤلم (odynophagia) مقابل عسر البلع (dysphagia) للجوامد المترقي عند مسن؟","b":"البلع المؤلم يشير لالتهاب مخاطية المريء؛ عسر البلع المترقي للجوامد عند مسن = ورم مريء حتى يثبت العكس ← تنظير علوي مع خزعة."},{"f":"المعيار الذهبي لتشخيص اللارتخائية (achalasia)؟","b":"قياس ضغوط المريء (manometry) — عدم استرخاء المصرة المريئية السفلية وغياب التمعج."},{"f":"شاب يتناول إيبوبروفن + ألم حاد خلف القص ينتشر للظهر يزداد بالشهيق + بلع مؤلم حتى للسوائل — التشخيص؟","b":"التهاب مريء دوائي (pill esophagitis) — التصاق الحبة بالمخاطية يسبب تقرحًا حادًا."},{"f":"مريض على علاج كيماوي + عسر بلع وبلع مؤلم — التشخيص الأرجح؟","b":"التهاب مريء بالمبيضات البيض (Candida esophagitis) — الكبت المناعي ينشّط المبيضات."},{"f":"القلس المزمن يؤهب لأي نمط من سرطان المريء: الغدية أم شائكة الخلايا؟","b":"السرطانة الغدية (adenocarcinoma) عبر مريء باريت (Barrett) — لا شائكة الخلايا؛ والتهاب المريء الإيوزيني ليس مؤهبًا للتسرطن."},{"f":"أدوية تخفض ضغط المصرة المريئية السفلية (LES) وتفاقم القلس — وما الاستثناء؟","b":"مضادات الكولين، النتروغليسرين، الديازيبام، حاصرات الكالسيوم — أما حاصرات بيتا فلا يجب تجنبها."},{"f":"عسر بلع متردد منذ 5 سنوات على السوائل والجوامد + ألم خلف القص — التشخيص؟","b":"تشنج المريء المعمم (diffuse esophageal spasm) — عسر بلع غير مترقٍّ باطراد يحاكي الذبحة؛ اللارتخائية عسر بلع مترقٍّ مع قلس ونقص وزن."}]},{"t":"أمراض المعدة والعفج","cards":[{"f":"أهم سبب للداء القرحي الهضمي عالميًا؟","b":"الخمج بالملوية البوابية (H. pylori) — يليه استعمال مضادات الالتهاب اللاستيروئيدية."},{"f":"المعيار الذهبي لتشخيص القرحة الهضمية؟","b":"التنظير الهضمي العلوي مع الخزعة — لاستبعاد السرطان المستبطن وتحرّي الملوية البوابية."},{"f":"اختبار غير باضع مفيد في تشخيص الملوية البوابية؟","b":"الكشف عن مستضد الملوية في البراز (Hp stool antigen)."},{"f":"مكونات علاج اجتثاث الملوية البوابية — وما الدواء الذي ليس منها؟","b":"مثبط مضخة بروتون + مضادان حيويان (أموكسيسيلين + كلاريثروميسين/ميترونيدازول) — الديكساميتازون ليس من العلاج بل يؤهب للقرحة."},{"f":"الملوية البوابية تؤهب لكل ما يلي ما عدا: القرحة، سرطانة المعدة، لمفوما MALT، متلازمة الأمعاء الهيوجة؟","b":"متلازمة الأمعاء الهيوجة (IBS) — اضطراب وظيفي لا علاقة له بالجرثومة؛ ولا تسبب التليف الكيسي."},{"f":"أي مضادات الالتهاب أقل تسببًا بالقرحات المعدية: الديكلوفيناك أم السيليكوكسيب؟","b":"السيليكوكسيب (celecoxib) — مثبط انتقائي لـ COX-2 بأمان هضمي نسبي."},{"f":"انثقاب قرحة هضمية: ما علاماته — وهل الحبن الغزير منها؟","b":"ألم شرسوفي مفاجئ + دفاع معمم + غياب أصوات الأمعاء + فقدان أصمية الكبد (هواء حر) — الحبن الغزير ليس منها."},{"f":"استطبابات العلاج الجراحي للقرحة الهضمية — وهل فرط الحموضة الشديد منها؟","b":"الانثقاب، النزف المستمر، انسداد مخرج المعدة، النكس — فرط الحموضة يُعالج دوائيًا بمثبطات مضخة البروتون."}]},{"t":"أمراض الأمعاء الدقيقة","cards":[{"f":"المعيار الذهبي لتشخيص الداء الزلاقي (celiac disease)؟","b":"خزعة الاثني عشر (العفج) + الفحوص المصلية النوعية (anti-tTG IgA وأضداد الإندوميزيوم)."},{"f":"هل يترافق الداء الزلاقي مع أمراض مناعية أخرى؟","b":"نعم — كالداء السكري نمط 1 والتهاب الدرق المناعي؛ عبارة (لا يترافق) خاطئة."},{"f":"مريضة زلاقية ملتزمة بالحمية بلا أعراض والأضداد سلبية حاليًا — ما التوصية؟","b":"الاستمرار على الحمية الخالية من الغلوتين مدى الحياة."},{"f":"قرحات الأعور ونهاية اللفائفي + حبيبوم متجبن نسيجيًا — داء كرون أم سل أمعاء؟","b":"سل الأمعاء (intestinal tuberculosis) — الحبيبوم المتجبن (caseating granuloma) يميزه عن داء كرون."},{"f":"هل العلاجات البيولوجية الحديثة شافية لداء كرون؟","b":"لا — مسيطرة على المرض وليست شافية."},{"f":"أي مما يلي لا يسبب زيادة التكاثر الجرثومي في الأمعاء (SIBO): الركودة المعوية أم الصادات واسعة الطيف؟","b":"الصادات واسعة الطيف — تعالج فرط النمو الجرثومي ولا تسببه."}]},{"t":"أمراض البنكرياس","cards":[{"f":"أشيع سبب لالتهاب البنكرياس المزمن؟","b":"الكحولية (alcohol)."},{"f":"أي مما يلي ليس من أسباب التهاب البنكرياس الحاد: الحصيات المرارية، فرط الشحوم الثلاثية، فرط نشاط الدرق؟","b":"فرط نشاط الدرق — وكذلك فرط كولسترول الدم ليس سببًا."},{"f":"هل توجد علاقة بين شدة التهاب البنكرياس الحاد ومقدار ارتفاع الأميلاز؟","b":"لا — قد تكون الأميلاز طبيعية؛ الشدة تُقدَّر بمعايير رانسون والعلامات السريرية."},{"f":"في معايير رانسون (Ranson): الكريات البيض أكثر من 4000 أم أكثر من 16000/مكL؟","b":"أكثر من 16000/مكL — عبارة (أكثر من 4000) خاطئة."},{"f":"هل الأمواج فوق الصوتية (الإيكو) مفيدة في تحديد شدة التهاب البنكرياس الحاد؟","b":"لا — تفيد في كشف الحصيات المرارية المسببة لا في تقدير الشدة."},{"f":"هل يُجرى ERCP خلال 48 ساعة لكل مرضى التهاب البنكرياس الحاد الحصوي؟","b":"لا — فقط عند وجود انسداد صفراوي أو التهاب طرق صفراوية مرافق."},{"f":"في التهاب البنكرياس الحاد: فرط كلس الدم أم نقصه؟ وهل نقص سكر الدم من مشاهداته؟","b":"نقص كلس الدم (تصبُّن الدهون saponification) — فرط الكالسيوم ونقص السكر ليسا من المشاهدات."},{"f":"العرض الأساسي في التهاب البنكرياس المزمن — وطبيعة إسهاله؟","b":"الألم البطني المزمن — والإسهال دهني (steatorrhea) غير مؤلم من سوء الامتصاص."}]},{"t":"أمراض القولون والمستقيم","cards":[{"f":"أكثر البوليبات القولونية قابلية للتسرطن؟","b":"البوليبات الغدية الزغابية (villous adenomas)."},{"f":"المظهر النسيجي المميز لالتهاب القولون التقرحي (ulcerative colitis)؟","b":"خراجات الخبايا (crypt abscesses) — والنواسير حول الشرج ليست من سماته بل من سمات داء كرون."},{"f":"متلازمة الأمعاء الهيوجة (IBS): الجنس، الإنذار، الوزن؟","b":"تصيب النساء أكثر من الرجال، متلازمة مزعجة سليمة الإنذار، لا تسبب نقص وزن — نقص الوزن يوجه لسبب عضوي."},{"f":"قاعدة ذهبية: مسن 75 سنة + تبدل عادات التغوط + فقر دم — ما الإجراء الأمثل؟","b":"استبعاد سرطان القولون أولًا — تنظير القولون (colonoscopy) هو الإجراء الأمثل."},{"f":"أي مما يلي ليس مؤهبًا لسرطان القولون: التهاب القولون التقرحي المزمن أم التهاب القولون الغشائي الكاذب؟","b":"التهاب القولون الغشائي الكاذب (Clostridioides difficile) — ليس مؤهبًا للتسرطن."},{"f":"أي مسكن لا يحرّض هجمة التهاب القولون التقرحي: الأسيتامينوفين أم مضادات الالتهاب اللاستيروئيدية؟","b":"الأسيتامينوفين (paracetamol) — الـ NSAIDs قد تحرّض الهجمة."}]},{"t":"أمراض الكبد والطرق الصفراوية","cards":[{"f":"ما هو ثلاثي شاركو (Charcot triad) وما تشخيصه؟","b":"ألم مراق أيمن + حمى + يرقان = التهاب طرق صفراوية صاعد حاد (acute ascending cholangitis)."},{"f":"التشخيص المصلي الأكيد لالتهاب الكبد A الحاد؟","b":"ضد HAV من نمط IgM إيجابي (Anti-HAV IgM) — والإصابة تمنح مناعة دائمة والعلاج عرضي مع راحة."},{"f":"التهاب الكبد B: هل ينتقل بالطعام أو البراز؟ وما الفحص الإيجابي بعد التمنيع؟","b":"لا ينتقل بالطعام أو البراز (ينتقل بالدم والجنس وعموديًا) — وبعد التمنيع يكون Anti-HBs إيجابيًا؛ وفي الخمج المزمن كل الواسمات إيجابية عدا Anti-HBs."},{"f":"أهم طريق لانتقال التهاب الكبد C؟ وهل يُشفى تمامًا بالعلاج؟","b":"المخدرات الوريدية (IV drug use) — وهو الوحيد بين التهابات الكبد المزمنة الذي يُشفى تمامًا بالعلاج الدوائي (مضادات الفيروسات المباشرة)."},{"f":"أي التهاب كبد فيروسي لا يسبب تشمعًا مزمنًا: A أم B أم C؟","b":"التهاب الكبد A (وكذلك E) — لا يتحولان لخمج مزمن ولا يسببان تشمعًا."},{"f":"المعيار الذهبي لتشخيص داء ويلسون (Wilson disease)؟","b":"عيار النحاس في خزعة الكبد (hepatic copper quantification)."},{"f":"المعيار المصلي الأكثر دقة لتشخيص التشمع الصفراوي البدئي (PBC)؟","b":"إيجابية الأضداد المضادة للميتوكوندريا نمط M2 (AMA-M2)."},{"f":"المعيار الذهبي لتشخيص التهاب الكبد التشحمي اللاكحولي (NASH)؟","b":"خزعة الكبد (liver biopsy)."},{"f":"مريض تشمع + آفة بؤرية كبدية 2.5 سم بالإيكو — ما الواسم الورمي المساعد؟","b":"ألفا فيتو بروتين (AFP) — يساعد في تشخيص سرطان الخلية الكبدية (HCC)."},{"f":"الوسيلة التشخيصية الأولى للحصيات الصفراوية؟","b":"الأمواج فوق الصوتية عبر البطن (abdominal ultrasound)."},{"f":"مريض 67 سنة + يرقان لا ألمي مترقٍّ + نقص وزن + فوسفاتاز قلوية مرتفعة وخمائر كبد طبيعية — الخطوة التشخيصية؟","b":"انسداد صفراوي خبيث مشتبه — الـ ERCP تشخيصي وعلاجي."},{"f":"حبن عالي المدروج عالي البروتين يُشاهد في: قصور القلب وبود-كياري — فأي مرض يعطي حبنًا منخفض المدروج؟","b":"تدرن البريتوان (حبن نضحي) — وكذلك الخباثات البريتوانية."},{"f":"مريض حبن: ألبومين المصل 2.9 وألبومين الحبن 1.2 غ/دل — ما التشخيص الأرجح؟","b":"تشمع كبد — SAAG = 1.7 (عالي المدروج ≥1.1) يوجه لفرط توتر وريد الباب."},{"f":"أي مما يلي ليس من مؤهبات تشكل الحصيات الصفراوية: السمنة أم الحمية عالية البروتين؟","b":"الحمية عالية البروتين — ليست مؤهبة؛ المؤهبات: الأنثى، السمنة، الحمل، نقص الوزن السريع."},{"f":"أي دواء قد يسبب تشمع كبد: ميتوتريكسات أم أسيتامينوفين؟","b":"الميتوتريكسات (methotrexate) — استعماله المديد قد يسبب تليفًا وتشمعًا كبديًا."},{"f":"أي مما يلي لا يحرّض اعتلالًا دماغيًا كبديًا عند مريض تشمع: الإنتان، النزف الهضمي، حاصرات بيتا؟","b":"حاصرات بيتا الأدرينرجية — لا تسبب اعتلالًا دماغيًا؛ البقية محرضات معروفة."},{"f":"أي فحص مخبري يشير للوظيفة التصنيعية (synthetic function) للكبد؟","b":"زمن البروترومبين (PT/INR) — يطول بقصور التصنيع الكبدي."},{"f":"تقعر الأظافر (koilonychia): من مظاهر تشمع الكبد غير المعاوض أم عوز الحديد؟","b":"عوز الحديد (iron deficiency) — ليست من مظاهر التشمع."},{"f":"التهاب الكبد المناعي الذاتي: هل يترافق مع الحمى الروماتويدية؟","b":"لا — الحمى الروماتويدية ليست من مرافقاته المذكورة."},{"f":"السبب الأشيع لخراجة الكبد القيحية (pyogenic liver abscess)؟","b":"الطريق الصفراوي الصاعد (biliary tract infection)."}]}]},{"s":"الكلية والشوارد","topics":[{"t":"التهابات المسالك وأمراض البروستات","cards":[{"f":"الجرثومة الأشيع إحداثًا لالتهاب المجاري البولية؟","b":"الإيشريشيا كولي (Escherichia coli)."},{"f":"البيلة الجرثومية اللاعرضية (asymptomatic bacteriuria) عند الحامل — تُعالج أم تُراقب؟","b":"تُعالج — خطر التهاب الحويضة والكلية والولادة المبكرة."},{"f":"التهاب الحويضة والكلية الحاد: هل الترفع الحروري نادر؟ وهل ارتفاع الضغط من مظاهره؟","b":"لا — الترفع الحروري شائع مع ألم الخاصرة وعسر التبول؛ وارتفاع الضغط ليس من مظاهره النموذجية."},{"f":"فرّق: الحمى والعرواءات — التهاب مثانة بسيط أم التهاب حويضة وكلية؟","b":"التهاب الحويضة والكلية (علوي) — التهاب المثانة البسيط: حرقة تبول وإلحاح دون حمى."},{"f":"كريات حمراء مشوهة (dysmorphic RBCs) في البول — منشأ كبيبي أم التهاب مثانة؟","b":"منشأ كبيبي (glomerular) — ليست من مظاهر التهاب المثانة النموذجية."},{"f":"هل يُجرى زرع الدم روتينيًا لكل مرضى الانتانات البولية؟","b":"لا — ليس استقصاءً روتينيًا لكل مريض."}]},{"t":"المظاهر السريرية والفحوصات","cards":[{"f":"ما تعريف البيلة البروتينية الزهيدة (microalbuminuria)؟","b":"30–300 ملغ/24 ساعة — أبكر مشعر لاعتلال الكلية السكري."},{"f":"ما ثلاثية المتلازمة النفروزية (nephrotic syndrome)؟","b":"وذمة + ارتفاع شحوم الدم + بيلة بروتينية (مع نقص ألبومين الدم)."},{"f":"الوذمات غير الانطباعية (non-pitting) تُشاهد في أي مرض: قصور القلب أم قصور الدرق؟","b":"قصور الدرق (وذمة مخاطية myxedema) — قصور الدرق لا يسبب وذمة انطباعية."},{"f":"أي مما يلي لا يرفع بوتاسيوم المصل: القصور الكلوي، السالبوتامول، المدرات التيازيدية؟","b":"السالبوتامول (salbutamol) يخفض البوتاسيوم — والتيازيدية تخفضه أيضًا؛ فرط الألدوستيرونية يسبب نقص بوتاسيوم لا ارتفاعه."},{"f":"فرّق بين آثار المدرات على الشوارد: الثيازيدية، مدرات العروة، الأسيتازولاميد؟","b":"الثيازيدية: نقص بوتاسيوم وارتفاع كالسيوم الدم؛ مدرات العروة: قلاء استقلابي (لا حماض)؛ الأسيتازولاميد: حماض استقلابي (لا قلاء)."},{"f":"متى ترتفع البولة الدموية بمعزل عن الكرياتينين؟","b":"في النزف الهضمي وزيادة الوارد البروتيني والحالة قبل الكلوية — أما النخر الأنبوبي الحاد فيرفعهما معًا."},{"f":"الكتلة العضلية تؤثر على عيار البولة أم الكرياتينين؟","b":"الكرياتينين — لا تؤثر على البولة الدموية."},{"f":"أي حماض يعطي فجوة أنيونية عالية: الحماض الكيتوني أم الانسمام بحمض كلور الماء؟","b":"الحماض الكيتوني (واللاكتيكي) — حمض كلور الماء يعطي حماضًا سويّ الفجوة (normal anion gap)."},{"f":"العلاج الأولي المباشر للحماض الاستقلابي الحاد الشديد في الطوارئ؟","b":"بيكربونات الصوديوم (sodium bicarbonate) وريديًا."},{"f":"اعتلال الكلية قليل التبدلات (minimal change): هل يسبب بيلة دموية؟","b":"لا — بيلة بروتينية انتقائية دون بيلة دموية نموذجيًا."},{"f":"أي مما يلي ليس من أسباب البوال الليلي: قصور القلب، تضيق الإحليل، ارتفاع البوتاسيوم؟","b":"تضيق الإحليل (يسبب أعراضًا انسدادية لا بوالًا) — وارتفاع البوتاسيوم ليس من أسباب البوال الليلي."},{"f":"صوديوم الدم 125 + نقص حجم + صوديوم البول مرتفع — ما التفسير الأرجح؟","b":"فقد ملحي كلوي (إدرار ملحي دماغي بعد نزف تحت العنكبوت) — الكلية تضيّع الصوديوم رغم نقص الحجم."},{"f":"أي مما يلي لا يُستخدم لتقييم وظيفة الكلية: الكرياتينين، البولة، عيار المتممة؟","b":"عيار المتممة (complement) — يُستخدم في الأمراض المناعية لا تقييم الوظيفة الكلوية."}]},{"t":"قصور الكلى الحاد","cards":[{"f":"الجزء المطروح من الصوديوم (FENa) أقل من 1% — قبل كلوي أم نخر أنبوبي حاد؟","b":"قبل كلوي (pre-renal) — في النخر الأنبوبي الحاد (ATN) يكون مرتفعًا."},{"f":"المادة الظليلة (contrast): هل تسبب قصورًا قبل كلوي؟","b":"لا — تسبب نخرًا أنبوبيًا حادًا (أذية كلوية مباشرة)."},{"f":"هل الكلية عديدة الكيسات من أسباب القصور الكلوي الحاد؟","b":"لا — تسبب قصورًا مزمنًا متدرجًا."},{"f":"أي مسكن لا يسبب قصورًا كلويًا حادًا نموذجيًا: الباراسيتامول أم NSAIDs؟","b":"الباراسيتامول — الـ NSAIDs تسبب قصورًا بتثبيط البروستاغلاندينات الكلوية."},{"f":"في القصور الكلوي الحاد: فرط كلس الدم أم نقصه؟","b":"نقص كلس الدم (hypocalcemia) — فرط الكالسيوم ليس من مشاهداته."}]},{"t":"أمراض الكبيبات والأوعية","cards":[{"f":"هل تسبب المتلازمة النفروزية زيادة القابلية للنزف؟","b":"لا — تسبب فرط تخثر (hypercoagulability) بضياع مضاد الثرومبين في البول."},{"f":"هل البيلة الدموية من سمات المتلازمة النفروزية النقية؟","b":"لا — النفروزية النقية: بيلة بروتينية دون بيلة دموية ودون ارتفاع توتر شرياني نموذجي."},{"f":"في التهاب الكبب والكلية التالي للعقديات: المتممة مرتفعة أم منخفضة في الطور الحاد؟","b":"منخفضة (انخفاض C3) — عبارة (المتممة مرتفعة) خاطئة؛ والشفاء عفوي غالبًا عند الأطفال لا قصور كلوي."},{"f":"اسطوانات كريات بيض (WBC casts) — أذية كبيبية أم التهاب خلالي/حويضة؟","b":"التهاب خلالي أو حويضة وكلية — الأذية الكبيبية: اسطوانات كريات حمر وكريات مشوهة."},{"f":"أي خافض ضغط ممنوع في تضيق الشريان الكلوي ثنائي الجانب: ARBs أم حاصرات الكالسيوم؟","b":"الـ ARBs (ومثبطات ACE) — خطر قصور كلوي حاد ثنائي."},{"f":"التنخر الحليمي الكلوي (papillary necrosis) يُشاهد في أي مرض؟","b":"الداء السكري (وكذلك فقر الدم المنجلي والتهاب الحويضة المزمن)."},{"f":"تضيق الشريان الكلوي أحادي الجانب: فرط ضغط خفيف سهل الضبط أم شديد معند؟","b":"شديد معند على العلاج — عبارة (خفيف سهل الضبط) خاطئة."},{"f":"هل يفيد اختبار ASLO في تشخيص التهاب الكبب والكلية سريع الترقي؟","b":"لا — سريع الترقي له أسباب مناعية أخرى (كـ ANCA وGoodpasture)."}]},{"t":"قصور الكلى المزمن","cards":[{"f":"في القصور الكلوي المزمن: الكالسيوم منخفض أم مرتفع؟ والفوسفور؟ والـ PTH؟","b":"نقص كالسيوم الدم + ارتفاع الفوسفور + ارتفاع PTH (فرط جارات ثانوي) — ارتفاع الكالسيوم وهبوط PTH ليسا من المشاهدات."},{"f":"أفضل علاج لفقر الدم في القصور الكلوي المزمن؟","b":"الإريثروبويتين (erythropoietin) — لعوز إنتاجه الكلوي."},{"f":"أفضل خافض ضغط يسيطر على البيلة البروتينية في CKD؟","b":"مثبطات الأنزيم المحول (ACE inhibitors) — لا حاصرات الكالسيوم."},{"f":"هل تُصحح البيلة البروتينية بحاصرات الكالسيوم؟","b":"لا — عبارة خاطئة؛ التصحيح بمثبطات ACE أو ARBs."},{"f":"مريض CKD وفقر دم بعوز الحديد — هل يكفي تعويض الإريثروبويتين؟","b":"لا — يُعالج عوز الحديد أولًا؛ الإريثروبويتين لا يصحح فقر الدم بعوز الحديد."},{"f":"في حمية القصور الكلوي المزمن: وارد فوسفور عالٍ أم منخفض؟ وتحديد بروتيني شديد؟","b":"وارد فوسفور منخفض — وتحديد الوارد البروتيني معتدل لا شديد."},{"f":"من أعراض القصور الكلوي المزمن: هل البدانة المركزية وفرط المنعكسات الوترية منها؟","b":"لا — كلتاهما ليستا من مظاهره."},{"f":"هل الستيروئيدات من العلاجات المحافظة للداء الكلوي المزمن؟","b":"لا — ليست من العلاج المحافظ الروتيني."}]},{"t":"الأمراض الخلالية والكيسية والحصوات","cards":[{"f":"القولنج الكلوي (renal colic): هل الترفع الحروري من أعراضه؟","b":"لا — ألم خاصرة ماغص شديد؛ وجود الحرارة يعني إنتانًا مرافقًا (حالة إسعافية)."},{"f":"أفضل وسيلة استقصائية لكشف الحصيات غير الظليلة؟","b":"التصوير الطبقي المحوسب غير الظليل (non-contrast CT)."},{"f":"في دراسة الحصيات الكلوية: هل يُطلب صوديوم البول؟ وهل نقص كلس الدم مؤهب؟","b":"لا — صوديوم البول لا يُطلب؛ ونقص كلس الدم ليس مؤهبًا (فرطه هو المؤهب)."}]},{"t":"تأثير الأمراض الجهازية والأدوية","cards":[{"f":"أي خافض ضغط مضاد استطباب مطلق عند الحوامل: ARBs أم حاصرات الكالسيوم؟","b":"الـ ARBs (ومثبطات ACE) — مشوهة للأجنة (teratogenic)."},{"f":"من تأثيرات NSAIDs على الكلية: نقص بوتاسيوم الدم أم فرطه؟","b":"فرط بوتاسيوم الدم مع احتباس صوديوم وماء — نقص البوتاسيوم ليس من تأثيراتها."},{"f":"الاستقصاء الأكثر حساسية للتشخيص المبكر للاعتلال الكلوي السكري؟","b":"البيلة الألبومينية الزهيدة (microalbuminuria) 30–300 ملغ/24 ساعة."}]},{"t":"الغسيل الكلوي وزرع الكلية","cards":[{"f":"من استطبابات التحال الإسعافي في القصور الحاد: فرط البوتاسيوم، الحماض الشديد، القلاء؟","b":"فرط البوتاسيوم والحماض الشديد وفرط حمل السوائل والاعتلال الدماغي — القلاء ليس استطبابًا."},{"f":"هل فرط البوتاسيوم من الآثار الجانبية للتحال الدموي؟","b":"لا — التحال يخفض البوتاسيوم؛ آثاره: هبوط ضغط وتشنجات عضلية."},{"f":"ما أفضل وصلة وعائية للتحال الدموي المزمن؟","b":"الوصلة الشريانية الوريدية الذاتية (AV fistula) — الأطول عمرًا والأقل اختلاطًا."}]}]},{"s":"الغدية والسكري","topics":[{"t":"مقدمة وفحص الغدد الصم","cards":[{"f":"فقدان وزن مع شهية جيدة يُشاهد في فرط الدرق والسكري — فهل يُشاهد في داء أديسون؟","b":"لا — داء أديسون يترافق مع نقص شهية؛ فقدان الوزن مع شهية جيدة لا يُشاهد فيه."},{"f":"ما معيار تشخيص الداء السكري بسكر الصيام؟","b":"سكر دم صيامي ≥126 ملغ/دل في قياسين متباعدين — أو ≥200 بعد ساعتين من حمل الغلوكوز الفموي."},{"f":"أي مما يلي لا يسبب بوالًا وعطاشًا (سهافًا): السكري، البيلة التفهة، فرط بوتاسيوم الدم؟","b":"فرط بوتاسيوم الدم — لا يسبب بوالًا؛ وداء أديسون لا يدخل في تفريقي البوال والعطاش."}]},{"t":"اضطرابات النخامية والوطاء","cards":[{"f":"أي دواء يخفض البرولاكتين لا يرفعه: البروموكريبتين أم الميتوكلوبراميد؟","b":"البروموكريبتين (bromocriptine) — ناهض دوبامين يخفض البرولاكتين؛ مضادات الحموضة والستيروئيدات لا تسبب فرط برولاكتين."},{"f":"مريض قصور نخامى شامل: أي هرمون لا يُعوَّض: الكورتيزول، الدرق، البرولاكتين؟","b":"البرولاكتين — لا يُعوَّض؛ يُعوَّض الكورتيزول والهرمون الدرقي والهرمونات الجنسية."},{"f":"في قصور النخامى: الجلد رطب وحار مع تعرق غزير أم جاف بارد؟","b":"جاف بارد شاحب — الجلد الرطب الحار المتعرق من علامات فرط الدرق لا قصور النخامى."}]},{"t":"أمراض الغدة الدرقية","cards":[{"f":"ما الصورة المخبرية لقصور الدرق البدئي (primary hypothyroidism)؟","b":"ارتفاع TSH + انخفاض FT4."},{"f":"TSH طبيعي + T3/T4 منخفض — قصور درقي بدئي أم ثانوي؟","b":"ثانوي (نخامى) — الخلل في النخامى لا في الدرق."},{"f":"TSH=8 مع FT4 طبيعي — ما التشخيص؟","b":"قصور درق تحت سريري (subclinical hypothyroidism)."},{"f":"الجحوظ (exophthalmos) يُشاهد في أي مرض درقي حصريًا؟","b":"داء غريفز (Graves disease) فقط."},{"f":"فقدان الثلث الوحشي للحاجب (lateral eyebrow loss) — علامة فرط الدرق أم قصوره؟","b":"قصور الدرق — ليست من علامات فرط النشاط."},{"f":"امرأة 48 سنة: مزاج مكتئب + زيادة نوم ووزن 20 كغ + بطء تفكير — ما أول اختبار مفيد؟","b":"تحري وظيفة الغدة الدرقية (TSH وFT4) — صورة قصور درق نموذجية."},{"f":"ما الذي يوجه لخباثة العقدة الدرقية: تعدد العقد، الجنس المؤنث، أم العقدة الوحيدة الصلبة سريعة النمو؟","b":"العقدة الوحيدة الصلبة سريعة النمو (مع ضخامة عقد لمفية) — تعدد العقد والجنس المؤنث لا يوجهان للخباثة."},{"f":"فرط نشاط درق مع نقص قبط اليود المشع — ما السبب الأرجح؟","b":"التهاب درق عابر (thyroiditis) — الدرق يُفرغ مخزونه دون تصنيع جديد؛ لا يُعالج بمضادات الدرق."},{"f":"ألم عنق ينتشر للفك يزداد بالبلع + سرعة تثفل 65 — التشخيص والتدبير؟","b":"التهاب الدرق تحت الحاد (دي كيرفان De Quervain) — السلعة مؤلمة؛ لا يُعالج بمضادات الدرق."},{"f":"مريض غريفز على ميثيمازول + حمى 40° + التهاب بلعوم — ما الاختلاط؟ وماذا تفعل؟","b":"ندرة المحببات (agranulocytosis) — أوقف الميثيمازول فورًا؛ ولا تُعطِ بروبيل ثيوراسيل (تفاعل متصالب)."},{"f":"حامل بعد استئصال درق جذري على تيروكسين 150 مكغ — ما الإجراء اللازم؟","b":"زيادة الجرعة (إلى 200 مكغ) — الحمل يرفع الحاجة للهرمون الدرقي."},{"f":"بعد استئصال درق تام: بماذا تُراقب الوظيفة الدرقية وتُضبط الجرعة التعويضية؟","b":"بقياس TSH (مع FT4) دوريًا."},{"f":"الإمساك المعند — من علامات قصور الدرق أم فرطه؟","b":"قصور الدرق — فرط النشاط يسبب تغوطًا متكررًا."}]},{"t":"جارات الدرق واستقالب الكالسيوم","cards":[{"f":"التهاب البنكرياس الحاد: هل يسبب ارتفاع كلس الدم؟","b":"لا — يسبب نقص كلس الدم (تصبُّن الدهون saponification)."},{"f":"في عوز فيتامين D الشديد: الفوسفور مرتفع أم منخفض؟","b":"منخفض — مع نقص الكالسيوم وارتفاع الفوسفاتاز القلوية؛ ارتفاع الفوسفور ليس من علاماته."},{"f":"سيدة 30 سنة: آلام هيكلية معممة + صعوبة النهوض من القرفصاء — ما التشخيص الأرجح؟","b":"تلين العظام (osteomalacia) بعوز فيتامين D — ضعف العضلات الدانية مميز."}]},{"t":"اضطرابات الغدة الكظرية","cards":[{"f":"في متلازمة كوشينغ: انخفاض ضغط الدم ونوب نقص السكر — صحيح أم خطأ؟","b":"خطأ — كوشينغ: ارتفاع ضغط وفرط سكر الدم؛ انخفاض الضغط ونوب نقص السكر ليستا من علاماته."},{"f":"هل ورم لب الكظر (القواتم) من أسباب متلازمة كوشينغ؟","b":"لا — كوشينغ من فرط قشر الكظر (كورتيزول)؛ ورم اللب يسبب فرط كاتيكولامينات."},{"f":"مريض تعب ونقص وزن — ما العلامة التي ترجح داء أديسون؟","b":"اغمقاق (تصبغ) الخطوط الراحية والثنيات — من فرط ACTH؛ مع هبوط توتر انتصابي (لا ارتفاع ضغط)."},{"f":"شحوب + تعرق + صداع نوبي + ارتفاع ضغط + خفقان — التشخيص الأرجح؟","b":"ورم القواتم (pheochromocytoma) — نوب كاتيكولامينات."},{"f":"متى يُستطب البحث عن سبب غدي لفرط الضغط الشرياني؟","b":"عند وجود كتلة كظرية أو علامات موجهة — القصة العائلية وحدها لا تستدعي الاستقصاء الغدي."},{"f":"بعد إيقاف الستيروئيدات المديدة: كم يحتاج المحور الوطائي النخامي الكظري للتعافي؟","b":"عدة أشهر — لا أسابيع؛ ولا تُوقف الستيروئيدات فجأة."},{"f":"فرّق سكريًا: كوشينغ مقابل أديسون؟","b":"كوشينغ = فرط سكر الدم؛ أديسون = ميل لنقص السكر مع نقص صوديوم وفرط بوتاسيوم."},{"f":"ما أشيع سبب لمتلازمة كوشينغ عمومًا؟","b":"السبب الدوائي (iatrogenic) — الستيروئيدات القشرية خارجية المنشأ."}]},{"t":"الغدد التناسلية والنمو","cards":[{"f":"متلازمة تيرنر (Turner): هل تسبب انقطاع حيض ثانوي؟","b":"لا — تسبب انقطاعًا بدئيًا (primary amenorrhea)؛ الثانوي أسبابه: الحمل، فرط برولاكتين، قصور مبيض مكتسب."},{"f":"امرأة متزوجة 33 سنة: غياب طمث ثانوي دون هبات ساخنة — ما الاستقصاء الأمثل أولًا؟","b":"اختبار الحمل — قبل أي استقصاء هرموني."},{"f":"في تأخر البلوغ البنيوي (constitutional delay): العمر العظمي أكبر أم أصغر من الزمني؟","b":"أصغر (متأخر) — عبارة (أكبر) خاطئة."},{"f":"التثدي الدوائي (drug-induced gynecomastia): هل يتراجع بإيقاف الدواء المحرض؟","b":"نعم — يتراجع عادةً بإيقاف السبب الدوائي."}]},{"t":"الداء السكري ومضاعفاته","cards":[{"f":"ما معيار تشخيص الداء السكري باختبار تحمل الغلوكوز الفموي؟","b":"سكر البلازما بعد ساعتين ≥200 ملغ/دل — أو صيامي ≥126 في قياسين متباعدين."},{"f":"لماذا الميتفورمين خط أول في السكري نمط 2 — وهل يحفز إفراز الأنسولين؟","b":"لا يحفز إفراز الأنسولين (يحسّن الحساسية) — ولا يسبب زيادة وزن ولا نقص سكر."},{"f":"العلاج الأمثل في السكري الحملي (gestational diabetes)؟","b":"الأنسولين (insulin)."},{"f":"الخضاب السكري HbA1c: عن أي مدة يعبّر؟ وكل كم يُعاير؟","b":"يعبّر عن ضبط السكر في 2–3 أشهر السابقة — ويُعاير كل 3 أشهر لا كل شهر؛ وهو أفضل مشعر للمراقبة."},{"f":"في الحماض الكيتوني السكري: البوتاسيوم الكلي مرتفع أم منخفض؟ وهل تُعطى خافضات فموية؟","b":"منخفض كليًا رغم سوائه البلازمي — ولا تُعطى خافضات سكر فموية في التدبير الحاد."},{"f":"متى تُعطى البيكربونات في الحماض الكيتوني السكري؟","b":"فقط في الحماض الشديد (pH < 6.9) — لا عندما يكون pH فوق 7.4."},{"f":"الأنسولين: هل ينقص الوزن عادةً؟","b":"لا — يزيد الوزن عادةً؛ عبارة (ينقص الوزن) خاطئة."},{"f":"من اختلاطات الأنسولين: الورم الشحمي مكان الحقن أم الضخامة الشحمية؟","b":"الضخامة الشحمية (lipohypertrophy) — (الورم الشحمي) عبارة خاطئة؛ ومن اختلاطاته: نقص السكر وزيادة الوزن."},{"f":"مقلدات DPP-4 في نمط 2: تحملها وتأثيرها على الوزن؟","b":"جيدة التحمل ولا تؤثر على الوزن."},{"f":"ما الحالة الوحيدة التي تسبب نقص سكر الدم عند سكري نمط 1 (حسب البنك)؟","b":"حدوث داء أديسون المرافق — أما كوشينغ فيسبب فرط سكر لا نقصه."},{"f":"هل يدخل الداء السكري نمط 1 في المتلازمة الاستقلابية (metabolic syndrome)؟","b":"لا — المتلازمة الاستقلابية مرتبطة بالمقاومة والنمط الثاني."},{"f":"سيدة بدينة + سكر عشوائي 200 متكرر — ما العلاج الأفضل؟","b":"الميتفورمين (metformin)."},{"f":"في مراقبة مريض السكري: هل يُطلب العامل الرثياني؟ وما هدف الضغط؟","b":"لا يُطلب العامل الرثياني — وهدف الضبط أقل من 130/80 لا 160/100."},{"f":"أي مما يلي ليس من اختلاطات السكري: اعتلال الشبكية، البراز الزفتي، تلين العظام؟","b":"البراز الزفتي وتلين العظام واضطراب السلوك — ليست من اختلاطات السكري."},{"f":"الميثيمازول (methimazole): هل هو من أدوية السكري الفموية؟","b":"لا — دواء مضاد للدرق؛ ليس من خافضات السكر."},{"f":"ما الدواء الأكبر أثرًا في خفض الخضاب السكري HbA1c؟","b":"الأنسولين (insulin)."}]}]},{"s":"الدموية","topics":[{"t":"الاضطرابات النزفية","cards":[{"f":"فرفرية نقص الصفيحات المناعية (ITP): هل تسبب ضخامة طحالية هامة؟","b":"لا — غياب ضخامة الطحال الهامة يميزها؛ وجودها يوجه لسبب آخر."},{"f":"متلازمة نقص الصفيحات الخثارية (TTP): الانحلال داخل الأوعية أم خارجها؟","b":"داخل الأوعية (microangiopathic) — مع خماسية: حمى، فقر دم انحلالي، نقص صفيحات، أعراض عصبية، قصور كلوي."},{"f":"داء فون ويلبراند (von Willebrand): هل يسبب نقص صفيحات؟","b":"لا — عوز أو خلل عامل فون ويلبراند؛ الصفيحات طبيعية العدد."},{"f":"فرّق: المتلازمة اليوريميائية الانحلالية (HUS) — هل يتطاول زمن البروترومبين (PT)؟","b":"لا — PT طبيعي فيها؛ تطاوله يوجه لاعتلال تخثر منتشر (DIC)."}]},{"t":"التظاهرات والفحص السريري","cards":[{"f":"في أي مرض تكون الضخامة الطحالية عرطلة (massive): الليشمانيا الحشوية أم انحلال الدم المناعي الذاتي؟","b":"الليشمانيا الحشوية (kala-azar) — الانحلال المناعي الذاتي لا يسبب ضخامة عرطلة."},{"f":"فقر الدم المنجلي بعد سن الخامسة: ضخامة طحال أم ضموره؟","b":"ضمور الطحال (autosplenectomy) بالاحتشاءات المتكررة — الضخامة عند الكبار ليست من سماته؛ والداء الزلاقي وفقر الدم اللاتصنعي ليستا من أسباب ضخامة الطحال."},{"f":"سرعة التثفل (ESR): هل ترتفع في فقر الدم المنجلي؟","b":"لا — قد تنخفض؛ ترتفع في الأخماج والخباثات والأمراض المناعية."},{"f":"فرط وحيدات النوى الخمجي (EBV): هل يرفع العدلات؟","b":"لا — يرفع اللمفاويات (وحيدات النوى)؛ ارتفاع العدلات في الإنتانات الجرثومية."},{"f":"الديكساميتازون: هل يسبب نقص العدلات؟","b":"لا — يسبب زيادة العدلات (neutrophilia)؛ نقصها من مضادات الاختلاج وبعض الأدوية."},{"f":"كثرة الحمر المطلقة: العيش في المرتفعات أم المنخفضات؟ والمدرات؟","b":"المرتفعات (نقص الأكسجة) — المنخفضات لا تسببها؛ والمدرات تسبب كثرة حمر نسبية (نقص حجم) لا مطلقة."},{"f":"قلة الكريات الشاملة: فرط الطحالية سبب مركزي أم محيطي؟","b":"محيطي (زيادة التدمير خارج النقي) — ليست من الأسباب مركزية المنشأ."},{"f":"LDH: هل يرتفع في فقر الدم اللاتصنعي (aplastic anemia)؟","b":"لا — يرتفع في فقر الدم الانحلالي؛ اللاتصنعي نقي قاحل دون انحلال."},{"f":"أي مما يلي لا يسبب ضخامة عقد لمفية: الناعور، الداء السكري، الأخماج الفيروسية؟","b":"الناعور (hemophilia) والداء السكري — ليستا من أسبابها؛ والأسيتامينوفين والكينولونات ليست من الأدوية المسببة لها."}]},{"t":"العلاج بمضادات التخثر","cards":[{"f":"ما الفحص المناسب لمتابعة التمييع عند مريضة تعالج بالهيبارين؟","b":"زمن الثرومبوبلاستين الجزئي (PTT/aPTT)."},{"f":"مريض على هيبارين يحتاج جراحة مستعجلة — ما الترياق الإسعافي؟","b":"سلفات البروتامين (protamine sulfate)."},{"f":"متى يكون هدف الوارفارين INR = 3.5؟","b":"الصمام التاجي (المترالي) الميكانيكي — هدف أعلى من الصمام الأبهري."}]},{"t":"منتجات الدم ونقل الدم","cards":[{"f":"في نقل الدم الكتلي: نقص بوتاسيوم الدم أم فرطه؟","b":"فرطه (hyperkalemia) — مع نقص كالسيوم الدم (بالسترات)؛ نقص البوتاسيوم ليس من اختلاطاته."},{"f":"الارتكاس الحراري المعزول بعد نقل الدم: هل يُعزى لتنافر الزمر Rh؟","b":"لا — الارتكاس الحموي غير الانحلالي لا يُعزى لتنافر Rh."},{"f":"قبل قبول التبرع بالدم: هل يُتحرى عن فيروس الهربس؟","b":"لا — يُتحرى عن HIV والتهاب الكبد B وC والزهري؛ الهربس ليس منها."},{"f":"مريض خضابه 8 غ/دل: هل نقل الدم قرار رقمي مطلق؟","b":"لا — القرار سريري (أعراض، نزف، ابيضاض حاد) لا رقمي فقط."}]},{"t":"خباثات الدم","cards":[{"f":"عصيات أور (Auer rods) في الأرومات — تؤكد المنشأ النقوي أم اللمفي للابيضاض؟","b":"النقوي (myeloid) — لا تُشاهد في الابيضاض اللمفي."},{"f":"النكس السحائي (CNS relapse) شائع في أي ابيضاض حاد: اللمفي (ALL) أم النقوي (AML)؟","b":"اللمفي الحاد (ALL) — ليس شائعًا في AML."},{"f":"مريض ورم نقوي (myeloma) تطور لديه تخليط ذهني — ما الاختبار الإسعافي؟","b":"معايرة كالسيوم الدم — فرط كلس الدم من اختلاطات الورم النقوي."}]},{"t":"فقر الدم","cards":[{"f":"في فقر الدم بعوز الحديد: إشباع الترانسفيرين مرتفع أم منخفض؟ والسعة الرابطة الكلية (TIBC)؟","b":"إشباع منخفض + TIBC مرتفعة + فيريتين منخفض — (ارتفاع الإشباع وانخفاض TIBC) عبارتان خاطئتان."},{"f":"أين يحدث امتصاص الحديد بأكبر فعالية: المعدة والدقاق أم العفج والصائم الداني؟","b":"العفج (duodenum) والصائم الداني — لا المعدة والدقاق."},{"f":"في تدبير عوز الحديد: هل يُوقف التعويض عند عودة الخضاب للطبيعي؟","b":"لا — يُستمر 3 أشهر إضافية لملء مخازن الحديد."},{"f":"في عوز الحديد: هل الشبكيات مرتفعة؟ وهل البيلوروبين المباشر مرتفع؟","b":"لا — الشبكيات غير مرتفعة والبيلوروبين المباشر غير مرتفع."},{"f":"ما العلامة التي ترجح عوز B12 على عوز الفولات؟","b":"الاضطرابات العصبية النفسية وإصابة الحس العميق (مع ارتفاع LDH) — الفولات لا يسبب أعراضًا عصبية."},{"f":"في فقر الدم بعوز B12: الكريات صغيرة ناقصة الصباغ أم عرطلة كبيرة؟ والشبكيات؟","b":"عرطلة كبيرة (macrocytic) — (صغيرة ناقصة الصباغ) خاطئة؛ والشبكيات غير مرتفعة."},{"f":"الأظافر الملعقية (koilonychia): من علامات عوز الحديد أم عوز B12؟","b":"عوز الحديد — ليست من علامات عوز B12."},{"f":"ما العلامة التشخيصية الهامة للتلاسيميا بيتا الصغرى؟","b":"ارتفاع الخضاب A2 (HbA2) — والضخامة الطحالية العرطلة ليست شائعة فيها."},{"f":"رحلان خضاب: HbA = 95.4% وHbA2 = 4.46% — ما التشخيص؟","b":"تلاسيميا بيتا صغرى (β-thalassemia minor)."},{"f":"رحلان خضاب قبل الزواج: HbS = 55% وHbA = 30% وHbA2 = 3% — ما التشخيص؟","b":"تلاسيميا منجلية (sickle-β+ thalassemia)."},{"f":"عوز G6PD: هل ينتقل بصفة جنسية سائدة؟ وهل الستيروئيدات مفيدة؟","b":"لا — مرتبط بالصبغي X (متنحي غالبًا)؛ والستيروئيدات ليست مفيدة؛ والانحلال يحتاج محرضًا ولا يحدث عند كل المصابين."},{"f":"في نوبة الفوال (G6PD): الشبكيات ناقصة أم مرتفعة؟","b":"مرتفعة (استجابة نقيوية) — نقص الشبكيات لا يوجه للفوال."},{"f":"في فقر الدم الانحلالي: البيلوروبين المباشر أم غير المباشر هو المرتفع؟","b":"غير المباشر (unconjugated) — ارتفاع المباشر عبارة خاطئة."},{"f":"في فقر الدم الالتهابي (الأمراض المزمنة): مستقبلات الترانسفيرين مرتفعة؟ والخضاب أقل من 6؟","b":"لا — مستقبلات الترانسفيرين طبيعية/منخفضة؛ والخضاب نادرًا ما ينزل تحت 6."},{"f":"في الداء المنجلي: هل ضمور اللوزتين من علاماته؟","b":"لا — ليست من علاماته؛ المميز: ضمور الطحال بعد سن الخامسة."},{"f":"طفل منجلي: ألم بطني حاد + شحوب + ضخامة طحال + خضاب 3 غ/دل + شبكيات 6% — التشخيص؟","b":"نوبة تشظي الطحال (splenic sequestration crisis)."},{"f":"شاب: تعب + يرقان خلسة + ضخامة طحال صغيرة + LDH مرتفع + شبكيات 4% — ما الفحص المشخص؟","b":"تفاعل كومبس المباشر (direct Coombs) الإيجابي — فقر دم انحلالي مناعي ذاتي."},{"f":"أي مما يلي ليس من أسباب فقر الدم صغير الكريات: عوز الحديد، التلاسيميا، عوز الفولات؟","b":"عوز الفولات (عرطل الكريات) — وكذلك قصور الدرق ليس منها."},{"f":"في فقر الدم العرطل (megaloblastic): نقي العظم ناقص أم مفرط الخلوية؟","b":"مفرط الخلوية (hypercellular) — عبارة (ناقص الخلوية) خاطئة."},{"f":"الشبكيات (reticulocytes): هل تحوي بقايا DNA؟","b":"لا — كريات حمر غير ناضجة تحوي بقايا RNA والعضيات دون نواة."}]}]},{"s":"العصبية","topics":[{"t":"أخماج الجهاز العصبي","cards":[{"f":"فرّق: موجودات السائل الدماغي الشوكي (CSF) في التهاب السحايا الجرثومي مقابل التهاب الدماغ الفيروسي","b":"الجرثومي: سائل عكر، كريات بيض على حساب العدلات، بروتين مرتفع، سكر منخفض. التهاب الدماغ الفيروسي: كثرة لمفاوية بسكر طبيعي — ارتفاع السكر «دومًا» عبارة خاطئة."},{"f":"قاعدة ذهبية: التهاب السحايا الجرثومي (Bacterial meningitis)","b":"كل التهاب سحايا جرثومي إسعاف يُعالَج في المستشفى بالصادات الوريدية (سيفترياكسون + فانكوميسين) حتى يثبت العكس — لا يُعالَج فمويًا في المنزل أبدًا."},{"f":"من سؤال حقيقي: أشيع فيروس مسبب لالتهاب الدماغ الفيروسي (Viral encephalitis)؟","b":"الهربس البسيط (HSV): يترافق بأعراض توضع عصبي وحالة سحائية حادة، ويُعالَج بالأسيكلوفير وريديًا."}]},{"t":"الأمراض الوعائية الدماغية","cards":[{"f":"قاعدة ذهبية: مريض بشلل شقي مفاجئ","b":"كل شلل شقي مفاجئ سكتة دماغية حتى يثبت العكس — الخطوة الأولى تصوير طبقي محوري دون حقن لنفي النزف قبل أي علاج (إعطاء الأسبرين قبل نفي النزف قد يكون قاتلًا)."},{"f":"نقطة ذهبية: الضغط الشرياني في السكتة الدماغية الحادة (Acute stroke)","b":"لا يُخفَّض الضغط بسرعة — يُترَك مرتفعًا باعتدال (ارتفاع متساهَل) للحفاظ على التروية الدماغية ما لم يتجاوز حدودًا حرجة."},{"f":"نمط: صداع رعدي مفاجئ شديد + إقياء + رهاب ضوء بعد جهد (نوب سعال شديدة)","b":"نزف تحت عنكبوتية (Subarachnoid hemorrhage) حتى يثبت العكس — يجب نفيه في أي صداع مفاجئ شديد."},{"f":"أنماط: استقصاءات السكتة الدماغية الحادة إسعافيًا","b":"طبقي محوري (نفي النزف)، مرنان، تخطيط قلب (مصدر صمي)، إيكو دوبلر للسباتيين، تعداد عام وسكر — ولا مكان لعيار النحاس والفوسفور أو وظائف الدرق إسعافيًا."}]},{"t":"الصرع والاختلاجات","cards":[{"f":"نقطة ذهبية: تدبير الحالة الصرعية (Status epilepticus) دوائيًا","b":"الخط الأول بعد تأمين العلامات الحيوية: بنزوديازبين — ديازيبام وريدي أو شرجي؛ الخط الثاني: فينيتوئين (Phenytoin) وريدي."},{"f":"نمط: دواء يسبب ضخامة لثة + عوز فيتامين D + عوز فولات + رنح","b":"الفينيتوئين (Phenytoin): ضخامة اللثة، فقر دم ضخم الأرومات بعوز الفولات، تلين عظام بعوز فيتامين D، ورنح ورأرأة بالتسمم المخيخي."},{"f":"فرّق: تعريف الحالة الصرعية","b":"نوب لم تتوقف تلقائيًا أو تكررت دون عودة الوعي بينها — إسعاف عصبي خطير لا يزول لوحده؛ أهم محرضاتها عدم الالتزام بالأدوية."},{"f":"من سؤال حقيقي: أي مما يلي ليس مضادًا للصرع: كلوربرومازين أم أمانتادين؟","b":"كلاهما ليسا مضاد صرع: الكلوربرومازين (Chlorpromazine) مضاد ذهان قد يخفض عتبة الاختلاج، والأمانتادين (Amantadine) مضاد فيروسات وباركنسوني."},{"f":"نمط: الكاربامازبين في الحالة الصرعية","b":"لا يوجد مستحضر وريدي من الكاربامازبين (Carbamazepine) — لا يُستخدَم في الحالة الصرعية أبدًا."}]},{"t":"الصداع والشقيقة","cards":[{"f":"نقطة ذهبية: مدة نوبة الشقيقة (Migraine) وصفاتها","b":"تستمر 4–72 ساعة: صداع نابض أحادي شديد مع غثيان/إقياء ورهاب ضوء وصوت؛ النسمة تحدث في نحو ثلث الحالات فقط — ليست «غالبًا»."},{"f":"فرّق: الصداع العنقودي (Cluster headache)","b":"شاب بألم شديد حجاجي أحادي، نوب 30–90 دقيقة مع دُماع واحتقان ملتحمة؛ تُوقَف النوبة بالأكسجين 100% أو السوماتريبتان تحت الجلد — الأفيونيات (كودئين) غير مفيدة."},{"f":"قاعدة ذهبية: صداع حاد مع صلابة نقرة","b":"كل صداع حاد مع صلابة نقرة يستوجب تقييمًا إسعافيًا عاجلًا حتى يثبت العكس — يوحي بالتهاب سحايا أو نزف تحت عنكبوتية."},{"f":"نقطة ذهبية: الوقاية من نوب الشقيقة","b":"بروبرانولول (Propranolol)، أميتريبتيلين (Amitriptyline)، فالبروات — أما مضادات الالتهاب غير الستيروئيدية فعلاج حاد للنوبة لا وقاية منها."},{"f":"نمط: الصداع العنقودي والجنس","b":"الصداع العنقودي يكثر عند الذكور."},{"f":"من سؤال حقيقي: صداع مزمن لسنوات دون أعراض توضع عصبي","b":"يوجَّه لصداع أولي (توتري أو شقيقة مزمنة) — الكتلة الدماغية تُظهِر عادة صداعًا مترقيًا مع علامات توضع أو وذمة حليمة."}]},{"t":"الأمراض العصبية التنكسية","cards":[{"f":"نقطة ذهبية: داء ألزهايمر (Alzheimer's disease)","b":"نقص الذاكرة الحديثة أولًا + لا أدائية (Apraxia) + ضمور دماغي شعاعيًا — الحوادث الوعائية تسبب الخرف الوعائي لا ألزهايمر."},{"f":"نقطة ذهبية: داء باركنسون (Parkinson's disease)","b":"رجفان راحي يخف بالحركة الإرادية + صمل (Rigidity) + بطء حركة؛ يبدأ غالبًا بعد عمر 60."},{"f":"فرّق: رجفان أثناء الحركة الإرادية","b":"يوجَّه للرجفان الأساسي (Essential tremor) لا لباركنسون — رجفان باركنسون راحي."}]},{"t":"التصلب اللويحي المتعدد","cards":[{"f":"نقطة ذهبية: التصلب اللويحي المتعدد (Multiple sclerosis)","b":"مرض مزيل للنخاعين (Demyelinating) يصيب الخلايا قليلة التغصن (Oligodendrocytes) — آفة متعددة المكان والزمان."},{"f":"نمط: تشخيص التصلب اللويحي","b":"لا يوجد اختبار نوعي وحيد للتشخيص — التشخيص بالمعايير السريرية والشعاعية."},{"f":"نمط: أكثر أماكن آفات التصلب اللويحي","b":"حول البطينات وتحت القشرية وفي النخاع — ليست جذع الدماغ."}]},{"t":"اضطرابات الوصل العصبي العضلي","cards":[{"f":"نقطة ذهبية: الوهن العضلي الوخيم (Myasthenia gravis)","b":"ضعف عضلي مترقٍّ بالجهد؛ من الأعراض الباكرة: اطراق (Ptosis) في نهاية النهار وشفع (Diplopia)."},{"f":"نمط: اختبار مؤكد للوهن العضلي الوخيم","b":"الاستجابة لبيريدوستيغمين (Pyridostigmine) تؤكد التشخيص."},{"f":"قاعدة ذهبية: أضداد مستقبلات الأستيل كولين سلبية","b":"سلبية الأضداد لا تنفي الوهن العضلي الوخيم حتى يثبت العكس — توجد حالات سلبية المصل وأضداد MuSK تُشخَّص سريريًا وكهربائيًا."}]},{"t":"أمراض الأعصاب المحيطية","cards":[{"f":"نقطة ذهبية: ألم الأعصاب المحيطية السكري (Diabetic neuropathy)","b":"الخط الأول: بريغابالين (Pregabalin) — إلى جانب الغابابنتين والدولوكستين."},{"f":"نقطة ذهبية: متلازمة غيلان باريه (Guillain-Barré)","b":"اعتلال أعصاب التهابي مزيل للنخاعين حاد مناعي أحادي الطور: ضعف صاعد من الأسفل للأعلى مع نقص/غياب المنعكسات الوترية (لا اشتدادها) — خطورته في القصور التنفسي."},{"f":"من سؤال حقيقي: كحولي مزمن بخزل وخدر وتنميل في الأطراف","b":"عوز فيتامين B12 — يسبب اعتلال أعصاب محيطية بتنكس الحبال الخلفية والجانبية."}]},{"t":"شلل العصب الوجهي","cards":[{"f":"نقطة ذهبية: علاج شلل العصب الوجهي (Bell's palsy)","b":"الستيروئيدات (بريدنيزولون) هي العلاج المثبت إحصائيًا."},{"f":"فرّق: ماذا يتأثر بنفس جهة الإصابة في شلل العصب الوجهي؟","b":"نقص حس الذوق (الحبل الطبلي)، فرط سمع (شلل العضلة الركابية)، نقص اللعاب، ألم خلف الأذن — ما عدا غياب حس الوجه (يتبع العصب مثلث التوائم الخامس)."},{"f":"من سؤال حقيقي: مضادات الاختلاج في شلل الوجهي","b":"بريغابالين وكاربامازبين وفينيتوئين لا تفيد في شلل العصب الوجهي — ليست بديلًا عن الستيروئيدات."}]},{"t":"التخليط الذهني والهذيان","cards":[{"f":"قاعدة ذهبية: تخليط ذهني حاد","b":"كل تخليط ذهني حاد سببه عضوي/استقلابي حتى يثبت العكس — نوب الشقيقة لا تسبب تخليطًا حادًا أبدًا."},{"f":"أنماط: أسباب التخليط الذهني الحاد","b":"خراج دماغي، متلازمة نظيرة ورمية، حماض خلوني شديد، اضطراب الصوديوم، حالة صرعية جزئية متكررة."},{"f":"نقطة ذهبية: الهذيان (Delirium)","b":"بداية حادة متقلبة على مدار اليوم مع اضطراب الانتباه والوعي — يختلف عن الخرف التدريجي."}]},{"t":"الغشي وفقد الوعي","cards":[{"f":"فرّق: عض اللسان في فقد الوعي","b":"عض اللسان علامة النوبة الصرعية لا الغشي — بادرة الغشي: خفة رأس، تعتم رؤية، طنين أذنين."},{"f":"قاعدة ذهبية: التمييز بين الغشي والنوبة الصرعية","b":"أهم وسيلة هي القصة السريرية الدقيقة من المريض والشهود حتى يثبت العكس — قبل أي استقصاء."},{"f":"نقطة ذهبية: الغشي (Syncope)","b":"نقص تروية دماغية عابر يحدث عادة بالوقوف، تسبقه خفة رأس ثم تعتم رؤية، وقد يصادف سلس بولي."}]},{"t":"عسر البلع والأعراض البصلية","cards":[{"f":"فرّق: الرتة التشنجية (Spastic dysarthria) مقابل ناقصة الحركة","b":"التشنجية: إصابة ثنائية الجانب للعصبون الحركي العلوي (متلازمة بصلية كاذبة). الكلام على وتيرة واحدة = رتة ناقصة الحركة في باركنسون."},{"f":"فرّق: عسر البلع الحاد مقابل المزمن","b":"الحاد: دفتيريا، غيلان باريه، ذيفان وشيقي (Botulism)، حادث وعائي — أما أدواء العصبون العلوي فتسبب عسر بلع مترقيًا مزمنًا لا حادًا."},{"f":"نمط: داء باركنسون والكلام","b":"باركنسون يسبب رتة ناقصة الحركة (Hypokinetic) لا تشنجية."}]}]},{"s":"الطب النفسي","topics":[{"t":"البنزوديازبينات والمنومات","cards":[{"f":"نقطة ذهبية: آلية البنزوديازبينات (Benzodiazepines)","b":"معدِّلات تفارقية إيجابية لمستقبلات GABA-A — لا ترتبط بمستقبلات السيروتونين إطلاقًا."},{"f":"قاعدة ذهبية: القلق المزمن والبنزوديازبينات","b":"لا تكون البنزوديازبينات الدعامة الرئيسية لعلاج القلق المزمن حتى يثبت العكس — خطر الإدمان والتعود وضعف الفعالية طويلة الأمد."},{"f":"نمط: الديازيبام الوريدي","b":"قد يسبب نومًا مباشرًا ونساوة عابرة وتفاعلًا تناقضيًا (هياج بدل التهدئة خاصة عند المسنين) — أما الإدمان فيتطلب استخدامًا مزمنًا لا جرعة إسعافية."}]},{"t":"مضادات الذهان","cards":[{"f":"نقطة ذهبية: استطبابات مضادات الذهان (Antipsychotics)","b":"حجر الأساس في الفصام والهوس الحاد — وتُفاقِم أعراض باركنسون لأنها تحصر مستقبلات الدوبامين."},{"f":"فرّق: الجيل الأول مقابل الثاني","b":"الأول: أعراض خارج هرمية أكثر (باركنسونية، تململ، عسر حركة متأخر). الثاني: أعراض خارج هرمية أقل لكن عبء استقلابي (زيادة وزن وسكري) — ليست «آثارًا أقل» بالمطلق."},{"f":"نمط: الدواء المسبب لنقص المحببات (Agranulocytosis)","b":"الكلوزابين (Clozapine) وحده — يستلزم تعداد دم دوريًا إلزاميًا."},{"f":"نمط: مضادات الذهان وتخطيط القلب والبرولاكتين","b":"تطوّل الفاصلة QT (خطر تورساد دي بوانت) ولا تقصّرها — وتسبب فرط برولاكتين الدم لا نقصه."},{"f":"من سؤال حقيقي: صنّف: ريزبيريدون، أريبيبرازول، هالوبيريدول، ديازيبام","b":"ريزبيريدون وأريبيبرازول جيل ثانٍ؛ هالوبيريدول وكلوربرومازين وفلوفينازين جيل أول — أما الديازيبام فبنزوديازبين وليس مضاد ذهان."}]},{"t":"مضادات الاكتئاب","cards":[{"f":"فرّق: ثلاثيات الحلقة مقابل SSRI قلبيًا","b":"ثلاثيات الحلقة سامة قلبيًا (تأثير شبيه بالكينيدين) — مضاد استطباب بعد احتشاء العضلة القلبية واضطرابات النظم؛ الـSSRI آمنة قلبيًا نسبيًا والسيرترالين المفضل بعد الأحداث القلبية."},{"f":"قاعدة ذهبية: مضادات الاكتئاب والهوس","b":"لا تُعطى مضادات الاكتئاب في هجمة الهوس حتى يثبت العكس — قد تفاقم الأعراض أو تحرض الهوس لدى ثنائي القطب."},{"f":"نقطة ذهبية: استطبابات ثلاثيات الحلقة خارج الاكتئاب","b":"ألم الاعتلال العصبي والوقاية من الشقيقة (أميتريبتيلين) — بتأثير مضاد للكولين: جفاف فم واحتباس بول (لا سلس بول)."},{"f":"نمط: الـSSRI والصوديوم","b":"قد تسبب متلازمة SIADH (نقص صوديوم خاصة عند المسنين) وأعراض سحب عند الإيقاف المفاجئ."}]},{"t":"الليثيوم ومثبتات المزاج","cards":[{"f":"نقطة ذهبية: الليثيوم (Lithium)","b":"المعيار الذهبي للاضطراب ثنائي القطب: يعالج هجمة الهوس الحادة ويقي من النكس — ليس مضاد ذهان ولا يسبب إدمانًا."},{"f":"نمط: أمان الليثيوم","b":"ليس آمنًا في القصور الكلوي ولا في الحمل، ويُقاس مستواه بالدم (هامش علاجي ضيق)."},{"f":"فرّق: الكاربامازبين","b":"مضاد اختلاج ومثبت مزاج — ليس مضاد ذهان من الجيل الثاني ولا مضاد اكتئاب أوليًا."}]},{"t":"الاضطرابات الاكتئابية","cards":[{"f":"نقطة ذهبية: علاج الاكتئاب الكبير","b":"دون أعراض ذهانية: خط أول SSRI (سيرترالين)؛ مع أعراض ذهانية: مضاد اكتئاب + مضاد ذهان (كويتابين)."},{"f":"نمط: الدونيبيزيل (Donepezil)","b":"مثبط أستيل كولين إستراز لداء ألزهايمر — ليس مضاد اكتئاب."},{"f":"من سؤال حقيقي: اكتئاب + ألم ليفي عضلي + اعتلال أعصاب","b":"ثلاثيات الحلقة (أميتريبتيلين) تفيد للاثنين معًا — الكلوربرومازين (مضاد ذهان) لا يفيد."},{"f":"نمط: أدوية ليست مضادات اكتئاب","b":"السوليبرايد (Sulpiride) والأريبيبرازول مضادا ذهان — لا يُستخدَمان علاجًا أوليًا للاكتئاب."}]},{"t":"الاضطراب ثنائي القطب والهوس","cards":[{"f":"أنماط: أدوية الهوس","b":"أملاح الليثيوم، مضادات الذهان (أولانزابين، ريزبيريدون)، بنزوديازبين للتهدئة (كلونازيبام) — حاصرات بيتا غير ملائمة."},{"f":"نقطة ذهبية: صورة هجمة الهوس","b":"ارتفاع مزاج + توهم عظمة + هلوسات سمعية + اضطراب بصيرة — غموض التفكير ليس منها."},{"f":"قاعدة ذهبية: قبل وصف مضاد اكتئاب","b":"كل اكتئاب يُتحرَّى فيه الاضطراب ثنائي القطب أولًا حتى يثبت العكس — خطر تحريض الهوس بمضاد الاكتئاب."}]},{"t":"الفصام والاضطرابات الذهانية","cards":[{"f":"نقطة ذهبية: العرض الأكثر نوعية للفصام","b":"إذاعة الأفكار (Thought broadcasting) — من أعراض شنايدر من الدرجة الأولى."},{"f":"فرّق: تسارع الأفكار مقابل بطئها مقابل إذاعتها","b":"تسارع الأفكار = هوس؛ بطء الأفكار والنشاط = اكتئاب؛ إذاعة الأفكار = فصام."},{"f":"أنماط: معايير تشخيص الفصام","b":"عرضان أو أكثر لمدة شهر مع ستة أشهر من التدهور الوظيفي — ارتفاع المزاج ليس منها، والانتحار اختلاط لا معيار."},{"f":"قاعدة ذهبية: علاج الذهان","b":"كل عرض ذهاني علاجه مضادات الذهان حتى يثبت العكس — الفينيتوين والكاربامازبين والفينوباربيتال ليست علاجًا للذهان."}]},{"t":"اضطرابات القلق","cards":[{"f":"فرّق: نوبة الهلع (Panic attack)","b":"نوبات متكررة غير متوقعة: خفقان وضيق تنفس وتعرق وخوف من الموت/الإغماء — الاستيقاظ باختناق وخوف من الموت هلع نومي (نحو 30% من الحالات)."},{"f":"نقطة ذهبية: الرهاب الاجتماعي (Social phobia)","b":"خوف من الإذلال والإحراج في المواقف الاجتماعية — والمريض يدرك أن خوفه مفرط وغير عقلاني (بخلاف التوهم)."},{"f":"نمط: القلق المعمم","b":"أرق وضعف تركيز وأعراض جسدية (إسهال، ألم بطني) — الاكتئاب مع الرغبة بالانتحار ليس من سماته."}]},{"t":"اضطراب الوسواس القهري","cards":[{"f":"نقطة ذهبية: علاج الوسواس القهري (OCD)","b":"المريض يملك بصيرة سليمة فإقناعه منطقيًا عديم الجدوى — العلاج: SSRI + التعرض ومنع الاستجابة (ERP)."},{"f":"نمط: دواء الوسواس عند مسن مع ضخامة بروستات","b":"باروكسيتين (SSRI) — تُتجنَّب ثلاثيات الحلقة لتأثيرها المضاد للكولين (احتباس بول وإمساك)."},{"f":"فرّق: هوس نتف الشعر (Trichotillomania)","b":"بقع ناقصة الكثافة وشعر بأطوال مختلفة (دليل النتف) — لا يُعالَج بالستيروئيدات الموضعية."}]},{"t":"اضطراب الشدة ما بعد الرض","cards":[{"f":"فرّق: ارتكاس الكرب الحاد مقابل PTSD","b":"الكرب الحاد خلال الشهر الأول من الرض؛ اضطراب الشدة ما بعد الصدمة (PTSD) بعد شهر: كوابيس اقتحامية وعدم ثبات انفعالي."},{"f":"نمط: مظاهر PTSD الجسدية","b":"فرط إثارة ودية: تعرق غزير وتسرع قلب وتنفس وارتفاع ضغط — زيادة التيروكسين ليست منها."},{"f":"قاعدة ذهبية: اضطرابات الشخصية والرضوض","b":"اضطرابات الشخصية سمات دائمة مستقرة من المراهقة — لا «تحدث» بعد رضّ حاد حتى يثبت العكس."}]},{"t":"الإدمان واضطرابات تعاطي المواد","cards":[{"f":"نمط: الاعتياد الفيزيائي","b":"نيكوتين، أمفيتامين، بنزوديازبينات، كحول — أما القنب الهندي فاعتياده نفسي أساسًا."},{"f":"فرّق: سحب البنزوديازبين — صغرى مقابل كبرى","b":"الصغرى: قلق وأرق وكوابيس (مزعجة غير مهددة)؛ الكبرى: اختلاجات معممة وأعراض ذهانية وقد تصل للوفاة."},{"f":"قاعدة ذهبية: إيقاف المهدئات","b":"كل إدمان على المهدئات يُعالَج بالتخفيف التدريجي حتى يثبت العكس — ومضادات الالتهاب غير الستيروئيدية لا تسبب إدمانًا."}]},{"t":"الطب النفسي عند الأطفال والمراهقين","cards":[{"f":"نقطة ذهبية: ADHD عند الطفل","b":"خط العلاج الدوائي الأول: ميثيل فينيدات (Methylphenidate) — منبه للجهاز العصبي المركزي."},{"f":"فرّق: التوحد الطفلي مقابل غير النموذجي","b":"النموذجي: شذوذات قبل عمر 3 سنوات؛ تراجع بعد تطور طبيعي حتى 4 سنوات = توحد غير نموذجي."},{"f":"نمط: القلق عند الأطفال","b":"تراجع دراسي وخوف من الظلام وقلق انفصال — التوحد والانعزال سمة طيف التوحد لا القلق."}]},{"t":"الطب النفسي عند كبار السن","cards":[{"f":"نقطة ذهبية: الفصام متأخر الحدوث (الفصام الشيخي)","b":"يبدأ بعد الستين وتغلب عليه الأعراض الزورانية (الاضطهادية) مع ندرة الأعراض السلبية."},{"f":"فرّق: هلوسات بصرية مفصلة عند مسن","b":"توجَّه لخرف أجسام ليوي (Lewy body) لا لألزهايمر — ألزهايمر قد يترافق بتوهمات واكتئاب وقلق."},{"f":"نمط: البنزوديازبينات عند المسنين","b":"تسبب تخليطًا نهاريًا ورنحًا وخطر سقوط — تُعطى قصيرة الأمد وبحذر شديد."}]},{"t":"اضطرابات الأكل","cards":[{"f":"نقطة ذهبية: التشخيص التفريقي للقهم العصبي (Anorexia nervosa)","b":"فقدان وزن شديد: اكتئاب، داء أمعاء التهابي، سوء امتصاص، قصور نخامية — داء السكري نمط 2 ليس منها."},{"f":"نقطة ذهبية: القهم العصبي","b":"خوف مرضي من زيادة الوزن مع صورة جسم مشوهة — قد يترافق بانقطاع الطمث."},{"f":"فرّق: الشره العصبي (Bulimia nervosa)","b":"نهم ثم تطهير (إقياء ذاتي) مع وزن طبيعي غالبًا — بخلاف القهم بنحوله الشديد."}]},{"t":"اضطرابات النوم","cards":[{"f":"فرّق: الأرق العابر مقابل المزمن","b":"العابر/بسبب السفر: زولبيدم (منوم قصير غير متراكم)؛ المزمن: العلاج السلوكي المعرفي — لا منومات مزمنة."},{"f":"نمط: الفلوكسيتين والنوم","b":"الفلوكسيتين (Fluoxetine) منشِّط قد يسبب الأرق — لا يُستخدَم لعلاج الأرق."},{"f":"نمط: فرط النوم النفسي غير العضوي","b":"نعاس نهاري نوبي يدوم أكثر من شهر دون منفعة ظاهرة — وجود منفعة وسلوك ابتزاز يوجَّه للتمارض."}]},{"t":"الانتحار","cards":[{"f":"قاعدة ذهبية: محاولة الانتحار في الإسعاف","b":"كل محاولة انتحار تستلزم قصة نفسية مفصلة واستشارة نفسية حتى يثبت العكس — غسيل المعدة الروتيني بعد ساعتين غير مستطب."},{"f":"أنماط: الانتحار","b":"ثاني أشيع سبب وفاة بين المراهقين والشباب؛ تزداد أهميته عند المسنين؛ محاولات الإناث أكثر من الذكور."},{"f":"نقطة ذهبية: تعب وآلام جسدية مع تفكير بالانتحار بعد فقد","b":"اكتئاب مرضي — لا «حالة طبيعية»."}]},{"t":"الحداد وارتكاسات الفقد","cards":[{"f":"نمط: ما قد يحدث بعد الفقد","b":"اضطراب تأقلم، ارتكاس أسى، اضطراب شدة ما بعد الرض — «ضمور نفسي دماغي» ليس كيانًا طبيًا."},{"f":"فرّق: الحداد الطبيعي مقابل الاكتئاب المرضي","b":"الطبيعي: حزن يخف تدريجيًا مع حفظ تقدير الذات؛ المرضي: يأس ولوم ذات وشعور بعدم القيمة."},{"f":"نقطة ذهبية: اضطراب التأقلم (Adjustment disorder)","b":"أعراض عاطفية/سلوكية خلال 3 أشهر من ضاغط نفسي محدد."}]},{"t":"التمييز بين الأمراض النفسية والعضوية","cards":[{"f":"قاعدة ذهبية: اضطراب الوعي","b":"كل اضطراب وعي سببه عضوي حتى يثبت العكس — الأمراض النفسية الوظيفية تحافظ على وعي سليم."},{"f":"أنماط: علامات المنشأ العضوي في الهياج","b":"أول نوبة، لا سوابق نفسية، قصة إغماء/فقد وعي، أعراض عصبية — أما مقاومة فتح العينين فعلامة وظيفية."},{"f":"فرّق: الهذيان مقابل الخرف","b":"الهذيان: بداية حادة متقلبة مع اضطراب انتباه؛ الخرف: بداية تدريجية مترقية."}]},{"t":"الإسعاف النفسي ونوبات العنف","cards":[{"f":"نمط: الدواء الإسعافي في نوبة العنف","b":"مضاد ذهان سريع المفعول: هالوبيريدول أو كلوربرومازين عضلي ± بنزوديازبين — الكاربامازبين الفموي بطيء لا يصلح للإسعاف."},{"f":"نمط: مضادات الاكتئاب في الهياج الحاد","b":"بطيئة المفعول (أسابيع) — لا تصلح للسيطرة على العنف الحاد."},{"f":"نقطة ذهبية: مبدأ السلامة في نوبة العنف","b":"سلامة المريض والطاقم أولًا قبل أي تدخل — ثم التهدئة اللفظية قبل الدوائية."}]},{"t":"مواضيع متفرقة","cards":[{"f":"نمط: أشيع عرض عبر الأمراض النفسية","b":"القلق والخوف — يشاهَدان في الاكتئاب والوسواس وPTSD والرهابات؛ التوهم والهلوسات خاصة بالذهانية."},{"f":"نقطة ذهبية: التسمم بالفوسفور العضوية (Organophosphates)","b":"متلازمة كولينرجية: تضيق حدقة (ميوزيس) لا توسعها + تعرق + تقلصات حزمية عضلية."},{"f":"فرّق: الرهاب مقابل التوهم والهلوسات","b":"الرهاب خاص باضطرابات القلق الرهابية؛ التوهم والهلوسات خاصة بالاضطرابات الذهانية."}]}]},{"s":"الرثوية","topics":[{"t":"التظاهرات والفحص السريري","cards":[{"f":"قاعدة ذهبية: التهاب مفصل وحيد حاد","b":"كل التهاب مفصل وحيد حاد يُبزَل دائمًا حتى يثبت العكس — لاستبعاد الخمج والبلورات."},{"f":"فرّق: ألم الظهر الالتهابي مقابل الميكانيكي","b":"الالتهابي: يزداد بالراحة ويخف بالحركة + يبوسة صباحية > ساعة + أعراض بنيوية؛ الميكانيكي: يزداد بالحركة ويخف بالراحة والدفء دون انتشار عصبي."},{"f":"أنماط: علامات الالتهاب المفصلي","b":"تورم واحمرار وحرارة ويبوسة صباحية مديدة — الفرقعة المفصلية صفة ميكانيكية تنكسية لا التهابية."},{"f":"أنماط: العلامات الحمراء لألم الظهر","b":"ستيروئيدات مديدة، نقص وزن، خباثة/نقائل، ألم مستمر صباحًا ومساءً، قصة سل — العمر 20–50 ليس علامة حمراء."},{"f":"نقطة ذهبية: الأضداد في الأمراض الرثوية","b":"anti-CCP نوعي للرثياني؛ anti-dsDNA يراقب فعالية الذئبة؛ anti-Sm نوعي للذئبة — أما ANA فمسح تشخيصي لا يراقب الفعالية."},{"f":"نمط: الـCRP في الأمراض الرثوية","b":"يرتفع في الرثياني والتهاب الأوعية والنقرس والخمج — طبيعي عادة في الذئبة الفعالة (ارتفاعه يوجَّه لإنتان مرافق)."},{"f":"نقطة ذهبية: مرفق التنس (Tennis elbow)","b":"ألم الجهة الوحشية للمرفق يزداد بالبسط الفاعل للمعصم — مرفق الغولف يصيب الجهة الأنسية."},{"f":"نمط: اعتلال عضلي حزامي قريب","b":"صعوبة النهوض من القرفصاء ورفع اليدين: ألم عضلات روماتزمي، كوشينغ، ستاتينات، أخماج فيروسية، تلين عظام — لا فرط البوتاسيوم ولا الكالسيتونين."},{"f":"نمط: الحمامى العقدة (Erythema nodosum)","b":"تترافق مع: داء كرون، ساركوئيد، خمج عقديات، سل — لا الداء الرثياني."},{"f":"فرّق: التهاب المفصل الوحيد الحاد — سرعة البدء","b":"النقرس: بدء سريع خلال ساعات؛ التدرن المفصلي: تطور بطيء؛ إسهال مائي سابق: التهاب مفصل ارتكاسي."},{"f":"نمط: سرعة التثفل (ESR) في الفصال العظمي","b":"طبيعية عادة — ارتفاعها يوجَّه لسبب التهابي آخر."},{"f":"من سؤال حقيقي: طفل بألم عند ارتكاز العضلة مربعة الرؤوس بعد الجهد واستقصاءات سوية","b":"ألم النمو — لا علامات التهابية جهازية أو مخبرية."}]},{"t":"أسس تدبير الاضطرابات العضلية الهيكلية","cards":[{"f":"نمط: أدوية ألم أسفل الظهر الميكانيكي","b":"مرخيات عضلية، تمارين استرخاء، مسكنات/مضادات التهاب — الميتوتركسات لا دور له."},{"f":"نقطة ذهبية: الراحة في ألم الظهر الحاد","b":"الراحة المطلقة المديدة غير مستحبة — الحركة المبكرة والتمارين أفضل."},{"f":"نمط: الخط الدوائي الأول لألم الظهر الميكانيكي","b":"مضادات الالتهاب غير الستيروئيدية (NSAIDs)."}]},{"t":"أمراض العظام","cards":[{"f":"فرّق: تلين العظام مقابل هشاشة العظام مخبريًا","b":"التلين: فوسفاتاز قلوية مرتفعة + فوسفور منخفض + PTH مرتفع (فرط دريقات ثانوي) + نقص فيتامين D؛ الهشاشة: فوسفاتاز قلوية طبيعية."},{"f":"أنماط: عوامل خطورة وهن العظام (Osteoporosis)","b":"ستيروئيدات، فقد إستروجين (إياس مبكر)، أمراض التهابية مزمنة، تدخين، فرط درق، كوشينغ — زيادة الوزن واقية، وقصور الدريقات ليس عامل خطورة."},{"f":"من سؤال حقيقي: مسنة فقدت 5 سم من طولها مع حدب خفيف ومخبر سوي","b":"كسور انضغاطية فقرية صامتة بتخلخل العظام."}]},{"t":"أمراض النسيج الضام","cards":[{"f":"نقطة ذهبية: الذئبة الحمامية الجهازية (SLE)","b":"شابة بالتهاب مفاصل غير مخرب + طفح فراشة يعف عن الطية الشفوية الأنفية + حساسية ضياء؛ ANA إيجابي بمعظم الحالات وanti-dsDNA للإصابة الشديدة."},{"f":"فرّق: التهاب مفاصل الذئبة مقابل الرثياني","b":"الذئبة: غير مشوه وغير مخرب؛ الرثياني: مخرب تآكلي."},{"f":"نمط: المتممة في الذئبة الفعالة","b":"تنخفض C3 وC4 بالمرض الفعال (استهلاك بالمعقدات المناعية) — ارتفاعها عبارة خاطئة."},{"f":"نقطة ذهبية: ظاهرة رينو (Raynaud)","b":"شحوب ثم ازرقاق ثم احمرار في الأصابع عند التعرض للبرد."},{"f":"نمط: داء جوغرن (Sjögren) والمفاصل","b":"التهابه المفصلي غير مخرب عادة — بخلاف الرثياني والنقرس."},{"f":"قاعدة ذهبية: ذئبة مع قصور كلوي","b":"كل ذئبة حمامية مع قصور كلوي تُحال لأخصائي الرثوية حتى يثبت العكس — اشتباه التهاب كلوبة ذئبية."}]},{"t":"التهاب المفاصل مجهول السبب عند اليفعان","cards":[{"f":"نقطة ذهبية: التهاب مفاصل الحمى الرثوية","b":"مهاجر يشفى خلال 1–2 أسبوع دون تخريب أو تشوه — من عقابيلها إصابة الصمامات القلبية ورقص سيدنهام."},{"f":"أنماط: معايير جونز الكبرى للحمى الرثوية","b":"التهاب قلب شامل، رقص سيدنهام، حمامى هامشية، التهاب مفاصل، عقيدات تحت جلد — ارتفاع ASLO دليل خمج عقدي سابق (داعم) لا معيار كبير."},{"f":"نمط: معايير جونز الصغروية","b":"تطاول PR معيار صغروي — نقص الصفيحات ليس من المعايير."}]},{"t":"التهاب المفصل المحدث بالبلورات","cards":[{"f":"قاعدة ذهبية: خافضات حمض البول في هجمة النقرس الحادة","b":"لا يُبدَأ بخافض حمض البول أثناء الهجمة الحادة حتى يثبت العكس — البدء قد يفاقمها؛ علاج الهجمة: كولشيسين (Colchicine)."},{"f":"نقطة ذهبية: تشخيص النقرس (Gout)","b":"رؤية بلورات حمض البول داخل البالعات بالسائل المفصلي مشخصة — وحمض البول قد يكون طبيعيًا أثناء الهجمة فلا ينفيها."},{"f":"فرّق: النقرس مقابل النقرس الكاذب","b":"النقرس: المشطي السلامي الأول لإبهام القدم؛ الكاذب (بيروفوسفات الكلسيوم): ركبة/معصم/كتف + تكلس غضروفي شعاعيًا."}]},{"t":"التهابات الأوعية","cards":[{"f":"نقطة ذهبية: التهاب الشريان الصدغي (Giant cell arteritis)","b":"مسنة + فقدان رؤية مفاجئ + صداع صدغي نابض + عرج فك + سرعة تثفل مرتفعة جدًا."},{"f":"نقطة ذهبية: داء بهجت (Behçet)","b":"قلاع فموي مؤلم ناكس (>3 مرات سنويًا) + قلاع تناسلي + فحص عين دوري + اختبار بثرة قد يكون إيجابيًا — يصيب الأوعية بكل أحجامها."},{"f":"نمط: فرفرية هينوخ-شونلاين","b":"نزف هضمي وألم بطني وألم مفصلي والتهاب كبب وكلية — ارتفاع الضغط ليس شائعًا."}]},{"t":"التهابات المفاصل الفقار سلبي المصل","cards":[{"f":"نقطة ذهبية: التهاب الفقار المقسط (Ankylosing spondylitis)","b":"شاب بألم إلية يخف بالحركة + يبوسة صباحية > ساعة + التهاب مرتكزات (وتر أشيل)؛ HLA-B27 إيجابي؛ إصابة فقرات تصاعدية من الأسفل للأعلى."},{"f":"فرّق: سلبي المصل مقابل الرثياني","b":"سلبي المصل: RF سلبي ولا عقيدات تحت جلد — العقيدات للداء الرثياني؛ والميتوتركسات لا يوقف التطور الفقري."},{"f":"نمط: المفاصل بين السلامية البعيدة (DIP)","b":"إصابتها سمة التهاب المفاصل الصدافي (مع إصابة الأظافر) — الرثياني يجنبها."}]},{"t":"خمج العظم والمفصل","cards":[{"f":"نقطة ذهبية: التهاب المفصل الخمجي (Septic arthritis)","b":"أشيع مسبب: العنقوديات المذهبة بكل الأعمار؛ السكري عامل خطورة؛ السائل: كريات بيض مرتفعة على حساب العدلات."},{"f":"قاعدة ذهبية: التهاب مفصل وحيد حاد حار مؤلم","b":"كل التهاب مفصل وحيد حاد حار مؤلم خمج حتى يثبت العكس — البزل إسعافي لا يُؤجَّل."},{"f":"نقطة ذهبية: التهاب العظم والنقي (Osteomyelitis) عند الأطفال","b":"أشيع مسبب العنقوديات المذهبة — يصيب مشاش العظام الطويلة."}]},{"t":"الداء الروماتوئيدي","cards":[{"f":"نقطة ذهبية: الداء الرثياني (Rheumatoid arthritis)","b":"التهاب عديد متناظر مخرب (تآكلي) يصيب المعصمين وبين السلاميات القريبة — يجنب البعيدة والعمود الظهري القطني."},{"f":"أنماط: منبئات سوء الإنذار في الرثياني","b":"عجز وظيفي منذ البدء، الجنس المؤنث، إصابة مشطية سلامية القدمين، التدخين، تآكلات شعاعية مبكرة، إيجابية RF."},{"f":"فرّق: الإصابة العينية في الرثياني","b":"صلبوية: التهاب صلبة/ظاهر صلبة (مهدد للبصر) — أما التهاب العنبية/الزجاجي فللفقار المقسط وبهجت والساركوئيد لا الرثياني."},{"f":"نمط: قبل بدء مثبطات المناعة","b":"تعداد عام وصيغة، خمائر ناقلات الأمين، تحري السل الكامن، التهاب كبد فيروسي — اختبار شيرمر غير مطلوب."},{"f":"نقطة ذهبية: مراقبة فعالية الرثياني","b":"سرعة التثفل وCRP تعكسان الفعالية الالتهابية — أما RF وanti-CCP فتشخيصية لا تراقب الفعالية."},{"f":"نمط: معايير تشخيص الداء الرثياني","b":"إصابة مفاصل صغيرة، مدة أعراض 6 أسابيع فأكثر، RF إيجابي، ارتفاع ESR/CRP — مدة أقل من أسبوعين تنفي الطابع المزمن."}]},{"t":"الفصال العظمي","cards":[{"f":"فرّق: الفصال العظمي (Osteoarthritis)","b":"يبوسة صباحية قصيرة (<30 دقيقة)، ألم يزداد بالحركة ويخف بالراحة، عقد هيبردن (بعيدة) وبوشارد (قريبة)، فرقعة عظمية — ليس مرضًا مناعيًا ذاتيًا."},{"f":"أنماط: عوامل خطورة الفصال العظمي","b":"تقدم العمر، البدانة، إجهاد مفصلي متكرر، انزلاق مشاشة رأس الفخذ — الرياضة دون رض مفصلي مهم ليست عامل خطورة."},{"f":"نمط: الستيروئيدات الجهازية والداء التنكسي","b":"لا دور لها في الداء التنكسي — بخلاف الرثياني والذئبة والتهاب الشريان الصدغي."}]}]},{"s":"الجلدية","topics":[{"t":"الصداف","cards":[{"f":"ما هي الصورة السريرية النموذجية للصداف اللويحي (plaque psoriasis)؟","b":"لويحات حمامية حمراء مغطاة بوسوف فضية (silvery scales) على السطوح الباسطة: المرفقين والركبتين وفروة الرأس."},{"f":"ظاهرة كوبنر (Koebner): ما هي وأين تُشاهد؟","b":"ظهور آفات جديدة مكان الرض الجلدي (خدش أو جرح أو حرق) — نمطية في الصداف، وتُشاهد أيضًا في الحزاز المسطح والبهق."},{"f":"فرّق: ظاهرة كوبنر × ظاهرة نيكولسكي (Nikolsky).","b":"كوبنر = آفات جديدة مكان الرض (الصداف والحزاز المسطح)؛ نيكولسكي = انسلاخ البشرة بالضغط الجانبي (الفقاع الشائع)."},{"f":"من سؤال حقيقي: أي دواء قد يُحدث الصداف أو يُفاقمه؟","b":"مضادات الملاريا (chloroquine) — ليست من علاجات الصداف المنتشر بل من مهيّجاته المعروفة."},{"f":"ما دور نظير فيتامين D الموضعي (كالسيتريول calcitriol) في الصداف؟","b":"يُبطئ تكاثر الخلايا الكيراتينية ويُعدّل تمايزها في الصداف الشائع، وغالبًا يُشارك مع كورتيكوستيروئيد موضعي."},{"f":"قاعدة ذهبية: كيف يؤثر الضياء (الشمس) في الصداف؟","b":"الصداف يتحسّن بالشمس والأشعة فوق البنفسجية (أساس المعالجة الضوئية UVB وPUVA) — وهو الاستثناء بين الأمراض الجلدية المتسوئة بالضياء."}]},{"t":"الحزاز المسطح","cards":[{"f":"ما هي قاعدة 4P في الحزاز المسطح (lichen planus)؟","b":"حطاطات بنفسجية (purple)، حطاطية (papular)، حاكة (pruritic)، مضلعة مسطحة القمة (polygonal) — لماعة على الرسغين والساعدين والساقين."},{"f":"ما هي خطوط ويكهام (Wickham's striae) وأين تُرى؟","b":"شبكة بيضاء دقيقة على مخاطية الخد (وعلى سطح الحطاطات) — علامة مميزة للحزاز المسطح."},{"f":"فرّق: الحزاز المسطح × الصداف.","b":"الحزاز: حطاطات بنفسجية حاكة + خطوط ويكهام؛ الصداف: لويحات حمراء بوسوف فضية على السطوح الباسطة + كوبنر."}]},{"t":"النخاليات","cards":[{"f":"ما هي بقعة الطليعة (herald patch) وفي أي مرض تُشاهد؟","b":"لطخة بيضوية وحيدة أكبر حجمًا تسبق الطفح المنتشر بأيام — مميزة للنخالية الوردية (pityriasis rosea)."},{"f":"هل النخالية الوردية معدية؟ وما سيرها الطبيعي؟","b":"غير معدية بالتماس؛ مرض محدد لذاته يشفى عفويًا خلال 6–8 أسابيع."},{"f":"ما الفيروسان الأكثر اتهامًا في النخالية الوردية؟","b":"الفيروسان الحلئيان البشريان السادس والسابع (HHV-6 وHHV-7)."}]},{"t":"العد الشائع (حب الشباب)","cards":[{"f":"ما هو الأثر الجانبي الأشيع للريتينوئيدات (الإيزوتريتينوئين isotretinoin)؟","b":"جفاف الجلد والمخاطيات — تشقق الشفاه هو الأشيع."},{"f":"ما أهم مراقبة مخبرية عند إعطاء الإيزوتريتينوئين الجهازي؟","b":"خمائر الكبد (transaminases) — الدواء سام للكبد؛ وتُراقب الشحوم، مع اختبار حمل لأنه مشوّه أجنة قوي (teratogen)."},{"f":"ما هي آفات العد الشائع؟ وأي آفة ليست منها؟","b":"زوان (مغلق ومفتوح)، حطاطة، بثرة، عقيدة أو كيسة — الحويصل (vesicle) ليس من آفات العد إطلاقًا."}]},{"t":"العد الوردي","cards":[{"f":"فرّق: العد الوردي (rosacea) × العد الشائع.","b":"الوردي: بلا زوان، مع توسع شعيرات (telangiectasia) واحمرار سهل، يصيب البالغين فوق 30 سنة؛ الشائع: زوان وحطاطات وبثرات عند المراهقين."},{"f":"هل الستيروئيدات الموضعية من علاج العد الوردي؟","b":"لا — بل تفاقمه؛ الاستخدام المطوّل على الوجه قد يُحدث آفات شبيهة بالوردية."},{"f":"ما هو الأنف الضخامي (rhinophyma)؟","b":"فرط تصنع جلد الأنف وتضخمه — من تظاهرات العد الوردي المتقدم."}]},{"t":"الأكزيما والتهاب الجلد","cards":[{"f":"ما آلية إكزيما التماس الأرجي؟ وكيف تُكشف؟","b":"فرط تحسس آجل بتواسط خلوي (النمط الرابع) — يُكشف باختبار الرقعة (patch test)."},{"f":"حويصلات دقيقة حاكة بشدة على جانبي الأصابع — التشخيص؟","b":"إكزيما عسر التعرق (dyshidrotic eczema / pompholyx)."},{"f":"أي إكزيما تتميز بجفاف الجلد لا بزيادة الزهم؟","b":"التهاب الجلد التأتبي (atopic dermatitis) — زيادة الزهم تُشاهد في الالتهاب الدهني (المثي) والعد الشائع والعد الوردي."}]},{"t":"الشرى","cards":[{"f":"ما هو الطفح المميز للشرى (urticaria)؟","b":"انتبارات (wheals) حاكة متنقلة عابرة — كل انتبار يزول خلال أقل من 24 ساعة."},{"f":"قاعدة ذهبية: انتبار ثابت أكثر من 24 ساعة، مؤلم، يترك كدمة — ما هو؟","b":"التهاب الأوعية الشروي (urticarial vasculitis) حتى يثبت العكس — وليس شرى بسيطًا."},{"f":"ما هي السمة الحسية الأساسية لانتبارات الشرى؟","b":"حاكة بشدة (pruritic)."}]},{"t":"الأمراض المناعية الفقاعية","cards":[{"f":"فرّق نسيجيًا: الفقاع الشائع (pemphigus vulgaris) × الفقاعاني الفقاعي (bullous pemphigoid).","b":"الشائع: انفكاك داخل البشرة فوق الطبقة القاعدية + IgG شبكي بين الخلايا (fishnet)؛ الفقاعاني: فقاعات متوترة تحت بشروية + IgG وC3 خطي على الغشاء القاعدي."},{"f":"انسلاخات فموية مؤلمة مزمنة + علامة نيكولسكي إيجابية — التشخيص والعلاج؟","b":"الفقاع الشائع — العلاج بالبريدنيزولون الجهازي (كورتيكوستيروئيد جهازي)."},{"f":"فقاعات متوترة تحت بشروية عند مسن دون إصابة فموية بارزة — التشخيص الأرجح؟","b":"الفقاعاني الفقاعي (bullous pemphigoid)."}]},{"t":"أمراض النسج الضامة الجلدية","cards":[{"f":"هل تتحول الذئبة الحمامية القرصية (DLE) غالبًا إلى ذئبة جهازية؟","b":"لا — نسبة صغيرة فقط (نحو 5%) من المرضى تتطور لديهم ذئبة جهازية."},{"f":"ما نسبة إيجابية ANA في الذأب الحمامي الجهازي؟","b":"إيجابي بعيارات مرتفعة في نحو 95–99% من المرضى."},{"f":"ما هو الضد النوعي لصلابة الجلد الجهازية المنتشرة (diffuse systemic sclerosis)؟","b":"Anti-Scl-70 (المضاد لتوبوإيزوميراز I) — ينذر بإصابة الأعضاء الداخلية الخطيرة."}]},{"t":"الحمامى العقدة","cards":[{"f":"ما هي الصورة السريرية للحمامى العقدة (erythema nodosum)؟","b":"عقيدات حمامية مؤلمة على الوجه الأمامي للساقين — لا تتقرح أبدًا وتشفى دون أن تترك ندبة."},{"f":"ما هو أشيع مسبب للحمامى العقدة؟","b":"التهاب البلعوم بالعقديات (Streptococcus) — التهاب سبلة حاجزي تالٍ للخمج."},{"f":"قاعدة ذهبية: عقيدات متقرحة على الساقين — هل هي حمامى عقدة؟","b":"لا — التقرح ينفي الحمامى العقدة ويوجّه نحو التهابات سبلة أخرى."}]},{"t":"الحمامى عديدة الأشكال","cards":[{"f":"ما هي الآفة المميزة للحمامى عديدة الأشكال (erythema multiforme)؟","b":"آفات هدفية (target lesions) نموذجية ثلاثية المناطق على اليدين والأطراف."},{"f":"ما هو أشيع مسبب للحمامى عديدة الأشكال؟","b":"فيروس الحلأ البسيط (HSV) — والأسيكلوفير الفموي يفيد وقائيًا في الحالات الناكسة المرتبطة بالهربس."},{"f":"أين تتوضع الحمامى عديدة الأشكال غالبًا؟","b":"على الأطراف (اليدين) — وليست أشد على الوجه."}]},{"t":"الأخماج البكتيرية الجلدية","cards":[{"f":"بمَ تتظاهر القوباء (impetigo)؟","b":"جلبات عسلية اللون (honey-colored crusts) على قاعدة حمامية — حول الفم والأنف عند الأطفال."},{"f":"لماذا يُعد الدمل (furuncle) في مثلث الوجه خطيرًا؟","b":"قد ينتشر الخمج عبر الأوردة الوجهية عديمة الصمامات إلى الجيب الكهفي مسببًا خثاره — اختلاط مهدد للحياة."},{"f":"ما هو العامل المسبب للحمرة (erysipelas)؟ وما صفتها السريرية؟","b":"العقديات الحالة للدم بيتا (المجموعة A) — لويحة التهابية محمرة محددة بدقة؛ نادرًا ما تسببها العنقوديات."}]},{"t":"الأخماج الفيروسية الجلدية","cards":[{"f":"حطاطات مقببة مسرّرة بلون الجلد عند طفل — التشخيص والسير؟","b":"المليساء المعدية (molluscum contagiosum) — تتراجع عفويًا خلال أشهر دون ندبة غالبًا."},{"f":"طفل بحمى واندفاع عديد الأشكال بأعمار مختلفة على الوجه والجذع — التشخيص؟","b":"الحماق (جدري الماء varicella): حطاطات وحويصلات وبثور وقشور معًا في آن واحد."},{"f":"ما هو العامل المسبب للثآليل التناسلية؟","b":"فيروس الورم الحليمي البشري (HPV) — الأنماط منخفضة الخطورة (6 و11)."},{"f":"ما هي سمة اندفاع الحلأ النطاقي (herpes zoster)؟","b":"حويصلات مؤلمة على مسار جلدي (dermatome) واحد لا تتجاوز الخط الناصف — تنشيط لفيروس VZV الكامن."},{"f":"ما هي بقع كوبليك (Koplik spots)؟","b":"بقع بيضاء صغيرة على مخاطية الخد تسبق طفح الحصبة (measles) — علامة باثوغمونية."},{"f":"ما هو العامل المسبب لداء اليد والقدم والفم؟","b":"فيروس كوكساكي A16 (Coxsackie A16)."}]},{"t":"الأخماج الفطرية","cards":[{"f":"كيف يُشخّص الخمج الفطري الجلدي مخبريًا؟","b":"بالفحص المباشر بـ KOH الذي يُظهر الخيوط الفطرية — التألق المناعي المباشر لا يُستخدم للفطور."},{"f":"لويحة رخوة مؤلمة ببثرات على فروة طفل مع سهولة انتزاع الشعر — التشخيص؟","b":"الشهدة (kerion) — استجابة مناعية شديدة من المضيف ضد الفطور الجلدية."},{"f":"ما هو أشيع مسبب فطري للمذح (intertrigo)؟","b":"المبيضات البيض (Candida albicans) — تنمو في الثنيات الرطبة الدافئة (تحت الثديين والمغبن)."},{"f":"ما هي سمة السعفة الحلقية (tinea corporis)؟","b":"آفة حلقية حاكة ذات حدود واضحة مع ميل للشفاء المركزي — أشيع مسبباتها الشعروية الحمراء (Trichophyton rubrum)."}]},{"t":"الليشمانيا الجلدية","cards":[{"f":"ما هو ناقل الليشمانيا الجلدية؟","b":"ذبابة الرمل (الفليبوتوم phlebotomus)."},{"f":"صِف السير السريري لليشمانيا الجلدية.","b":"حطاطة أو عقيدة غير مؤلمة على المناطق المكشوفة تتقرح تدريجيًا على مدى أسابيع إلى أشهر (قرحة الشرق) ثم تشفى بندبة."},{"f":"قاعدة ذهبية: قرحة جلدية مزمنة مؤلمة بشدة — هل هي ليشمانيا؟","b":"لا — الليشمانيا غير مؤلمة نمطيًا؛ الألم الشديد يوجّه لسبب آخر (كالدمل)."}]},{"t":"الجرب والقمل والطفيليات","cards":[{"f":"ما هي الصورة النموذجية للجرب (scabies)؟","b":"حكة ليلية شديدة مع آفات على المسافات بين الأصابع والرسغين والثنيات — يتجنب الوجه والرأس عند البالغين."},{"f":"متى يُشاهد الجرب النرويجي (المقشر)؟","b":"عند المثبطين مناعيًا والمسنين والمقعدين — لا يصادف لدى الأسوياء مناعيًا."},{"f":"أين يضع قمل الجسد بيوضه؟","b":"في درزات الملابس — التشخيص بفحص درزات الملابس بحثًا عن الصئبان والقمل."},{"f":"هل يُرى قمل الرأس بالعين المجردة؟","b":"نعم — القمل البالغ 1–3 ملم ويُرى بالعين المجردة؛ التشخيص بالرؤية المباشرة."}]},{"t":"الأمراض المنتقلة بالجنس","cards":[{"f":"ما هو العلاج المختار للإفرنجي (السفلس syphilis)؟","b":"البنزاثين بنسلين (حقنة عضلية وحيدة طويلة المفعول) — فعال في كل مراحل الإفرنجي."},{"f":"فرّق: القرح السفلسي (chancre) × القريح (chancroid).","b":"السفلسي: غير مؤلم وجاسئ القاعدة؛ القريح: مؤلم بشدة."},{"f":"أيٌّ مما يلي ليس مرضًا منتقلًا بالجنس: السفلس، السيلان، القوباء، القريح؟","b":"القوباء (impetigo) — خمج جلدي سطحي عند الأطفال ينتقل بالتماس العادي."}]},{"t":"داء بهجت","cards":[{"f":"ما هو الثالوث السريري لداء بهجت (Behçet)؟","b":"قلاع فموي ناكس + تقرحات تناسلية + التهاب عنبية عيني (مع آفات عدّية الشكل على الجلد)."},{"f":"ما هي طبيعة داء بهجت المرضية؟","b":"التهاب أوعية جهازي (systemic vasculitis)."},{"f":"شاب بقلاع فموي ناكس أكثر من 3 مرات سنويًا + قرحة صفنية — التشخيص؟","b":"داء بهجت — التقرح الفموي التناسلي الناكس يثيره بقوة."}]},{"t":"الأورام الجلدية","cards":[{"f":"ما هو أشيع ورم جلدي خبيث؟ وما إنذاره؟","b":"السرطانة قاعدية الخلايا (BCC) — أفضلها إنذارًا؛ تنمو ببطء وتكاد لا تعطي انتقالات بعيدة."},{"f":"ما هو أشيع توضع للسرطانة قاعدية الخلايا؟","b":"الوجه (الأنف والجفون والشفة العليا) — مناطق التعرض الشمسي المزمن."},{"f":"أي آفة تُعد ما قبل سرطانية؟ وماذا قد تتحول؟","b":"التقران السفعي (actinic keratosis) — قد يتحول إلى سرطانة شائكة الخلايا (SCC)."},{"f":"تقرح مزمن على الشفة السفلية عند فلاح مسن لا يستجيب للموضعيات — التشخيص؟","b":"سرطانة شائكة الخلايا (SCC) — آفات الشفة والأذن عالية خطورة النقائل."},{"f":"ما هو أسوأ سرطانات الجلد إنذارًا؟","b":"الميلانوما (melanoma) الخبيثة."},{"f":"ما هي قاعدة ABCDE في تقييم الشامات المشبوهة؟","b":"عدم التناظر (Asymmetry)، اضطراب الحدود (Border)، تعدد الألوان (Color)، القطر أكبر من 6 مم (Diameter)، التطور والتغير (Evolution)."}]},{"t":"أمراض الشعر والأظافر","cards":[{"f":"لماذا تُحفظ المنطقة القفوية في الحاصة الاندروجينية؟","b":"أشعارها مقاومة للأندروجين (DHT) — ومنها تُؤخذ طعوم زراعة الشعر."},{"f":"هل تترك الثعلبة (الحاصة البقعية alopecia areata) ندبة؟","b":"لا — حاصة غير ندبية قد تشفى عفويًا؛ الخلايا الجذعية الجريبية لا تُستهدف."},{"f":"أي أمراض فروة الرأس التالية لا تسبب حاصة ندبية؟","b":"سعفة الرأس (سعفة جازة) — الشعر ينمو مجددًا بعد علاج الخمج الفطري."}]},{"t":"اضطرابات التصبغ","cards":[{"f":"لطخات بيضاء متناظرة غير متقشرة + قصة داء غريفز — التشخيص؟","b":"البهق (vitiligo) — فقدان صباغ مناعي ذاتي يترافق مع أمراض الدرق المناعية."},{"f":"ما هي المناطق الأكثر مقاومة لعلاج البهق؟","b":"نهايات الأطراف (الأصابع) والشفتان — الأكثر مقاومة للعلاج."},{"f":"هل الكلف (melasma) يصيب الرجال؟","b":"نعم — أقل شيوعًا لكنه يصيبهم؛ الشمس والحمل وموانع الحمل من عوامله."},{"f":"فرّق: البهق × النخالية المبرقشة.","b":"البهق: بقع زائلة الصباغ غير متقشرة؛ المبرقشة (tinea versicolor): بقع متقشرة فطرية."}]},{"t":"مواضيع متفرقة","cards":[{"f":"كيف يميّز الفحص بالشفوفية (diascopy) بين الحمامى والفرفرية؟","b":"الحمامى (احتقان وعائي) تختفي بالضغط بالشريحة؛ الفرفرية (نزف خارج وعائي) لا تختفي."},{"f":"أي مرض جلدي يتحسّن بالضياء بدل أن يسوء به؟","b":"الصداف — يتحسن بالشمس (أساس المعالجة الضوئية)."},{"f":"ما هي سمة طفح السفلس الثانوي من حيث الحكة؟","b":"غير حاكٍ نمطيًا — بما فيه طفح الراحتين والأخمصين."},{"f":"هل تترك النخالية الوردية ندبات؟","b":"لا — تشفى عفويًا خلال 6–8 أسابيع دون ندبة."}]}]},{"s":"الأذنية","topics":[{"t":"أمراض الأذن والسمعيات","cards":[{"f":"ما هو تدبير تصلب الركابة (otosclerosis)؟","b":"نقص سمع توصيلي بتثبت قاعدة الركابة — التدبير بالسماعة الطبية أو جراحيًا (stapedectomy)."},{"f":"ما هو التدبير الأمثل لالتهاب الأذن الوسطى المصلي عند الأطفال؟","b":"المراقبة الدورية لمدة 3 أشهر أولًا — معظم الحالات تشفى عفويًا؛ الصادات لا تفيد."},{"f":"صِف التهاب الأذن الخارجية النخري (الخبيث).","b":"يصيب السكريين ومضعفي المناعة؛ العامل العصيات الزرق (Pseudomonas) — صادات وريدية لأسابيع؛ قد يصيب العصب الوجهي ثم IX وX وXI."},{"f":"علامة خطر: بحة صوت مستمرة أكثر من 3 أسابيع — ما الاشتباه؟","b":"خباثة حنجرية حتى يثبت العكس."},{"f":"علامة خطر: نقص سمع حسي عصبي أحادي الجانب — ما الاشتباه؟","b":"ورم العصب السمعي (acoustic neuroma / vestibular schwannoma) حتى يثبت العكس."},{"f":"علامة خطر: سيلان أذني كريه الرائحة مزمن — ما الاشتباه؟","b":"ورم كولستريني (cholesteatoma)."},{"f":"ماذا يُظهر اختبارا رينه وويبر في نقص السمع التوصيلي؟","b":"رينه سالب (التوصيل العظمي أفضل من الهوائي) وويبر يتحوّل نحو الجهة المصابة."},{"f":"ما هو علاج الورم الكولستريني؟","b":"جراحي — لا يشفى بالصادات."},{"f":"ما هي علامة التهاب الخشاء الحاد (mastoiditis)؟","b":"تورم مؤلم خلف الصيوان يزيحه للأمام والأسفل — اختلاط لالتهاب الأذن الوسطى الحاد."},{"f":"نقص السمع الحسي العصبي المفاجئ — كيف يُصنّف؟","b":"حالة إسعافية أذنية."},{"f":"صِف شيخوخة السمع (presbycusis).","b":"نقص سمع حسي عصبي ثنائي متناظر يبدأ بالتواترات العالية عند المسنين."},{"f":"ما هي علامة الرض الصوتي المزمن في تخطيط السمع؟","b":"شق مميز عند التواتر 4kHz."},{"f":"اذكر أدوية سامة للأذن (ototoxic).","b":"الأمينوغليكوزيدات، الفوروسيميد، السيسبلاتين."},{"f":"ما مصير ثقب غشاء الطبل الرضي؟","b":"يشفى عفويًا غالبًا خلال أسابيع — مع إبقاء الأذن جافة."},{"f":"ما هو أشيع عامل لالتهاب الأذن الوسطى الحاد عند الأطفال؟","b":"المكورات الرئوية (Streptococcus pneumoniae)."},{"f":"ما هي علامة التهاب الأذن الخارجية الحاد (أذن السباح)؟","b":"ألم يزداد بشدّ الصيوان والضغط على الزنمة."},{"f":"فرّق: ألم التهاب الأذن الخارجية × ألم التهاب الوسطى.","b":"الخارجية: يزداد بشد الصيوان؛ الوسطى: لا يتأثر بشد الصيوان."},{"f":"ما هو أذن الطائرة (barotrauma)؟","b":"ألم واحتقان أذني أثناء الهبوط بسبب تعذر معادلة الضغط عبر نفير أوستاش."},{"f":"طنين نابض متزامن مع النبض — ما التوجّه؟","b":"سبب وعائي (ورم كبي glomus أو تشوه شرياني وريدي)."},{"f":"صِف التهاب التيه الفيروسي (labyrinthitis).","b":"دوار شديد + نقص سمع حسي عصبي + طنين — يلي خمجًا تنفسيًا علويًا فيروسيًا."}]},{"t":"أمراض الأذن العصبية والدوار والعصب الوجهي","cards":[{"f":"ما هو الثالوث السريري لداء منيير (Ménière)؟","b":"دوار نوبي + طنين منخفض التواتر + نقص سمع حسي عصبي متذبذب يصيب التواترات المنخفضة — سببه استسقاء اللمف الباطن."},{"f":"فرّق: التهاب العصب الدهليزي × داء منيير.","b":"الدهليزي (vestibular neuritis): دوار حاد شديد دون نقص سمع — يصيب الفرع الدهليزي فقط؛ منيير: دوار + طنين + نقص سمع متذبذب."},{"f":"ما هو أشيع سبب لشلل العصب الوجهي المحيطي؟","b":"شلل بل (Bell's palsy)."},{"f":"ما هو داء رامزي هانت (Ramsay Hunt)؟","b":"حلأ نطاقي أذني (حويصلات في الصيوان) + شلل العصب الوجهي المحيطي."}]},{"t":"أمراض الأنف والجيوب الأنفية","cards":[{"f":"ما هو الاستقصاء الشعاعي المعتمد لالتهاب الجيوب المزمن؟","b":"الطبقي المحوري — الأمواج فوق الصوتية (الإيكو) لا دور لها."},{"f":"ما هي أشيع اختلاطات التهاب الجيوب الأنفية؟","b":"الاختلاطات الحجاجية — لقرب الجيب الغربالي من الحجاج."},{"f":"ما هو ورم بوت (Pott's puffy tumor)؟","b":"خراج تحت سمحاق الجبهة — اختلاط لالتهاب الجيب الجبهي."},{"f":"هل يشيع التهاب الجيوب المزمن عند الأطفال؟","b":"لا — هو مرض البالغين أساسًا."},{"f":"ما هي أعراض ضخامة القرينات الأنفية؟ وأي عرض ليس منها؟","b":"انسداد الأنف والصداع والرعاف — السيلان القيحي ليس منها (يدل على خمج جرثومي)."},{"f":"أشيع منشأ للرعاف (90%)؟ وما أول تدبير؟","b":"أمامي من ضفيرة كيسلباخ (Kiesselbach) في الحاجز الأمامي — أول تدبير: الضغط المباشر."},{"f":"صِف التهاب الأنف التحسسي.","b":"عطاس وحكة وسيلان أنفي مائي ثنائي الجانب + حكة عينية."},{"f":"ما هو ثالوث سامتر (Samter)؟","b":"بوليبات أنفية + ربو + عدم تحمل الأسبرين."},{"f":"ما هي سمة ألم التهاب الجيب الفكي؟","b":"ألم خدي يزداد بالانحناء للأمام."},{"f":"ما دور الكورتيزون في التهاب الجيوب المزمن؟","b":"جزء أساسي من التدبير — موضعيًا أو جهازيًا."},{"f":"طفل بسيلان أنفي قيحي أحادي الجانب كريه الرائحة — التشخيص؟","b":"جسم أجنبي أنفي."},{"f":"أي الجيوب موجودة منذ الولادة؟","b":"الغربالي والفكي — الجيب الجبهي يتطور بعد عمر سنتين."},{"f":"فقد الشم التدريجي عند بالغ — ما أشيع سبب؟","b":"البوليبات الأنفية المنتشرة."}]},{"t":"أورام الأنف والبلعوم الأنفي والرعاف","cards":[{"f":"ما هي أكثر علامة توجّه لسرطان البلعوم الأنفي؟","b":"ضخامة العقد اللمفاوية الرقبية (خلف زاوية الفك) — انتشار لمفاوي مبكر غزير."},{"f":"كتلة تحت زاوية الفك + نقص سمع توصيلي أحادي عند بالغ — التشخيص؟","b":"ورم البلعوم الأنفي — يمتد لفوهة نفير أوستاش فيسبب انسداده."},{"f":"من أين ينشأ الرعاف الخلفي؟","b":"من الشريان الوتدي الحنكي — أقل شيوعًا وأخطر، يصيب المسنين غالبًا."},{"f":"مراهق ذكر برعاف متكرر وانسداد أنفي أحادي — التشخيص؟","b":"الورم الليفي الوعائي البلعومي الأنفي (juvenile nasopharyngeal angiofibroma)."},{"f":"ما هي سمة الورم الحليمي المقلوب (inverted papilloma)؟","b":"ورم أنفي وحيد الجانب قد يتحول إلى سرطانة شائكة الخلايا."},{"f":"ما الفيروس المرتبط بسرطان البلعوم الأنفي؟","b":"فيروس إبشتاين-بار (EBV)."},{"f":"كي نترات الفضة — لأي رعاف يفيد؟","b":"يسيطر على الرعاف الأمامي لا الخلفي."}]},{"t":"أمراض الفم والبلعوم واللوزتين","cards":[{"f":"ما هو الاستطباب المطلق لاستئصال اللوزات؟","b":"الشك باللمفوما — ضخامة لوزة وحيدة الجانب مشبوهة بالخباثة."},{"f":"أي الطلاوة أسوأ إنذارًا: البيضاء أم الحمراء؟","b":"الحمراء (erythroplakia) — نسبة تحولها للخباثة أعلى بكثير."},{"f":"الضزز (trismus) أشيع ما يُشاهد في أي حالة؟","b":"خراج حول اللوزة (quinsy) — بسبب تهيج العضلة الجناحية الإنسية المجاورة."},{"f":"ما هو أشيع عامل جرثومي لالتهاب اللوزات الحاد؟","b":"العقديات الحالة للدم بيتا (المجموعة A) — الإشريكية الكولونية ليست منها."},{"f":"ما هي علامة خراج حول اللوزة؟","b":"تورم أحادي الجانب مع انحراف اللهاة للجهة المقابلة — اختلاط لالتهاب اللوزات."},{"f":"ما هي اختلاطات التهاب البلعوم بالعقديات؟","b":"الحمى الرثوية (rheumatic fever) والتهاب الكبب والكلية الحاد."},{"f":"لطخات بيضاء فموية تُكشط تاركة قاعدة نازفة — التشخيص؟","b":"السلاق الفموي (oral thrush) — بالمبيضات عند مثبطي المناعة أو بعد الصادات."}]},{"t":"أمراض وأورام الغدد اللعابية","cards":[{"f":"ما هي أشيع غدة تصاب بالحصيات اللعابية؟ ولماذا؟","b":"تحت الفكية — مفرزاتها مخاطية لزجة وقناة وارطون صاعدة ضد الجاذبية."},{"f":"لماذا حصيات الغدة النكفية أصعب تدبيرًا؟","b":"قناة ستينون ضيقة وملتوية وقريبة من فروع العصب الوجهي."},{"f":"صِف الورم المختلط السليم (pleomorphic adenoma).","b":"أشيع ورم نكفي — كتلة صلبة مفصصة ملساء بطيئة النمو، ذروة حدوثه في العقد الخامس."},{"f":"ما هي سمات ورم وارثين (Warthin)؟","b":"يصيب المدخنين، قد يكون ثنائي الجانب، يتوضع في الفص السفلي للنكفة."},{"f":"هل يكشف التصوير الشعاعي البسيط كل الحصيات اللعابية؟","b":"لا — بعض الحصيات غير ظليلة للأشعة (radiolucent) فيلزم الإيكو."},{"f":"ما هي متلازمة شوغرن (Sjögren)؟","b":"جفاف العين + جفاف الفم ± التهاب مفاصل رثياني."},{"f":"ما هي اختلاطات التهاب النكفة الوبائي (mumps)؟","b":"التهاب الخصية والتهاب البنكرياس والتهاب السحايا."},{"f":"كتلة نكفية + شلل العصب الوجهي — ما الدلالة؟","b":"علامة خباثة حتى يثبت العكس."}]},{"t":"أمراض الحنجرة واضطرابات الصوت والأورام","cards":[{"f":"تضيق تحت المزمار — صرير أم بحة؟","b":"صرير شهيقي وضيق تنفس دون بحة تُذكر — الحبال الصوتية سليمة."},{"f":"هل النمطان 6 و11 من HPV من عوامل سرطان الحنجرة؟","b":"لا — يسببان الورم الحليمي التنفسي الراجع؛ الأنماط عالية الخطورة (16 و18) هي المرتبطة بالتسرطن."},{"f":"جراحة ربط القناة الشريانية (PDA) تؤذي أي عصب حنجري راجع؟","b":"الأيسر فقط — يلتف حول القناة الشريانية، بينما الأيمن يلتف حول الشريان تحت الترقوة."},{"f":"ما هو الكروب (croup)؟","b":"التهاب حنجرة ورغامى فيروسي (نظير الإنفلونزا) عند الأطفال — سعال نباحي وصوت أجش وزلة شهيقية."},{"f":"التهاب لسان المزمار عند الأطفال — ما الممنوع؟","b":"حالة إسعافية (المستدمية النزلية) — يُمنع فحص البلعوم بخافض اللسان."},{"f":"قاعدة ذهبية: بحة صوت أكثر من 3 أسابيع عند مدخن — ما هو؟","b":"سرطان حنجرة حتى يثبت العكس."},{"f":"ما هي عقيدات الحبال الصوتية؟","b":"عقيدات ثنائية متناظرة عند مستعملي الصوت (معلمين ومغنين) تسبب بحة."},{"f":"ما هي سمة شلل الحبل الصوتي؟","b":"صوت مبحوح ضعيف مع خطر الشفط (الشرقة)."},{"f":"اذكر عاملًا مؤهبًا لسرطان الحنجرة غير التدخين.","b":"القلس المعدي البلعومي المزمن — والطلاوة الحنجرية آفة محتملة التسرطن."},{"f":"ما هو العامل الأول لسرطان الحنجرة؟","b":"التدخين بأشكاله."},{"f":"ما هو الاستقصاء الأهم لبحة صوتية مستمرة؟","b":"تنظير الحنجرة المباشر."}]},{"t":"إسعافات مجرى الهواء وكتل العنق","cards":[{"f":"أين يُجرى خزع الرغامي الإسعافي؟ وأين المبرمج؟","b":"الإسعافي: عبر الغشاء الدرقي الحلقي؛ المبرمج: بين الحلقتين الرغاميتين الثانية والثالثة."},{"f":"ما هو اختلاط آني لخزع الرغامي؟ وما المتأخر؟","b":"الآني: الريح الصدرية (خصوصًا عند الأطفال)؛ المتأخر: الناسور الرغامي المريئي."},{"f":"اذكر علامات الخباثة في الدرق.","b":"عقدة باردة على الومضان، عقد رقبية أكبر من 3 سم، عسرة بلع، صرير حنجري — عديدة العقد ليست علامة خباثة."},{"f":"هل داء غريف من مؤهبات خباثة الدرق؟","b":"لا — يرتبط بفرط نشاط حميد."},{"f":"قاعدة ذهبية: كتلة عنقية صلبة عند بالغ مدخن فوق 40 سنة — ما هي؟","b":"خباثة حتى يثبت العكس."},{"f":"كيسة خط الوسط في العنق تتحرك مع البلع ومدّ اللسان — ما هي؟","b":"الكيسة الدرقية اللسانية (thyroglossal cyst)."},{"f":"ما هو أشيع سبب لكتل العنق الحميدة عند الأطفال؟","b":"التهاب العقد اللمفاوية التالي لخمج تنفسي علوي."},{"f":"خراج خلف البلعوم عند الأطفال — كيف يتظاهر؟","b":"صرير وتشنج رقبي — حالة إسعافية."}]},{"t":"اضطرابات الحنجره الخلقيه تلين الحنجره","cards":[{"f":"ما هو أشيع سبب للصرير عند الرضع؟","b":"التلين الحنجري (laryngomalacia)."},{"f":"رضيع بصرير شهيقي يتحسن بالاستلقاء على البطن — التشخيص؟","b":"التلين الحنجري."},{"f":"ما هو سير التلين الحنجري الطبيعي؟","b":"يتحسن عفويًا مع النمو غالبًا — يختفي بعمر 12–18 شهرًا."}]}]},{"s":"العينية","topics":[{"t":"أمراض الملحقات والقطعة الأمامية","cards":[{"f":"متى يحدث التهاب القرنية التعرضي (عين الأرنب)؟","b":"بعد شلل العصب الوجهي أو الجحوظ — لعدم انغلاق الأجفان خاصة أثناء النوم؛ تُفضل خياطة حواف الأجفان الجزئية."},{"f":"صِف القرنية المخروطية (keratoconus).","b":"مرض غير التهابي وغير مؤلم — ترقق مترقٍ وازدياد تحدب القرنية، ثنائي الجانب غالبًا، مع حسر بصر ولابؤرية غير منتظمة."},{"f":"فرّق: القرحة القرنية الجرثومية × الحلئية من حيث الألم.","b":"الجرثومية مؤلمة بشدة؛ الحلئية (بالحلأ البسيط) تترافق بنقص حس القرنية لا بألم شديد."},{"f":"ما هي سمات التهاب القرنية بالحلأ البسيط؟","b":"نقص حس القرنية، وحيد الجانب غالبًا، بطيء الشفاء قد يستغرق شهرًا."},{"f":"ما فائدة تلوين الفلوريسين (fluorescein)؟","b":"يكشف العيوب الظهارية في القرنية (القرحات والسحجات)."},{"f":"ما هي سمة التهاب الملتحمة الجرثومي؟","b":"مفرزات قيحية تلصق الأجفان صباحًا."},{"f":"ما هي سمة التهاب الملتحمة الفيروسي (adenovirus)؟","b":"مفرزات مائية + اعتلال عقد لمفاوية أمام الأذن."},{"f":"ما هو العامل المسبب للتراخوما؟ وما اختلاطها المسبب للعمى؟","b":"المتدثرة التراخومية (Chlamydia trachomatis) — الشعرة (trichiasis) باحتكاك الأهداب بالقرنية."},{"f":"فرّق: الشعيرة (hordeolum) × البردة (chalazion).","b":"الشعيرة: خمج عنقودي حاد مؤلم في غدد الجفن؛ البردة: التهاب حبيبومي مزمن غير مؤلم في غدة ميبوميوس."},{"f":"ما هو سبب التهاب كيس الدمع عند الولدان؟ وما سيره؟","b":"انسداد القناة الدمعية الأنفية — يتحسن عفويًا غالبًا؛ التدليك أولًا."},{"f":"فرّق: انقلاب الجفن للداخل (entropion) × للخارج (ectropion).","b":"للداخل: احتكاك الأهداب بالقرنية؛ للخارج: دمع وتعرّض الملتحمة."},{"f":"ما هي سمة التهاب حواف الأجفان (blepharitis)؟","b":"قشور دهنية على قاعدة الأهداب وحواف الأجفان."},{"f":"ما هو اختبار شيرمر (Schirmer)؟","b":"يقيس إفراز الدمع — يُستخدم في تشخيص جفاف العين."},{"f":"ما هي الظفرة (pterygium)؟","b":"نمو مثلثي من الملتحمة نحو القرنية جهة الأنف — مرتبط بالتعرض الشمسي المزمن."},{"f":"فرّق: التهاب الصلبة (scleritis) × التهاب ظاهر الصلبة (episcleritis).","b":"الصلبة: ألم شديد يوقظ من النوم؛ ظاهر الصلبة: أخف ألمًا ويبيضّ بتقطير الفينيليفرين."},{"f":"ما هي سمة التهاب الملتحمة الربيعي؟","b":"حكة شديدة + حليمات عملاقة (cobblestone) — عند الأطفال في فصل الربيع."},{"f":"جحوظ نابض — ما التوجّه؟","b":"ناسور سباتي كهفي (carotid-cavernous fistula)."},{"f":"تدلي الجفن (ptosis) + حدقة متسعة — ما الاشتباه؟","b":"شلل العصب الثالث — إسعاف (يُخشى أم دم دماغية)."},{"f":"ما هي السوية القيحية (hypopyon)؟","b":"قيح عقيم في الغرفة الأمامية — قد تظهر قبل انثقاب القرحة القرنية الجرثومية."},{"f":"ما هي أشيع عوامل القرحة القرنية الجرثومية؟","b":"الجراثيم العنقودية (Staphylococcus) والعقدية (Streptococcus)."}]},{"t":"أمراض العدسة والزرق","cards":[{"f":"اذكر أسباب الساد الولادي والخلقي.","b":"الأخماج داخل الرحم (الحصبة الألمانية، التوكسوبلاسموز)، الاضطرابات الاستقلابية (الغالاكتوزيمية)، التعرض للأشعة — التهاب الملتحمة ليس منها."},{"f":"ما هي سمات مرحلة الساد المنتبج (intumescent)؟","b":"زيادة حجم العدسة بامتصاص الماء + حسر بصر + ارتفاع ضغط داخل العين (زرق ثانوي) — لا يزداد خطر انفصال الشبكية."},{"f":"ما هي علامات هجمة الزرق الحاد مغلق الزاوية؟","b":"احتقان هدبي شديد حول الحوف + قرنية وذمية غير رائقة + غرفة أمامية ضحلة + حدقة نصف متسعة غير متفاعلة للضوء."},{"f":"صِف الزرق البدئي مفتوح الزاوية.","b":"ضغط داخل مقلة فوق قدرة تحمل الأنسجة مع زاوية مفتوحة — مرض لا عرضي يُكشف متأخرًا بتأثر الساحة البصرية؛ العلاج دوائي بالدرجة الأولى."},{"f":"ما هو أشيع سبب للعمى القابل للعلاج عالميًا؟","b":"الساد (cataract) الشيخي."},{"f":"فرّق: اتجاه انزياح العدسة في مارفان × بيلة الهوموسيستين.","b":"مارفان: للأعلى والوحشي (superotemporal)؛ بيلة الهوموسيستين: للأسفل والأنسي (inferonasal)."},{"f":"ما هو ثالوث الزرق الولادي (عين الثور buphthalmos)؟","b":"كبر المقلة + تغيم القرنية + دمع غزير."},{"f":"صِف حسر البصر (myopia) بصريًا.","b":"القوة الكاسرة زائدة أو القطر الأمامي الخلفي أطول — الأشعة المتوازية تتجمع في بؤرة أمام الشبكية — يُصحح بعدسات مقعرة مبعدة."},{"f":"صِف مد البصر (hyperopia) بصريًا.","b":"الأشعة المتوازية تتجمع في بؤرة خلف الشبكية — يُصحح بعدسات محدبة مقربة؛ يسبب حولًا أنسيًا عند الأطفال."},{"f":"ما هي اختلاطات الكورتيزون الموضعي المديد على العين؟","b":"ساد خلفي تحت المحفظة + زرق (ارتفاع ضغط داخل المقلة)."},{"f":"زرق انسداد الزاوية أشيع عند أي مرضى؟","b":"عند مديدي البصر — الغرفة الأمامية ضحلة لديهم."},{"f":"ما هو المعيار الذهبي لقياس الضغط داخل المقلة؟","b":"مقياس غولدمان للتسطح (Goldmann applanation tonometry)."},{"f":"بمَ تُصحح اللابؤرية (astigmatism)؟","b":"بعدسات أسطوانية (cylindrical lenses)."},{"f":"لماذا يتطلب فحص قعر العين توسيع الحدقة في حسر البصر؟","b":"لرؤية المحيط الشبكي — الحسيرون معرضون لتنكسات محيطية وتمزقات شبكية."}]},{"t":"أمراض العنبة والشبكية والجسم الزجاجي","cards":[{"f":"ما هي سمات التوكسوبلاسموز العيني؟","b":"آفات شبكية مشيمية متعددة تترك ندبًا مصطبغة + النكس من حافة ندبة سابقة — يُعالج بالبيريميتامين والسلفاديازين."},{"f":"ما خطورة الإصابة العينية في داء بهجت؟","b":"مهددة للبصر: التهاب عنبية شديد + التهاب أوعية شبكية — تكرار الهجمات يُدهور القدرة البصرية."},{"f":"متى يحدث التهاب العنبة القيحي (endophthalmitis)؟","b":"كاختلاط للقرحات القرنية المنثقبة والجروح النافذة والجراحات داخل العين — لا يلي التهاب الملتحمة التحسسي."},{"f":"ما هي علامات اعتلال الشبكية السكري البسيط (غير التكاثري)؟","b":"أوردة متوسعة متعرجة + أمهات دم مجهرية + نزوف نقطية ونتحات قاسية في القطب الخلفي — الشدي من سمات التكاثري."},{"f":"ما هي اختلاطات الاعتلال السكري التكاثري؟","b":"أوعية حديثة (neovascularization) → نزف زجاجي وانفصال شبكية شدي."},{"f":"ما هي علامة انسداد الشريان الشبكي المركزي؟","b":"فقد بصر مفاجئ غير مؤلم + بقعة كرزية حمراء (cherry-red spot) في اللطخة."},{"f":"ما هي علامة انسداد الوريد الشبكي المركزي؟","b":"نزوف شبكية منتشرة غزيرة (صورة العاصفة الدموية)."},{"f":"ما هو ثالوث أعراض انفصال الشبكية؟","b":"ومضات ضوئية + عوائم (floaters) + ستارة أو ظل في الساحة البصرية."},{"f":"صِف التهاب العنبية الأمامي (anterior uveitis).","b":"ألم + رهاب ضوء + حدقة متضيقة — يترافق مع HLA-B27 (التهاب الفقار اللاصق)."},{"f":"فرّق: التنكس البقعي الجاف × الرطب.","b":"الجاف: رواسب دروزن (drusen)؛ الرطب: أوعية مشيمية حديثة."},{"f":"ما هي عوامل اعتلال الشبكية الخداجي (ROP)؟","b":"الخداجة + الأكسجة العالية."},{"f":"التهاب الشبكية بالفيروس المضخم للخلايا (CMV) — متى وأين؟","b":"عند مثبطي المناعة — آفات نزفية منتشرة (صورة البيتزا)."},{"f":"ما هو أشيع سبب لتدني البصر عند السكريين؟","b":"وذمة اللطخة (macular edema) السكرية."},{"f":"بمَ يُتابع ثقب اللطخة الصفراء؟","b":"بشبكة أمسلر (Amsler grid) — تشوه الخطوط يدل على إصابة اللطخة."},{"f":"عوائم مفاجئة عند مسن دون ومضات — ما هو؟","b":"انفصال الجسم الزجاجي الخلفي — حميد غالبًا."},{"f":"ما هو أشيع ورم عيني خبيث عند الأطفال؟","b":"الورم الأرومي الشبكي (retinoblastoma) — يتظاهر بحدقة بيضاء."},{"f":"ما هو أشيع ورم عيني خبيث بدئي عند البالغين؟","b":"الورم القتاميني المشيمي (choroidal melanoma)."},{"f":"ما هي علامات اعتلال الشبكية بفرط الضغط الشرياني؟","b":"تضيق شرياني + أسلاك نحاسية ثم فضية + نزوف ونتحات قطنية."},{"f":"كم مرة يُفحص قعر العين عند السكري؟","b":"سنويًا على الأقل — للكشف المبكر عن الاعتلال السكري."},{"f":"تمزق شبكي محيطي مكتشف صدفة — ما أهميته؟","b":"يسبق الانفصال التمزقي — يُعالج وقائيًا بالتخثير الضوئي بالليزر."}]},{"t":"أمراض العصب البصري وحركية العين","cards":[{"f":"تدني مفاجئ في الرؤية + ألم بتحريك المقلة + قعر عين طبيعي — التشخيص؟","b":"التهاب العصب البصري خلف المقلة الحاد."},{"f":"الوذمة الحليمية (papilledema) ثنائية الجانب — ما دلالتها؟","b":"ارتفاع الضغط داخل القحف حتى يثبت العكس."},{"f":"مسن بفقد بصر مفاجئ + ألم صدغي — ما الإسعاف؟","b":"التهاب الشريان الصدغي (GCA) — خطر العمى الثنائي."},{"f":"طفل 3 سنوات بحول أنسي + مد بصر 4 درجات — ما التدبير الأمثل؟","b":"تصحيح سوء الانكسار بالنظارة أولًا (ومعالجة الغطش إن وجد)."},{"f":"ما هو أخطر اختلاط عيني للأميودارون؟","b":"اعتلال العصب البصري — مهدد للبصر (الترسبات القرنية شائعة لكنها سليمة)."},{"f":"ما هي علامة شلل العصب الثالث؟","b":"حدقة متسعة + العين منحرفة للأسفل والخارج (down and out)."},{"f":"ما هي علامة شلل العصب السادس؟","b":"حول أنسي — العين لا تُبعد نحو الخارج."},{"f":"ما هي علامة شلل العصب الرابع؟","b":"شفع عمودي + إمالة الرأس المعاوضة — صعوبة النظر للأسفل."}]},{"t":"الرضوض والأورام العينية","cards":[{"f":"اذكر أسباب الحدقة البيضاء (leukocoria).","b":"الساد الولادي، الورم الأرومي الشبكي، اعتلال الشبكية الخداجي، انفصال الشبكية — الزرق الولادي ليس منها."},{"f":"ما هو الورم المختلط (mixed tumor) في العين؟","b":"ورم ظهاري سليم ينشأ على حساب الغدة الدمعية الأساسية — بطيء التطور."},{"f":"ما هي سمة ورم المخروط خلف المقلة؟","b":"جحوظ محوري مستقيم غير مؤلم — دون اضطرابات حركية باكرة."},{"f":"أوعية حديثة على سطح القزحية — علامة سلامة أم خبث؟","b":"من علامات الخبث في أورام القزحية القتامينية — ليست علامة سلامة."},{"f":"ما هي سمة كسر قاع الحجاج (blow-out fracture)؟","b":"انحصار العضلة المستقيمة السفلية + شفع عمودي + خدر الخد."},{"f":"أي الرضوض الكيميائية أخطر: القلوية أم الحمضية؟","b":"القلوية — تنفذ أعمق في الأنسجة؛ الغسيل الفوري الغزير بالماء أولًا."},{"f":"ما هو سير النزف تحت الملتحمة؟","b":"حميد يمتص عفويًا خلال أسبوع إلى أسبوعين."},{"f":"جسم أجنبي قرني حديدي — ما الاختلاط الموضعي؟","b":"حلقة صدأ (rust ring) — يُزال باكرًا."},{"f":"ما هو التجمع الدموي في الغرفة الأمامية (hyphema)؟","b":"دم في الغرفة الأمامية بعد رض مغلق — الراحة وتجنب الأسبرين ومميعات الدم."}]},{"t":"أسواء الانكسار والتشخيص والفحوص العينية","cards":[{"f":"بمَ يُصحح حسر البصر؟","b":"بعدسات مقعرة مبعدة (diverging)."},{"f":"أين تتجمع الأشعة في مد البصر؟ وبمَ يُصحح؟","b":"خلف الشبكية — يُصحح بعدسات محدبة مقربة."},{"f":"اذكر مضادات استطباب تصحيح أسواء الانكسار بالإكزيمر.","b":"الحمل، القرنية المخروطية، جفاف العين الشديد، التهاب كيس الدمع المزمن — العمر فوق 18 شرط لا مانع."},{"f":"ما هو الفحص الأساسي في متابعة الزرق مفتوح الزاوية؟","b":"فحص الساحة البصرية (perimetry) — يكشف التدهور قبل الأعراض."}]}]},{"s":"الجراحة العامة","topics":[{"t":"أمراض المريء الجراحية","cards":[{"f":"نقطة ذهبية: ما التشخيص عند رؤية «منقار الطير» (Bird's beak) في الجزء البعيد من المري مع توسع المري القريب باللقمة الباريتية؟","b":"تعذّر الارتخاء المريئي (الأكالازيا - Achalasia)."},{"f":"من سؤال حقيقي: شابة بعسرة بلع منذ 4 سنوات دون نقص وزن + توسع مري وتضيق أسفله بشكل منقار الطير — ما أفضل علاج لها؟","b":"عملية هيللر (Heller myotomy): قطع عضلات المعصرة المريئية السفلية جراحيًا — الخيار الجذري الأمثل للشابة، أما التوسيع بالبالون فأقل ديمومة."},{"f":"نقطة ذهبية: ما المعيار الذهبي (Gold standard) لتشخيص الأكالازيا والتمييز بينها وبين التشنج المريئي المنتشر؟","b":"قياس ضغوط المري (Esophageal manometry) — تشخيصي ومميّز بين اضطرابات الحركة المريئية."},{"f":"فرّق: عسرة بلع مترددة مزمنة عند شابة دون نقص وزن VS عسرة بلع ثابتة مترقية عند مسن مدخن مع نقص وزن؟","b":"الأولى: أكالازيا (Achalasia). الثانية: سرطان المري — من أفتك سرطانات السبيل الهضمي، والمرض السريري الظاهر فيه مرادف للمرحلة المتقدمة."},{"f":"نقطة ذهبية: ما العرض السريري النموذجي لداء القلس المعدي المريئي (GERD)؟","b":"الحرقة خلف القص (Heartburn)."},{"f":"قاعدة ذهبية: كل سرطان في الثلث السفلي للمري / القسم البطني / الفؤاد (Cardia) هو؟","b":"سرطان غدي (Adenocarcinoma) — هو النمط الأشيع في القسم البطني والفؤاد؛ بينما يسود الشائكي (Squamous cell) في الثلثين العلويين."},{"f":"من سؤال حقيقي: تمزق المري (متلازمة بورهااف - Boerhaave syndrome) — هل العلاج محافظ؟ وما علامتاه الكلاسيكيتان؟","b":"لا — حالة إسعافية تتطلب التداخل الجراحي المبكر مع تغطية بالمضادات الحيوية (وليس العلاج المحافظ). العلامتان: غاز تحت الجلد (Subcutaneous emphysema) وعلامة هامان (Hamman's sign) في إصغاء القلب."},{"f":"من سؤال حقيقي: كحولي منذ 10 سنوات راجع بنزف هضمي صاعق غزير — التشخيص؟","b":"دوالي المري (Esophageal varices) — تُنزف بكميات غزيرة صاعقة عند مرضى الكبد الكحوليين."},{"f":"نقطة ذهبية: تشنج عضلي وحس نخز معمم بعد 24 ساعة من استئصال درق تام — ما الإجراء الأمثل؟","b":"نقص كلس الدم (Hypocalcemia) بعد أذية/استئصال جارات الدرق → تسريب غلوكونات الكالسيوم (Calcium gluconate) عبر الوريد."}]},{"t":"أمراض المعدة والعفج الجراحية","cards":[{"f":"من سؤال حقيقي: شاب مدخن بألم شرسوفي طاعن مفاجئ + بطن مدافع كاللوح + تعرق وشحوب — ما أول إجراء لتأكيد التشخيص؟","b":"انثقاب قرحة هضمية (الأرجح عفجية) مع التهاب صفاق كيميائي → أول إجراء: صورة صدر/بطن بالوقوف مع إظهار الحجابين بحثًا عن هواء حر (Pneumoperitoneum) تحت الحجاب الحاجز."},{"f":"قاعدة ذهبية: كل قرحة عفجية هي ... حتى يثبت العكس؟","b":"حميدة (Benign) — القرحة العفجية لا تتسرطن أبدًا؛ التسرطن من اختلاطات القرحة المعدية لا العفجية."},{"f":"نقطة ذهبية: ما العامل المؤهب الأكثر أهمية لسرطان المعدة؟","b":"الإنتان بالملتوية البوابية (H. pylori) — عبر التهاب المعدة الضموري المزمن (Chronic atrophic gastritis)."},{"f":"فرّق: الملوية البوابية تؤهب لكل ما يلي ما عدا؟ (قرحة عفجية / سرطان معدة غدي / مفوما MALT / قلس معدي مريئي)","b":"القلس المعدي المريئي (GERD) — لا تسببه الملوية البوابية؛ أما القرحة العفجية وسرطان المعدة الغدي ومفوما MALT المعدية فكلها من مخاطرها."},{"f":"نقطة ذهبية: النزف من قرحة عفجية خلفية — ما الشريان المسؤول؟","b":"الشريان المعدي العفجي (Gastroduodenal artery) — يقع خلف البصلة العفجية وينزف عند انثقاب القرحة الخلفية."},{"f":"نقطة ذهبية: ما الصحيح في أورام اللحمة بالسبيل الهضمي (GISTs)؟ (أشيع موقع / الانتشار اللمفي)","b":"أشيع موقع: المعدة (وليس المستقيم) — ولا تميل للانتقال بالطريق اللمفي (الانتشار اللمفي نادر في GIST)."},{"f":"أنماط: مسن بشحوب وتعب ووهن + كتلة شرسوفية مجسوسة + عقدة فوق الترقوة اليسرى — التشخيص الأرجح؟","b":"سرطان المعدة — عقدة فيرشو (Virchow's node: فوق الترقوة اليسرى) دليل انتقال بعيد كلاسيكي."},{"f":"فرّق: ألم شرسوفي شديد + بطن مدافع + أميلاز مرتفع قليلًا — هل يغير الأميلاز المرتفع قليلًا التشخيص؟","b":"لا — الصورة النموذجية (ألم طاعن مفاجئ + بطن لوح) هي انثقاب قرحة عفجية؛ الأميلاز المرتفع قليلًا لا ينفي الانثقاب، والتهاب البنكرياس الحاد يتظاهر بألم حزامي يمتد للظهر لا ببطن مدافع."}]},{"t":"أمراض الأمعاء الدقيقة الجراحية","cards":[{"f":"نقطة ذهبية: ما العرض الأساسي في التهاب الزائدة الدودية؟","b":"الألم البطني — يبدأ حول السرة ثم يتركز في الحفرة الحرقفية اليمنى."},{"f":"أنماط: في التهاب الزائدة الحاد دون انثقاب، كل ما يلي من العلامات ما عدا؟ (ألم حفرة يمنى / فقدان شهية / حرارة 40°)","b":"ترفع حروري 40° — حرارة بهذا الارتفاع ليست من علامات الزائدة غير المثقوبة؛ وفقدان الشهية (Anorexia) من علاماتها الكلاسيكية."},{"f":"نقطة ذهبية: ما السبب الأكثر شيوعًا لانسداد الأمعاء الدقيقة عند البالغين؟","b":"الالتصاقات (Adhesions) التالية لجراحة سابقة على البطن — هي السبب الأشيع على الإطلاق."},{"f":"فرّق: انغلاف الأمعاء (Intussusception) في الانسداد المعوي — عند البالغين VS عند الأطفال؟","b":"عند البالغين: السبب الأقل تواردًا في الانسداد الميكانيكي. عند الأطفال في سن المدرسة: أشيع سبب للانسداد هو الفتق الإربي الغاصص (وليس الانغلاف)."},{"f":"نقطة ذهبية: ما أهم علامة سريرية للإقفار/الاحتشاء المساريقي الحاد؟","b":"ألم بطني شديد غير متناسب مع موجودات الفحص (Pain out of proportion) — ألم عنيف مع مضض بطني خفيف."},{"f":"نقطة ذهبية: من أين تأتي الصمة الشريانية المسببة للاحتشاء المساريقي عادة؟","b":"من القلب (الرجفان الأذيني غالبًا) — وليست من الطرف السفلي."},{"f":"فرّق: رتج ميكل (Meckel's diverticulum) — أين يتوضع؟ وما أشيع اختلاطاته؟ وهل يُستأصل إن وُجد صدفة؟","b":"يتوضع على بعد ~60 سم (قدمان) من الدسام اللفائفي الأعوري — وليس مترين. الاختلاط الأشيع هو النزف (وليس الانسداد). وإن وُجد صدفة أثناء جراحة أخرى فلا يُستأصل."},{"f":"نقطة ذهبية: ما علامة روفزينغ (Rovsing's sign)؟","b":"الضغط على الحفرة الحرقفية اليسرى يُحدث ألمًا في الحفرة الحرقفية اليمنى — علامة التهاب زائدة."},{"f":"نقطة ذهبية: علامة البسواس (Psoas) وعلامة ماكبرني (McBurney) — في أي مرض؟","b":"التهاب الزائدة الدودية الحاد — البسواس: ألم عند بسط الورك (زائدة خلف الأعور)؛ ماكبرني: ألم بأقصاه عند نقطة ماكبرني في الحفرة اليمنى."},{"f":"من سؤال حقيقي: طفلة بعمر 10 سنوات بألم حفرة حرقفية يمنى — ما أشيع ما يلتبس بالتهاب الزائدة عند الأطفال؟","b":"التهاب العقد المساريقية (Mesenteric adenitis) — هو الأشيع التباسًا بالزائدة عند الأطفال."},{"f":"نقطة ذهبية: ما دور الرحضة الشرجية (Barium enema) في الانغلاف المعوي؟","b":"مشخصة وأحيانًا معالجة (تردّ الانغلاف) — التشخيص والعلاج في خطوة واحدة."},{"f":"من سؤال حقيقي: ناسور عالي النتاج بعد يومين من استئصال جزء أمعاء مع مفاغرة — ما السبب المحتمل؟","b":"انفلات المفاغرة (Anastomotic leak) — هو السبب الأشيع للناسور المبكر عالي النتاج بعد الجراحة المعوية."},{"f":"نقطة ذهبية: ما الآلية الإمراضية الأكثر تواردًا في التهاب الزائدة الدودية الحاد؟","b":"الانسداد اللُمَعي: بالحصيات البرازية (Fecolith) أو فرط التنسج اللمفاوي (Lymphoid hyperplasia)."},{"f":"فرّق: الشرايين المستهدفة في نقص التروية المعوية تشمل المساريقي العلوي — وأي شريان ليس منها؟","b":"الشريان الفخذي الأصلي (Common femoral) — ليس من شرايين التروية المعوية."},{"f":"أنماط: هل انسداد الأمعاء علامة باكرة في التهاب الزائدة الدودية؟","b":"لا — أبدًا؛ انسداد الأمعاء ليس علامة باكرة للزائدة الحادة."},{"f":"نقطة ذهبية: ما أدق وسيلة لتشخيص الإقفار المساريقي الوريدي؟","b":"الطبقي المحوري متعدد الشرائح مع الحقن (CT angiography) — بينما الإقفار الشرياني الحاد: دوبلر منشأ الشرايين / التصوير الوعائي."},{"f":"قاعدة ذهبية: كل ألم حفرة حرقفية يمنى عند طفلة بعمر 12 سنة يدخل في تفريقه الزائدة والتهاب العقد المساريقية — ما عدا؟","b":"التهاب المرارة الحاد (ور تج ميكل النازف في سياق آخر) — المرارة الحادة ليست من تفريق ألم الحفرة اليمنى السفلي عند طفلة."},{"f":"نقطة ذهبية: في ألم حاد بالحفرة الحرقفية اليمنى عند طفلة 12 سنة، أي التشخيصات التالية لا يدخل في التفريق؟ (زائدة / عقد مساريقية / رتج ميكل نازف)","b":"رتج ميكل النازف — يتظاهر بنزف هضمي سفلي غير مؤلم لا بألم حفرة يمنى."}]},{"t":"أمراض الكولون والمستقيم الجراحية","cards":[{"f":"نقطة ذهبية: ما أشيع عرض في سرطان الكولون الأيمن؟","b":"فقر الدم (بعوز الحديد) — الكولون الأيمن واسع اللُمعة فينزف بصمت ويتظاهر بفقر دم لا بانسداد."},{"f":"نمط امتحاني: امرأة 60 سنة بشحوب + كتلة قاسية غير منتظمة في الحفرة الحرقفية اليمنى + دم خفي إيجابي بالبراز — التشخيص؟","b":"سرطان القولون الأعور (Cecal cancer) — النمط الكلاسيكي لسرطان الكولون الأيمن."},{"f":"نمط امتحاني: رجل 75 سنة بتبدل عادات التغوط + نقص وزن + تغوط مدمى — التشخيص الأرجح؟","b":"سرطان السين (Sigmoid cancer) — الكولون الأيسر ضيق اللُمعة فيتظاهر بتغير عادات التغوط والنزف الظاهر."},{"f":"نقطة ذهبية: علامة «عضة التفاحة» (Apple-core sign) على التصوير — ما التشخيص؟","b":"سرطان الكولون — تضيق حلقي خبيث كلاسيكي."},{"f":"نقطة ذهبية: في انسداد الكولون الورمي، أين يحدث الانثقاب أشيع؟","b":"الأعور (Cecum) — أرق جدار الكولون وأوسعه قطرًا فينثقب أولًا بقانون لابلاس."},{"f":"قاعدة ذهبية: كل داء رتوج (Diverticulosis) هو ... من حيث التسرطن؟","b":"لا يتسرطن أبدًا — التسرطن ليس من اختلاطات داء الرتوج؛ ومعظم مرضى داء الرتوج لا يصابون بالتهاب رتوج خلال حياتهم."},{"f":"نقطة ذهبية: ما أفضل وسيلة لتشخيص التهاب الرتوج الحاد (Acute diverticulitis)؟","b":"الطبقي المحوري (CT) — الاستقصاء الأفضل والأدق."},{"f":"فرّق: انفتال السين (Sigmoid volvulus) — الفئة العمرية والأعراض؟","b":"يصيب المسنين (وليس الشباب) — ويتظاهر بانسداد (ألم + انتفاخ + إمساك) دون نزف هضمي سفلي."},{"f":"نقطة ذهبية: ما أشيع استطباب للجراحة في داء كرون (Crohn's disease)؟","b":"الانسداد (التضيقات الليفية) — والجراحة في كرون اقتصادية ولا تُشترط حواف استئصال سليمة مجهريًا."},{"f":"نقطة ذهبية: ما أشيع سبب للناسور المستقيمي المهبلي (Rectovaginal fistula)؟","b":"الأذيات التوليدية (Obstetric trauma) — هي السبب الأشيع على الإطلاق."},{"f":"فرّق: داء البوليبات العائلي (FAP) — متى يبدأ المسح بالتنظير؟ وسرطان القولون الوراثي دون سليلات (لينش) أين يتوضع أشيع؟","b":"المسح في FAP يبدأ مبكرًا (بعمر 10-12 سنة) — وليس بعمر 60. وسرطان لينش (HNPCC) يتوضع أشيع في الكولون الأيمن (الصاعد) لا المعترض."}]},{"t":"أمراض القناة المغبنية","cards":[{"f":"قاعدة ذهبية: كل بواسير داخلية هي ... من حيث الألم؟","b":"غير مؤلمة — البواسير الداخلية فوق الخط المسنن (Dentate line) فلا تسبب ألمًا؛ عرضها الرئيسي النزف غير المؤلم، والألم ليس عرضها الرئيسي أبدًا."},{"f":"نقطة ذهبية: ما الطريقة المثلى لتشخيص البواسير الداخلية؟","b":"التنظير عبر الشرج (Anoscopy) — الفحص المشخص للباسور الداخلي."},{"f":"نقطة ذهبية: ما الاختلاط الأكثر شيوعًا بعد عملية استئصال البواسير؟","b":"احتباس البول (Urinary retention) — هو الاختلاط الأشيع بعد استئصال البواسير."},{"f":"نقطة ذهبية: ما علاج البواسير من الدرجة الرابعة؟","b":"الجراحة — الدرجة الرابعة (المتدلية غير القابلة للرد) علاجها المختار جراحي."},{"f":"فرّق: الشق الشرجي المزمن — ما الصحيح في تدبيره؟ (خزع كامل للمعصرة الداخلية / خزع جزئي جانبي / صادات جهازية)","b":"خزع جزئي جانبي للمعصرة الداخلية (Lateral internal sphincterotomy) — لا الخزع الكامل؛ والمعالجة بالصادات الجهازية ليست من علاج الشق الشرجي."},{"f":"نقطة ذهبية: هل علاج النواسير الشرجية محافظ دومًا؟","b":"لا — النواسير الشرجية علاجها جراحي (العلاج المحافظ دومًا عبارة خاطئة)."},{"f":"فرّق: السرطان الشائع في القناة الشرجية VS في منطقة الشرج؟ وما السبب الرئيسي للخراجات حول الشرج؟","b":"القناة الشرجية: شائك الخلايا (Squamous cell carcinoma). منطقة الشرج: السرطان الوسفي (Verrucous carcinoma). والخراجات حول الشرج سببها الرئيسي التهاب غدد هيرمان (Cryptoglandular infection)."}]},{"t":"أمراض الكبد الجراحية","cards":[{"f":"قاعدة ذهبية: في الكيسة المائية الكبدية (Hydatid cyst) — هل البزل عبر الجلد وسيلة تشخيصية جيدة؟ وهل تُعالج بالميترونيدازول؟","b":"لا للاثنين — البزل عبر الجلد ليس وسيلة جيدة للتشخيص (خطر التسرب والانثقاب والصدمة التحسسية)، والميترونيدازول ليس علاجها (علاجها الجراحي/الألبيندازول)."},{"f":"نقطة ذهبية: هل يتسرطن جوف الكيسة المائية الكبدية؟","b":"لا — التسرطن ليس من اختلاطات الكيسة المائية الكبدية."},{"f":"نقطة ذهبية: يعتمد تشخيص الكيسات المائية الكبدية على الإيكو والمصلية — ما الاستقصاء الذي لا يدخل في التشخيص؟","b":"التصوير الوعائي الظليل لأوعية الكبد — لا دور له في تشخيص الكيسة المائية."},{"f":"من سؤال حقيقي: كيسة كبدية بسيطة 2 سم، جدار رقيق، محتوى رائق، غير مجسوسة ولا عرضية — ما التدبير الأمثل؟","b":"المراقبة بالإيكو فقط — الكيسات الكبدية البسيطة الصغيرة غير العرضية لا تستطب الجراحة."},{"f":"نقطة ذهبية: ورم وعائي كبدي (Hemangioma) أقل من 2 سم غير عرضي — ما الإجراء؟","b":"المراقبة — الأورام الوعائية الكبدية الصغيرة غير العرضية لا تُستأصل."},{"f":"نقطة ذهبية: أي الآفات الكبدية تحمل خطر التحول للخباثة: الورم الوعائي أم الأدينوما الكبدية؟","b":"الأدينوما الكبدية (Hepatic adenoma) — تحمل خطر التحول الخبيث (ولا يُعتمد على إيقاف مانعات الحمل وحده لإزالة هذا الخطر)."},{"f":"نقطة ذهبية: ما الاختلاط الأول لرضوض الكبد النافذة؟","b":"تدمي الصفراء (Hemobilia) — نزف في الطرق الصفراوية بعد رض الكبد."},{"f":"نقطة ذهبية: متى لا يُستطب قطع الكبد في الانتقالات الكبدية؟","b":"عند وجود سائل حبن (Ascites) في جوف البريتوان — دليل قصور كبدي/انتشار يمنع الاستئصال."}]},{"t":"أمراض الطرق الصفراوية والمرارة","cards":[{"f":"نمط امتحاني: ألم في المراق الأيمن + يرقان + حرارة/عرواءات (ثلاثي شاركو) — التشخيص؟","b":"التهاب الطرق الصفراوية الصاعد (Ascending cholangitis) — الثلاثي الكلاسيكي: ألم مراق أيمن + يرقان + حرارة."},{"f":"فرّق: علامة مورفي إيجابية (ألم مراق أيمن + حرارة + إقياء) VS قولنج مراري؟","b":"مورفي + حرارة = التهاب مرارة حاد (Acute cholecystitis). القولنج المراري (Biliary colic): ألم ماغص بعد الطعام ينتشر للكتف الأيمن، بلا حرارة مرتفعة (39-40°) وغير مستمر."},{"f":"نقطة ذهبية: ما أول استقصاء عند مريض يرقان انسدادي؟ وماذا بعده إذا أظهر توسع القناة الجامعة؟","b":"الأول: الإيكو (الأمواج فوق الصوتية). التالي بعد توسع القناة الجامعة: التنظير الراجع للطرق الصفراوية ERCP."},{"f":"نقطة ذهبية: هواء في الطرق الصفراوية شعاعيًا يدل على؟ وما أشيع النواسير الهضمية الصفراوية؟","b":"ناسور صفراوي عفجي (Cholecystoduodenal fistula). وأشيع النواسير الهضمية الصفراوية: المرارية الاثنا عشرية."},{"f":"نقطة ذهبية: ما علامة كورفوازييه (Courvoisier's law)؟","b":"مرارة غير مؤلمة مجسوسة + يرقان = سبب ورمي (مجل فاتر/رأس البنكرياس) — وليس حصويًا."},{"f":"نمط امتحاني: مسن بيرقان متردد صامت دون ألم + مرارة مجسوسة غير مؤلمة — التشخيص؟","b":"سرطان مجل فاتر (Ampullary carcinoma) — وإنذاره أفضل من سرطان رأس البنكرياس (وليس أسوأ)."},{"f":"نقطة ذهبية: ما الصحيح في سرطان المرارة؟","b":"غير قابل للاستئصال الشافي في معظم الحالات (يُكتشف متأخرًا) — ولا تتطلب المعالجة دومًا استئصال فص كبدي أيمن."},{"f":"قاعدة ذهبية: الحصيات المرارية الصامتة (اللاعرضية) — هل هي حالة مستقرة لا تختلط أبدًا؟","b":"لا — قد تختلط (التهاب مرارة، التهاب طرق، التهاب بنكرياس)؛ وليس صحيحًا أن سرطان المرارة يحدث فقط مع الحصيات الصامتة."},{"f":"أنماط: أقل الفئات إصابة بالحصيات المرارية؟","b":"الرجال المدخنون — الحصيات تصيب غالبًا: أنثى، بدينة، خصوبة، في الأربعين (4F)."},{"f":"نقطة ذهبية: ما مضاد الاستطباب المطلق لاستئصال المرارة بالجراحة التنظيرية؟","b":"الشك بوجود سرطان المرارة — يستطب الفتح الجراحي."},{"f":"فرّق: كل ما يلي من اختلاطات الحصيات المرارية ما عدا؟ (التهاب مرارة / التهاب طرق صاعد / التهاب بنكرياس / نزف هضمي علوي)","b":"النزف الهضمي العلوي — ليس من اختلاطات الحصيات؛ والألم الشرسوفي الطاعن ليس من أعراضها."},{"f":"نقطة ذهبية: في التهاب الطرق الصفراوية الحاد — هل خمائر الكبد طبيعية؟","b":"لا — ترتفع (نمط ركودي: فوسفاتاز قلوية مرتفعة أضعاف الطبيعي مع بيليروبين مرتفع)."},{"f":"من سؤال حقيقي: مسن 65 سنة بحكة + ألم بطني + بول غامق + يرقان + فوسفاتاز قلوية 4 أضعاف الطبيعي — ما الخطوة التشخيصية التالية؟","b":"إيكو للبطن — الخطوة الأولى في أي يرقان انسدادي قبل أي إجراء غازٍ."}]},{"t":"آفات البنكرياس الجراحية","cards":[{"f":"نمط امتحاني: مسن 65 سنة بيرقان + مرارة مستسقية غير مؤلمة مجسوسة + نقص وزن وتعب — التشخيص؟","b":"سرطان رأس البنكرياس — وهو غير قابل للجراحة الشافية عند غالبية المرضى (يُكتشف متأخرًا)."},{"f":"فرّق: أورام رأس البنكرياس VS أورام الجسم والذيل — أيها يتظاهر بيرقان انسدادي؟","b":"أورام الرأس (تضغط القناة الجامعة) — أورام الجسم والذيل لا تتظاهر بيرقان انسدادي عادةً."},{"f":"من سؤال حقيقي: طفل 12 سنة بكتلة كبيرة أعلى البطن بعد رض دراجة قبل شهرين — التشخيص؟","b":"كيسة بنكرياسية كاذبة (Pancreatic pseudocyst) — تتكون بعد التهاب البنكرياس الحاد أو رضه بأسابيع."},{"f":"نقطة ذهبية: هل تُدبَّر الكيسة البنكرياسية الكاذبة بجراحة فورية عند التشخيص؟ وهل تُفاغَر على الكولون المعترض؟","b":"لا للاثنين — لا جراحة فورية عند التشخيص (تُراقب أولًا)، والمفاغرة ليست على الكولون المعترض (بل على المعدة أو الصائم)."},{"f":"نمط امتحاني: شاب بحصيات مرارية ناعمة أصيب فجأة بألم زناري ينتشر للظهر — التشخيص؟","b":"التهاب البنكرياس الحاد (الحصوي) — الألم الزناري المنتشر للظهر هو النمط الكلاسيكي."},{"f":"نقطة ذهبية: في علاج التهاب البنكرياس المزمن دوائيًا — هل يُعطى المورفين؟","b":"لا — إعطاء المورفين ليس من مبادئ العلاج الدوائي (خطر الإدمان)؛ يُفضَّل تجنب الأفيونات."}]},{"t":"النزف الهضمي وآفات الطحال","cards":[{"f":"نقطة ذهبية: ما أشيع سبب للنزف الهضمي العلوي؟","b":"القرحة المعدية (Gastric ulcer) — هي أشيع أسباب النزف الهضمي العلوي."},{"f":"فرّق: ما الحد التشريحي الفاصل بين النزف الهضمي العلوي والسفلي؟","b":"رباط ترايتز (Ligament of Treitz) — وليس الوصل اللفائفي الأعوري؛ العلوي قريبه والسفلي بعيده."},{"f":"نقطة ذهبية: كحولي بإقياء دموي — ما الاستقصاء الأفضل؟ وهل الإيكو من تدبير النزف الهضمي العلوي؟","b":"التنظير الهضمي العلوي (Upper endoscopy) هو الأفضل — والإيكو ليس من تدبير النزف الهضمي العلوي أبدًا."},{"f":"فرّق: من اختلاطات استئصال الطحال كل ما يلي ما عدا؟ (إنتان شديد بعد الاستئصال OPSI / ارتفاع صفيحات تفاعلي / نقص صفيحات)","b":"نقص الصفيحات — ليس من اختلاطات استئصال الطحال (بل يحدث ارتفاع صفيحات تفاعلي)؛ وأهم اختلاط: الإنتان الشديد بعد الاستئصال (OPSI). وأفضل علاج لأعراض داء الكريات المكورة الوراثي: استئصال الطحال مع البحث عن الأطحلة الإضافية واستئصالها."}]},{"t":"أمراض البريتوان والبطن الحاد","cards":[{"f":"نمط امتحاني: ألم بطني شديد مفاجئ + بطن خشبية (لوح) + هلال غازي تحت الحجاب الحاجز الأيمن بصورة الصدر — التشخيص والتدبير؟","b":"انثقاب حشا أجوف (Perforated hollow viscus) → فتح بطن أو تنظير بطن إسعافي."},{"f":"نقطة ذهبية: ما الطريقة المفضلة لتشخيص انثقاب حشا أجوف؟","b":"صورة بطن/صدر بسيطة بوضعية الوقوف مع إظهار الحجابين — بحثًا عن هواء حر (Pneumoperitoneum)."},{"f":"قاعدة ذهبية: كل بطن حاد يحتاج تدخلًا جراحيًا؟","b":"لا — ليس دائمًا؛ مثال: التهاب البنكرياس الحاد بطن حاد يُدبَّر محافظًا ولا يحتاج تداخلًا جراحيًا فوريًا."},{"f":"نمط امتحاني: شابة 25 سنة بألم مفاجئ بالحفرة الحرقفية اليمنى + شحوب + هبوط ضغط + تسرع قلب + حرارة طبيعية — التشخيص الأرجح؟","b":"تمزق حمل هاجر (Ruptured ectopic pregnancy) — النمط الكلاسيكي: صدمة نزفية مع حرارة طبيعية."},{"f":"نقطة ذهبية: الخراج الحوضي (Pelvic abscess) — هل يتظاهر بألم منتشر للكتف؟","b":"لا — الألم المنتشر للكتف ليس من مظاهر الخراج الحوضي (بل من تهيج الحجاب: كتمزق طحال أو حمل هاجر)."},{"f":"فرّق: الحالات غير الجراحية المقلدة للبطن الحاد — هل الانسداد المعوي منها؟","b":"لا — الانسداد المعوي حالة جراحية؛ أما المقلدات غير الجراحية فمثل: التهاب البنكرياس الحاد، المغص الكلوي، الحماض الكيتوني."},{"f":"نقطة ذهبية: ألم شرسوفي حاد مفاجئ خلال ثوانٍ — هل التهاب الزائدة الدودية الحاد من تشخيصه التفريقي؟","b":"لا — الزائدة الحادة ألمها حفرة يمنى متدرج؛ أما الشرسوفي المفاجئ فتفريقه: انثقاب قرحة، التهاب بنكرياس حاد، احتشاء سفلي، تمزق أم دم أبهرية."}]},{"t":"الصدمة ورضوض البطن","cards":[{"f":"نقطة ذهبية: ما أفضل تعريف للصدمة؟","b":"نقص إرواء الأنسجة (Hypoperfusion of tissue) — هذا جوهر كل أنواع الصدمة."},{"f":"نقطة ذهبية: ما الحشا الأكثر إصابة في الرضوض المغلقة للبطن؟","b":"الطحال (Spleen) — هو الحشا الأشيع إصابة في الرضوض البطنية المغلقة."},{"f":"نقطة ذهبية: في إنعاش صدمة نقص الحجم بعد حادث سير — ما أقل المحاليل فائدة؟","b":"المحلول السكري (Dextrose) — لا يفيد في الإنعاش الحجمي؛ تُستخدم البلوريات الملحية والدم."},{"f":"فرّق: طعنة سكين نافذة في البطن — ما أخطر عضو يمكن إصابته؟ وماذا لو كان الثرب متبارزًا والمريض مستقرًا؟","b":"الأبهر البطني (Abdominal aorta) هو الأخطر. والثرب المتبارز للخارج (Evisceration) يستطب فتح بطن استقصائي حتى مع الاستقرار الهيموديناميكي."},{"f":"نقطة ذهبية: ما أكثر عامل يؤدي لتأخر شفاء الجروح؟ وما أشيع سبب للوفاة بعد أسابيع من الرضوض؟","b":"الانتان (Infection) أكثر ما يؤخر شفاء الجروح. وأشيع سبب للوفاة المتأخرة (بعد أسابيع) عند المريض المرضوض: قصور الأعضاء المتعدد (MOF)."}]},{"t":"الفتوق وجدار البطن","cards":[{"f":"نقطة ذهبية: ما الفتق الأشيع عند النساء؟","b":"الفتق الإربي (Inguinal hernia) — وبالتحديد غير المباشر؛ وهو الأشيع عند النساء أيضًا (رغم أن الفخذي أشيع نسبيًا عندهن من الرجال)."},{"f":"قاعدة ذهبية: كل فتق فخذي هو ... من حيث الغصص والاختناق؟","b":"الأكثر عرضة للغصص والاختناق بين فتوق جدار البطن — الفتق الفخذي (Femoral hernia) أضيق عنقًا فيختنق أشيع."},{"f":"نمط امتحاني: امرأة 30 سنة بانتباج وحشي وأسفل حديبة العانة — التشخيص؟","b":"فتق فخذي (Femoral hernia) — الموقع الكلاسيكي: وحشي وأسفل حديبة العانة (Pubic tubercle)."},{"f":"نقطة ذهبية: ما الفتق الأكثر تسببًا في انسداد الأمعاء؟","b":"الفتق الفخذي — لضيق عنقه وسرعة اختناقه وغصصه."},{"f":"فرّق: الفتق المختنق (Strangulated) — هل يتغير حجمه مع السعال؟ وهل ينقل حس الدفع؟","b":"لا للاثنين — الفتق المختنق: مؤلم، متوتر، غير قابل للرد، لا يتغير حجمه مع السعال ولا ينقل حس الدفع (impulse)."},{"f":"فرّق: الفتق الإربي المباشر VS غير المباشر — أيهما أشيع؟ وهل يستعجل علاج المباشر خوفًا من الاختناق؟","b":"غير المباشر (Indirect) أشيع. والمباشر (Direct) نسبة اختناقه منخفضة فلا يستعجل علاجه خوفًا من الاختناق."},{"f":"نقطة ذهبية: ما اسم الفتق الذي يحدث في مكان ندبة العمل الجراحي؟","b":"الفتق الاندحاقي (Incisional hernia)."},{"f":"نقطة ذهبية: كل ما يلي من اختلاطات فتوق جدار البطن ما عدا؟ (الغصص / الاختناق / الانسداد / الناسور)","b":"الناسور — ليس من اختلاطات الفتق البطني؛ أما الغصص والاختناق والانسداد فهي اختلاطاته الكلاسيكية."}]},{"t":"أمراض الثدي الجراحية","cards":[{"f":"نقطة ذهبية: سيدة 55 سنة بكتلة ثدي 3 سم بالفحص — ما الخطوة الأولى في المقاربة التشخيصية؟","b":"ماموغرافي + إيكو للثديين (Mammography + Ultrasound) — الخطوة الأولى قبل أي خزعة."},{"f":"نقطة ذهبية: ما الطريقة المثلى لوضع تشخيص دقيق لكتلة مشتبهة في الثدي؟","b":"الخزعة اللبية (Core Needle Biopsy) — هي المشخصة الدقيقة؛ الواسمات الورمية ليست من وسائل تشخيص الكتلة."},{"f":"نقطة ذهبية: علامة قشر البرتقال (Peau d'orange) بالفحص — على ماذا تدل؟","b":"ورم خبيث متقدم موضعيًا (Locally advanced) — من علامات التقدم الموضعي لسرطان الثدي."},{"f":"نقطة ذهبية: ما السبب الأكثر شيوعًا للنز الدموي من الحلمة؟","b":"الحليموم داخل الأقنية (Intraductal papilloma) — أشيع أسباب النز الدموي من الحلمة."},{"f":"نقطة ذهبية: ما أسوأ سرطانات الثدي إنذارًا؟","b":"السرطان الالتهابي (Inflammatory breast cancer) — الأسوأ إنذارًا على الإطلاق."},{"f":"نقطة ذهبية: ما التشخيص المؤكد لسرطان الثدي الالتهابي؟","b":"الخزعة الجلدية (Skin biopsy) — مع الفحص السريري؛ هي الاستقصاء الأمثل والمؤكد."},{"f":"نمط امتحاني: شابة 20 سنة بكتلة ثدي غير مؤلمة قطرها 2 سم — التشخيص الأرجح؟","b":"ورم غدي ليفي (Fibroadenoma) — كتلة الشابة الكلاسيكية؛ ولا يُشاهد غالبًا في الأعمار المتقدمة."},{"f":"نمط امتحاني: سيدة بكتل عديدة في الثديين تصبح مؤلمة قبل الدورة وتخف بعدها — التشخيص؟","b":"الداء الليفي الكيسي (Fibrocystic disease) — النمط الكلاسيكي المرتبط بالدورة الشهرية."},{"f":"نمط امتحاني: مسنة 60 سنة بطفح أحمر أكزيمائي مع حكة في الحلمة واللعوة بلا كتل مجسوسة — ما الإجراء الأفضل؟","b":"خزعة من الآفة — النمط الكلاسيكي لداء باجيت (Paget's disease) في الحلمة."},{"f":"فرّق: كل ما يلي من عوامل سوء إنذار سرطان الثدي ما عدا؟ (كبر الحجم / إصابة العقد / الدرجة العالية / إيجابية مستقبلات الإستروجين)","b":"إيجابية مستقبلات الإستروجين (ER+) — ليست عامل سوء إنذار بل عامل إنذار جيد وتنبؤ بالاستجابة الهرمونية."},{"f":"نقطة ذهبية: نز حليبي من الحلمة عند سيدة غير حامل وغير مرضع — غالبًا يترافق مع؟","b":"الورم الغدي النخامي (Prolactinoma) — فرط برولاكتين الدم."},{"f":"نقطة ذهبية: هل علاج التثدي (Gynecomastia) جراحي باستئصال الثدي المصاب دائمًا؟","b":"لا — العبارة خاطئة؛ التثدي يُدبَّر أولًا بعلاج السبب والمراقبة، والجراحة ليست حتمية دائمًا."},{"f":"فرّق: الجراحة المحافظة للثدي — هل تتعلق بمكان الورم؟ ومتى لا يُستطب الاستئصال الربعي؟","b":"نعم تتعلق بمكان الورم (العبارة النافية خاطئة) — ولا يُستطب الاستئصال الربعي مع التكلسات الناعمة المنتشرة بالثدي."}]},{"t":"الجراحة التنظيرية وجراحة البدانة والعناية حول الجراحية","cards":[{"f":"نقطة ذهبية: ما الاختلاط الأكثر خطورة لجراحة البدانة؟","b":"التسريب من المفاغرة (Anastomotic leak) — هو الأخطر على الإطلاق."},{"f":"قاعدة ذهبية: هل شفط الدهون (Liposuction) من عمليات جراحة البدانة؟","b":"لا أبدًا — شفط الدهون إجراء تجميلي لنحت القوام وليس من جراحة البدانة."},{"f":"نقطة ذهبية: جراحة البطن التنظيرية — هل تُجرى تحت التخدير القطني؟","b":"لا — التخدير العام حصرًا (بسبب استرواح الصفاق بغاز CO2 وتأثيراته التنفسية والدورانية)."},{"f":"نقطة ذهبية: ما العلامة الأكثر أهمية في التفاعل الانحلالي الحاد لنقل الدم لدى المريض اليقظ؟","b":"انخفاض الضغط الشرياني (Hypotension) — الأهم لأنه يدل على الصدمة ويستدعي إيقاف النقل والإنعاش الفوري."}]}]},{"s":"الجراحة البولية","topics":[{"t":"إنتانات الجهاز البولي، سل السبيل البولي، وزرع الكلية","cards":[{"f":"نمط امتحاني: التهاب مثانة مزمن معند على المعالجة الصحيحة — ما التشخيص الأكثر احتمالًا؟","b":"سل المثانة (Bladder tuberculosis) — التهاب المثانة المزمن المعند على الصادات يوجه للسل البولي."},{"f":"نقطة ذهبية: ما الاستقصاء الأدق لتشخيص التهاب الحويضة والكلية (Pyelonephritis)؟","b":"الطبقي المحوري مع الحقن (Contrast CT) — هو الأدق لتشخيص التهاب الحويضة والكلية."},{"f":"نقطة ذهبية: الانتان الفعال — هل هو مضاد استطباب نسبي لزرع الكلية؟","b":"لا — الانتان الفعال مضاد استطباب مطلق (وليس نسبيًا) لزرع الكلية."}]},{"t":"الحصيات البولية، انسداد الطرق البولية، والأسر البولي","cards":[{"f":"نقطة ذهبية: ما أفضل طريقة لعلاج حصيات الكلية الكبيرة (أكبر من 2.5 سم)؟","b":"استخراج الحصيات الكلوية عبر الجلد (PCNL - Percutaneous nephrolithotomy) — الخيار الأفضل للحصيات الكبيرة."},{"f":"فرّق: حصاة أسفل الحالب 0.5 سم مع استسقاء منذ أسبوع VS حصاة أسفل الحالب 1 سم مع استسقاء — التدبير؟","b":"0.5 سم: استئصال بتنظير الحالب (Ureteroscopy). 1 سم: تفتيت الحصاة عبر التنظير مع وضع قثطرة حالبية (Stent)."},{"f":"من سؤال حقيقي: حصاة قرن وعل (Staghorn) أكبر من 5 سم والكلية وظيفية 10% بالومضانية — ما التدبير المفضل؟","b":"استئصال الكلية جراحيًا (Nephrectomy) — كلية شبه متوقفة وظيفيًا مع حصاة قرن وعل = استئصال."},{"f":"نقطة ذهبية: ما أدق وسيلة لتشخيص حصيات الحالب؟","b":"الطبقي المحوري دون حقن (Non-contrast CT) — الأدق لحصيات الحالب."},{"f":"قاعدة ذهبية: القولنج الكلوي (Renal colic) — هل يترافق بترفع حروري؟","b":"لا أبدًا — الترفع الحروري ليس من القولنج الكلوي؛ الحرارة تعني انتانًا مرافقًا (التهاب حويضة وكلية انسدادي = إسعاف)."},{"f":"نقطة ذهبية: هل يفيد تحميض البول في علاج حصيات السيستين (Cystine)؟","b":"لا — حصيات السيستين تُعالَج بقلونة البول (وليس تحميضه)."},{"f":"نقطة ذهبية: الحصيات الكلوية تسبب كل المضاعفات التالية ما عدا؟ (انسداد / انتان / استسقاء / التهاب كبب وكلية)","b":"التهاب الكبب والكلية (Glomerulonephritis) — ليس من مضاعفات الحصيات الكلوية."}]},{"t":"رضوض وأذيات السبيل البولي (الكلية، الحالب، المثانة، والإحليل)","cards":[{"f":"نقطة ذهبية: متى تكثر مصادفة أذيات الإحليل الرضية؟","b":"بعد الافتراق العاني (Pubic diastasis) — كسور الحوض مع تباعد العانة هي السياق الكلاسيكي لأذية الإحليل."},{"f":"فرّق: رضوض الكلية — ما الآلية الأكثر شيوعًا؟ وهل العلاج جراحي دومًا؟","b":"الآلية الأشيع: الرض الكليل (Blunt trauma) — وليس النافذ. والعلاج ليس جراحيًا دومًا (كثير من رضوض الكلية تُدبَّر محافظًا)."},{"f":"نقطة ذهبية: ما الفحص الأكثر موثوقية في رضوض الكلية؟","b":"الطبقي المحوري للبطن مع الحقن (Contrast CT) — الأكثر موثوقية؛ والإيكو أبسط وسيلة تشخيصية أولية."},{"f":"نقطة ذهبية: البيلة الدموية — هل هي من التظاهرات الدالة على نزف مهم خلف البريتوان عقب رض كلية؟","b":"لا — البيلة الدموية علامة موضعية على أذية السبيل البولي وليست دالة على حجم النزف خلف البريتوان."}]},{"t":"ضخامة البروستات الحميدة والمثانة العصبية","cards":[{"f":"فرّق: المثانة العصبية الرخوة (Flaccid) — هل تترافق بزيادة تقلصات عضلة المثانة؟","b":"لا — الرخوة = نقص/غياب التقلصات مع احتباس؛ زيادة التقلصات من صفات المثانة التشنجية (Spastic)."},{"f":"من سؤال حقيقي: مسن 78 سنة بضخامة موثة كبيرة + رتج مثانة كبير + حصاة مثانة 3 سم + استسقاء كلوي — ما التدبير الأفضل؟","b":"استئصال الموثة والرتج والحصاة جراحيًا — الاختلاطات المتراكمة (رتج + حصاة + استسقاء) تستطب الجراحة المفتوحة الشاملة."},{"f":"نقطة ذهبية: في تدبير المثانة التشنجية — هل يُجرى خزع المعصرة عند الإناث؟","b":"لا — خزع المعصرة (Sphincterotomy) عند الإناث ليس من تدبير المثانة التشنجية."}]},{"t":"التشوهات الخلقية البولية وأمراض الكلية الكيسية","cards":[{"f":"نمط امتحاني: طفلة 5 سنوات بإنتان بولي مزمن ناكس — ما التشخيص الأكثر احتمالًا؟","b":"الجذر المثاني الحالبي (Vesicoureteral reflux - VUR) — أشيع سبب للإنتان البولي الناكس عند الأطفال."},{"f":"فرّق: دسامات الإحليل الخلفي (Posterior urethral valves) — هل يتوسع الإحليل القضيبي؟ وهل تضمر عضلة المثانة؟","b":"لا للاثنين — يتوسع الإحليل الخلفي القريب للدسامات (لا القضيبي)، وعضلة المثانة تتضخم وتتسمك (لا تضمر) بسبب الانسداد المزمن."},{"f":"نقطة ذهبية: القيلة الحالبية (Ureterocele) — هل هي ثنائية الجانب في أغلب الحالات؟","b":"لا — وحيدة الجانب في أغلب الحالات."},{"f":"نقطة ذهبية: الكلية متعددة الكيسات وحيدة الجانب (Multicystic kidney) — هل العلاج استئصال الكلية؟","b":"لا — تُراقب (تضمر تلقائيًا غالبًا)؛ الاستئصال ليس العلاج."},{"f":"قاعدة ذهبية: الكيسة الكلوية البسيطة (Simple cyst) — هل هي نادرة الحدوث؟","b":"لا — شائعة جدًا (تزداد مع العمر) وليست نادرة."},{"f":"نقطة ذهبية: في كلية نعل الفرس (Horseshoe kidney) — الكليتان أقرب للخط الناصف، فهل هما أعلى من الموضع الطبيعي؟","b":"لا — أخفض من الموضع الطبيعي (تعثر هجرتهما الصاعدة عند الشريان المساريقي السفلي)."},{"f":"نقطة ذهبية: التضاعف الحالبي غير التام (Partial) VS التام (Complete) — أيهما أشيع؟","b":"غير التام أشيع من التام."},{"f":"نقطة ذهبية: هل استئصال الكيسات الجراحي هو العلاج المثالي للداء الكلوي متعدد الكيسات؟","b":"لا — العلاج محافظ/داعم؛ الاستئصال الجراحي للكيسات ليس العلاج المثالي."}]},{"t":"أورام الجهاز البولي والأعضاء التناسلية الذكرية","cards":[{"f":"نقطة ذهبية: أين أول ما ينتقل سرطان الموثة (البروستات)؟","b":"إلى الفقرات (العظم المحوري) — النقائل العظمية هي الأولى والأشيع."},{"f":"نقطة ذهبية: نقائل عظمية لسرطان البروستات — ما الإجراء الأول؟","b":"العلاج الهرموني (Androgen deprivation) — هو الخط الأول عند النقائل."},{"f":"قاعدة ذهبية: هل يسبب استئصال الخصيتين انقطاعًا كاملًا للأندروجين؟","b":"لا — يبقى أندروجين قشر الكظر (Adrenal androgens)؛ الانقطاع غير كامل."},{"f":"فرّق: PSA — هل هو نوعي لتأكيد تشخيص سرطان البروستات؟","b":"لا — يرتفع أيضًا في الضخامة الحميدة والالتهاب والرض؛ التشخيص المؤكد بالخزعة."},{"f":"فرّق: العلاج الأساسي لسرطان البروستات في المراحل الباكرة VS المرحلة الرابعة؟","b":"الباكرة: الاستئصال الجذري/الإشعاع (وليس الهرموني). الرابعة: لا يُستطب الاستئصال الجذري (العلاج هرموني/جهازي)."},{"f":"نقطة ذهبية: الحقن بالـ BCG داخل المثانة — هل يُستطب لأورام المرحلة T0؟","b":"لا — يُستخدم للأورام السطحية (Ta/T1/CIS) لا للمرحلة T0."},{"f":"نقطة ذهبية: هل البيلة الدموية من علامات سوء إنذار سرطان الكلية؟ وهل توجد قصة عائلية في سرطان البروستات؟","b":"البيلة الدموية ليست من علامات سوء إنذار سرطان الكلية. والقصة العائلية موجودة في سرطان البروستات (عامل خطر معروف)."}]},{"t":"آفات الخصية وكيس الصفن، العقم الذكري، واعتلالات الذكورة","cards":[{"f":"قاعدة ذهبية: بعد فشل الرد اليدوي لانفتال الخصية — المعالجة؟ وخلال كم ساعة كحد أقصى؟","b":"جراحية في كل الحالات — والنافذة الذهبية 6 ساعات (وليس 48 ساعة) قبل فقدان الخصية."},{"f":"نمط امتحاني: ذكر 12 سنة بألم حاد بنصف الصفن — التشخيص الأكثر احتمالًا؟","b":"انفتال الحبل المنوي (Testicular torsion) — يصيب المراهقين والشباب (وليس العقد الرابع غالبًا)."},{"f":"فرّق: دوالي الحبل المنوي (Varicocele) — أي جهة أشيع؟ وهل العلاج جراحي في كل الحالات؟","b":"الجهة اليسرى أشيع (وليس اليمنى). والعلاج ليس جراحيًا في كل الحالات — والوقاية من الضعف الجنسي ليست استطبابًا للجراحة."},{"f":"من سؤال حقيقي: طفل بعمر سنة بخصية مجسوسة في القناة الإربية اليسرى — ما الإجراء الأمثل؟","b":"الإنزال الجراحي للخصية الهاجرة (Orchidopexy) — بعد عمر السنة لا تُنتظر الهجرة التلقائية."},{"f":"نقطة ذهبية: ما أشيع مكان للخصية المنتبذة (Ectopic testis)؟","b":"الحلقة الإربية السطحية (Superficial inguinal ring) — أشيع أماكن الانتباذ."},{"f":"نقطة ذهبية: ضخامة صفن يسرى عند كهل — هل الفتق الإربي المباشر من التشخيص التفريقي؟","b":"لا — كتلة الصفن اليسرى عند الكهل: قيلة مائية، ورم خصية، دوالي... والفتق الإربي المباشر ليس منها."}]}]},{"s":"جراحة الأوعية","topics":[{"t":"رضوض الشرايين والانسدادات الحادة","cards":[{"f":"نقطة ذهبية: ما العلامات السريرية الباكرة لنقص التروية الحاد في الطرف؟","b":"الخدر وشواش الحس (Paresthesia) — من العلامات الباكرة؛ أما التبقع (Mottling) والزرقة فعلامات متأخرة."},{"f":"نمط امتحاني: مريض برجفان أذيني راجع بألم حاد وشحوب في الطرف السفلي — ما التدبير الأفضل؟","b":"استئصال الصمة — استخراج الخثرة بقثطرة فوغارتي (Fogarty) عبر شق جراحي؛ والرجفان الأذيني هو أشيع أسباب الانسداد الشرياني الحاد."},{"f":"نقطة ذهبية: بعد إعادة التروية لطرف مسدود بـ24 ساعة: ألم + عجز عن الثني الظهري للقدم — التشخيص؟","b":"تناذر الحجرات (Compartment syndrome) — اختلاط إعادة التروية الكلاسيكي."},{"f":"نقطة ذهبية: في الانسداد الشرياني الحاد الصمي (بدأ منذ 5 ساعات) — هل التصوير الشرياني الظليل ضروري قبل الجراحة؟","b":"لا — لا يُؤخَّر التداخل الإسعافي بالتصوير؛ الاستئصال الفوري أولى."},{"f":"نقطة ذهبية: ما السمة المميزة للمرحلة المتقدمة/النهائية من نقص التروية الشريانية الحادة؟","b":"الشلل الحسي والحركي في القدم والساق — علامة المرحلة الحرجة المتأخرة."},{"f":"نقطة ذهبية: كل ما يلي من أسباب الصمات المحيطية ما عدا؟ (رجفان أذيني / خثرة بطينية / خثار وريدي عميق)","b":"الخثار الوريدي العميق (DVT) — الصمات المحيطية شريانية المصدر (قلبية) لا وريدية."},{"f":"فرّق: علامات الانسداد الشرياني الحاد (6P) — هل الاحمرار وقصور الصافن وتموت الأصابع منها؟","b":"لا — لا احمرار (بل شحوب)، ولا قصور صافن، وتموت الأصابع علامة متأخرة لا باكرة."},{"f":"نقطة ذهبية: في الانسداد الحاد على مستوى الشريان الفخذي الأصلي — هل التبقع/الزرقة هي العلامة الأولى؟","b":"لا — العلامة الأولى الألم والخدر وشواش الحس؛ التبقع والزرقة متأخرتان."}]},{"t":"التصلب العصيدي ونقص التروية المزمن","cards":[{"f":"فرّق: داء لوريش (Leriche) — النبض الفخذي مجسوس؟ وحرارة الأطراف السفلية؟","b":"النبض الفخذي غائب (نبض فخذي مجسوس عبارة خاطئة) — والأطراف باردة لا سوية/مرتفعة؛ وغياب النبض المأبضي ليس من صفاته."},{"f":"نقطة ذهبية: الاستقصاء الأولي لمريض بعرج متقطع (Claudication)؟ وللاشتباه بإصابة شريانية مسدودة مزمنة؟","b":"العرج المتقطع: مؤشر الضغط الكاحلي العضدي (ABI). الإصابة المسدودة المزمنة: الدوبلكس الملون (Duplex)."},{"f":"قاعدة ذهبية: في تدبير العرج المتقطع الوعائي — هل نقلل المشي لتجنب الألم؟","b":"لا أبدًا — برنامج المشي المنتظم هو حجر الأساس (يُحسّن المسافة)؛ تقليل المشي عبارة خاطئة."},{"f":"نقطة ذهبية: الآفات الأبهرية الحرقفية السادة المنتشرة — ما المجازة المفضلة؟","b":"مجازة أبهرية فخذية ثنائية الجانب (Aortobifemoral bypass) — هي المفضلة للآفات المنتشرة."}]},{"t":"تسلخ الأبهر وأمهات الدم الشريانية","cards":[{"f":"نمط امتحاني: مسن بارتفاع ضغط شرياني شكا فجأة من ألم صدري كطعنة السكين ينتشر للظهر — التشخيص؟ وما العلامة المميزة؟","b":"تسلخ الأبهر (Aortic dissection) — والعلامة المميزة: افتراق النبض والضغط بين الطرفين العلويين."},{"f":"نقطة ذهبية: كيف يُعالَج تسلخ الأبهر من النوع A؟","b":"معالجة جراحية فورية — النوع A (الصاعد) إسعاف جراحي لا يقبل التأجيل."},{"f":"من سؤال حقيقي: رجل 65 سنة بأم دم أبهر بطني 7 سم راجع بألم حول السرة ينتشر للخلف — هل نعطي مسكنات ونراقب؟","b":"لا أبدًا — أم دم كبيرة عرضية = تمزق وشيك/حاصل؛ التدبير إسعافي جراحي لا مراقبة وتسكين."},{"f":"نمط امتحاني: كتلة نابضة مجسوسة تطورت بعد أسابيع-أشهر من جرح قاطع أنسي الفخذ — التشخيص؟","b":"أم دم كاذبة (Pseudoaneurysm) — النمط الكلاسيكي بعد الرض النافذ."},{"f":"نقطة ذهبية: الدراسة التشخيصية المختارة لأمهات دم الأبهر الصدرية؟ وللأبهرية البطنية (Gold standard)؟","b":"الصدرية: الطبقي المحوري مع الحقن. البطنية AAA: التصوير المقطعي متعدد الشرائح MSCTA."},{"f":"نقطة ذهبية: ما أشيع مواقع فوهة الدخول (Entry tear) في تسلخ الأبهر؟","b":"الأبهر الصاعد (Ascending aorta) — هو الأشيع."},{"f":"فرّق: كل ما يلي من أسباب الوفاة المبكرة في تسلخ الأبهر الصاعد ما عدا؟ (تمزق الأبهر / اندحاق تاموري / قصور أبهري حاد / نقص التروية المحيطية)","b":"نقص التروية المحيطية — ليست من أسباب الوفاة المبكرة؛ الأسباب: التمزق والاندحاق التاموري والقصور الأبهري."},{"f":"نقطة ذهبية: كل ما يلي من مضاعفات النواسير الشريانية الوريدية ما عدا؟","b":"الصمة الرئوية — ليست من مضاعفات الناصور الشرياني الوريدي (مضاعفاته: قصور قلب عالِ النتاج، ضخامة الطرف)."}]},{"t":"المتلازمات الوعائية والتهابات الشرايين","cards":[{"f":"نمط امتحاني: شاب 30 سنة مدخن بشدة بنقص تروية طرف سفلي + عرج متقطع + التهاب أوردة سطحية — التشخيص؟","b":"داء برغر (Buerger's disease / Thromboangiitis obliterans) — يصيب الشباب المدخنين (وليس شائعًا فوق 65)؛ والتدخين عامل مؤهب أساسي."},{"f":"فرّق: داء تكاياسو (Takayasu) — أي الأطراف تُصاب أشيع: العلوية أم السفلية؟","b":"العلوية — يصيب شرايين القوس الأبهرية (الطرفين العلويين) أكثر من السفليين."},{"f":"نقطة ذهبية: نقص تروية دماغية — ما الإجراء الأول؟ وهل القثطرة القلبية من الإجراءات التشخيصية؟","b":"الأول: مرنان الدماغ (MRI). والقثطرة القلبية ليست من إجراءات تشخيص نقص التروية الدماغية."},{"f":"نقطة ذهبية: فقد الرؤيا العابر (Amaurosis fugax) في تضيق الشريان السباتي — في العين نفس جهة التضيق أم المقابلة؟","b":"نفس الجهة (Ipsilateral) — فقد الرؤيا في العين المقابلة للتضيق عبارة خاطئة."},{"f":"نقطة ذهبية: متلازمة مخرج الصدر (Thoracic outlet syndrome) — هل الألم الصدري من أعراضها؟","b":"لا — الألم الصدري ليس من أعراضها (أعراضها: عصبية/وعائية في الطرف العلوي)."},{"f":"فرّق: نقص التروية المعوية ينجم عن إصابة المساريقي العلوي — وأي الشرايين ليس منها؟ (تحت الترقوة الأيسر / الفخذي الأصلي)","b":"كلاهما ليسا منها — لا تحت الترقوة الأيسر ولا الفخذي الأصلي من شرايين التروية المعوية."},{"f":"نقطة ذهبية: ما السبب الأكثر شيوعًا للقرحات (التقرحات) في الأطراف السفلية؟","b":"الأمراض الوريدية (Venous disease) — هي أشيع أسباب قرحات الساق."}]},{"t":"أمراض الأوردة والأوعية اللمفية","cards":[{"f":"فرّق: التهاب الوريد الخثري العميق (DVT) — هل غياب النبض المحيطي من علاماته؟","b":"لا — النبض المحيطي موجود في DVT (الآفة وريدية لا شريانية)؛ غياب النبض من علامات الانسداد الشرياني."},{"f":"نقطة ذهبية: ما العلاج الأكثر أهمية والأولي للخثار الوريدي العميق الحاد؟","b":"الهيبارين منخفض الوزن الجزيئي تحت الجلد (LMWH) — هو الخط الأول."},{"f":"فرّق: كل ما يلي من العوامل المؤهبة للـ DVT ما عدا؟ (الركودة / الرض / فرط الخثارية / ارتفاع شحوم الدم / ارتفاع الضغط الشرياني)","b":"ارتفاع شحوم الدم وارتفاع الضغط الشرياني — ليسا من مؤهبات DVT (المؤهبات: ثالوث فيرخو)."},{"f":"قاعدة ذهبية: D-dimer في التهاب الوريد الخثري — الإيجابي يشخص؟ والسلبي ينفي؟","b":"الإيجابي لا يشخص (غير نوعي) — والسلبي ينفي (حساسية عالية)؛ إيجابية D-dimer تنفي العبارة خاطئة والتشخيصية خاطئة."},{"f":"نقطة ذهبية: ما العلاج الأساسي لالتهاب الوريد الخثري السطحي (Superficial thrombophlebitis)؟","b":"مضادات الالتهاب غير الستيرويدية (NSAIDs) — العلاج الأساسي للحالة السطحية."},{"f":"نقطة ذهبية: داء رينو (Raynaud) — هل المسبب الرئيسي هو التصلب العصيدي؟","b":"لا — رينو تشنج وعائي (Vasospasm) استجابة للبرد/الشدة؛ التصلب العصيدي ليس مسببه الرئيسي."},{"f":"من سؤال حقيقي: سكري بغنغرينا (تموت) في أصابع القدم — ما التدبير الأمثل؟","b":"محاولة التوسيع الوعائي (رأب الوعاء) أولًا ثم البتر — يُحاوَل إنقاذ الطرف قبل البتر."},{"f":"فرّق: استطبابات جراحة دوالي الطرف السفلي — هل الخثار الوريدي العميق منها؟ وهل العلاج دائمًا جراحي؟","b":"لا للاثنين — الخثار الوريدي العميق مضاد استطباب للجراحة (وليس استطبابًا)، والدوالي ليست دائمًا جراحية."},{"f":"فرّق: أعراض القصور الوريدي المزمن — هل الألم عند المشي الذي يزول بالتوقف منها؟","b":"لا — هذا نمط العرج الشرياني؛ القصور الوريدي: ثقل ووذمة مسائية وقرحات حول الكعب الأنسي."},{"f":"نقطة ذهبية: قرحة قصور الصافن القصير (Small saphenous) — هل تتوضع عادة في الحفرة المأبضية؟","b":"لا — القرحات الوريدية الكلاسيكية حول الكعب الأنسي (Gaiter area)؛ الحفرة المأبضية ليست موضعها المعتاد."}]}]},{"s":"الجراحة العصبية","topics":[{"t":"رضوض الدماغ والجمجمة والنزوف داخل القحف","cards":[{"f":"جحوظ نابض وحيد الجانب + نفخة مسموعة بالإصغاء على الحجاج = التشخيص؟","b":"ناسور سباتي كهفي (Carotid-cavernous fistula) — الثالوث: جحوظ نابض، احتقان ملتحمة، نفخة مسموعة."},{"f":"قاعدة ذهبية: كل نزف فوق الجافية (Epidural) هو ... حتى يثبت العكس؟","b":"منشأ شرياني (تمزق الشريان السحائي الأوسط غالبًا) + مظهر عدسي محدب على CT + إنذاره جيد مع التدخل المبكر."},{"f":"فرّق: فترة الصحو (lucid interval) بين فقد الوعي البدئي والتدهور التالي تُشاهد في أي نزف؟","b":"النزف فوق الجافية (Epidural) — حاد. أما الأعراض الخفيفة المتأخرة لأيام/أسابيع فهي صفة النزف تحت الجافية المزمن (Subdural)."},{"f":"أشيع أنماط النزف داخل القحف (Intracranial Hemorrhage) هو؟","b":"النزف تحت العنكبوتية (Subarachnoid) — يرافق معظم رضوض الرأس المتوسطة والشديدة."},{"f":"العرض البادري الأشيع للنزف تحت العنكبوتية؟","b":"صداع شديد مفاجئ (صداع الرعد — أسوأ صداع في الحياة)."},{"f":"مسن يتناول مميعات، بعد 4 أسابيع من رض رأس يتظاهر بتغيم وعي وإقياءات = التشخيص؟","b":"نزف تحت الجافية مزمن (Chronic subdural) — بطء التراكم، وصفية للمسنين على المميعات."},{"f":"العلامة المؤكدة (Pathognomonic) لكسر قاعدة الجمجمة؟","b":"نز السائل الدماغي الشوكي CSF من الأذن (Otorrhea) أو الأنف (Rhinorrhea) — يثبت تمزق السحايا."},{"f":"كسر قاعدة قحف + سيلان CSF: ماذا يُمنع تمامًا؟","b":"وضع دكة أنفية + وضع أنبوب أنفي معدي — العلاج محافظ."},{"f":"في تكدم جذع الدماغ: أي عبارة خاطئة؟","b":"فقد وعي مؤقت يزول سريعًا — الصواب: سبات مطول + وضعية نزع المخ (فرط بسط) + حدقات غير متفاعلة."},{"f":"فرّق: نسيان ما بعد الرض vs نسيان ما قبل الرض في الارتجاج؟","b":"النمطي في الارتجاج: نسيان ما بعد الرض (تقدمي) — أما نسيان الأحداث قبل الحادثة فليس النمط المعتاد."},{"f":"متلازمة ما بعد الارتجاج: ماذا يُستثنى من مظاهرها؟","b":"الشلل النصفي أو الضعف الحركي البؤري الدائم — مظاهرها وظيفية: صداع، دوار، تغير شخصية، قلق."},{"f":"من استطبابات قبول رض الرأس بالمشفى: ماذا ليس استطبابًا؟","b":"جروح الفروة المعزولة دون علامات عصبية — الاستطبابات: تغيم الوعي، نز CSF، كسر، علامات بؤرية."},{"f":"علاج خراج الدماغ القياسي: أي إجراء ليس جزءًا منه؟","b":"البزل المتكرر عبر ثقب الجمجمة كعلاج وحيد ودائم — القياسي: صادات وريدية طويلة + تفريغ/استئصال الكبسولة."}]},{"t":"أذيات النخاع الشوكي وأمراض العمود الفقري","cards":[{"f":"تناذر براون سيكوار (Brown-Sequard): شلل حركي موافق + فقد حس الألم والحرارة...؟","b":"مقابل (contralateral) أسفل مستوى الإصابة — مع فقد الحس العميق موافق."},{"f":"أسوأ المتلازمات النخاعية إنذارًا؟","b":"متلازمة النخاع الأمامي (Anterior cord syndrome) — شلل + فقد حس الألم/الحرارة مع حفظ الحس العميق."},{"f":"فرّق: العرج العصبي المتقطع vs العرج الوعائي؟","b":"العصبي: ألم يزداد بالمشي والانحناء للخلف ويخف بالانحناء للأمام والجلوس + نبض طبيعي. الوعائي: أعراض بعد مسافة مشي ثابتة."},{"f":"المظهر الباكر لانضغاط الحبل الشوكي (مرحلة صدمة النخاع): اشتداد منعكسات أم غيابها؟","b":"غياب المنعكسات (شلل رخو) في المرحلة الباكرة — اشتدادها يأتي لاحقًا."},{"f":"في إصابة الحبل الظهري (الصدري): الشلل نصفي أم سفلي؟","b":"شلل سفلي (Paraplegia) — الطرفان السفليان، مع حفظ وظيفة الطرفين العلويين."},{"f":"أفضل وسيلة تصوير لتشخيص فتق النواة اللبية؟","b":"الرنين المغناطيسي (MRI) — يظهر القرص والجذور والكيس السحائي بوضوح."}]},{"t":"إصابات الأعصاب المحيطية والضفائر العصبية","cards":[{"f":"هبوط القدم أشيع أسبابه؟","b":"فتق نواة لبية قطنية بالمستوى ق4-ق5 (إصابة الجذر ق5 — العطف الظهري للقدم)."},{"f":"هبوط اليد علامة إصابة أي عصب؟","b":"العصب الكعبري (Radial) — شلل العضلات الباسطة للرسغ والأصابع."},{"f":"علامة فرومنت (Froment) في اليد ترى في إصابة أي عصب؟","b":"العصب الزندي (Ulnar) — ضعف العضلة المقربة للإبهام."},{"f":"فرّق: ضمور عضلات الضرة (Thenar) vs ضمور بين العظام (Interossei)؟","b":"الضرة: إصابة العصب الناصف (Median). بين العظام: إصابة العصب الزندي (Ulnar)."},{"f":"متلازمة النفق الرسغي: متى تشتد الأعراض الحسية؟","b":"ليلًا وعند الاستيقاظ صباحًا — بسبب عطف الرسغ أثناء النوم."},{"f":"العلاج المحافظ في متلازمة النفق الرسغي: هل هو الخيار الأفضل دومًا؟","b":"لا — الحالات الشديدة/المترقية/مع ضمور تستدعي التحرير الجراحي."},{"f":"المنعكس الداغصي (الركبي): يغيب في إصابة العصب الوركي أم لا؟","b":"لا يغيب — يتبع العصب الفخذي والجذور القطنية العليا. إصابة الوركي: هبوط قدم + غياب المنعكس العقبي."}]},{"t":"التشوهات العصبية الخلقية واستسقاء الدماغ","cards":[{"f":"الاستسقاء عند الرضع (دروز مفتوحة): ماذا يُشاهد؟","b":"زيادة محيط الجمجمة + توتر اليافوخ الأمامي + علامة غروب الشمس + توسع أوردة الفروة."},{"f":"لماذا لا تُشاهد وذمة حليمة العصب البصري في استسقاء الرضع؟","b":"الدروز المفتوحة تبدد الضغط بتمدد الرأس — الوذمة تُشاهد مع دروز مغلقة (بالغين)."},{"f":"النزف تحت العنكبوتية يسبب استسقاءً انسداديًا أم تواصليًا؟","b":"تواصليًا (خلل الامتصاص) — أما الانسدادي فمن النزوف داخل البطينات."},{"f":"القيلة السحائية (فتق السحايا فقط) vs القيلة النخاعية السحائية: الإنذار العصبي؟","b":"السحائية: إنذار عصبي جيد. النخاعية السحائية: سيئة — الجراحة تغلق العيب لكن لا تشفي الأعراض العصبية."}]},{"t":"أورام الجهاز العصبي المركزي","cards":[{"f":"عمى شقي صدغي مزدوج (Bitemporal hemianopia) = ورم؟","b":"ورم نخامي (Pituitary) — يضغط التصالبة البصرية (Optic chiasm)."},{"f":"ممنوع مطلقًا في الكتلة الدماغية؟","b":"بزل CSF القطني — خطر الانفتاق الدماغي المميت بتدرج الضغط."},{"f":"أورام الزاوية الجسرية المخيخية: نمط الأعصاب القحفية المصابة؟","b":"ق5-ق7-ق8 (الثلاثي التوائم، الوجهي، السمعي) — ورم العصب السمعي هو النمط."},{"f":"أشيع أورام النخاع داخل السحايا خارج النخاع (IDEM)؟","b":"الورم السحائي (Meningioma)."}]},{"t":"الحوادث الوعائية الدماغية والتقييم العصبي","cards":[{"f":"النشبة الدماغية العابرة (TIA): مدة الأعراض؟","b":"تزول تمامًا خلال أقل من 24 ساعة دون عقابيل."},{"f":"في النشبة الدماغية الحادة: ماذا لا يُعطى مباشرة قبل التصوير؟","b":"الهيبارين — يجب نفي النزف بالـCT أولًا."},{"f":"الموت الدماغي: الحدقات متوسعة ومتفاعلة ببطء — صح أم خطأ؟","b":"خطأ — متوسعة وثابتة غير متفاعلة + سبات تام + غياب المنعكسات القرنية + اعتماد كامل على المنفسة."},{"f":"تغيم الوعي قبل البزل القطني: بزل مباشرة أم تصوير أولًا؟","b":"تصوير طبقي أولًا لنفي الكتلة/ارتفاع الضغط — البزل المباشر ممنوع."},{"f":"مضادات استطباب البزل القطني تشمل: وذمة حليمة العصب البصري، الوارفارين العلاجي، نقص الصفيحات الشديد — الأسبرين وحده مضاد استطباب؟","b":"لا — الأسبرين وحده ليس مضاد استطباب."},{"f":"أشيع اختلاط مبكر (دقائق-ساعات) للتخدير الشوكي؟","b":"هبوط الضغط — حصار ودي وتوسع وعائي."},{"f":"من اختلاطات البزل القطني المحتملة: الشلل النصفي؟","b":"لا — المحتملة: صداع ما بعد البزل، إنتان، نزف/ورم دموي."},{"f":"البزل القطني المدمى يرتبط تشخيصيًا بأي نزف؟","b":"النزف تحت العنكبوتية (يُفرَّق عن الرض الرضحي بالزانثوكروميا)."},{"f":"أي إجراء ممنوع كتخدير أساسي لاستئصال فص الرئة؟","b":"التخدير النصفي (شوكي/فوق الجافية) — يصلح لجراحات تحت مستوى السرة فقط."},{"f":"المعيار الذهبي للتمييز بين الإقفار الحاد والنزف الدماغي؟","b":"الرنين المغناطيسي (MRI) — الطبقي بدون ظليل بديل أقل حساسية للإقفار المبكر."},{"f":"تخطيط الدماغ (EEG): من استقصاءات نقص التروية الدماغية الروتينية؟","b":"لا — الروتينية: دوبلر السباتيين، إيكو + تخطيط قلب، قياس الضغط."}]},{"t":"اصابه العصبون المحرك","cards":[{"f":"إصابة العصبون المحرك السفلي: الشلل رخو أم تشنجي؟","b":"شلل رخو (Flaccid) — مع نقص/غياب المنعكسات الوترية، والضمور يظهر بعد أسابيع."},{"f":"المنعكس الأخمصي بالانبساط (بابنسكي): علوي أم سفلي؟","b":"علوي — ليس من مظاهر إصابة العصبون المحرك السفلي."},{"f":"فرّق: إصابة العصبون العلوي vs السفلي في المنعكسات؟","b":"علوي: فرط منعكسات + منعكسات مرضية (بابنسكي). سفلي: نقص/غياب المنعكسات."}]},{"t":"ملاحظات متفرقه","cards":[{"f":"علامة لازيك (Lasegue): منعكس مرضي أم اختبار؟","b":"اختبار استطالة للعصب الوركي — ليست منعكسًا مرضيًا (المرضية: بابنسكي، هوفمان، الخطم، المص)."},{"f":"من علامات التهاب السحايا: علامة لازيك؟","b":"لا — علامات السحايا: صلابة النقرة، برودزنسكي، كيرنيغ. لازيك للجذر الوركي."},{"f":"المنعكسات المرضية عند البالغين تشمل؟","b":"بابنسكي، هوفمان، الخطم، المص — ظهورها يدل على آفة العصبون الحركي العلوي."}]},{"t":"سلم تقييم الوعي","cards":[{"f":"مقياس غلاسكو للغيبوبة (GCS) يقيّم أي معايير؟","b":"فتح العينين + الاستجابة اللفظية + أفضل استجابة حركية."},{"f":"أعلى درجة في GCS؟","b":"15 — وعي تام (إصابة خفيفة عند 13-15)."},{"f":"هل الاستجابة الحدقية للضوء من معايير GCS؟","b":"لا — المعايير ثلاثة فقط: عين، كلام، حركة."}]},{"t":"أسئلة متفرقة","cards":[{"f":"السبب الرئيسي للأذية النخاعية المتأخرة بعد كسر الفقرات؟","b":"تشكل ندبة ليفية مفرطة (دشبذ) تضغط النخاع تدريجيًا — الورم الدموي سبب باكر."},{"f":"الأذية النخاعية بالدشبذ الليفي: باكرة أم متأخرة بعد الكسر؟","b":"متأخرة: بعد فترة من الكسر — وليست باكرة كالورم الدموي أو تبدل الشظايا."},{"f":"قاعدة ذهبية: الاضطراب الإحساسي في إصابة النخاع الظهري يكون على مستوى الإصابة أم أسفلها؟","b":"الخلل الوظيفي يحدث أسفل مستوى الإصابة لا على مستواه — علامة بيفور الإيجابية معهودة."}]}]},{"s":"الجراحة العظمية","topics":[{"t":"مبادئ الرضوض والتقييم وتدبير الكسور واختلاطاتها العامة","cards":[{"f":"قاعدة ذهبية: التثبيت في الكسر المفتوح يكون داخليًا أم خارجيًا؟","b":"كسر الساق المفتوح جرح ملوث — التثبيت الداخلي في حقل ملوث = إنتان عميق؛ المثبت الخارجي يؤمّن الثبات بعيدًا عن التلوث ويسمح بالتنضير."},{"f":"عدم الاندمال شائع في: الزورقي، جسم العضد، عنق الفخذ داخل المحفظة — ماذا يُستثنى؟","b":"كسر كولس (Colles) — خارج مفصلي غني بالتروية يندمل عادة."},{"f":"من اختلاطات الاضطجاع الطويل: إنتان بولي، قرحة اضطجاعية، ذات رئة ركودية — ماذا يُستثنى؟","b":"الصمة الشحمية — تحرر نقي العظم في الكسور الطويلة، لا من الركودة."},{"f":"أعراض تناذر الأسطوانة الجبسية الضاغطة: الإجراء الفوري؟","b":"خزع الجهاز الجبسي أو تبديله فورًا — التأخير يهدد تروية الطرف."}]},{"t":"كسور وخلوع الطرف العلوي والكتف والرسغ","cards":[{"f":"الأكثر فعالية في تدبير خلع الكتف الناكس؟","b":"الجراحي (إصلاح بانكارت) — السبب آفة تشريحية (بانكارت/هيل-ساكس) لا يصلحها التثبيت."},{"f":"بعد نوبة اختلاج أو صدمة كهربائية: أي خلع كتف يُتوقع؟","b":"خلع الكتف الخلفي — تقلص العضلات المدورة داخليًا يدفع الرأس للخلف."},{"f":"أشيع اختلاط عصبي لكسر جسم العضد؟","b":"أذية العصب الكعبري (Radial) — يلتف حول جسم العضد في الثلم الحلزوني."},{"f":"تناذر فولكمان (تقلص إقفاري لليد) يحدث كاختلاط لأي كسر؟","b":"كسر فوق اللقمتين العضديتين — أذية الشريان العضدي → متلازمة حجرات → تقلص فولكمان."},{"f":"اختلاط متأخر شائع لكسر كولس: تمزق وتر أي عضلة؟","b":"باسطة الإبهام الطويلة (EPL) — اهتراء بالاحتكاك على حدبة ليستر بعد أسابيع."},{"f":"الأكثر حساسية لكشف كسر الزورقي الخفي؟","b":"الرنين المغناطيسي (MRI) — الأشعة البسيطة قد تبقى سلبية لأسابيع."},{"f":"فرّق: كسر كولس vs كسر سميث في اتجاه التبدل؟","b":"التبدل الظهري (تشوه شوكة العشاء) — التبدل الراحي لكسر سميث."},{"f":"أشهر اختلاط لكسر العظم الزورقي؟","b":"النخرة الجافة — التروية الراجعة تُقطع عن القطب القريب."},{"f":"كسر الثلث العلوي للزند مع خلع رأس الكعبرة = ؟","b":"كسر مونتيغا (كسر الثلث العلوي للزند + خلع رأس الكعبرة)."}]},{"t":"كسور وخلوع الحوض والطرف السفلي والقدم والكاحل","cards":[{"f":"كسر معترض متبدل في جسم الفخذ عند شاب: العلاج الأمثل؟","b":"السفود داخل النقي (Intramedullary nail) — ثبات محوري + تحميل باكر."},{"f":"وضعية الطرف في خلع الورك الخلفي الرضي؟","b":"ثني + تقريب + دوران داخلي — العكس (دوران خارجي) للخلع الأمامي."},{"f":"كسر عنق فخذ متبدل عند مسن بعمر 75: العلاج الأفضل؟","b":"تبديل مفصل الورك (رأس الفخذ) — لتجنب النخرة والركودة القاتلة."},{"f":"كسر عنق فخذ داخل المحفظة عند شاب: العلاج الأفضل؟","b":"رد مغلق + تثبيت داخلي بالبراغي — الحفاظ على الرأس الأصلي أولوية."},{"f":"أشيع اختلاط لكسر عنق الفخذ داخل المحفظة؟","b":"النخرة الجافة (اللاوعائية) — تمزق الأوعية المغذية لرأس الفخذ."},{"f":"كسور الورك: داخل المحفظة أم خارجها أفضل إنذارًا؟","b":"خارج المحفظة (بين/تحت المدورين) — تروية غنية فتندمل بسهولة."},{"f":"لماذا سُمّي كسر عنق الفخذ «كسر الموت» عند تورنر؟","b":"كسر الموت = التهاب الوريد الخثري من الركودة المديدة → صمة رئوية."},{"f":"من اختلاطات كسر الحوض: أذية الإحليل/المثانة، صدمة نزفية — ماذا يُستثنى؟","b":"انفلات المصرات — عرض عصبي لا ينتج عن كسر الحوض نفسه."}]},{"t":"أذيات الأوتار والأربطة والغضاريف والمحفظة المفصلية","cards":[{"f":"الاختبار السريري الأكثر حساسية لتمزق الرباط المتصالب الأمامي (ACL)؟","b":"اختبار لاشمان (Lachman) — سحب الظنبوب للأمام والركبة بثني 20-30 درجة."},{"f":"أشيع الأربطة إصابة في أذية أربطة الركبة الحادة؟","b":"الرباط الجانبي الأنسي (MCL) — بآلية الإجهاد الأروح."},{"f":"من موجودات تمزق الغضروف الهلالي: ماذا يُستثنى؟","b":"اختبار الجارور (يقيّم الأربطة المتصالبة) — الموجودات الأخرى: إيلام الخط المفصلي، ماكموري إيجابي."},{"f":"لماذا لا يندمل التمزق المركزي للغضروف الهلالي؟","b":"غياب التروية الدموية — الثلث المركزي (المنطقة البيضاء) لا تصله تروية."},{"f":"خلع الكتف الأمامي الرضي: الآفة التشريحية المسؤولة عن النكس؟","b":"أذية بانكارت (Bankart) — انقلاع الشفا والمحفظة عن حافة الجوف العنابي."},{"f":"داء دوبيرتان (Dupuytren): مستوى التبدلات المرضية؟","b":"الصفاق الراحي — تليف عقدي يثبت الأصابع بوضعية عطف."}]},{"t":"جراحة عظام الأطفال وتشوهات العمود الفقري وصفائح النمو","cards":[{"f":"خلع ورك ولادي بعمر أسبوعين (بارلو/أورتولاني إيجابي): التدبير الأمثل؟","b":"جهاز بافلك (Pavlik) قبل 6 أشهر — يحافظ على العطف والتبعيد الفسيولوجي."},{"f":"أفضل اختبار لتشخيص خلع الورك الولادي ما حول الولادة؟","b":"الإيكو (الأمواج فوق الصوتية) قبل تعظم رأس الفخذ — بعد السنة يتعظم الرأس فيحجب الرؤية."},{"f":"داء بيرتس (Perthes): أكثر حركات الورك تأثرًا؟","b":"تحدد التبعيد والدوران الداخلي — العلامة السريرية الكلاسيكية."},{"f":"هدف العلاج في داء بيرتس؟","b":"منع تشوه رأس الفخذ — الاحتواء (containment) يبقيه كرويًا داخل الجوف الحقاني."},{"f":"انزلاق مشاش رأس الفخذ (SCFE): وضعية الطرف السفلي؟","b":"الدوران الخارجي مع تحدد الدوران الداخلي — انزلاق المشاش للخلف والإنسي."},{"f":"تصنيف سالتر-هاريس (Salter-Harris): النمط الأشيع؟","b":"النمط 2 (انفصال المشاش مع جزء من الكردوس) — وهو الأشيع."},{"f":"شفاء الكسور عند الأطفال: أسرع في الطفولة المبكرة أم المراهقة؟","b":"الأصغر عمرًا يشفى أسرع — السمحاق الأثخن وصفيحات النمو النشطة."},{"f":"فرّق: الجنف البنيوي vs غير البنيوي؟","b":"الجنف البنيوي: دوران فقري ثابت لا يزول بالانحناء. غير البنيوي: مرن دون دوران."},{"f":"طفل صغير يرفض استخدام طرفه العلوي بعد سحبه من يده: التشخيص والتدبير؟","b":"المرفق المشدود — رد مغلق بسيط (عطف + بسط الساعد + استلقاء) دون جراحة."},{"f":"طفل 6 سنوات، عرج + ألم ركبة، الركبة طبيعية بالفحص: التشخيص؟","b":"داء بيرتس — ألم يُحال للركبة مع ورك مؤلم في الفحص."}]},{"t":"أمراض المفاصل التنكسية والإنتانات العظمية المفصلية","cards":[{"f":"العلاج النوعي لذات العظم والنقي في العظام الطويلة؟","b":"التجريف الجراحي + صادات طويلة الأمد — الصادات وحدها لا تصل للنسج الميتة."},{"f":"طفل 4 سنوات، ألم ورك حاد + علامات التهابية: الإجراء الإسعافي؟","b":"بزل سائل المفصل للزرع فورًا — قبل الصادات؛ التأخير يدمر الغضروف."},{"f":"سبب الوفاة في ذات العظم والنقي الحادة؟","b":"الصدمة الإنتانية — التجرثم الدموي من الإنتان الشديد."}]},{"t":"أورام العظام السليمة والخبيثة والآفات شبيهة الورم","cards":[{"f":"مصادر الانتقالات العظمية الشائعة: ماذا يُستثنى؟","b":"الثدي، البروستات، الرئة، الدرق، الكلية — سرطان الكبد ليس من المصادر الشائعة."},{"f":"غرن إيونغ (Ewing): انتقالاته متأخرة أم مبكرة؟","b":"مبكرة (للرئة خصوصًا) — ورم عدواني يعطي انتقالات مبكرة لا متأخرة."},{"f":"الأكثر حساسية للكشف المبكر عن الآفات العظمية؟","b":"ومضان العظام — يلتقط زيادة الاستقلاب قبل التغيرات الشعاعية."}]}]},{"s":"جراحة الصدر","topics":[{"t":"رضوض الصدر والأذيات الإسعافية","cards":[{"f":"المهددات الآنية للحياة في رضوض الصدر تشمل؟","b":"الريح الضاغطة، المصراع الصدري، السطام التاموري، التدمي الغزير — ليس الفتق الحجابي/تمزق المريء."},{"f":"الإجراء الفوري في الريح الصدرية الضاغطة؟","b":"إبرة ثخينة في الورب الثاني على الخط منتصف الترقوة — تشخيص سريري دون انتظار التصوير."},{"f":"أهم سبب للوفاة في الاسترواح الصدري الضاغط؟","b":"الوهط الدوراني (Circulatory Collapse) — انضغاط المنصف يعيق العود الوريدي."},{"f":"التدبير الإسعافي للمصراع الصدري (الصدر المخلخل)؟","b":"الاستلقاء على الجانب المصاب — يثبت القطعة السائبة بوزن الجسم."},{"f":"الآلية الأساسية للقصور التنفسي في المصراع الصدري؟","b":"ظاهرة بندلوفت (Pendelluft) — حركة هوائية شاذة بين الرئتين + حركة متناقضة للجدار."},{"f":"تدبير كسور الأضلاع البسيطة غير المضاعفة؟","b":"مسكنات قوية + دعم تنفسي — التسكين يمكّن السعال ويمنع ذات الرئة."},{"f":"سطام تاموري (هبوط ضغط + انتباج أوداج + أصوات تنفسية طبيعية): التدبير الإسعافي؟","b":"بزل التامور (Pericardiocentesis) — التشخيص بالإيكو لا بالصورة البسيطة."},{"f":"تمزق الحجاب الحاجز الرضي: أي جانب أشيع؟","b":"الجانب الأيسر أشيع — الكبد يحمي الأيمن."},{"f":"استطبابات فتح الصدر بعد تفجير التدمي الجنبي؟","b":"تصريف >1500 مل دفعة واحدة، أو >200 مل/ساعة لأكثر من 4-6 ساعات — وليس 500 مل."},{"f":"تمزق المريء: العلاج الأساسي؟","b":"جراحي إسعافي (بويرهاف) — ليس دوائيًا بالصادات وحده."},{"f":"ألم صدري أيسر بعد إقياء شديد: الاستقصاء الأفضل؟","b":"صورة الصدر البسيطة أولًا (استرواح المنصف / انصباب أيسر)."},{"f":"انتباج أوداج + هبوط ضغط + أصوات تنفسية طبيعية بعد رض: ما التشخيص البديل للمصراع؟","b":"تسلخ الأبهر — ألم صدري حاد مهاجر بين اللوحين بعد قصة سقوط."},{"f":"من آفات الصدر المؤثرة على تبادل الغازات: ماذا يُستثنى؟","b":"السطام التاموري — اضطراب دوراني لا تنفسي."},{"f":"من إجراءات تنظير الصدر: ماذا يُستثنى؟","b":"فتح الصدر بمساعدة الفيديو (VATS) — ليس فتح عظم القص الكامل."},{"f":"من الأذيات المهددة للحياة في رض الصدر: ماذا يُستثنى؟","b":"الريح البسيطة غير الموترة/المفتوحة — والانصباب الدموي غير الغزير."},{"f":"انثقاب المريء: هل هو من المهددات الآنية الفورية في رضوض الصدر؟","b":"لا — خطير لكنه ليس فوريًا. المهددات الآنية: الريح الضاغطة/المفتوحة، المصراع، السطام، التدمي الغزير."}]},{"t":"أمراض وجراحة الجنب","cards":[{"f":"النمط الكلاسيكي للريح الصدرية العفوية؟","b":"شاب طويل نحيل مدخن — تمزق فقاعات قمية (النوع البدئي)."},{"f":"فرّق: الريح الموترة vs المفتوحة في آلية الضغط؟","b":"الموترة: صمام وحيد الاتجاه في جوف مغلق. المفتوحة: ضغط متعادل مع الخارج."},{"f":"أفضل علاج للريح الصدرية الناكسة لدى شاب؟","b":"لا — جراحي (VATS + استئصال الفقاعات + إيثاق الجنب بالجدارية)."},{"f":"الريح الصدرية الشاملة لنصف الصدر: التدبير؟","b":"تفجير الصدر بأنبوب — البزل الإبري للموترة إسعافيًا فقط."},{"f":"إيثاق الجنب الجراحي: أي طبقة تُستأصل؟","b":"استئصال/حك الجنب الجدارية لا الحشوية — الحشوية تضر الرئة."},{"f":"من أسباب الريح العفوية الثانوية: ماذا يُستثنى؟","b":"الفقاعة القمية (سبب البدئية) — الثانوية: سل، سرطان، ربو، نفاخ."},{"f":"استطبابات الجراحة في الريح الصدرية؟","b":"الناكسة، المزمنة (تسرب مستمر)، الرئة الوحيدة، المهن عالية الخطورة — وليس الشاملة في الهجمة الأولى."},{"f":"أشيع سبب لتقيح الجنب (Empyema)؟","b":"الإنتانات الرئوية (ذات الرئة المجاورة) — سكر سائل البزل منخفض <60 والـpH <7.2."},{"f":"تقيح الجنب: فرّق التدبير حسب المرحلة؟","b":"الانصباب غير المختلط: صادات دون تفجير. القيح المرئي: تفجير. المحجب: تقشير الجنب (VATS)."},{"f":"العلامة القرعية النموذجية للانصباب الجنبي؟","b":"الأصمية لا الطبلية — مع خفوت الأصوات ونقص الاهتزازات الصوتية."},{"f":"من استطبابات وضع أنبوب الصدر: ماذا يُستثنى؟","b":"التليف الرئوي — مرض متنفس لا يستطب تفجيرًا."},{"f":"شاب مدخن بألم صدري فجائي وزلة: التشخيص والاستقصاء الأول؟","b":"ألم صدري أيمن فجائي + زلة + خفوت أصوات + طبلية بالقرع — الاستقصاء: صورة بسيطة."},{"f":"التدبير البدئي للريح الموترة؟","b":"بزل الورب الثاني إسعافيًا — ثم تفجير لاحقًا."},{"f":"استطبابات الجراحة في الريح البدئية (عدا النكس):","b":"التحول لموترة، فقاعات كبيرة (>2-3 سم)، حدوث ثنائي الجانب، مهن عالية الخطورة (غواصون/طيارون)."}]},{"t":"سرطان الرئة والنقائل الورمية","cards":[{"f":"قاعدة ذهبية: كل مسن مدخن بنفث دموي حديث هو ...؟","b":"مسن مدخن مع نفث دموي حديث — سرطان رئة حتى يثبت العكس."},{"f":"أشيع أعراض سرطان الرئة؟","b":"السعال — أشيع عرض. والتشخيص غالبًا متأخر وغير جراحي."},{"f":"أسوأ أنماط سرطان الرئة إنذارًا؟","b":"صغير الخلايا — الأسرع نموًا والأسوأ إنذارًا."},{"f":"ارتشاح جدار الصدر في سرطان الرئة: هل يمنع الجراحة؟","b":"لا يمنع — T3 يُستأصل مع جدار الصدر. أما N3 والنقائل البعيدة وانصباب الجنب الورمي فتمنع."},{"f":"أهم سبب لاستئصال الفص الرئوي؟","b":"استئصال الفص الرئوي (Lobectomy) مع تجريف العقد المنصفية."},{"f":"ألم وخدر بالحافة الإنسية للطرف العلوي في سرطان رئة = ؟","b":"ورم بانكوست (Pancoast) — غزو الضفيرة العضدية (C8-T1) + هورنر."},{"f":"من وسائل التقييم المرحلي لسرطان الرئة: ماذا يُستثنى؟","b":"الواسمات الورمية — التقييم: طبقي، PET، ومضان عظام، تنظير منصفي."},{"f":"نقائل سرطان الرئة النموذجية خارج الصدر تشمل: الدماغ، الكبد، الكظر، العظام — ماذا يُستثنى؟","b":"سرطان الرئة (الغدية أشيع الأنماط) — وليس ضخامة العقد الإبطية."},{"f":"هل يتراجع خطر سرطان الرئة لمستوى غير المدخنين بعد إيقاف التدخين؟","b":"لا — الأسبست يؤهب له، والخطر لا يتراجع لمستوى السوي بعد الإقلاع."}]},{"t":"الآفات الرئوية الإنتانية والخمجية","cards":[{"f":"الكيسة المائية الرئوية السليمة: التشخيص والعلاج الرئيسي؟","b":"التشخيص: صورة الصدر (ظل مدور متجانس). العلاج الرئيسي: جراحي — الألبندازول مساعد فقط."},{"f":"الكيسة المائية المتمزقة: العلامة الشعاعية المميزة؟","b":"علامة زنبقة الماء (Water lily) — الغشاء المتموج يطفو على السائل."},{"f":"تظاهرات الكيسة المائية المنفتحة على القصبات؟","b":"سعال تشنجي شديد + قيء صدري (ماء صخري) + صدمة تأقية."},{"f":"من اختلاطات الكيسة المائية المفتوحة: ماذا يُستثنى؟","b":"قصور القلب — بقية الاختلاطات: قيء صدري، سعال، تأق، شرى."},{"f":"التوسع القصبي الولادي المنتشر: هل يُستأصل؟","b":"لا تُستأصل — الجراحة للموضع العرضي بفص واحد أو المختلط (نفث/خراج)."},{"f":"الخراج الرئوي البدئي عند سليم المناعة: العلاج الأول؟","b":"الصادات طويلة الأمد (4-6 أسابيع) — الجراحة للمختلط فقط."},{"f":"الخراجة الرئوية البدئية تتوضع في القمة أم القطع التابعة؟","b":"القطع التابعة (الخلفية من العلوي / العلوية من السفلي) — القمة للسل."},{"f":"أكثر الطرق فعالية لاستقصاء الانصباب الجنبي السلي؟","b":"تنظير الجنب مع خزعة (نسيج + زرع) — الأعلى حساسية."},{"f":"الانصباب الجنبي السلي: متى تكون الجراحة خيارًا رئيسيًا؟","b":"الانصباب الدرني البسيط: دوائي. المعقد المحجب (رئة محبوسة): تقشير الجنب."},{"f":"تظاهرات أورام المنصف: ماذا يُستثنى؟","b":"تناذر الوريد الأجوف العلوي، بحة صوت (الحنجري الراجع)، أزيز معند — وليس نفث الدم."}]},{"t":"تشوهات جدار الصدر وأورام المنصف","cards":[{"f":"من آفات المنصف التي تُستأصل جراحيًا: ماذا يُستثنى؟","b":"اللمفوما المنصفية — تُعالَج كيميائيًا وشعاعيًا لا جراحيًا."},{"f":"من أورام المنصف الأمامي (4T): ماذا يُستثنى؟","b":"الفيوكروموسيتوما — تتوضع في المنصف الخلفي (من السلسلة الودية)."},{"f":"من علامات الخباثة في أورام جدار الصدر: ماذا يُستثنى؟","b":"الكتلة المتحركة — الخبيثة: ثابتة + ألم + ازدياد سريع + نقص وزن."},{"f":"أشيع تشوهات جدار الصدر؟","b":"الصدر القمعي (Pectus excavatum) — قد يسبب قصورًا تنفسيًا متقدمًا بانضغاط القلب."}]},{"t":"الإجراءات الصدرية وتدبير الطريق الهوائي","cards":[{"f":"الاختلاط الكلاسيكي للتنبيب الرغامي المديد؟","b":"زلة مترقية + صرير بعد أسابيع من التنبيب — الإجراء الأفضل: تنظير قصبات."},{"f":"التشظي الرئوي (Sequestration): مصدر التروية الشريانية؟","b":"من الأبهر (الدوران الجهازي) لا من الشريان الرئوي — في الميزابة الفقرية الضلعية اليسرى."},{"f":"استئصال الكيسات المائية: هل VATS مثالية لها؟","b":"فتح الصدر لا VATS — خطر انسكاب محتويات الكيسة."},{"f":"طفل مترشدق بملبسة ومزرق: الإجراء الإسعافي؟","b":"مناورة هايمليش (Heimlich) — دفعات بطنية."},{"f":"من مناورات تأمين الطريق الهوائي: ماذا يُستثنى؟","b":"دفع الفك للأمام (jaw thrust) وسحب اللسان — وليس سحب الفك للخلف."},{"f":"من استطبابات خزع الرغامى الإسعافي: ماذا يُستثنى؟","b":"تلين الحنجرة — ليس انسدادًا حادًا متفاقمًا."}]},{"t":"أسئلة متفرقة","cards":[{"f":"الإريثرومايسين (ماكروليد): أي جرثومة تُستثنى من تغطيته؟","b":"الكلاميديا، الشاهوقية، اللجيونيلا، العطيفة، الميكوبلازما — لا تغطي سلبية الغرام المعوية."},{"f":"تغطية الماكروليدات باختصار؟","b":"جراثيم لانوائية وإيجابية الغرام — وسلبيات الغرام المعوية لا تستجيب."},{"f":"هل الإريثرومايسين يغطي الإشريكية القولونية؟","b":"لا — التغطية للانوائية والإيجابيات فقط."}]}]},{"s":"جراحة القلب","topics":[{"t":"دارة القلب والرئة الاصطناعية","cards":[{"f":"بعد انتهاء عملية القلب المفتوح: كيف يُعاكس الهيبارين؟","b":"بالبروتامين (Protamine) — بعد انتهاء التروية لاستعادة التخثر."},{"f":"أي نوع مؤكسج يُستخدم في دارة القلب والرئة الاصطناعية الحديثة؟","b":"المؤكسج الغشائي (لا الفقاعي) هو المستعمل — ويؤكسج الدم الوارد من القنية الوريدية."},{"f":"دارة القلب والرئة: هل تُوقف التروية عند تبريد 25°؟","b":"التروية بالدارة تستمر أثناء التبريد ولا تُوقف عند 25° — والقنية الأبهرية تُعيد الدم المؤكسج."}]},{"t":"داء الشرايين الإكليلية وجراحة المجازات","cards":[{"f":"الطعم الذهبي للمفاغرة على الشريان الأمامي النازل؟","b":"الشريان الثدي الباطن الأيسر (LIMA) — الأعلى سلوكية مع السنوات."},{"f":"أكثر الأوردة استخدامًا في المجازات الإكليلية؟","b":"الوريد الصافن الطويل (الكبير) لا «الوحشي» القصير."},{"f":"استطبابات المجازات الإكليلية الجراحية الكبرى؟","b":"تضيق الجذع الإكليلي الأيسر الرئيسي >50% + داء الثلاثة أوعية — حتى مع وظيفة بطينية محفوظة."},{"f":"الاختلاطات الميكانيكية لاحتشاء العضلة القلبية: ماذا يُستثنى؟","b":"تمزق الجدار الحر، تمزق الحاجز (فتحة بين بطينين)، تمزق العضلة الحليمية (قصور تاجي حاد)، أم الدم البطينية — وليس القصور الأبهري الحاد."},{"f":"قصور تاجي حاد بعد احتشاء: البالون داخل الأبهر مستطب أم مضاد استطباب؟","b":"البالون المضاد للنبضان — يخفف الحمل البعدي ويدعم النتاج في الصدمة القلبية."},{"f":"من الطعوم الشريانية الممكنة للمجازات: ماذا يُستثنى؟","b":"الشريان الفخذي — مصدر التروية الرئيسي للطرف السفلي."}]},{"t":"أمراض صمامات القلب وجراحتها","cards":[{"f":"العلاج النهائي للتضيق الأبهري الشديد العرضي؟","b":"جروحيًا بتبديل الصمام بصمام صنعي — لا يوجد دواء يغير الإنذار بعد ظهور الأعراض."},{"f":"أشيع سبب لتضيق الصمام الأبهري بعمر 70؟","b":"التكلس التنكسي على الصمام ثنائي الشرف أو الطبيعي — الرثوية غلبت بالأعمار الأصغر."},{"f":"القثطرة وتصوير الإكليلي قبل جراحة الصمام: عند كل المرضى الشباب؟","b":"لا — تُستطب فوق 35-40 سنة أو مع عوامل خطورة إكليلية فقط."},{"f":"من استطبابات تبديل الدسام التاجي: ماذا يُستثنى؟","b":"انقطاع الحبال الوترية — قابل للإصلاح (رأب) لا للتبديل."}]},{"t":"تشوهات القلب الخلقية والوالدية","cards":[{"f":"رباعي فالو: هل يرتفع الضغط الرئوي؟","b":"ارتفاع ضغط البطين الأيمن فقط — تضيق مخرج البطين الأيمن يحمي الرئتين (ضغط رئوي طبيعي/منخفض)."},{"f":"آفة خلقية تسبب زرقة مركزية فور الولادة؟","b":"تبادل منشأ الأوعية (DTGA) — زرقة صاعقة فور الولادة بدورتين متوازيتين."},{"f":"الاسم عند انعكاس تحويلة يسار-يمين طويلة الأمد إلى زرقة؟","b":"تناذر أيزنمنغر (Eisenmenger) — ارتفاع غير عكوس للمقاومة الرئوية بانعكاس التحويلة يمين-يسار."},{"f":"من آفات القلب الخلقية المسببة لقصور قلب في الشهر الأول: ماذا يُستثنى؟","b":"فتحة بين الأذينين الكبيرة (ASD) — تتأخر أعراضها للطفولة المتأخرة."},{"f":"فرّق: النبض في تضيق برزخ الأبهر؟","b":"نبض قوي علويًا + ضعيف متأخر سفليًا — عكس العبارة الشائعة."},{"f":"هل يستطب إغلاق أي فتحة بين البطينين جراحيًا ولو صغيرة؟","b":"لا — الصغيرات تلتئم عفويًا بالمراقبة؛ الكبيرة تُغلق مبكرًا (3-6 أشهر)."}]},{"t":"آفات التامور والسطام والدعم الدوراني","cards":[{"f":"ثالوث السطام التاموري؟","b":"ثلاثي بيك (Beck): هبوط ضغط شرياني + انتباج أوداج + خفوت أصوات القلب."},{"f":"الضغط الوريدي المركزي في السطام التاموري: يرتفع أم يهبط؟","b":"يرتفع (انتباج أوردة العنق) — الشرياني يهبط والنتاج ينقص."},{"f":"البالون داخل الأبهر المعاكس للنبضان: أي حمل يخفف؟","b":"البالون: يخفف الحمل البعدي (لا القبلي) + يعزز التروية الإكليلية انبساطيًا."},{"f":"رض + ضغط 70/50 + انتباج أوردة العنق = التشخيص؟","b":"السطام التاموري — صدمة انسدادية (أوردة منتبجة تميزها عن النزفية)."}]},{"t":"تسلخ الأبهر وجراحة الأبهر","cards":[{"f":"أسباب الوفاة المبكرة في تسلخ الأبهر الصاعد: ماذا يُستثنى؟","b":"السطام التاموري الحاد (تمزق في التامور)، احتشاء عضلة قلبية (امتداد للإكليلي)، قصور أبهري حاد — وليس امتداد التسلخ نحو النازل."},{"f":"تسلخ الأبهر الصاعد: دوائي أم جراحي إسعافي؟","b":"إعادة بناء الأبهر الصاعد جراحيًا — النوع الصاعد جراحي إسعافي."},{"f":"هل يُكتفى بالعلاج الدوائي وحده في تسلخ الأبهر الصاعد؟","b":"لا — التدبير: مسكنات + تحكم بالضغط والنبض، لكن الصاعد يستلزم الجراحة."}]},{"t":"الانعاش القلبي الريوي","cards":[{"f":"من أنماط توقف القلب المستدعية للإنعاش الفوري: ماذا يُستثنى؟","b":"الرجفان الأذيني — نظم مؤدٍّ (يوجد نتاج قلبي) لا يستدعي CPR."},{"f":"من أدوية الإنعاش الروتينية (أدرينالين، أميودارون): ماذا يُستثنى؟","b":"كلوريد البوتاسيوم — يُعالج فرط البوتاسيوم المسبب للتوقف لا الروتين."},{"f":"أنماط توقف القلب المستدعية CPR الفوري؟","b":"الرجفان البطيني، اللاانقباضية، الافتراق الكهربائي-الميكانيكي، الحصار القلبي التام."}]}]},{"s":"الجراحة التجميلية","topics":[{"t":"الحروق","cards":[{"f":"الخطورة الأكبر في اليومين الأوليين لحرق واسع؟","b":"صدمة نقص الحجم (Hypovolemia) — هروب البلازما من الشعيرات في الساعات الأولى."},{"f":"السبب الأشيع للوفاة المتأخرة لدى مريض الحروق؟","b":"الإنتان واختلاطاته — فقدان الحاجز الجلدي + تثبيط مناعي."},{"f":"من خصائص حرق الدرجة الثالثة: الألم الشديد؟","b":"غير مؤلم (يخرب النهايات العصبية) — الألم فقط حول الحواف."},{"f":"المشعر الأساسي لكفاية الإنعاش بالسوائل عند مريض الحروق؟","b":"نتاج البول (0.5-1 مل/كغ/ساعة) — وليس الضغط الوريدي المركزي."},{"f":"العامل الأساسي في حساب تعويض السوائل بالحروق؟","b":"المساحة الإجمالية للحرق من سطح الجسم (TBSA) — قاعدة التسعات للتقدير السريع."},{"f":"العرض الأخطر في حروق الوجه والأذية الاستنشاقية؟","b":"الزلة التنفسية — تستدعي تأمين الطريق الهوائي فورًا (تنبيب)."},{"f":"المسحوق الكيماوي الجاف: غسيل أم مسح جاف أولًا؟","b":"المسح/الفرشاة الجافة أولًا — الغسيل قد يفعّل تفاعلًا حراريًا."},{"f":"حرق التوتر العالي: بيلة خضابية أم ميوجلوبينية؟","b":"بيلة ميوجلوبينية (Myoglobinuria) — انحلال عضلي يهدد الكلية."},{"f":"الأكثر دلالة على شدة الأذية النسيجية في الحروق الكهربائية؟","b":"مستوى الميوجلوبين في البول — يعكس حجم العضلات المتنخرة."},{"f":"المجموعة العمرية الأخطر في الحروق؟","b":"الأطفال دون سنتين — سطح/كتلة عالٍ + مناعة غير ناضجة."},{"f":"قرحة الشدة الناجمة عن الحروق الشديدة: موقعها الأشيع؟","b":"قرحة كورلينغ (Curling) في المعدة — من نقص التروية المخاطية."},{"f":"أشيع سبب لتأخر اندمال الجروح الجراحية؟","b":"الإنتان الموضعي — يطيل المرحلة الالتهابية ويعيق الكولاجين."},{"f":"من علامات أذية الاستنشاق: بحة صوت، سخام، حروق وجه — ماذا لا يفيد مبكرًا؟","b":"صورة الصدر — تبقى طبيعية في الساعات الأولى (التغيرات متأخرة)."},{"f":"الوجه الأمامي للفخذ يعادل كم من سطح الجسم؟","b":"نحو 9% (الطرف السفلي كاملًا 18%) — دون عتبة القبول للبالغين (15%)."}]},{"t":"الجراحة الترميمية والتجميلية","cards":[{"f":"أشيع المواقع المعطية للطعوم جزئية السماكة؟","b":"الفخذان (الوجه الأمامي-الوحشي) — مساحة واسعة وسهل الإخفاء."},{"f":"الطعم جزئي السماكة vs كامل السماكة: أيهما محدد المساحة؟","b":"الطعم كامل السماكة (محدود المساحة — يحتاج إغلاقًا جراحيًا للمنطقة المعطية)."},{"f":"فرّق: تغذية الشريحة الحرة vs الطعم الجلدي الحر؟","b":"الشريحة الحرة: مفاغرة وعائية مجهرية — التشرب (Imbibition) للطعوم الجلدية الحرة."},{"f":"انكشاف عظمي على القحف 6×8 سم: الطعم أم الشريحة؟","b":"شريحة من الجوار (دوارة) — الطعوم لا تعيش على عظم مكشوف بلا سمحاق."},{"f":"من طرق تصنيع الثدي بعد الاستئصال: ماذا يُستثنى؟","b":"شريحة العضلة الصدرية الكبرى — المعتمدة: بدائل، TRAM، الظهرية العريضة."},{"f":"أفضل وسيلة لمنع الانتان في جرح مفتوح بالساق بعد الرض؟","b":"التنضير الجراحي — النسيج المتموت وسط مثالي للجراثيم."},{"f":"قطب الأطراف السفلية: متى تُنزع؟","b":"10-14 يومًا — لضعف التروية وبطء الالتئام."},{"f":"النسيج الحبيبي يظهر في المرحلة الالتهابية للالتئام؟","b":"التكاثر (Proliferative) — النسيج الحبيبي ليس من المرحلة الالتهابية."},{"f":"هل شد البطن (Abdominoplasty) يهدف لإنقاص الوزن؟","b":"لا — شد البطن لاستئصال الفائض الجلدي بعد نزول الوزن، وليس لإنقاصه."}]},{"t":"أورام الجلد","cards":[{"f":"قرحة مزمنة غير ملتئمة بحواف مرتفعة على حرق قديم = التشخيص؟","b":"سرطان شائك الخلايا (SCC) — قرحة مارجولين على ندبة مزمنة."},{"f":"من الآفات السابقة للتسرطن: ماذا يُستثنى؟","b":"ندبة حرق حديث — السابقة للتسرطن هي الندبة المزمنة القديمة لا الحديثة."},{"f":"أشيع أنماط الميلانوما؟","b":"السطحية المنتشرة (نحو 70%) — العقيدية أخطر لكنها أقل شيوعًا."},{"f":"أشيع سرطان الشفة السفلية؟","b":"SCC — للتعرض المزمن للشمس (وليس BCC كعموم الجلد)."},{"f":"إنذار SCC مقابل BCC: أفضل أم أسوأ؟","b":"أسوأ — SCC تعطي نقائل بينما BCC نادر النقائل."}]}]},{"s":"جراحة الأطفال","topics":[{"t":"التشوهات الخلقية في الجهاز الهضمي والحجاب الحاجز","cards":[{"f":"الصورة النموذجية لتضيق البواب الضخامي؟","b":"إقياءات نافورية غير صفراوية + تجفاف + قلاء استقلابي ناقص الكلور والبوتاسيوم (ذروته 2-8 أسابيع، ذكور 4:1)."},{"f":"المعيار الذهبي لتشخيص تضيق البواب الضخامي؟","b":"الإيكوغرافي (سماكة العضلة ≥4 ملم) — حل محل الصورة الظليلية كمعيار ذهبي."},{"f":"علاج تضيق البواب الضخامي: إسعافي أم مؤجل حتى التصحيح؟","b":"خزع عضلة البواب (رامشتدت) بعد تصحيح التجفاف والقلاء — الجراحة ليست إسعافية أبدًا."},{"f":"قاعدة ذهبية: كل وليد بإقياءات صفراوية فجائية هو ... حتى يثبت العكس؟","b":"سوء دوران الأمعاء مع انفتال — حالة إسعافية جراحية."},{"f":"أهم وأبكر عرض لرتق المري؟","b":"تراكم المفرزات اللعابية (إلعاب رغوي) — التدبير الأول: رشف المفرزات ومنع الاستنشاق."},{"f":"هل يظهر غاز معوي في الشكل الشائع لرتق المري؟","b":"الشكل الشائع (85%): رتق + ناسور رغامي-مريئي بعيد — فيمر الهواء للسبيل الهضمي."},{"f":"الفتق الحجابي الولادي: البطن متمدد أم زورقي؟","b":"البطن زورقي مسطح لا متمدد — الأحشاء في الصدر."},{"f":"فرّق: فتق بوكدالك vs فتق مورغاني في الموقع؟","b":"بوكدالك: خلفي-وحشي (الظهري الفقر-الضلعي). مورغاني: أمامي خلف القص."},{"f":"رتق العفج (الاثني عشر): المرافقات الخلقية؟","b":"داون (25-40%) + خداج + تشوهات قلبية — علامته: الفقاعة المزدوجة."},{"f":"التدبير الأولي لانسداد الأمعاء بالعقي غير المختلط؟","b":"رحضة باريتية باليوروغرافين (غاستروغرافين) — تشخيصية وعلاجية."},{"f":"الاستطباب المطلق للتداخل الجراحي في التهاب الأمعاء والكولون النخري؟","b":"تهوي البريتوان (غاز حر) — الاستطباب المطلق للجراحة."},{"f":"العلامة التشخيصية المميزة لالتهاب الأمعاء والكولون النخري؟","b":"تهوية جدار الأمعاء (Pneumatosis intestinalis) — علامته المميزة لا علامة انسداد العقي."},{"f":"طفل بسعال ليلي متكرر وانتانات رئوية متكررة: التشخيص الأساسي؟","b":"الفتق الحجابي (القلس والاستنشاق الليلي) — لا تعذر الارتخاء."},{"f":"فتق سري 2 سم عند طفل بعمر سنة: التدبير؟","b":"المراقبة والانتظار — يشفى عفويًا خلال السنة الأولى/الثانية."},{"f":"الإقياءات الصفراوية منذ الولادة: هل تتوافق مع تضيق البواب؟","b":"لا — تنفيه؛ الانسداد قبل الحليمة العفجية فيكون الإقياء غير صفراوي. الصفراوية = انسداد بعد الحليمة."}]},{"t":"الانسدادات المعوية وآفات جدار البطن والمنطقة المغبنية","cards":[{"f":"الصورة النموذجية للانغلاف المعوي؟","b":"بكاء نوبي (مغصي) + براز هلام الكرز + كتلة مجسوسة — ذروته 3-12 شهرًا."},{"f":"تشخيص وعلاج الانغلاف المعوي الأولي؟","b":"الحقنة الشرجية (الهوائية/الظليلية) — مشخصة ومعالجة أحيانًا (علامة الكماشة)."},{"f":"الصفة المميزة لألم الانغلاف المعوي؟","b":"الألم النوبي المتقطع — وليس الألم المستمر."},{"f":"داء هيرشبرنغ: المعيار الذهبي للتشخيص؟","b":"غياب العقد العصبية بخزعة المستقيم (المعيار الذهبي) — الصورة الظليلية دون تحضير."},{"f":"آلية الفتق الإربي عند الأطفال؟","b":"بقاء الناتئ الغمدي مفتوحًا (فتق غير مباشر) — لا ضعف الجدار الخلفي."},{"f":"الفتق الإربي عند الأطفال: مراقبة أم جراحة مبكرة؟","b":"جراحي مبكر (إصلاح بسيط دون تدعيم) — لا مراقبة لخطر الاختناق."},{"f":"العضو الأكثر ترافقًا مع الفتق الإربي عند الإناث؟","b":"المبيض — عبر قناة نوك (النظير الأنثوي للناتئ الغمدي)."},{"f":"الفتوق الإربية عند الأطفال: أشيع عند أي فئة؟","b":"أشيع عند الخدج — لعدم انغلاق الناتئ الغمدي."},{"f":"التوقيت المناسب لجراحة الخصية الهاجرة؟","b":"تثبيت الخصية قبل نهاية السنة الأولى (سنة ونصف كحد أقصى)."},{"f":"أشيع اختلاط لرتج ميكل عند الأطفال؟","b":"النزف الهضمي السفلي غير المؤلم — من النسيج المعدي الهاجر."},{"f":"رتج ميكل: حقيقي أم كاذب؟","b":"رتج حقيقي (كل طبقات الجدار) — من بقايا القناة المحية، على الجدار المقابل للمساريقا."},{"f":"أشيع سبب للنز الأصفر من سرة الرضيع؟","b":"الإنتان السري الشديد (قيحي أصفر) — وليس بقايا القناة المحية."},{"f":"سيلان البول من السرة: الاستقصاء الأساسي؟","b":"تصوير المثانة الظليل — بقاء العصيب (القناة السرارية-المثانية) مفتوحًا."},{"f":"انتباج صفني مؤلم عند طفل: ماذا يُستثنى من التشاخيص؟","b":"القيلة المائية — انتباج غير مؤلم يشف بالضوء."},{"f":"الانغلاف المعوي بعد عمر 6 سنوات: شائع؟","b":"لا — ذروته 3-12 شهرًا ونادر بعد 6 سنوات؛ وعند الكبار غالبًا بنقطة انطلاق مرضية."}]},{"t":"أورام الأطفال الجراحية ورتق الطرق الصفراوية","cards":[{"f":"طفل 5 سنوات: كتلة بطنية + بيلة دموية شاملة = التشخيص؟","b":"ورم ويلمز (Wilms) — أشيع أورام الكلية الخبيثة (ذروته 2-5 سنوات)."},{"f":"موقع ورم ويلمز بين أورام الأطفال البطنية؟","b":"أشيع الأورام البطنية الخبيثة الصلبة عند الأطفال."},{"f":"من عبارات ورم ويلمز: أي مصطلح دخيل يُستثنى؟","b":"الدوران الجانبي (مصطلح تقويمي) — لا علاقة له بورم ويلمز."}]},{"t":"التهاب البنكرياس عند الاطفال","cards":[{"f":"أشيع سبب لالتهاب البنكرياس الحاد عند الأطفال؟","b":"الرضوض البطنية الكليلة (رض مقود الدراجة)."},{"f":"الآلية المرضية الرئيسية لالتهاب الزائدة عند الأطفال؟","b":"الانسداد الحاد في لمعة الزائدة (بفرط تصنع النسيج اللمفاوي)."},{"f":"من التشاخيص التفريقية لالتهاب الزائدة عند مراهقة: ماذا يُستثنى؟","b":"التهاب رتج ميكل — يحاكي الزائدة سريريًا. أما التهاب الرتج القولوني فمرض كبار السن."}]},{"t":"رتج ميكل","cards":[{"f":"الاختلاط الأشيع لرتج ميكل عند طفل بعمر سنتين؟","b":"النزف الهضمي السفلي غير المؤلم بعمر سنتين."},{"f":"لماذا ينزف رتج ميكل؟","b":"التقرح بالنسيج المعدي الهاجر — قاعدة الاثنينات (2 إنش، 2%، بعمر سنتين)."},{"f":"مراهق ببطن حادة بعد آلام متكررة بمنتصف البطن: ما التشخيص المغفول؟","b":"التهاب رتج ميكل — التشخيص الذي يغيب عن ذهن الطبيب."}]},{"t":"أسئلة متفرقة","cards":[{"f":"طفل 13 سنة ببطن حادة: التشخيص الذي يغيب عن الذهن؟","b":"الانغلاف المعوي — غالبًا بنقطة انطلاق مرضية (رتج ميكل، بوليب، لمفوما)."},{"f":"رضيع بتطبل بطني حاد: ماذا يُستثنى من الأسباب؟","b":"الانسدادات السفلية/البعيدة — رتق العفج انسداد عالٍ لا يسبب تطبلًا."},{"f":"أسباب التطبل البطني الحاد عند الرضيع؟","b":"التظاهرات النموذجية للتطبل: رتق الشرج، انسداد العقي، هيرشبرنغ."}]}]},{"s":"جراحة الأورام","topics":[{"t":"جراحة أورام الغدة الدرقية وجارات الدرق","cards":[{"f":"أشيع سرطانات الدرق وأفضلها إنذارًا؟","b":"الحليمي (Papillary) — أشيع (نحو 80%) وأفضل إنذارًا. الأسوأ: الكشمي (غير المتمايز)."},{"f":"المشعر الورمي للسرطان الحليمي (المتمايز)؟","b":"الخلايا الجريبية — وليس الكالسيتونين (مشعر اللبي)."},{"f":"السرطان الجريبي: انتشار لمفاوي أم دموي؟","b":"دموي مبكر (عظام ورئة) — اللمفاوي سمة الحليمي."},{"f":"السرطان اللبي: من أي خلايا ينشأ؟","b":"الخلايا C جانب الجريبية (عصبية صماوية) — وراثي 25% (MEN2)، مشعره الكالسيتونين."},{"f":"فتاة بارتفاع كالسيتونين وقصة عائلية لسرطان درق لبي: التدبير؟","b":"استئصال درق تام — القصة العائلية + ارتفاع الكالسيتونين."},{"f":"شاب 15 سنة بسحنة مارفانية وكتلة درقية: التشخيص؟","b":"سحنة مارفانية + كتلة درقية = MEN2B — سرطان درق لبي."},{"f":"تكزز شديد بعد 36 ساعة من استئصال درق تام: السبب والعلاج الإسعافي؟","b":"تكزز نقص الكلس (قصور جارات الدرق) — الإسعافي: غلوكونات الكالسيوم وريديًا."},{"f":"ضيق تنفس + تورم عنقي شديد بعد ساعات من استئصال الدرق: التشخيص والتدبير الأول؟","b":"ورم دموي ضاغط — التدبير الأول: فتح الجرح على سرير المريض فورًا."},{"f":"أشيع اختلاط لاستئصال الدرق؟","b":"قصور الدرق (معيضة تيروكسين مدى الحياة) — وليس الريح الصدرية."},{"f":"اختلاطات جراحة الدرق: ماذا يُستثنى؟","b":"بحة الصوت (إصابة الحنجري الراجع)، رض المريء، التكزز — الريح الصدرية ليست منها."},{"f":"الاختبار الأهم لأي عقدة درقية باردة ≥1 سم؟","b":"الخزعة بالإبرة الرفيعة (FNA) — طفيفة الرض وتوجه القرار."},{"f":"عقدة درقية باردة عند شاب: أي عبارة شائعة خاطئة؟","b":"العقدة الباردة (أميل للخباثة من الحارة) — الحليمي هو الأشيع لا الجريبي."},{"f":"التدبير الجذري للكيسة الدرقية اللسانية؟","b":"عملية سيسترونك (استئصال مع الجزء المركزي من العظم اللامي) — البزل وحده ينكس."},{"f":"داء غريفز: متى يُفضل اليود المشع على الجراحة؟","b":"غريفز: اليود المشع يُفضل عند كبار السن — الجراحة للحوامل ومضاد استطباب اليود."},{"f":"فرط جارات الدرق البدئي: اللوحة المخبرية؟","b":"فرط كلس الدم + نقص فوسفور + حصيات بولية — والـpH منخفض (حماض) لا مرتفع."},{"f":"من أسباب فرط الكلس: ماذا يُستثنى؟","b":"التهاب البنكرياس الحاد يسبب نقص الكلس (تشكل صابون الكالسيوم)."},{"f":"سلعة عقدية ضاغطة تسبب ضيق نفس عند شاب: العلاج الأمثل؟","b":"السلعة العقدية الضاغطة على الرغامى — انضغاط ميكانيكي لا يزول إلا بالاستئصال."},{"f":"سرطان حليمي 4 سم مع ضخامات عقدية: التدبير الأمثل؟","b":"استئصال كامل للدرق + تجريف العقد الرقبية — ورم كبير مع اعتلال عقدي."},{"f":"من السرطانات المسببة للتثدي: ماذا يُستثنى؟","b":"التثدي: سرطان الخصية (HCG)، الكبد، الكظر، النخامة (برولاكتين) — سرطان الكلية يُستثنى."},{"f":"التهاب الدرق ريدل (Riedel): الصورة النموذجية؟","b":"غدة صلبة خشبية مؤلمة مع أعراض انضغاطية (عسرة بلع/تنفس) + ترافق مع أمراض مناعية جهازية."}]},{"t":"متفرقات الكارسينوييد","cards":[{"f":"في الورم السرطاوي (Carcinoid) بدون متلازمة: ماذا يُستثنى من الأعراض؟","b":"نوبات التوهج الجلدي — تخص المتلازمة السرطاوية الخبيثة (نقائل كبدية)، لا الورم الموضعي."},{"f":"أعراض الورم السرطاوي الموضعي (بدون متلازمة)؟","b":"انسداد معوي جزئي، إسهال انسدادي، نقص وزن، ألم بطني، نزف هضمي."},{"f":"متى يظهر الإسهال الإفرازي في الورم السرطاوي؟","b":"الإسهال الإفرازي — مع النقائل الكبدية التي تفلت السيروتونين للجهازي."}]},{"t":"أسئلة متفرقة","cards":[{"f":"من فحوص المسح السرطاني (ماموغرام، تنظير قولون، مسحة عنق الرحم): ماذا يُستثنى؟","b":"تنظير القصبات — إجراء تشخيصي/علاجي غازٍ لا مسح سكاني."},{"f":"أمثلة فحوص المسح السرطاني؟","b":"الماموغرام، تنظير القولون، الفحص الذاتي للثدي، مسحة عنق الرحم — تُجرى على الأصحاء."},{"f":"الكيسة الدرقية اللسانية: هل تختفي في الأسبوع الثالث من الحمل؟","b":"تبقى كبقايا قناة درقية لسانية — تدبيرها عملية سيسترونك."}]}]},{"s":"التوليد","topics":[{"t":"القصة المرضية والفحص السريري","cards":[{"f":"ما العرض المؤكد (positive) للحمل؟","b":"سماع دقات قلب الجنين — أو جسّ حركات الجنين من قبل الفاحص، أو رؤية الجنين بالإيكو. انقطاع الطمث والأعراض الودّية والبولية والجلدية: علامات ظنّية فقط."},{"f":"قاعدة ذهبية: بمَ يُقدَّر عمر الحمل سريريًا في الأسابيع الأولى؟","b":"بأول يوم من آخر طمث LMP (قاعدة نيغلي: +7 أيام −3 أشهر). قياسات الإيكو (BPD، محيط الجمجمة، طول الفخذ) تُستخدم في الثلث الثاني والثالث."},{"f":"في الفحص الحوضي: متى يُمنع استخدام المادة المزلقة؟","b":"عند أخذ لطاخة عنق الرحم — المزلق يتداخل مع الخلايا ويفسد القراءة الخلوية؛ يُستخدم للفحص اليدوي فقط."},{"f":"الحمل الكاذب (Pseudocyesis): هل ينقطع الطمث فيه؟","b":"نعم، الطمث ينقطع فعلًا في الحمل الكاذب رغم غياب الجنين — ومن هنا جاءت التسمية. العلامات: ازدياد حجم البطن، غثيان وإقياء، وغالبًا برغبة شديدة بالحمل أو خوف من فقدان الشريك."}]},{"t":"الإباضة والدورة الطمثية","cards":[{"f":"متى يُقاس البروجسترون الدموي لتحري حدوث الإباضة؟","b":"في اليوم 21 من دورة 28 يومًا (الطور الأصفري المتوسط). في اليوم 14 — موعد الإباضة نفسه — يكون منخفضًا ولا يفيد."},{"f":"ما الدليل المؤكد الوحيد لحدوث الإباضة؟","b":"حدوث الحمل. مخطط حرارة الجسم الأساسية ومخاط عنق الرحم وخزعة باطن الرحم الإفرازية: قرائن غير قاطعة."},{"f":"قاعدة ذهبية: ما العامل الذي يُبقي الجسم الأصفر (corpus luteum) بعد التعشيش؟","b":"ارتفاع hCG من الأرومة الغاذية (trophoblast) — يشبه LH بنيويًا فيرتبط بمستقبلاته في المبيض، فيمنع تراجع الجسم الأصفر ويستمر إفراز البروجسترون لتثبيت الحمل."}]},{"t":"الإخصاب وتطور المشيمة","cards":[{"f":"متى يحدث الانغراس (التعشيش) بعد الإخصاب؟","b":"في اليوم 6-7 بعد الإخصاب — الكيسة الأريمية (blastocyst) تنغرس في بطانة الرحم في طورها الإفرازي."},{"f":"أي الإستروجينات هو الرئيسي في الحمل وكم يرتفع؟","b":"الاستريول (estriol) — يُصنع في المشيمة من سلائف جنينية (كبريتات DHEA)، ويرتفع نحو 1000 ضعف أثناء الحمل (البروجسترون يرتفع ~10 أضعاف فقط)."},{"f":"فرّق: أي الهرمونات مشيمية وأيها ليس مشيميًا؟","b":"مشيمية: البروجسترون، الإستروجين (الاستريول)، hCG، واللاكتوجين المشيمي hPL. ليست مشيمية: LH (نخامية أمامية)، التستوستيرون (خصية/قشر كظر)."},{"f":"أنماط: ما الغلوبولين المناعي الوحيد الذي يعبر المشيمة؟","b":"IgG فقط — بالنقل الفاعل عبر مستقبلات خاصة (مناعة منفعلة للوليد). IgM لا يعبر أبدًا: وجوده في دم الجنين يدل حتمًا على إنتان داخل الرحم."}]},{"t":"المضغة والجنين","cards":[{"f":"أي وسيلة تشخيصية ممنوعة مطلقًا للاضطرابات الجنينية أثناء الحمل؟","b":"التصوير الشعاعي الظليل (كصورة الرحم والبوقين HSG) — أشعة مؤينة مسخّنة ومسرطنة للجنين. التشخيص الغازي المقبول: الخزعة الكوريونية وبزل السائل الأمنيوسي."},{"f":"ما الفترة الأكثر حساسية لحدوث التشوهات البنيوية الكبرى؟","b":"فترة تخلق الأعضاء (organogenesis): الأسابيع 3-8 من الحمل — لا 8-10. ذروة الانقسام والتمايز الهيكلي السريع."},{"f":"ما العوامل المؤثرة على حدوث التشوه الجنيني؟","b":"التكوين الوراثي للجنين والأم (الاستعداد الجيني)، جرعة العامل المسخّن، والتعرض للأشعة العلاجية — المسخّية تعتمد مباشرة على الجرعة ونوع المادة."}]},{"t":"التغيرات الفيزيولوجية والترشيحية في الحمل","cards":[{"f":"فرّق: كيف يزداد حجم الرحم في الحمل — hyperplasia أم hypertrophy؟","b":"بتضخم الخلايا (hypertrophy) وتمطّطها — لا بفرط التنسج (hyperplasia). الوزن يرتفع من ~70 غ إلى ~1100 غ نهاية الحمل."},{"f":"لماذا يحدث فقر الدم الفيزيولوجي في الحمل؟","b":"حجم البلازما يزداد (~50%) بنسبة أكبر من زيادة كتلة الكريات الحمراء (~25-30%) — فيتناقص تركيز الخضاب والهيماتوكريت (تخفيف dilutional)."},{"f":"من سؤال حقيقي: ما تغيرات الغدة الدرقية في الحمل «ما عدا»؟","b":"TSH لا يزداد بل ينقص — hCG يحفّز مستقبل TSH فتُثبَّط النخامى بالتغذية الراجعة السلبية. يزداد: حجم الغدة، T4 الكلي (~1.5 ضعف بحلول الأسبوع 16)، وT3."},{"f":"ما علامة هيغار (Hegar sign)؟","b":"ليونة برزخ الرحم (isthmus) بالجس الثنائي اليد في الأسابيع 6-8 — علامة احتمالية مبكرة للحمل (تشادويك = ازرقاق عنق الرحم)."},{"f":"أين يُجس قعر الرحم في الأسبوع 20 من الحمل؟","b":"عند مستوى السرة. (12 أسبوعًا: عند ارتفاق العانة، 16 أسبوعًا: منتصف المسافة بينهما، ثم ~1 سم أسبوعيًا)."},{"f":"الإقياء الحملي الشديد: ما الاضطراب الحمضي-القاعدي وما العلاج الأول؟","b":"قلاء استقلابي ناقص الكلور والبوتاسيوم مع تجفاف وكيتونية — لا حماض. العلاج: البيريدوكسين (فيتامين B6)."}]},{"t":"الرعاية السابقة للولادة","cards":[{"f":"ما استطبابات الاستشارة الوراثية «ما عدا»؟","b":"إنجاب طفل متخلف عقليًا، سوابق وفيات حديثي الولادة، إسقاطات متكررة، ارتفاع AFP عند الأم. التعرض للأشعة في حمل سابق منتهٍ: ليس استطبابًا."},{"f":"ما عتبة العمر الأمومي لتحري الشذوذات الجنينية؟","b":"35 سنة فما فوق — عمر 30 سنة وحده ليس استطبابًا للتحري."},{"f":"لماذا التتراسيكلين ممنوع في الحمل؟","b":"يتراكم في الأسنان النامية والعظام: تصبغ سني لا رجعة فيه + تثبيط نمو العظام، وقد يسبب تنكسًا دهنيًا حادًا قاتلًا في كبد الحامل."},{"f":"فرّق: مضاد التخثر الآمن في الحمل مقابل الممنوعات؟","b":"الآمن: الهيبارين — لا يعبر المشيمة لضخامة جزيئه. الممنوعة: الوارفارين (اعتلال جنيني: نقص تنسج الأنف وتشوهات هيكلية)، اليود المشع (يدمر درقية الجنين)، الكلورامفينيكول (متلازمة الطفل الرمادي)."},{"f":"ما استطبابات الإيكو في الثلث الأول «ما عدا»؟","b":"تحديد ارتكاز المشيمة — المشيمة «تهاجر» مع نمو الرحم، فيُقيَّم الارتكاز النهائي في الثلث الثاني/الثالث. الباقي مشروع: عدد أكياس الحمل، عمر الحمل، الفعالية القلبية، الشفافية القفوية (11-14 أسبوعًا)."},{"f":"أي استقصاء ليس من الثلث الأخير؟","b":"خزعة الزغابات المشيمية CVS — من استقصاءات الثلث الأول (الأسبوع 10-13). الثلث الأخير: دوبلر وعائي، عدّ الحركات، اختبار اللاشدة."},{"f":"متى يُتحرى عن السكري الحملي؟","b":"بين الأسبوع 24 و28 — وليس من فحوص الزيارة الأولى الروتينية (تعداد وصيغة، بول وراسب، ABO وريزوس، لطاخة مهبلية)."},{"f":"أدق وسيلة لتحديد سن الحمل في الثلث الأول؟","b":"قياس الطول القمي العجزي CRL بالإيكو — هامش خطأ 3-5 أيام فقط (أدق من تاريخ آخر طمث)."},{"f":"ماذا يزيد التدخين في الحمل «ما عدا»؟","b":"يزيد: انفكاك المشيمة الباكر، انبثاق الأغشية الباكر، المخاض الباكر، تأخر النمو داخل الرحم (IUGR). لا يزيد: المشيمة الملتحمة (مرتبطة بندبة القيصرية والمنزاحة)."},{"f":"مع ماذا يترافق ارتفاع AFP المصلي عند الأم؟","b":"عيوب الأنبوب العصبي المفتوحة، عيوب جدار البطن، الحمل المتعدد، وتناذر تورنر — علامة فحص تستدعي إيكو مفصلًا لا تشخيصًا."},{"f":"أفضل اختبار لتشخيص قصور عنق الرحم؟","b":"الإيكو المهبلي (Vaginal Ultrasound) لقياس طول العنق وتحري التبوق (funneling) — يوجه قرار التطويق."},{"f":"ما المشعر السريري الأدق لالتهاب الكوريو-أمنيوسي (chorioamnionitis)؟","b":"حمى الأم — أثناء تدبير تمزق الأغشية الباكر هي العلامة السريرية الأوثق."},{"f":"ما علامات ولادة أو حمل سابق «ما عدا»؟","b":"تشققات البطن، اصطباغ الهالة حول الثدي، الحليمات الآسية (بقايا غشاء البكارة بعد الولادة)، ندبة العجان. الباسور الشرجي: ليس علامة نوعية — قد يحدث دون حمل."},{"f":"ماذا تسبب الالتصاقات الحوضية «ما عدا»؟","b":"تسبب: العقم (عامل بوقي)، الألم الحوضي المزمن، عسرة الجماع، الحمل الهاجر. لا تسبب: الرحى العدارية (اضطراب تكاثر الأرومة الغاذية)."},{"f":"من مخاطر الخروسة المسنة (≥35) «ما عدا»؟","b":"الإجهاض، ما قبل الإرجاج، الإقياءات المعندة، الشذوذات الصبغية (داون)، السكري الحملي، انفكاك المشيمة الباكر. ليست منها: المشيمة المنزاحة (عواملها تعدد الولادات والندبات الرحمية)."},{"f":"ما الأمراض التي يُتحرى عن مناعتها قبل الحمل «ما عدا»؟","b":"الحصبة الألمانية (تشوهات خلقية)، الحماق، الهربس التناسلي، التهاب الكبد ب. الحصبة: لا تحرٍّ مصلي روتيني قبل الحمل."},{"f":"أقل فحص إفادة لتشخيص حمل بعمر 8 أسابيع؟","b":"الفحص البطني — الرحم بحجم قبضة اليد ولا يتجاوز الارتفاق العاني. الإيكو المهبلي وBhCG (مصل/بول) وLMP هي الأدق."}]},{"t":"سير الولادة وتدبيرها","cards":[{"f":"ما عناصر مشعر بيشوب (Bishop score) «ما عدا»؟","b":"الاتساع، الامحاء (الطول)، القوام، التوضع، نزول المقدمة — يقيّم نضج عنق الرحم. ضربات قلب الجنين: تقيّم سلامة الجنين لا العنق."},{"f":"فرّق: مراحل المخاض الثلاث؟","b":"الأولى: من بداية التقلصات المنتظمة حتى تمام اتساع العنق (10 سم). الثانية: من تمام الاتساع حتى ولادة الجنين. الثالثة: من ولادة الجنين حتى خروج المشيمة (الخلاص)."},{"f":"قاعدة ذهبية: ما تعريف التدخل (engagement)؟","b":"دخول القطر الأكبر للمجيء — القطر بين الجداريين BPD في المجيء القمي — في المضيق العلوي (مدخل الحوض)."},{"f":"ما صفات التقلصات الرحمية الفعالة؟","b":"3-5 مرات كل 10 دقائق، تستمر 60-90 ثانية، مؤلمة، تؤثر على عنق الرحم (اتساعًا وانمحاءً)، وتدفع بالجنين."},{"f":"انبثاق جيب المياه: هل يُبطئ المخاض؟ وما مخاطره؟","b":"لا — يسرّع المخاض (احتكاك الرأس بالعنق يحرر البروستاغلاندينات). مخاطره: انسدال الرسن، انفكاك مشيمة باكر، إنتان، ولون السائل العقي يدل على تألم الجنين."},{"f":"فرّق: خزع الفرج الناصف (median) مقابل الجانبي؟","b":"الناصف: إصلاحه أسهل وألم ونزف أقل — خطره امتداده ليمزق المعصرة الشرجية والمستقيم. الجانبي: ألم أشد ونزف أكبر."}]},{"t":"النفاس","cards":[{"f":"قاعدة ذهبية: ما أسباب نزف الخلاص (4Ts)؟","b":"Tone: عطالة الرحم (أشيع سبب) — Trauma: تمزقات السبيل التناسلي — Tissue: بقاء فلق مشيمية أو أغشية — Thrombin: اضطرابات التخثر. ليست منها: نقص وزن الجنين، وهبوط الرحم."},{"f":"نزف أحمر فاتح بعد ولادة مهبلية مع تقبض رحمي جيد: السبب الأرجح؟","b":"تمزقات تناسلية (مهبل/فرج/عنق الرحم) — دم حديث من مصدر خارج الرحم. العطالة تعطي نزفًا داكنًا مع رحم رخو غير متقبض."},{"f":"هل الإرضاع الطبيعي يسبب نقص انطمار الرحم؟","b":"لا — بل يعزز الانطمار: مصّ الحلمة يحرّض الأوكسيتوسين فيتقلص الرحم. أسباب نقص الانطمار: الحمل المتعدد، العرطلة، بقاء فلق مشيمية أو أغشية."},{"f":"كم تستمر الهلابة الحمراء (lochia rubra) طبيعيًا؟","b":"3-4 أيام فقط ثم تصبح مصلية ثم بيضاء. استمرار النزف الأحمر أكثر من أسبوعين: غير طبيعي — فتّش عن بقايا مشيمية أو إنتان."}]},{"t":"الاختلاطات الصغرى في الحمل","cards":[{"f":"ما منغصات (الاختلاطات الصغرى) الحمل الشائعة «ما عدا»؟","b":"الوهن، وذمة الساقين، الخفقان، الصداع، الأعراض الودية، مغص الرجلين، الألم الظهري، نفق الرسغ. ارتفاع الضغط الشرياني: ليس منها — حالة مرضية خطيرة (منذر لما قبل الارتعاج)."},{"f":"ما علاج الإقياءات الحملية الخفيفة «ما عدا»؟","b":"وجبات صغيرة متكررة، الزنجبيل، البيريدوكسين (B6)، والميتوكلوبراميد عند الحاجة. لا: شرب الماء أثناء الطعام — يُشرب بين الوجبات لأنه مع الطعام يزيد الغثيان."},{"f":"ما سبب القلس (الحرقة) في الثلث الأول من الحمل؟","b":"البروجسترون يرخي المصرة المريئية السفلية فيسمح بارتجاع الحمض. ضغط الرحم على المعدة: سبب متأخر (الأثلاث الأخيرة) لا الأول."}]},{"t":"الإجهاض والإسقاط","cards":[{"f":"قاعدة ذهبية: ما ثلاثي التهديد بالإسقاط (threatened abortion)؟","b":"نزف مهبلي خفيف في النصف الأول + عنق رحم مغلق + جنين حي وحجم رحم متناسب مع العمر الحملي — الحمل قد يتابع طبيعيًا."},{"f":"التدبير الأمثل للتهديد بالإسقاط (جنين حي ينبض)؟","b":"طمأنة ومراقبة فقط — لا تجريف رحمي ولا ميتوتريكسات؛ الإجراءات الغازية تقتل جنينًا حيًا قابلًا للحياة."},{"f":"ما الصورة الكلاسيكية لقصور عنق الرحم؟","b":"خروج غير مؤلم لمحصول الحمل في الثلث المتوسط، وأغلب الحالات تلي تداخلات جراحية على عنق الرحم (قد يكون خلقيًا أحيانًا)."},{"f":"متى يُجرى تطويق عنق الرحم الوقائي؟","b":"أثناء الحمل في الأسبوع 12-14 (بداية الثلث الثاني) — لا قبل الحمل ولا في الأسبوع 17."},{"f":"ما أسباب الإسقاطات المتكررة؟","b":"تشوهات الرحم الخلقية، قصور الفوهة الباطنة لعنق الرحم، الأسباب المناعية (أضداد الفوسفولبيد)، شذوذات صبغية عند أحد الأبوين، وقصور الدرق غير المعالج."},{"f":"ما الذي ليس سببًا للإسقاطات المتكررة؟","b":"سوابق إصابة بالحصبة الألمانية مع اكتساب المناعة، وسوابق الولادة المبكرة — ليست من الأسباب."},{"f":"ما استطبابات الإجهاض الدوائي (العلاجي)؟","b":"أمومية مهددة للحياة: قصور قلب درجة رابعة، توتر رئوي شديد، ذهان شديد، علاج كيماوي، سرطان ثدي. جنينية قاتلة: انعدام الجمجمة، الداء الانحلالي الجنيني الشديد، موت الجنين، الرحى العدارية."},{"f":"ما الذي ليس استطبابًا للإجهاض الدوائي؟","b":"داء كرون، السكري غير المختلط (يُدبَّر بالضبط السكري)، والحمل غير المرغوب — دافع اجتماعي لا طبي."}]},{"t":"الحمل خارج الرحم","cards":[{"f":"ما عوامل خطورة الحمل الهاجر «ما عدا»؟","b":"سوابق حمل هاجر (أقوى مؤهب)، جراحة بوقية، الداء الحوضي الالتهابي، اللولب (خاصة النحاسي)، الإخصاب المساعد، الاندومتريوز، التعقيم. ليست مؤهبة: PCOS، المشيمة المنزاحة."},{"f":"ما أشيع توضع للحمل الهاجر؟ وما الاستقصاء الأهم للتشخيص؟","b":"الأشيع: البوق (المجل). الأهم: الإيكو المهبلي — يؤكد خلو جوف الرحم من كيس الحمل ويكشف كتلة الملحقات."},{"f":"هل عدم تضاعف β-hCG كل 48 ساعة «يؤكد» الحمل الهاجر؟","b":"لا — يوحي بالحمل الهاجر أو غير الحيوي لكنه لا يؤكد؛ التأكيد بالإيكو المهبلي (وتنظير البطن)."},{"f":"ما شروط الميثوتريكسات في الحمل الهاجر؟","b":"مستقرة هيموديناميكيًا + كتلة هاجرة <3.5 سم + hCG أقل من 5000 + غياب فعالية قلبية جنينية + سلامة وظائف الكبد والكلية."},{"f":"أنماط: متى يُمنع الميثوتريكسات منعًا باتًا؟","b":"في الحمل المغاير (heterotopic: حمل داخل رحمي حي + هاجر معًا) — الدواء سيقتل الحمل الداخلي الحي؛ التدبير جراحي محافظ."},{"f":"فرّق: تدبير الحمل الهاجر المتمزق مقابل غير المتمزق؟","b":"المتمزق (غير مستقر): استئصال البوق جراحيًا لضبط النزف. غير المتمزق مع رغبة بالخصوبة: فغر البوق المحافظ (salpingostomy) أو ميثوتريكسات."},{"f":"الحمل الهاجر العنقي النازف الشديد غير المسيطر عليه: ما التدبير؟","b":"قد يستدعي استئصال الرحم (hysterectomy) لضبط النزف."}]},{"t":"نزف أشهر الحمل الأخيرة","cards":[{"f":"فرّق: نزف المشيمة المنزاحة مقابل انفكاك المشيمة الباكر؟","b":"المنزاحة: نزف مهبلي أحمر قانئ مفاجئ غير مؤلم في الثلث الثالث. الانفكاك: نزف مؤلم مع رحم قاسٍ خشبي متكزز."},{"f":"ما أقوى عامل خطورة للمشيمة المنزاحة؟","b":"سوابق الولادة القيصرية — الندبة تخرب بطانة القطعة السفلية فينغرس الجنين واطئًا، ويزداد الخطر مع تكرار القيصريات. ليست عوامل: قلة الإنجاب، الحمل المفرد، صغيرات السن."},{"f":"أي الحمول يرفع خطر انفكاك المشيمة الباكر؟","b":"التوائم (الحمل المتعدد) — فرط تمدد الرحم وكبر مساحة الارتكاز المشيمي."},{"f":"نزف مهبلي في الثلث الثالث: ما الإجراء الممنوع قبل نفي المنزاحة بالإيكو؟","b":"الفحص المهبلي بالإصبع — منعًا باتًا؛ قد يخترق نسيج المشيمة المرتكزة على الفوهة ويحرض نزفًا صاعقًا مميتًا."},{"f":"مشيمة منزاحة + سوابق قيصرية سفلية: ما الاختلاط الأشيع؟","b":"المشيمة الملتصقة (accreta spectrum) — الندبة تعيق تشكل الغشاء الساقط فيلتصق النسيج المشيمي مباشرة بعضلة الرحم ويصعب انفكاكه."},{"f":"ما عوامل خطورة المشيمة المندخلة (الملتصقة) «ما عدا»؟","b":"كل ما يخرب بطانة الرحم: سوابق قيصريات (الأقوى)، تجاريف رحمية، المشيمة المنزاحة، خزع الرحم. ليس منها: تطويق عنق الرحم (إجراء على العنق لا يمس البطانة)."},{"f":"أفضل وقاية من القصور الكلوي الحاد في انفكاك المشيمة الباكر؟","b":"تعويض الدم والحجم المفقود بسرعة — السبب صدمة نزفية ونقص تروية كلوية (نخر نبيبي حاد). المدرات والتحال: ليست وقاية."},{"f":"ما مسببات DIC في التوليد «ما عدا»؟","b":"انفكاك المشيمة الباكر (الأشيع والأخطر)، احتباس الجنين الميت طويلًا، الانتان الرحمي، الصمة الأمنيوسية. ليست منها: المشيمة المنزاحة — نزف خارجي ظاهر دون هرس نسيجي شديد."},{"f":"ما أسباب نزوف أشهر الحمل الأخيرة «ما عدا»؟","b":"انفكاك المشيمة الباكر، المشيمة المنزاحة، الوعاء المتقدم على المجيء، تمزق الرحم. ليست منها: الإجهاضات — الإجهاض فقدان الحمل قبل الأسبوع 20."}]},{"t":"ارتفاع الضغط الرئوي عند الحمل","cards":[{"f":"ما الفيزيولوجيا المرضية الأساسية لما قبل الارتعاج؟","b":"تشنج وعائي معمم — خلل وظيفة البطانة الوعائية وقصور غزو الأرومة الغاذية للشرايين الحلزونية الرحمية؛ فيرتفع الضغط وتنقص تروية الأعضاء."},{"f":"ما التعريف السريري لما قبل الارتعاج (pre-eclampsia)؟","b":"ارتفاع ضغط (140/90 أو أكثر) + بيلة بروتينية، بشرط حدوثهما بعد الأسبوع 20 من الحمل."},{"f":"ما المعيار الكلاسيكي لتشخيص ارتفاع الضغط عند الحامل مقارنة بقيمها القاعدية؟","b":"ارتفاع الانقباضي أكثر من 30 ملم زئبق أو الانبساطي أكثر من 15 ملم زئبق عن قيم الزيارات السابقة — حتى لو بقيت القيم المطلقة دون 140/90."},{"f":"ما سبب الألم في المراق الأيمن عند مريضة ما قبل الارتعاج؟","b":"تمطط محفظة الكبد من الاحتقان والنزف تحت المحفظة (يُرى في HELLP) — ليس التهاب مرارة ولا بنكرياس."},{"f":"ما ثلاثية متلازمة HELLP؟","b":"انحلال الدم (Hemolysis) + ارتفاع خمائر الكبد (Elevated Liver enzymes) + نقص الصفيحات (Low Platelets). أشيع عند متعددات الولادة والمسنات — لا عند الخروسات."},{"f":"ما تدبير متلازمة HELLP؟","b":"إنهاء الحمل فورًا بعد استقرار الأم مهما كان عمر الحمل — المراقبة فقط دون إنهاء خطأ قاتل."},{"f":"سلفات المغنزيوم: ما آليتها وما الذي يُراقب وما ترياق تسممها؟","b":"مضادة للاختلاج بتثبيط الانتقال العصبي العضلي (منافسة الكالسيوم). تُراقب: المنعكسات الوترية ومعدل التنفس والصبيب البولي. الترياق: غلوكونات الكالسيوم الوريدية (ليس البروتامين — ذاك ترياق الهيبارين)."},{"f":"لمدة كم تُعطى سلفات المغنزيوم في ما قبل الارتعاج؟","b":"تُستمر 24 ساعة بعد الولادة (فترة الخطر الأعلى) ثم تُوقف عند الاستقرار."},{"f":"في نوبة الإرجاج: أي إجراء ممنوع؟","b":"المدرات (كالثيازيد) — تنقص حجم البلازما المتضائل أصلًا وتُفاقم نقص التروية المشيمية. المطلوب: طريق هوائي ووريدي + سلفات مغنزيوم."},{"f":"ما العلامات الإنذارية لقرب الإرجاج «ما عدا»؟","b":"صداع قفوي شديد، اضطرابات بصرية قد تصل للعمى، ألم شرسوفي شديد، بيلة بروتينية +++، فرط منعكسات، شح بول. ليست منها: الغثيان والإقياء."},{"f":"ما اختلاطات ما قبل الارتعاج «ما عدا»؟","b":"HELLP، القصور الكلوي، انفكاك المشيمة الباكر، تحدد النمو الجنيني (IUGR). ليست منها: زيادة تركيز الصوديوم."},{"f":"أنماط: ما قبل الارتعاج يظهر قبل الأسبوع 20 — ما الذي تبحث عنه؟","b":"مرض الطبقة المغذية (الرحى العدارية) — الظهور المبكر غير نمطي ويستوجب نفيه."}]},{"t":"الاضطرابات القلبية الوعائية التنفسية الدموية العصبية والهضمية في الحمل","cards":[{"f":"قاعدة ذهبية: لمن يُعطى Anti-D ومتى؟","b":"للسلبية غير المتحسسة فقط: الأسبوع 28 + بعد الولادة (خلال 72 ساعة إن كان الوليد إيجابيًا) + بعد الإسقاط وبزل السائل الأمنيوسي. المتحسسة أصلًا: لا فائدة إطلاقًا — تُراقب بدوبلر الشريان المخي المتوسط."},{"f":"كيف تُكشف العلامات الباكرة لفقر الدم الجنيني؟","b":"بدوبلر الشريان المخي المتوسط (MCA) ابتداءً من الأسبوع 18 — ارتفاع السرعة يعني فقر الدم. الاستسقاء الجنيني (الخزب): دليل فقر دم شديد."},{"f":"ما أسباب DIC في الحمل «ما عدا»؟","b":"الانتان (سلبيات الغرام بالذيفان الداخلي)، انفكاك المشيمة الباكر، الصمة الأمنيوسية، احتباس الجنين الميت، النزف الغزير، HELLP. ليست منها: الاندومتريوز."},{"f":"أي خمج يُعدّن كلاسيكيًا مسببًا لاعتلال التخثر الاستهلاكي؟","b":"الخمج بسلبيات الغرام (بتأثير الذيفان الداخلي) — لا الخمج بإيجابيات الغرام."},{"f":"التهاب الزائدة في الحمل: ما الصعب وما الممنوع؟","b":"التشخيص صعب: الزائدة ترتفع مع تقدم الحمل والألم في موضع مرتفع + ارتفاع فيزيولوجي للكريات البيض. ممنوع: تأجيل الاستئصال لما بعد الولادة — خطر الانثقاب والتهاب الصفاق."},{"f":"هل يسبب التهاب الزائدة انسمامًا حمليًا؟","b":"لا — الانسمام الحملي (ما قبل الإرجاج) اضطراب مشيمي وعائي بآلية مختلفة (خلل غزو الأرومة الغاذية) ولا علاقة سببية له بالتهاب الزائدة."},{"f":"النفخة الانبساطية في الحمل: طبيعية أم مرضية؟","b":"مرضية دائمًا — توحي بداء صمامي (تضيق تاجي/أبهري) وتستدعي التقييم القلبي. الطبيعي في الحمل: نفخة انقباضية نفخية، S3، انشطار واسع، أورام وعائية عنكبوتية."},{"f":"ما التغيرات القلبية الدموية في الحمل الطبيعي «ما عدا»؟","b":"يزداد: معدل ضربات القلب، النتاج القلبي، وسرعة التثفل. تنقص: المقاومة الوعائية المحيطية. ضغط الدم: لا يزداد بل ينخفض (أدناه منتصف الحمل)."},{"f":"ما مظاهر متلازمة أضداد الفوسفولبيد «ما عدا»؟","b":"خثارات وريدية وشريانية، إجهاضات متكررة، تحدد نمو داخل الرحم، وفاة الجنين، أضداد الكارديوليبين. ليست منها: ارتفاع الهيموسيستين، ولا الصمة الأمنيوسية."},{"f":"الربو الشديد غير المضبوط في الحمل: ماذا يرفع؟","b":"الإسقاطات، الولادة الباكرة، ونقص النمو داخل الرحم (نقص أكسجة مزمن). نقص السعة الوظيفية المتبقية (FRC): فيزيولوجي في الحمل نفسه لا من الربو."},{"f":"بمَ تُعاكس الهيبارين؟","b":"بروتامين سلفات — 1 ملغ لكل 100 وحدة هيبارين بتسريب وريدي بطيء (بحد أقصى 50 ملغ) مع مراقبة التأق. (يعاكس غير المجزأ كاملًا والمجزأ جزئيًا)."},{"f":"كيف تُقدَّر الجرعة اللازمة من Anti-D؟","b":"باختبار كلايهاور (Kleihauer) لقياس كمية النزف الجنيني-الأمومي. ويُجرى اختبار كومبس اللامباشر لمتابعة الأم سلبية الريزوس."}]},{"t":"الاضطرابات الغدية أثناء الحمل","cards":[{"f":"متى وكيف يُتحرى عن السكري الحملي؟","b":"باختبار تحمل الغلوكوز الفموي OGTT بين الأسبوع 24 و28 — لا بين 34 و38."},{"f":"ما عوامل خطورة السكري الحملي؟","b":"سوابق ولادة جنين عرطل، سوابق طفل مشوه، زيادة BMI، عمر الأم فوق 30-35 سنة، والقصة العائلية للسكري."},{"f":"فرّق: هل يسبب السكري الحملي تشوهات جنينية؟","b":"لا — يظهر بعد الأسبوع 24 أي بعد اكتمال التعضي. التشوهات من مضاعفات السكري السابق للحمل غير المضبوط."},{"f":"ما أشيع اختلاطات السكري الحملي؟","b":"ضخامة الجنين (macrosomia) → انعضال الكتفين أثناء الولادة المهبلية. عند الوليد: نقص سكر الدم (فرط الأنسولين الجنيني) — لا ارتفاعه."},{"f":"ما العلاج المفضل للسكري أثناء الحمل؟ وما بعده؟","b":"الأنسولين — لا يعبر المشيمة. تُخفض الجرعة بعد الولادة (بانتهاء المقاومة المشيمية)، ويُعاد OGTT بعد ~12 أسبوعًا لكشف السكري الصريح."},{"f":"متى تبلغ الحاجة للأنسولين ذروتها في الحمل؟","b":"في النصف الثاني وخاصة الثلث الثالث — بتأثير الهرمونات المشيمية المقاومة للأنسولين (كالمشيمائي اللبني). لا في النصف الأول."},{"f":"من تأثيرات السكري في الحمل «ما عدا»؟","b":"موه السلى، ما قبل الارتعاج، التشوهات الخلقية (في السابق للحمل)، البيلة الجرثومية المتكررة، ضخامة الجنين. ليس منها: تحدد النمو داخل الرحم — إلا مع اعتلال وعائي سكري شديد."}]},{"t":"الأخماج أثناء الحمل","cards":[{"f":"لقاح الحصبة (MMR) والحمل: ما الصحيح؟","b":"لقاح حي ممنوع في الحمل. إعطاؤه خطأً للحامل: لا يستدعي إنهاء الحمل. لا يمنع الإرضاع. لغير الحامل: الامتناع عن الحمل شهر واحد فقط بعده (لا عامًا)."},{"f":"ما مظاهر الخمج الخلقي بـ CMV «ما عدا»؟","b":"صغر الرأس (لا كبره)، تكلسات دماغية حول البطينات، استسقاء دماغي، نقص نمو متناظر، نقص سمع حسي عصبي (أشيع اختلاط)، وفيات حول ولادية. ليست منها: الإجهاضات المتكررة."},{"f":"أي العوامل الممرضة مشوهة للجنين «ما عدا»؟","b":"الحصبة الألمانية، الفيروس المضخم للخلايا CMV، الحلأ البسيط (البدئي)، والسفلس (الإفرنجي). ليست مشوهة: العنقوديات المذهبة."},{"f":"البيلة الجرثومية اللاعرضية في الحمل: ما المسبب الأشيع ولماذا يُعالَج؟","b":"الأشيع: الإشريكية القولونية E. coli. العلاج ضروري: غير المعالجة تتطور لالتهاب حويضة وكلية حاد في 20-30% (ركودة البول وتوسع الحالبين هرمونيًا)، والنكس بعد العلاج عند ربع السيدات."},{"f":"من اختلاطات البيلة الجرثومية اللاعرضية «ما عدا»؟","b":"الولادة الباكرة، نقص وزن الوليد، التهاب الحويضة والكلية الحاد، التهاب باطن الرحم النفاسي. ليست منها: ما قبل الارتعاج."}]},{"t":"أمراض المشيمة وأغشيتها","cards":[{"f":"ما أقوى عامل خطورة للمشيمة الملتحمة (accreta)؟","b":"ارتكاز المشيمة المعيب — المنزاحة خاصة مع ندبة قيصرية سابقة (يزداد بتكرار القيصريات). ليست عوامل: صغيرات السن والخروسات والارتكاز الطبيعي على القعر أو الجدار الخلفي."},{"f":"فرّق: أسباب موه السلى مقابل قلة/انعدام السلى؟","b":"موه: السكري (فرط تبول الجنين)، عيوب الأنبوب العصبي المفتوحة وانعدام الجمجمة، رتق المريء/العفج (تعذر البلع)، توائم أحادية الكوريون، تنافر الزمر. قلة/انعدام: عدم تكون الكلية، الكلية عديدة الكيسات، الدسام الإحليلي الخلفي (انسداد بولي)، قصور المشيمة، تمزق الأغشية الباكر."},{"f":"قاعدة ذهبية: أي الرحى أسوأ إنذارًا — التامة أم الجزئية؟","b":"التامة — نحو 15-20% تتطور لورم أرومي غاذي حملي مستمر مقابل أقل من 5% في الجزئية."},{"f":"ما أشيع تظاهر سريري في الرحى العدارية التامة؟","b":"النزف المهبلي (~90% — قد يحوي حويصلات عنبية). يليه: رحم أكبر من العمر الحملي، إقياءات شديدة، فرط نشاط درق، ما قبل ارتعاج قبل الأسبوع 20."},{"f":"ما المظهر الإيكوي الكلاسيكي للرحى العدارية؟","b":"عاصفة الثلج (snowstorm) — حويصلات كيسية مائية متعددة كعناقيد العنب؛ ليس مظهرًا ليفيًا مصمتًا."},{"f":"في تدبير الرحى العدارية: أي إجراء خطأ؟","b":"استئصال كيسات المبيض اللوتينية-التكائية — تتراجع تلقائيًا بعد إفراغ الرحم. الصحيح: إفراغ بالممص + صورة صدر (نقائل رئوية) + منع حمل بعد الإفراغ لمتابعة β-hCG."},{"f":"ما عوامل خطورة الرحى العدارية «ما عدا»؟","b":"أعمار أمومية متطرفة (أصغر من 21 أو أكبر من 40)، العرق الآسيوي، عوز حمض الفوليك B9. ليس منها: عوز فيتامين B12."},{"f":"ما أقوى عامل خطورة لانفكاك المشيمة الباكر؟","b":"ارتفاع التوتر الشرياني (مزمن أو ما قبل ارتعاج) — يسبب تنخرًا وعائيًا في الشرايين الحلزونية للقاعدة المشيمية."},{"f":"ما عوامل خطورة ارتكاز المشيمة المعيب «ما عدا»؟","b":"الندب الرحمية: سوابق قيصرية، تجريف رحم، استئصال ورم ليفي — والحمل المتعدد وسوابق التخليص اليدوي للمشيمة. ليست منها: سوابق الولادة المبكرة."},{"f":"ما أشيع سبب لانعدام سائل السلى (anhydramnios)؟","b":"انسداد بولي جنيني — من منتصف الحمل يصبح البول الجنيني المصدر شبه الوحيد للسائل السلوي (عدم تكون الكليتين، الكلية عديدة الكيسات، الدسام الإحليلي الخلفي)."}]},{"t":"الاختلافات في مدة الحمل","cards":[{"f":"ما تعريف الحمل المديد بالأيام والأسابيع؟","b":"42 أسبوعًا كاملًا فأكثر = 294 يومًا فأكثر من أول يوم لآخر طمث. (280 يومًا = تمام الحمل 40 أسبوعًا)."},{"f":"بمَ يترافق الحمل المديد «ما عدا»؟","b":"تعقي السلى (تلوث بالعقي)، انعضال الكتفين، عرطلة جنينية، قصور مشيمي، ندرة السائل السلوي. ليس منها: ارتفاع التوتر الشرياني."},{"f":"حمل 42 أسبوعًا و3 أيام مع عنق غير مواتٍ (اتساع 1 سم): ما التدبير؟","b":"قيصرية — تحريض الأوكسيتوسين على عنق غير ناضج (بيشوب منخفض) محكوم بالفشل ويعرض الجنين للخطر."},{"f":"ما أهم مشعر في المفرزات العنقية لتحري الولادة الباكرة؟","b":"الفيبرونكتين الجنيني (fetal fibronectin) — قيمته التنبؤية السلبية عالية: السلبية تستبعد الولادة الباكرة الوشيكة بقوة."},{"f":"ما مثبطات المخاض الباكر «ما عدا»؟","b":"حاصرات الكلس، مضادات الأوكسيتوسين النوعية (أتيوسيبان)، الإندوميتاسين، سلفات المغنزيوم (حماية عصبية)، ومنبهات بيتا 2. ليست منها: حاصرات بيتا."},{"f":"ما فائدة الكورتيكوستيرويدات (بيتاميتازون) في المخاض الباكر؟","b":"تسريع نضج رئتي الجنين + الوقاية من النزف داخل البطينات لدى الخدج."},{"f":"متى يُمنع توقيف المخاض دوائيًا؟","b":"توسع عنق الرحم أكثر من 5 سم (مخاض متقدم)، النزف الغزير، التهاب السلى، انفكاك المشيمة، تألم الجنين."},{"f":"هل الإنتان من مسببات التهديد بالولادة المبكرة؟","b":"نعم — من أهمها: التهاب المشيمة والسلى والتهاب المسالك البولية. إنكاره هو الخطأ الشائع في الأسئلة."},{"f":"انبثاق أغشية باكر بعمر 32-34 أسبوعًا دون اختلاطات: إنهاء فوري أم ترقب؟","b":"ترقب: ستيروئيدات + صادات وقائية + مراقبة لكسب النضج الرئوي. الإنهاء الفوري عند: تألم جنيني، تشوهات غير متناسبة مع الحياة، IUGR شديد، موت الجنين."},{"f":"ما السبب الرئيسي لوفيات الولدان؟","b":"الخداج ومضاعفاته (الضائقة التنفسية، النزف داخل البطينات، إنتان الوليد)."}]},{"t":"الجنين المعرض للخطورة","cards":[{"f":"هل تحدد النمو داخل الرحم (IUGR) استطباب دومًا للقيصرية؟","b":"لا — طريقة الولادة تُحدد بحسب حالة الجنين: المراقبة بالـCTG والدوبلر. لا يُفضل التحدي بالأوكسيتوسين."},{"f":"فرّق: التباطؤ المبكر والمتغير والمتأخر في تخطيط قلب الجنين؟","b":"المبكر: حميد بلا أهمية إنذارية (ضغط رأس الجنين). المتغير: انضغاط الحبل السري. المتأخر: نقص أكسجة وخلل تدفق مشيمي-رحمي — منذر."},{"f":"ما اختبارات تقييم سلامة الجنين غير الغازية «ما عدا»؟","b":"عدّ حركات الجنين، تخطيط قلب الجنين (NST/CTG)، الإيكو (المشعر الفيزيائي الحيوي)، دوبلر سرعة التدفق. ليس منها: البزل السلوي — إجراء غازٍ تشخيصي."}]},{"t":"المجيئات المعيبة","cards":[{"f":"ما قطر التدخل (engagement) في المجيء القمي؟","b":"القطر تحت القفوي-البرغماوي (~9.5 سم) — يعبر مدخل الحوض أولًا في الولادة القمية الطبيعية."},{"f":"أي المجيئات يمكن أن يتم بولادة مهبلية؟","b":"المقعدي وحده (بشروط: تقدير الحوض وخبرة المولد). المعترض والكتفي والجبهي والذقني الخلفي الثابت: قيصرية حتمًا."},{"f":"ما الحقائق الامتحانية عن المجيء المقعدي؟","b":"النمط الألوي (Frank breech) أشيع؛ يزداد عند عديدات الولادة والخدج؛ ترتفع وفيات ما حول الولادة؛ فرط انبساط الرأس (النظر للنجوم) يجعل الولادة أصعب — قيصرية غالبًا."},{"f":"قاعدة ذهبية: متلازمة نقل الدم الجنيني TTTS في أي توائم تحدث؟","b":"حصرًا في التوائم أحادية المشيمة (اشتراك الدورة الدموية المشيمية) — لا تحدث في الحمل ثنائي البيضة/ثنائي المشيمة أبدًا."},{"f":"مجيء معترض + انبثاق أغشية عند تمام الحمل (37 أسبوعًا): ما الولادة المثلى؟","b":"قيصرية إسعافية فورية — المجيء المعترض مضاد استطباب مطلق للولادة المهبلية والتحريض (خطر انسدال الحبل السري وتمزق الرحم)."},{"f":"ما أسباب المجيء الوجهي «ما عدا»؟","b":"تضيقات الحوض، ارتكاز المشيمة المعيب، تعدد الولادات، التشوهات الخلقية (كانعدام الجمجمة). ليس منها: انفكاك المشيمة الحاد."}]},{"t":"المجيئات الجنينية المعيبة","cards":[{"f":"حبل سري نابض متقدم على المجيء مع جيب مياه سالم في مخاض بعمر 39 أسبوعًا: ما التدبير؟","b":"قيصرية فورية مباشرة — تدلي/تقدم الحبل السري (cord presentation)؛ أي بثق للأغشية يحوله لتدلٍّ صريح مع انضغاط الحبل واختناق الجنين."},{"f":"فرّق: المجيء الوجهي ذقني أمامي مقابل ذقني خلفي؟","b":"الذقني الأمامي: قطر التدخل تحت الذقني-البرغماوي (9.5 سم — أصغر أقطار الرأس) فيلد مهبليًا عادة. الذقني الخلفي الثابت: لا يلد مهبليًا — قيصرية."},{"f":"ما أسوأ أنواع المجيئات ولماذا؟","b":"الجبهي — قطر التدخل الذقني-القذالي (~13.5 سم) أكبر من أقطار الحوض فلا ولادة مهبلية؛ مجيء غير مستقر قد يتحول لوجهي أو قمي."},{"f":"ما شروط الولادة المهبلية للمجيء المقعدي «ما عدا»؟","b":"تناسب حوضي جنيني، وزن تقديري 2500-3500 غ، مقعدي تام أو ناقص (صرف)، رأس بوضعية عطف. ليس منها: المجيء القدمي — ممنوع (خطر تدلي الحبل وانحشار الرأس الأخير)."}]},{"t":"المخاض الشاذ (عسر المخاض)","cards":[{"f":"ما التشخيص الأدق والقطعي لعدم التناسب الحوضي الجنيني؟","b":"تجربة المخاض نفسها — تشخيص وظيفي لا يُحسم بالقياسات التشريحية (فحص حوضي، قصر قامة، تصوير شعاعي، إيكو)."},{"f":"في انعضال الكتفين: أي مناورة ممنوعة منعًا باتًا؟","b":"الضغط على قعر الرحم (مناورة كريستلر) — يزيد انحشار الكتف الأمامي خلف الارتفاق ويرفع خطر تمزق الرحم وأذية الجنين."},{"f":"ما العوامل المؤهبة لتمزق الرحم «ما عدا»؟","b":"الرحم المندب (قيصرية خاصة الكلاسيكية، استئصال ورم ليفي، تجريف عميق)، التحريض المفرط، المخاض المسدود. ليست منها: وهن العضلة (عكس التمزق)، سوابق الإسقاط العفوي، المخاض السريع."}]},{"t":"اضطرابات النفاس","cards":[{"f":"ما أشيع سبب لنزف ما بعد الولادة؟","b":"العطالة الرحمية (uterine atony) — نحو 70-80% من الحالات؛ يفشل الرحم بالانقباض فتبقى الجيوب الوعائية مفتوحة."},{"f":"ما أخطر اختلاط لتوليد المشيمة بالشد على الحبل السري؟","b":"انقلاب الرحم (uterine inversion) — إسعاف مهدد للحياة: صدمة نزفية وعصبية حادة تتطلب الرد الفوري."},{"f":"ما أسباب عطالة الرحم وضعف الانطمار «ما عدا»؟","b":"فرط تمدد الرحم (حمل متعدد، موه سلى، جنين عرطل)، الورم الليفي، المثانة الممتلئة، بقاء فلق مشيمية أو أغشية، الانتان. ليست منها: المخاض السريع."},{"f":"ما عوامل خطر خمج باطن الرحم النفاسي «ما عدا»؟","b":"انبثاق الأغشية المديد، الولادة القيصرية (أقوى عامل)، السكري، المس المهبلي المتكرر. ليست منها: المخاض السريع، وقصور الدرق."},{"f":"ما أشيع سبب لاستمرار ارتفاع الحرارة بعد الولادة؟","b":"التهاب باطن الرحم النفاسي (endometritis) — حمى تبدأ عادة بين اليوم 2 و10 مع ألم رحمي ومفرزات كريهة الرائحة."},{"f":"استمرار نزف قانئ (أحمر فاتح) بعد ولادة طبيعية والرحم متقبض جيدًا: السبب؟","b":"تمزق مهبلي/فرجي (أو عنق الرحم) — مصدر النزف خارج الرحم. انحباس المشيمة يعيق التقبض الجيد."},{"f":"ما الجراثيم الشائعة في الإنتانات النفاسية «ما عدا»؟","b":"العقديات القولونية، العنقوديات المذهبة، اللاهوائيات، العقديات المجموعية A وB — فلورا صاعدة متعددة الميكروبات. ليست منها: العصيات الزرق (Pseudomonas — مشفوية)."},{"f":"ما عوامل خطورة الاكتئاب ما بعد الولادة «ما عدا»؟","b":"الحمل في سن المراهقة، التأهب الوراثي/سوابق اكتئاب، غياب الدعم العائلي، الحمل غير المخطط. ليس منها: تعدد الولادات بحد ذاته."},{"f":"فرّق: نزف الخلاص الباكر مقابل المتأخر؟","b":"الباكر: أشيع بعد المخاض المديد (إنهاك عضلة الرحم → عطالة) — لا السريع. المتأخر: أشيع أسبابه الاندمال السيء (subinvolution) والبقايا والانتان."},{"f":"في التشخيص التفريقي للحمى النفاسية «ما عدا»؟","b":"التهاب باطن الرحم، التهاب الثدي، التهاب الوريد الخثري، التهاب الحويضة والكلية، ذات الرئة الاستنشاقية، إنتان الجرح. ليست منها: الحصبة الألمانية."}]},{"t":"العمليات التوليدية","cards":[{"f":"ما الاستطباب المطلق للقيصرية؟","b":"المشيمة المنزاحة المركزية (تغطي الفوهة الباطنية كليًا — الولادة المهبلية نزف كارثي). نسبية: التوأم، المقعدي، ندبة قيصرية واحدة، الجنين العرطل."},{"f":"ما شروط تطبيق ملقط الجنين «ما عدا»؟","b":"اتساع تام (10 سم)، أغشية منبثقة، رأس متدخل، حوض كافٍ، مثانة فارغة، تسكين كافٍ. لا: اتساع 7 سم — غير كافٍ إطلاقًا."},{"f":"ملقط بايبر (Piper): لأي حالة؟","b":"للرأس التالي (aftercoming head) في المجيء المقعدي — يُطبق على الرأس بعد ولادة الجسم."},{"f":"ما استطبابات تحريض المخاض «ما عدا»؟","b":"موت الجنين داخل الرحم، ما قبل الارتعاج الشديد، التهاب المشيمة والسلى، الحمل المديد. ليست منها: حالة الجنين غير المطمئنة — تستدعي قيصرية عاجلة لا تحريضًا يستغرق ساعات."},{"f":"بمَ يُحرَّض المخاض «ما عدا»؟","b":"الأوكسيتوسين، الميزوبروستول (بروستاغلاندين)، قثطرة فولي، بثق الأغشية. ليس منها: الأرغوميترين — يسبب تقلصات مستمرة خطرة على الجنين (للنزف التالي للولادة)."},{"f":"ما عناصر مشعر بيشوب «ما عدا»؟","b":"الاتساع، الامحاء (الطول)، القوام، التوضع، تدخل/نزول المجيء. ليست منه: سلامة الأغشية، لون السائل السلوي، ضربات قلب الجنين."},{"f":"ما شروط التحويل بالأعمال الخارجية (ECV)؟","b":"يُجرى في الأسبوع 37 فأكثر + ارتكاز مشيمة نظامي + سرر بطول نظامي + سائل أمنيوسي معتدل + تناسب حوضي جنيني + ألا يكون المجيء متدخلًا."},{"f":"ما مضادات استطباب التحويل الرأسي الخارجي «ما عدا»؟","b":"النزف التناسلي، تمزق الأغشية، الحمل المتعدد، التشوه الرحمي الكبير، المشيمة المنزاحة، الشدة الجنينية. ليس منها: بلوغ الأسبوع 37 — فهو شرط إجرائه لا مضاد استطباب."},{"f":"من استطبابات الأوكسيتوسين «ما عدا»؟","b":"النزف بعد الولادة وعلاج العطالة، حث المخاض وتحريضه، الوقاية من النزف في الإجهاض الناقص. ليس منها: اختبار اللاشدة NST — عفوي بلا تحريض؛ الأوكسيتوسين لاختبار الإجهاد بالتقلصات CST."},{"f":"ما مضادات استطباب تحريض المخاض «ما عدا»؟","b":"ارتكاز المشيمة المعيب، المجيء الجبهي، سوابق 3 قيصريات. ليس منها: التهاب المشيماء والسلى — استطباب للإنهاء والتحريض."},{"f":"المجيء المعترض المشخص أثناء المخاض: ما التدبير؟","b":"قيصرية فورية — الكتف لا يعبر الحوض؛ التحريض ممنوع (تمزق رحم)، والتحويل الخارجي قبل المخاض فقط، والداخلي مهجور."},{"f":"ما استطبابات القيصرية «ما عدا»؟","b":"سوابق قيصريتين، تألم الجنين، المجيء الوجهي، الجبهي، الوجهي ذقني خلفي، عدم التناسب الحوضي، المنزاحة. ليست منها: تطاول الطور الكامن (راحة وتهدئة وإعادة تقييم)، والمجيء القمي الخلفي."},{"f":"هل المجيء القمي الخلفي استطباب للقيصرية؟","b":"لا — مجيء رأسي قابل للولادة المهبلية (قد تطول المرحلة الثانية مع الدوران العفوي) وليس استطبابًا مطلقًا."},{"f":"هل الحمل التوأمي استطباب مطلق للقيصرية؟","b":"لا — قد يلد مهبليًا بشروط (المجيء القمي للتوأم الأول وتناسب حوضي). المطلق: المنزاحة المركزية."}]},{"t":"الوبائيات في التوليد","cards":[{"f":"ما أسباب الوفيات الوالدية المباشرة «ما عدا»؟","b":"النزوف التوليدية (السبب الأول عالميًا)، ما قبل الارتعاج/الارتعاج، الصمة الأمنيوسية، الصدمة الإنتانية، الصمة الخثرية. أمراض القلب: سبب غير مباشر. ليست أسبابًا: انسدال التاجي، والاكتئاب النفاسي."},{"f":"ماذا يزداد في حمل المسنات (≥35) «ما عدا»؟","b":"ما قبل الارتعاج، السكري الحملي، داون والشذوذات الصبغية، انفكاك المشيمة الباكر، الإجهاض، الولادة القيصرية. ليس منها: المخاض الباكر."},{"f":"ما استقصاءات الوفيات حول الولادة «ما عدا»؟","b":"الحصبة الألمانية (TORCH)، أضداد الفوسفولبيد، البارفوفيروس B19 (استسقاء جنيني)، تفاعل كلايهاور (نزف جنيني-أمومي). ليس منها: التهاب الكبد A — المهم حول الولادة هو B."}]},{"t":"حديث الولادة","cards":[{"f":"ما عناصر مشعر أبغار الخمسة «ما عدا»؟","b":"اللون (المظهر)، معدل ضربات القلب، الاستجابة للتنبيه (التجهم)، المقوية العضلية، التنفس. ليس منها: التبول."},{"f":"أي الشذوذات الخلقية تستدعي جراحة فورية بعد الولادة «ما عدا»؟","b":"عدم انثقاب الشرج، انسداد الإحليل الخلفي (خطر كلوي)، الفتق الحجابي (خطر تنفسي)، رتق المري (خطر استنشاق). ليست منها: الفتحة بين البطينين — تُدبَّر محافظًا وكثير منها يُغلق عفويًا."},{"f":"زرقة مركزية معندة على الأكسجين + قلب طبيعي + ظل محيطي بالصدر: التشخيص؟","b":"ناسور شرياني وريدي رئوي خلقي — تحويلة يمين-يسار خارج القلب تمرر الدم غير المؤكسج مباشرة للدوران الجهازي متجاوزًا الأسناخ."}]},{"t":"الوليد ناقص الوزن","cards":[{"f":"قاعدة ذهبية: هل يسبب السكري الحملي تحدد النمو داخل الرحم؟","b":"لا أبدًا — يسبب ضخامة الجنين (macrosomia): سكر الأم العالي يحفز أنسولين الجنين وهو هرمون نمو قوي. الاستثناء الثابت في كل أسئلة IUGR."},{"f":"ما أسباب تحدد النمو داخل الرحم (IUGR)؟","b":"التدخين، الكحول، ما قبل الارتعاج وارتفاع الضغط، عمر الأم ≥35، CMV والانتانات داخل الرحم، التشوهات الصبغية، الحمل المتعدد، سوء التغذية وفقر الدم الشديد، أضداد الفوسفولبيد، انفكاك المشيمة."},{"f":"ما الذي ليس سببًا لتحدد النمو داخل الرحم؟","b":"المشيمة المنزاحة (تسبب نزفًا لا تحدد نمو)، البكرية (الخروس) بحد ذاتها، وتطويق عنق الرحم (إجراء وقائي)."}]},{"t":"أسئلة منوعة","cards":[{"f":"حمل توأمي رأسي-معترض: هل هو استطباب مطلق للقيصرية؟","b":"لا — التوأم الأول رأسي فيمكن الولادة مهبليًا (الثاني المعترض يُدبَّر بالقلب الداخلي والاستخراج المقعدي). يزيد التوأمي: السكري الحملي، الانسمام الحملي، الولادات المبكرة، نزوف الخلاص."},{"f":"ما حقائق التوائم ثنائية البيضة «ما عدا»؟","b":"دائمًا ثنائيا الكوريون وثنائيا الأمنيون، وقد يكونان من جنسين مختلفين — ليستا دومًا من نفس الجنس. أشيع عند العرق الأسود والقصة العائلية مؤهبة."},{"f":"ما أسباب نزوف الثلث الأول «ما عدا»؟","b":"الإجهاض الناقص، الحمل الهاجر، الرحى العدارية (جزئية/كاملة). ليست منها: المشيمة المنزاحة — سبب كلاسيكي لنزف الثلث الثاني والثالث غير المؤلم."},{"f":"حجم الرحم أكبر من العمر الحملي: ما الأسباب؟ وما الخاطئ؟","b":"الرحى العدارية، الحمل التوأمي، الجنين العرطل، الورم الليفي المرافق. الخاطئ: موت محصول الحمل — يجعل الرحم أصغر من المتوقع (توقف النماء وتراجع السائل)."}]},{"t":"مواضيع أخرى","cards":[{"f":"ما العرض الأشيع للحصيات البولية في الحمل؟","b":"ألم خاصري حاد (مغص كلوي) + بيلة دموية — المزيج المميز في 80-90% من الحالات (خدش الحصاة للطرق البولية)."},{"f":"فرّق: حرارة مقابل حرقة بولية في سياق حصاة الحمل؟","b":"الحرارة: توحي بالتهاب مرافق (التهاب حويضة وكلية) لا بالحصاة البسيطة. الحرقة وتعدد البيلات والزحير: التهاب مثانة/إحليل أكثر منها حصيات."},{"f":"لماذا تحدث البيلة الدموية مع الحصيات البولية؟","b":"خدش الحصاة لحويضة الكلية أو الحالب أثناء مرورها — بيلة دموية مجهرية أو عيانية مرافقة للمغص الكلوي."}]}]},{"s":"النسائية","topics":[{"t":"انزياحات الرحم والأذيات والهبوطات الرحمية المهبلية","cards":[{"f":"ما عوامل الهبوط التناسلي «ما عدا»؟","b":"الولادات المهبلية العسيرة، تعدد الحمول، الإمساك المزمن، السعال المزمن، الكتل الحوضية، البدانة — كلها تضعف أرضية الحوض أو ترفع الضغط البطني. ليست منها: نقص الوزن، الاندومتريوز، الأدينوميوز."},{"f":"فرّق: الدرجة الثانية مقابل الثالثة في الهبوط التناسلي؟","b":"الثانية: عنق الرحم يصل إلى مستوى الفرج. الثالثة: يتجاوز الفرج ويبرز خارجه."},{"f":"هل علاج السلس والهبوط التناسلي جراحي في كل الحالات؟","b":"لا — يبدأ محافظًا: تمارين أرضية الحوض (دورها كبير في الهبوط والسلس الجهدي) والفرزجة (pessary). الوقوف يساعد في التشخيص، وهو أشيع بعد سن الإياس."}]},{"t":"الحالات ما قبل السرطانية والسرطانية في السبيل التناسلي الأنثوي","cards":[{"f":"ما العوامل المؤهبة لسرطان بطانة الرحم «ما عدا»؟","b":"البدانة، سن الضهي المتأخر، متلازمة المبيض عديد الكيسات، التاموكسيفين، البلوغ المبكر، التقدم بالعمر، ناقصات الخصوبة، ارتفاع الضغط والسكري. ليست منها: البلوغ المتأخر، نقص الوزن، ومانعات الحمل الفموية (وقائية)."},{"f":"كيف يُشخَّص فرط تصنع بطانة الرحم؟","b":"نسيجيًا حصرًا: الفحص المجهري لمجروفات باطن الرحم أو الخزعة — لا وسيلة تصويرية (إيكو/رنين/طبقي) تشخّصه."},{"f":"سيدة 60 سنة بنزف تناسلي وبطانة 7 ملم بالإيكو: ما التدبير؟","b":"خزعة رحم إلزامية — أي نزف بعد الضهي يستدعي نفي الخباثة؛ الحد الطبيعي للبطانة بعد الضهي 4-5 ملم. ممنوع: الهرمونات أو الطمأنة قبل النسيج."},{"f":"ما العلاج الأهم للمرحلة الأولى من سرطان بطانة الرحم؟","b":"الجراحي: استئصال الرحم الكلي مع البوقين والمبيضين وتدريج العقد اللمفاوية — يزيل الورم ويحدد المرحلة نسيجيًا (الشعاعي والكيماوي متممان)."},{"f":"في تصنيف FIGO الكلاسيكي: ماذا تعني المرحلة IIB لسرطان بطانة الرحم؟","b":"غزو لحمة عنق الرحم (cervical stromal invasion) مع بقاء الورم محصورًا في الرحم."},{"f":"فرّق: المسح مقابل التشخيص في سرطان عنق الرحم؟","b":"المسح: لطاخة بابانيكولا Pap (مع/بدون HPV). التشخيص النهائي: الخزعة النسيجية فقط — اللطاخة لا تثبت الغزو."},{"f":"ما النمط النسيجي الأشيع لسرطان عنق الرحم؟","b":"شائك الخلايا (SCC) — نحو 80-85%. لا يُستأصل المبيضان روتينيًا في كل الحالات (يُحفظان للشابات)."},{"f":"أي أنماط HPV تسبب سرطان عنق الرحم؟","b":"الأنماط عالية الخطورة 16 و18. الأنماط 1 و2 و3: ثآليل جلدية سليمة لا سرطانية."},{"f":"مسحة HSIL: ما الخطوة التالية الأفضل؟","b":"الخزعات الموجهة بتنظير عنق الرحم المكبر (colposcopy) للتأكيد النسيجي واستبعاد الغزو — لا مخروطية قبل التأكيد."},{"f":"CIN2 عند شابة 21-25 سنة: ما العلاج «ما عدا»؟","b":"علاج موضعي محافظ: الجراحة القرية (LEEP)، الليزر CO2، التخثير الكهربائي، الخزعة المخروطية. ليس منها: استئصال الرحم — جذري مفرط لآفة داخل ظهارية."},{"f":"كيف يُعالَج سرطان عنق الرحم المبكر مقابل المتقدم؟","b":"المبكر: استئصال رحم جذري + تجريف عقد حوضية. المتقدم: العلاج الشعاعي مع الكيماوي هو الأساس."},{"f":"ما وسائل استقصاء أمراض عنق الرحم «ما عدا»؟","b":"لطاخة بابانيكولا، التنظير المكبر، اختبار شيلر (اليود)، الخزعة المخروطية. ليس منها: تنظير البطن — للجوف البريتواني لا يصل لعنق الرحم."},{"f":"ما أقوى عامل خطر وراثي لسرطان المبيض؟","b":"القصة العائلية لسرطان الثدي — متلازمة BRCA1/BRCA2 (الثدي-المبيض الوراثية)."},{"f":"ما أشيع طريق لانتشار سرطان المبيض؟","b":"عبر سائل البريتوان: تتساقط الخلايا الورمية في الحبن وتُزرع على البريتوان والثرب — أشيع من اللمفاوي والدموي."},{"f":"ما أشيع ورم خبيث في الفرج؟","b":"سرطانة شائكة الخلايا SCC (~90%) — مرتبطة بـHPV أو الحزاز المتصلب. الميلانوما ثانية لكنها أندر بكثير."},{"f":"سيدة بنزف بعد 12 سنة من الضهي: ما الأسباب الممكنة «ما عدا»؟","b":"ضمور بطانة الرحم (أشيع سليم)، بوليبات باطن الرحم، سرطان بطانة الرحم (يُنفى دائمًا)، المعالجة الهرمونية المعيضة. ليس منها: الاندومتريوز — يضمر بعد الضهي."},{"f":"متى تُجرى الخزعة المخروطية لعنق الرحم؟","b":"عندما تكون منطقة الوصل (التحول) غير مرئية أو تمتد الآفة لقناة عنق الرحم — تشخيصية وعلاجية معًا."},{"f":"موزائيكية (mosaicism) بتنظير عنق الرحم المكبر: ما الإجراء؟","b":"خزعة موجهة نسيجية — الموزائيكية والتنقيط والأوعية الشاذة علامات آفات عالية الدرجة."},{"f":"من الأعراض الوعائية الحركية في سن اليأس «ما عدا»؟","b":"الهبات الساخنة، التعرق الليلي، الأرق، الخفقان. ليس منها: عسر الجماع — عرض ضموري بولي تناسلي لا وعائي حركي."},{"f":"قاعدة ذهبية: البلوغ المبكر مقابل المتأخر في سرطان بطانة الرحم؟","b":"البلوغ المبكر مؤهب (يطيل تعرض البطانة للإستروجين غير المعارض)؛ البلوغ المتأخر يقصّر المدة فلا يزيد الخطر."}]},{"t":"اضطرابات الدورة الطمثية","cards":[{"f":"فتاة 20 سنة: ألم بطني دوري + انقطاع طمث بدئي + تطور ثدي وشعر إبط وعانة طبيعي: التشخيص الأرجح؟","b":"عدم انثقاب غشاء البكارة — الدم الطمثي محتبس (ألم دوري) رغم نضج المحور الهرموني والصفات الثانوية."},{"f":"ما الأساس الفيزيولوجي المرضي لمتلازمة المبيض متعدد الكيسات PCOS؟","b":"اللاإباضة المزمنة (chronic anovulation) — مع فرط أندروجينية ومقاومة أنسولين."},{"f":"ما معايير روتردام لتشخيص PCOS؟","b":"2 من 3: فرط أندروجينية (سريري/مخبري)، لاإباضة مزمنة، مبيض متعدد الكيسات بالإيكو."},{"f":"في PCOS: ماذا يحدث لمقاومة الأنسولين والتستوستيرون الحر وSHBG؟","b":"مقاومة الأنسولين تزداد (متلازمة X الاستقلابية)، التستوستيرون الحر يرتفع، والغلوبولين الرابط للهرمونات الجنسية SHBG ينقص — لا العكس."},{"f":"أي علامة ليست من PCOS بل توجّه لورم مفرز للأندروجين؟","b":"خشونة الصوت — علامة ذكورة شديدة (virilization) لا تُرى في PCOS المعتادة."},{"f":"ما الذي ليس من علاجات المبيض عديد الكيسات؟","b":"ناهضات GnRH — ليست من بروتوكول علاج PCOS (العلاج: إنقاص وزن، ميتفورمين، حبوب مركبة، محرضات إباضة كالكلوميفين/ليتروزول)."},{"f":"ما متلازمة شيهان وما أشيع أعراضها؟","b":"نخر النخامى الإقفاري بعد نزف ولادي شديد وصدمة → قصور نخامي شامل. أشيع عرض: انقطاع الطمث (+ فشل إدرار الحليب، قصور درق وكظر ثانوي)."},{"f":"فرّق: شيهان مقابل كالمان في انقطاع الطمث؟","b":"شيهان: ثانوي مكتسب بعد ولادة (نخر نخامي). كالمان: بدئي خلقي — نقص GnRH مع فقد الشم (قصور غدد تناسلية ناقص موجهات القند منذ البلوغ)."},{"f":"ما تناذر أشرمان؟","b":"التصاقات ليفية داخل جوف الرحم بعد التجريف (ولادة/إسقاط) → انقطاع طمث ثانوي تشريحي رغم سلامة المحور الهرموني — وليس سببًا غديًا ولا سببًا للنزف الطمثي."},{"f":"سيدة بعد ولادة خضعت لتجريف رحم ثم انقطع طمثها: التشخيص الأرجح؟","b":"تناذر أشرمان — التصاقات جوف الرحم التالية للتجريف."},{"f":"ما أسباب انقطاع الطمث الثانوي «ما عدا»؟","b":"الحمل (الأشيع)، الإرضاع، فرط البرولاكتين، القهم العصبي، قصور المبيض الباكر، شيهان، أشرمان. ليست منها: كالمان والتأنيث الخصيوي — أسباب بدئية (لم يحدث الطمث أبدًا)."},{"f":"قاعدة ذهبية: ما أول استقصاء في انقطاع الطمث الثانوي؟","b":"اختبار الحمل المناعي — نفي الحمل أولًا دائمًا قبل أي عيار هرموني (FSH، برولاكتين، اختبار البروجسترون)."},{"f":"ما استقصاءات انقطاع الطمث الثانوي «ما عدا»؟","b":"HCG، TSH، البرولاكتين، FSH/LH (مرتفع = قصور مبيضي، منخفض = سبب مركزي)، اختبار سحب البروجسترون. ليست منها: مسحة/لطاخة عنق الرحم — للمسح السرطاني."},{"f":"ما الذي يسبب ارتفاع البرولاكتين «ما عدا»؟","b":"الحمل (فيزيولوجي)، البرولاكتينوما (أشيع مرضي)، السرج التركي الفارغ (يقطع التثبيط الدوباميني). ليس منها: السكري."},{"f":"ماذا يفعل فرط البرولاكتين بالدورة؟","b":"يثبط إفراز GnRH من الوطاء فيوقف الإباضة → انقطاع طمث ثانوي (وقد يسبب ثرّ الحليب)."},{"f":"في تدبير النزف التناسلي في سن النشاط: ما الذي لا يدخل؟","b":"اللولب النحاسي — يزيد النزف الطمثي أصلًا فلا يُستخدم لتدبيره."},{"f":"ما أشيع أذية في استئصال الرحم؟","b":"أذية المثانة — لقربها التشريحي من عنق الرحم أثناء التسليخ."},{"f":"ما الورم المبيضي الأكثر تعرضًا للانفتال؟","b":"التيراتوما (الورم العجائبي) — لكتلته وثقله وحركته."},{"f":"فتاة 16 سنة بصفات جنسية ثانوية دون طمث: ما الإجراء الأول؟","b":"الفحص العياني للأعضاء التناسلية — لنفي انسداد المسلك (غشاء بكارة، حاجز مهبلي) قبل أي استقصاء هرموني."},{"f":"هل يتحسن الداء الحوضي الالتهابي باستئصال الرحم؟","b":"لا — العبارة خاطئة؛ الداء الحوضي الالتهابي إنتان صاعد يُعالج بالصادات، واستئصال الرحم ليس علاجه."}]},{"t":"سن الإياس","cards":[{"f":"قاعدة ذهبية: أي نزف تناسلي بعد سن الضهي؟","b":"يُعد خبيثًا حتى يثبت العكس — نفي سرطان بطانة الرحم أولًا دائمًا. أشيع سبب سليم: ضمور بطانة الرحم والمهبل."},{"f":"ما أسباب النزف بعد الضهي «ما عدا»؟","b":"ضمور البطانة والمهبل، البوليبات، سرطان بطانة الرحم وعنق الرحم، التهاب المهبل الشيخي، المعالجة الهرمونية المعيضة. ليست منها: الورم الليفي والأندومتريوز (يضمران بعد الضهي)، كيسة الجسم الأصفر (لا إباضة)، الاضطرابات النزفية الوراثية (تظهر باكرًا)."},{"f":"سيدة 52 سنة بنزف مهبلي بعد سن الضهي: ما الإجراء الأول؟","b":"الإيكو المهبلي — لقياس سماكة بطانة الرحم (الطبيعي 4-5 ملم بعد الضهي) قبل الخزعة."},{"f":"كيف يُعالَج ضمور المهبل بعد سن الضهي؟","b":"دوائيًا: إستروجين موضعي ومرطبات مهبلية — لا جراحة؛ الضمور حالة هرمونية لا تشريحية."},{"f":"ما أعراض سن اليأس «ما عدا»؟","b":"الهبات الساخنة (تصيب الأغلبية)، التعرق الليلي، الأرق، الخفقان، والأعراض الضمورية (عسر الجماع). ليست منها: ثر الحليب، والتغيرات الهرمونية الفجائية — الانتقال تدريجي."},{"f":"ما التغير الهرموني المميز لسن اليأس؟","b":"ارتفاع FSH وLH (قصور مبيضي أولي) مع انخفاض الإستروجين."},{"f":"ما اختلاطات سن اليأس «ما عدا»؟","b":"تخلخل العظام، زيادة التصلب العصيدي، الأرق والهبات. ليس منها: الساد الشيخي (إعتام عدسة مرتبط بالعمر لا بالإياس)."},{"f":"ضخامة البظر بعد سن الضهي: طبيعية أم مرضية؟","b":"مرضية — توجّه نحو ورم مفرز للأندروجين (مبيضي/كظري) وتستدعي الاستقصاء الفوري."}]},{"t":"تشوهات السبيل التناسلي الأنثوي وكيساته وأورامه الحميدة","cards":[{"f":"سيدة 40 سنة: نزف طمثي وفقر دم + كتلة حوضية قاسية غير مؤلمة: التشخيص؟","b":"ورم ليفي رحمي (عضلي أملس) — الصورة الكلاسيكية: نزف طمثي غزير مع كتلة قاسية غير مؤلمة."},{"f":"هل الورم الليفي عرضي دومًا؟ وما محفز نموه؟","b":"لا — كثير منه لاعرضي. ورم سليم معتمد على الإستروجين؛ ارتفاع البروجسترون ليس محفز نموه."},{"f":"ما سبب الألم في الأورام الليفية أثناء الحمل؟","b":"التنكس الأحمر (red degeneration) — احتشاء الورم الليفي مع نمو الرحم الحملي."},{"f":"هل يُستأصل الورم الليفي خلال القيصرية؟","b":"لا — ممنوع؛ خطر النزف الغزير من الرحم الحملي المتوعي. يُترك ويُعالَج لاحقًا."},{"f":"متى لا نستأصل الرحم في الورم الليفي؟","b":"إذا كان لاعرضيًا وحجمه بحجم رحم 8 أسابيع أو أقل — مراقبة فقط. كذلك الليفي المكتشف صدفة أثناء القيصرية ليس استطبابًا للاستئصال."},{"f":"تنظير باطن الرحم: متى لا يفيد في الأورام الليفية؟","b":"في الأورام ضمن الجدار (intramural) — التنظير يرى ويعالج التجويف فقط (تحت المخاطية البارزة فيه)."},{"f":"هل الورم الليفي تحت المصلي لاعرضي دائمًا؟","b":"لا — قد يسبب أعراضًا ضغطية (مثانة/مستقيم) رغم كونه خارج التجويف."},{"f":"ما حقائق الكيسات الوظيفية المبيضية «ما عدا»؟","b":"صغيرة (معظمها أقل من 8 سم)، تتراجع تلقائيًا، إنذار ممتاز، ولا استحالة خبيثة إطلاقًا. الحجم الكبير (أكثر من 10 سم) يرجّح كيسًا مرضيًا لا وظيفيًا."},{"f":"الكيسة الجريبية: متى تظهر؟","b":"في سن النشاط التناسلي فقط — من جريب ناضج لم يتمزق؛ وحيدة المسكن وأصغر من 5 سم. لا تظهر بعد سن اليأس إطلاقًا (أي كيسة بعد الضهي تُعامَل بشك)."},{"f":"ما أسباب الكيسات اللوتيئينية (theca-lutein) «ما عدا»؟","b":"فرط تحريض المبيض بـhCG العالي: الرحى العدارية، الحمل المتعدد. ليست منها: PCO — لاإباضة مزمنة بأكياس جريبية صغيرة لا لوتيئينية."},{"f":"تيراتوما المبيض: هل تُستأصل مهما كان حجمها؟","b":"لا — الكيسات الجلدانية الصغيرة (أقل من 6 سم) غير العرضية تُراقب بالتصوير الدوري. ثنائية الجانب في 10% من الحالات."},{"f":"الورم الليفي المبيضي: هل هو ورم ظهاري؟","b":"لا — من أورام الحبل الجنسي/السدى (sex cord-stromal) لا الظهارية (البشروية)."},{"f":"هل الورم العجائبي (teratoma) من سرطانات المبيض الظهارية؟","b":"لا — ورم خلية جرثومية (germ cell) لا ظهاري (بشروي)."},{"f":"متى يرتفع CA125؟","b":"في الورم المصلي الخبيث (serous cystadenocarcinoma) — المشعر الورمي الأساسي للأورام المبيضية الظهارية المصلية."},{"f":"من اختلاطات الورم الليفي «ما عدا»؟","b":"النزف، فقر الدم، العقم/الإسقاط، الأعراض الضغطية. ليست منها: المشيمة الملتحمة."},{"f":"ما الذي ليس من معالجات الورم العضلي الأملس؟","b":"قص الرباط الرحمي العجزي — لا دور له في علاج الليفي."},{"f":"هل للعامل النفسي دور في حدوث الورم الليفي؟","b":"لا — ورم هرموني (إستروجيني) لا نفسي المنشأ."},{"f":"كتلة حوضية قاسية 10 سم عند سيدة: ما الذي ليس من التشخيص التفريقي؟","b":"الرحى العدارية — حمل رحوي داخل الرحم لا كتلة حوضية قاسية؛ التفريقي يشمل الليفي وأورام المبيض."},{"f":"ما أشيع أعراض الورم العضلي الأملس «ما عدا»؟","b":"النزف الطمثي الغزير وفقر الدم. ليس منها: الألم الحوضي المزمن — ليس من الأعراض النموذجية."}]},{"t":"العقم","cards":[{"f":"ما أكثر أسباب العقم عند الأنثى؟","b":"اللاإباضة (anovulation) — على رأسها PCOS."},{"f":"متى تُستخدم تقنية IVF (الإخصاب في وسط الزرع)؟","b":"في العقم الناجم عن أسباب بوقية — كانسداد الأنابيب؛ الحل الأفضل للأنابيب المسدودة."},{"f":"فرّق: IVF مقابل الحقن داخل الرحم IUI؟","b":"IVF أكثر فعالية من IUI. والحقن داخل الرحم ليس الحل الوحيد للعقم غير المفسَّر."},{"f":"متى يُجرى تصوير الرحم والملحقات (HSG)؟","b":"بعد الطمث في الطور الجريبي المبكر — لا قبله (خطر دفع بطانة حائضة أو إخفاء حمل مبكر)."},{"f":"في تحليل السائل المنوي الطبيعي: ما غير الطبيعي؟","b":"7-10 كريات بيض في المل — الكريات البيض الكثيرة توحي بالتهاب تناسلي لا سائل طبيعي."},{"f":"تنظير البطن في العقم: ماذا لا يفعل؟","b":"لا يستأصل بوليب الرحم — ذلك بتنظير باطن الرحم (hysteroscopy)؛ تنظير البطن للجوف البريتواني والبوقين."}]},{"t":"بطانة الرحم الهاجرة (الاندومتريوز) والداء العضلي الغدي (الأدينوميوز)","cards":[{"f":"ألم حوضي مزمن + عسرة طمث + عقم: التشخيص المرجح؟","b":"الاندومتريوز (endometriosis) — الثلاثي الكلاسيكي."},{"f":"ما المكان الأشيع لتوضع الاندومتريوز؟","b":"المبيض — كيسات الشوكولاتة (endometrioma). ليست البوق أشيع التوضعات."},{"f":"ما أدق وأهم وسيلة لكشف الاندومتريوز؟","b":"تنظير البطن (laparoscopy) — الرؤية المباشرة للآفات مع إمكانية الخزعة."},{"f":"فرّق: الاندومتريوز مقابل الأدينوميوز؟","b":"الاندومتريوز: نسيج بطانة خارج الرحم (مبيض/بريتوان). الأدينوميوز: غزو بطانة الرحم لعضلته — رحم متضخم مؤلم لين القوام، أشيع عند متعددات الولادة لا الخروسات."},{"f":"عسر الجماع في الاندومتريوز: سطحي أم عميق؟","b":"عميق — العسر السطحي ليس من سماته."},{"f":"ما العلاج الدوائي المعتمد للاندومتريوز؟","b":"مقلدات GnRH — تثبط المحور وتحدث سن يأس دوائي مؤقت يضمّر الآفات."},{"f":"هل الكافيين يخفف أعراض الاندومتريوز؟","b":"لا — العبارة خاطئة؛ لا دور علاجي للكافيين في الاندومتريوز."},{"f":"من أعراض الاندومتريوز «ما عدا»؟","b":"عسرة الطمث، الألم الحوضي المزمن، عسر الجماع العميق، العقم. ليست منها: تباعد الطموث."}]},{"t":"موانع الحمل","cards":[{"f":"من مضادات استطباب موانع الحمل الفموية المركبة «ما عدا»؟","b":"سوابق خثار وريدي، الشقيقة مع نسمة، التدخين فوق 35 سنة، ارتفاع ضغط غير مضبوط، سرطان الثدي، أمراض الكبد الفعالة. ليس منها: العمر 35-40 وحده دون تدخين."},{"f":"ما الذي ليس مضاد استطباب للمركبة؟","b":"كيسات المبيض الوظيفية — بل تُستخدم المركبة لعلاجها أحيانًا."},{"f":"ما مانع الحمل المثالي خلال الإرضاع؟","b":"حبوب البروجسترون فقط POP — المركبة تنقص إدرار الحليب."},{"f":"ما موانع الحمل مديدة التأثير LARC «ما عدا»؟","b":"اللولب النحاسي، اللولب البروجستروني، الغرسة تحت الجلد. ليست منها: حبوب البروجسترون فقط — قصيرة التأثير (يومية)."},{"f":"فرّق: آلية البروجسترون المفرد مقابل المركبة؟","b":"المفرد: محيطية — زيادة لزوجة مخاط عنق الرحم وضمور بطانة الرحم. المركبة: تثبيط مركزي للمحور الوطائي-النخامي-المبيضي (لا يثبطه المفرد)."},{"f":"هل تزيد المركبة سرطان المبيض؟","b":"لا — بل تقي منه ومن سرطان بطانة الرحم (البروجسترون يعاكس الإستروجين)."},{"f":"من فوائد المركبة «ما عدا»؟","b":"تنظيم الدورة، علاج عسرة الطمث وحب الشباب، الوقاية من سرطان المبيض والبطانة وفقر الدم. ليست منها: الوقاية من التهاب الوريد الخثري — بل ترفع خطره."},{"f":"سيدة بسوابق التهاب وريد خثري ترغب بمنع حمل فعال: بمَ تنصح؟","b":"اللولب النحاسي — فعال دون هرمونات جهازية؛ المركبة ممنوعة مع سوابق الخثار."},{"f":"هل العمر فوق 38 مضاد استطباب للولب؟","b":"لا — العمر وحده ليس مضاد استطباب للولب (نحاسي أو بروجستروني)."},{"f":"من موانع الحمل عالية الفعالية «ما عدا»؟","b":"اللولب والغرسة والتعقيم عالية الفعالية. ليس منها: الواقي الذكري — فعالية متوسطة مع الاستخدام النموذجي."},{"f":"هل يسبب اللولب البروجستروني هشاشة العظام؟","b":"لا — هشاشة العظام من آثار حقن DMPA المديدة لا اللولب. (واللولب البروجستروني يحوي ليفونورجستريل)."}]},{"t":"إنتانات السبيل التناسلي","cards":[{"f":"ضائعات مهبلية بيضاء قشدية + حكة: التشخيص؟ وهل يُعالَج الشريك؟","b":"الكانديدا (المبيضات البيض) — الحكة عرض شائع جدًا. لا تستدعي علاج الشريك (ليست منتقلة بالجنس)."},{"f":"ما العوامل المؤهبة لداء المبيضات المهبلي «ما عدا»؟","b":"السكري غير المضبوط، الصادات واسعة الطيف، الحمل، الإستروجين. ليست منها: اللوالب الرحمية."},{"f":"بمَ يُعالَج التهاب المهبل الفطري «ما عدا»؟","b":"مضادات الفطور (كلوتريمازول موضعي/فلوكونازول فموي). ليست منها: الستيروئيدات."},{"f":"ما الأمراض المنتقلة بالجنس «ما عدا»؟","b":"الكلاميديا، السيلان، التريكوموناس، الحلأ التناسلي، الزهري. ليست منها: المبيضات البيض."},{"f":"كيف نتحرى عن التريكوموناس (Trichomonas)؟","b":"بالعينة الرطبة (wet mount) من الرتج الخلفي للمهبل — تُرى متحركة تحت المجهر."},{"f":"ما العامل الممرض الأشيع لالتهاب البوقين؟","b":"الكلاميديا (Chlamydia trachomatis) — تليها النيسرية البنية (السيلان)."},{"f":"ما عقابيل الداء الحوضي الالتهابي «ما عدا»؟","b":"العقم البوقي، الحمل الهاجر، الألم الحوضي المزمن، الالتصاقات. ليست منها: الإسقاطات المتكررة."},{"f":"هل يؤكَّد تشخيص الداء الحوضي الالتهابي بتنظير البطن؟","b":"لا — التشخيص سريري (ألم ملحقات + مفرزات + حمى)؛ التنظير ليس للتأكيد الروتيني. والعامل المسبب غالبًا متعدد لا وحيد."},{"f":"هل يُستخدم التصوير الظليل للرحم في تشخيص PID الحاد؟","b":"لا — التصوير الظليل (HSG) للعقم والتشوهات؛ في PID الحاد قد ينشر الإنتان."},{"f":"هل الحرارة عرض شائع في التهاب المهبل؟","b":"لا — التهاب المهبل موضعي (حكة/ضائعات/رائحة)؛ الحرارة توجّه لالتهاب صاعد (PID)."},{"f":"في الحلأ التناسلي: النكس أسوأ من الهجمة الأولى؟","b":"لا — العكس: الهجمة الأولى (البدئية) أشد، والنكسات أخف وأقصر."},{"f":"ما الذي يضعف المناعة الذاتية للمهبل «ما عدا»؟","b":"الصادات واسعة الطيف، السكري، الحمل، الدوش المهبلي. ليس منها: الرياضة."},{"f":"هل داء المشعرات المهبلية يسبب التهاب الملحقات (PID)؟","b":"لا — PID إنتان صاعد بكتيري (كلاميديا/سيلان)؛ المشعرات التهاب مهبلي سفلي منتقل بالجنس."}]},{"t":"الاضطرابات الفيزيولوجية والفيزيائية للدورة الطمثية","cards":[{"f":"فرّق: عسرة الطمث البدئية مقابل الثانوية؟","b":"البدئية: بلا سبب عضوي — مسببها البروستاغلاندين (لا ارتفاع الإستروجين)، والفحص طبيعي، وعلاجها NSAIDs. الثانوية: سبب عضوي (اندومتريوز، أدينوميوز، ليفي) والفحص غير طبيعي دومًا."},{"f":"هل علاج عسرة الطمث دومًا جراحي؟","b":"لا — البدئية تُعالَج بمضادات الالتهاب اللاستيروئيدية (تثبط البروستاغلاندين)؛ الجراحة للسبب العضوي في الثانوية فقط."},{"f":"من أسباب عسرة الطمث الثانوية «ما عدا»؟","b":"الاندومتريوز، الأدينوميوز، الورم الليفي، الداء الحوضي الالتهابي المزمن. ليس منها: الفازوبريسين."},{"f":"هل تترافق متلازمة ما قبل الطمث (PMS) دومًا مع غزارة الطمث؟","b":"لا — PMS أعراض جسدية ونفسية دورية في الطور الأصفري؛ الغزارة ليست لازمة لها."},{"f":"ما الذي ليس من علاج متلازمة ما قبل الطمث؟","b":"اللولب النحاسي — لا يعالج PMS (بل قد يزيد النزف)."},{"f":"من أسباب الألم الحوضي المزمن «ما عدا»؟","b":"الاندومتريوز، الالتصاقات الحوضية، الأدينوميوز، احتقان الحوض. ليس منها: التهاب المهبل الفطري — التهاب سفلي موضعي."}]},{"t":"الأمراض النسائية في مرحلة الطفولة والمراهقة","cards":[{"f":"في متلازمة التأنيث الخصيوي (عدم حساسية الأندروجين): هل يوجد رحم وعنق طبيعيان؟","b":"لا — النمط الصبغي XY: ثدي طبيعي، غياب الرحم والعنق، ومهبل أعور قصير (مشتقات مولر تضمر بتأثير AMH من الخصيتين الخفيتين)."},{"f":"في تناذر تورنر (45,X0): هل يغيب الرحم؟ وهل المهبل أعور؟","b":"لا — الرحم موجود (مشتقات مولر سليمة) والمهبل طبيعي؛ المميز: قصر القامة، الرقبة المجنحة، وقصور مبيضي أولي (انقطاع بدئي)."},{"f":"من أسباب النزف التناسلي عند الطفلات قبل البلوغ «ما عدا»؟","b":"البلوغ المبكر، الجسم الأجنبي المهبلي، الرضوض، الأورام. ليست منها: فرط تصنع قشر الكظر الخلقي، الأدينوميوز، بوليب باطن الرحم — أسباب بالغات."}]},{"t":"ترشيح الجهاز التناسلي الأنثوي","cards":[{"f":"هل يُحاط المبيض بالوريقة الحشوية للبريتوان؟","b":"لا — المبيض لا يوجد في جوف البريتوان محاطًا بالصفاق الحشوي؛ بل يغطيه الظهارة الجرثومية (germinal epithelium)."},{"f":"أين يقع المبيض تشريحيًا؟","b":"في حفرة المبيض على الجدار الجانبي لجوف الحوض، معلقًا بالرباط العريض عبر مسراق المبيض (mesovarium)."},{"f":"قاعدة ذهبية: ما غطاء سطح المبيض؟","b":"الظهارة الجرثومية — لا الصفاق الحشوي؛ لذلك تُعد أورامه الظهارية ناشئة من هذه الظهارة السطحية."}]},{"t":"السبيل البولي وعلاقته بالأمراض النسائية","cards":[{"f":"السلس البولي الإلحاحي: هل علاجه جراحي بالدرجة الأولى؟","b":"لا — العلاج الأول سلوكي/دوائي (مضادات الكولين)؛ الجراحة ليست الخط الأول للإلحاحي."},{"f":"فرّق: بمَ نبدأ في السلس الجهدي مقابل الإلحاحي؟","b":"الجهدي: نبدأ محافظًا — تمارين أرضية الحوض (لا دوائي أولًا). الإلحاحي: نبدأ دوائيًا/سلوكيًا (لا جراحي أولًا)."},{"f":"ما سبب السلس البولي الجهدي؟","b":"أذية الأربطة الداعمة لعنق المثانة (ضعف دعم الإحليل) — يتسرب البول مع الجهد والسعال."}]},{"t":"الحالات الخثلية والضمورية","cards":[{"f":"امرأة بحكة فرجية ضمورية: ما العلاج الأكثر فعالية؟","b":"كريمات الإستروجين الموضعية — تعيد الترطيب والسماكة للظهارة الضمورة بنقص الإستروجين."},{"f":"ما سبب الحكة الفرجية الضمورية؟","b":"ضمور الفرج بنقص الإستروجين بعد سن الضهي — جلد رقيق جاف سهل التهيج والحكة."},{"f":"ما علاقة الحزاز المتصلب بسرطان الفرج؟","b":"الحزاز المتصلب آفة ضمورية مزمنة مؤهبة لسرطان الفرج شائك الخلايا (SCC) — يستوجب المتابعة."}]},{"t":"الثدي","cards":[{"f":"من مؤهبات سرطان الثدي «ما عدا»؟","b":"القصة العائلية (BRCA1/BRCA2)، البلوغ المبكر، الضهي المتأخر، ناقصات الولادة، التعرض للإشعاع. ليس منها: سرطان عنق الرحم — عاملا خطر مختلفان تمامًا."},{"f":"قاعدة ذهبية: ما الرابط الوراثي بين سرطان الثدي والمبيض؟","b":"طفرتا BRCA1/BRCA2 — متلازمة الثدي-المبيض الوراثية؛ قصة عائلية لأحدهما تستدعي تقصي الآخر."},{"f":"هل الحمل والرضاعة يؤهبان لسرطان الثدي؟","b":"لا — بل واقيان؛ كل حمل كامل والرضاعة المديدة يخفضان الخطر (تثبيط الإباضة وتقليل التعرض الإستروجيني التراكمي)."}]}]},{"s":"الأطفال 1","topics":[{"t":"الطفل في المجتمع","cards":[{"f":"ما عمر الأم الأقل خطورة لوفاة الرضيع (العمر الأمثل للحمل)؟","b":"عمر 25–29 سنة هو العمر الأمثل للحمل والأقل خطورة. عوامل الخطورة: الخداج، نقص وزن الولادة، التشوهات الخلقية، العوامل الاجتماعية السيئة."},{"f":"خلع البلورة (Ectopia lentis) يُشاهد في أي مرض استقلابي؟ وما الفرق عن الغالاكتوزيميا؟","b":"بيلة الهوموسيستين (Homocystinuria) — تنزاح العدسة نحو الأسفل والأنف. فرّق: الغالاكتوزيميا (Galactosemia) تسبب الساد (Cataract) لا خلع العدسة."},{"f":"قاعدة ذهبية: سلبية الـ CRP عند وليد مشتبه بإنتان دم باكر تعني؟","b":"سلبية CRP لا تنفي إنتان الدم الباكر — يرتفع متأخرًا وحساسيته محدودة في البداية. الصورة السريرية (تثبيط عام، رفض رضاعة، حرارة بعد انبثاق أغشية باكر) تكفي للتدبير التخبيري."}]},{"t":"القصة والفحص السريري","cards":[{"f":"فرّق: تبقرط الأصابع (Clubbing) يُشاهد في أي الحالات، ولا يُشاهد في أيها؟","b":"يُشاهد في: داء كرون، التوسع القصبي (Bronchiectasis)، التهاب الشغاف الإنتاني (Endocarditis)، رباعي فالو (Tetralogy of Fallot). لا يُشاهد في: الحمى الرثوية، ولا في قصور القلب الحاد (يحتاج شهورًا ليتطور)."},{"f":"قاعدة ذهبية: كل قصور قلب عند الرضع هو ضخامة كبد (وليس طحال) + نظم خبب + ضعف رضاعة حتى يثبت العكس.","b":"ضخامة كبد (وليس طحال — الاحتقان الوريدي الجهازي يظهر في الكبد)، نظم خبب (Gallop rhythm)، تسرع قلب، ضعف رضاعة، تعرق، انتانات تنفسية متكررة."},{"f":"فرّق: يدخل في التشخيص التفريقي لضخامة الطحال ما عدا؟","b":"الليشمانيا الحشوية (كالا-آزار)، داء وحيدات النوى الخمجي (إبشتاين-بار)، الابيضاض اللمفاوي الحاد، فرط توتر الباب/تشمع الكبد. الورم الأرومي الكبدي (Hepatoblastoma) يسبب ضخامة كبد لا طحال."},{"f":"فرّق: من أسباب ضخامة الكبد عند الأطفال ما عدا؟","b":"أدواء خزن الغليكوجين (Glycogen storage diseases)، قصور القلب الاحتقاني، إنتان إبشتاين-بار، الابيضاض اللمفاوي الحاد. الداء الزلاقي (Celiac disease) لا يسبب ضخامة كبد."}]},{"t":"تطور الطفل الطبيعي","cards":[{"f":"نقطة ذهبية: ماذا يحدث لوزن الوليد الطبيعي في الأسبوع الأول من العمر؟","b":"حتى 10% من وزن الولادة خلال الأسبوع الأول — طبيعي (فقدان سوائل، طرح العقي، تأخر إدرار الحليب). يستعيد وزن الولادة بعمر 10–14 يومًا؛ فقدان أكثر من 10% أو عدم الاستعادة يستوجب التقييم."},{"f":"أنماط: متى يتضاعف وزن الولادة؟ ومتى يتضاعف ثلاث مرات؟","b":"يتضاعف وزن الولادة بعمر 4–6 أشهر (مثلًا 3450غ ← ~7كغ)، ويتضاعف ثلاث مرات تقريبًا بعمر السنة."},{"f":"نقطة ذهبية: العمر الوسيط للمشي المستقل، ومتى يُعتبر تأخرًا؟ وما خطورة فقدان المهارة المكتسبة؟","b":"العمر الوسيط للمشي المستقل 12–13 شهرًا، والتفاوت الطبيعي حتى 18 شهرًا — بعدها يُعدّ تأخرًا يستوجب التقييم. تنبيه: فقدان مهارة المشي المكتسبة علامة منذرة تستدعي تقييمًا إسعافيًا (نفي الأمراض التنكسية العصبية) دون انتظار."},{"f":"أنماط: تسلسل رسم الأشكال الهندسية حسب العمر؟","b":"الدائرة أولًا (3 سنوات)، ثم المربع (4 سنوات)، ثم المثلث (5 سنوات). وبعمر 3 سنوات يعرف الطفل جنسه؛ ربط الحذاء بعمر 5–6 سنوات."},{"f":"أنماط: التطور اللغوي — كلمة؟ جملة من كلمتين؟ جملة من 3 كلمات؟","b":"الكلمة الأولى بعمر السنة، جملة من كلمتين بعمر السنتين، جملة من 3 كلمات بعمر 3 سنوات (السنة الثالثة). بعمر 5 سنوات يقص قصة كاملة."},{"f":"نقطة ذهبية: الشرب من الكأس بيديه؟ الجلوس دون مساعدة؟ الاستدارة نحو الصوت؟","b":"الشرب من الكأس بيديه: 12 شهرًا. الجلوس دون مساعدة: 7 أشهر. الاستدارة نحو جهة الصوت: 7 أشهر."},{"f":"نقطة ذهبية: متى يُعرَّف تأخر بزوغ الأسنان؟ ومتى تبزغ السن الأولى عادة؟","b":"تأخر التسنين = عدم بزوغ أي سن بعد عمر 13 شهرًا. السن اللبنية الأولى (القواطع السفلية الوسطى) تبزغ عادة بين 6–8 أشهر."},{"f":"من سؤال حقيقي: طفل بعمر سنتين يقوم بكل ما يلي عدا؟","b":"يستطيع: الركض، المشي/الجري للخلف، رسم خط عمودي، نطق جملة من كلمتين — ولا يستطيع الوقوف على قدم واحدة (يتأخر حتى 2.5–3 سنوات)."},{"f":"فرّق: الابتسامة الاجتماعية بعمر أسبوعين أم 6 أسابيع؟ ومتى تصبح علامة حمراء؟","b":"الابتسامة الاجتماعية بعمر 6 أسابيع (وليس أسبوعين). غياب الابتسام الاجتماعي بعد 8 أسابيع = علامة حمراء (حد أحمر للتأخر)."}]},{"t":"المشكلات التطورية والطفل ذو الاحتياجات الخاصة","cards":[{"f":"قاعدة ذهبية: كل شلل دماغي (Cerebral palsy) هو اضطراب حركي غير مترقي في الدماغ النامي — ونقص الأكسجة حول الولادة ليس السبب الأكثر شيوعًا.","b":"الشلل الدماغي = اضطراب حركي غير مترقي (Non-progressive) في الدماغ النامي. نقص الأكسجة حول الولادة مسؤول عن أقلية صغيرة فقط؛ الغالبية أسباب قبل الولادة (الخداج، نزف داخل بطيني، أذية المادة البيضاء)."},{"f":"من سؤال حقيقي: وليد أصيب بشلل دماغي نتيجة يرقان نووي (Kernicterus) — أي شكل أكثر احتمالًا؟","b":"شلل دماغي بعسرة الحركة (Dyskinetic) من النمط الرقصي الكنعي (Choreoathetoid) — اليرقان النووي يصيب العقد القاعدية، وليس الشلل التشنجي أو الرنحي."},{"f":"فرّق: أسباب نقص السمع الحسي العصبي (Sensorineural) عند الأطفال — وما السبب الذي يعطي نقص سمع توصيليًا؟","b":"الخداج، فرط بيليروبين الدم (اليرقان النووي يؤذي العصب السمعي)، الأمينوغليكوزيدات (سامة للأذن الداخلية)، التهاب السحايا. أما سوء وظيفة نفير أوستاش فيسبب نقص سمع توصيليًا (انصباب الأذن الوسطى) لا حسيًا عصبيًا."}]},{"t":"الحالات الإسعافية عند الأطفال","cards":[{"f":"من سؤال حقيقي: طفل مع صدمة تآقية — ما الإجراء الأول؟","b":"الأدرينالين (الإيبينفرين) حقنًا عضليًا بتركيز 1:1000 — الدواء المنقذ للحياة والخط الأول. الحقن تحت الجلد أبطأ، والستيروئيدات ومضادات الهيستامين أدوية مساعدة لاحقة. فرّق: السالبوتامول للتشنج القصبي (الأزيز) وليس للصرير (انسداد علوي → إرذاذ أدرينالين)."},{"f":"فرّق: علامات الصدمة المعاوضة مقابل الصدمة غير المعاوضة عند الأطفال؟","b":"المعاوضة: تسرع قلب وتنفس، تطاول زمن عود الامتلاء الشعري (>2 ثانية)، جلد شاحب بارد، نقص المرونة الجلدية، شح بول. غير المعاوضة = انكسار الآليات: هبوط الضغط الشرياني، تدني مستوى الوعي، تباطؤ القلب."},{"f":"قاعدة ذهبية: الوقاية من متلازمة موت الرضيع المفاجئ (SIDS) — وضعية النوم؟","b":"يُنام الرضيع على ظهره حصرًا — النوم على البطن ممنوع ويزيد خطر SIDS. مع: تجنب فرط التدفئة، إبقاء الرضيع في غرفة الأهل أول 6 أشهر (دون مشاركة السرير خاصة على الكنبة)، تجنب التدخين بجواره."},{"f":"نقطة ذهبية: ماذا يتضمن التقييم السريع للطرق الهوائية والتنفسية عند الأطفال (ما عدا)؟","b":"السحب الوربي، عدد مرات التنفس، الوزيز، الإشباع بالأكسجين. الضغط الشرياني يقيّم الدوران وليس الطرق الهوائية والتنفسية."}]},{"t":"الحوادث والتسممات","cards":[{"f":"فرّق: طفل باختلاجات + تقبض حدقة + زيادة إلعاب — أي مادة سامة؟ وكيف نفرّقها عن الأفيونات والأمفيتامين؟","b":"مركبات الفوسفور العضوية (مثبطات الكولين إستراز) — متلازمة كولينية (SLUDGE): تقبض حدقة + زيادة إلعاب ودموع وإسهال وتبول + بطء قلب + تشنج قصبي. فرّق: الأفيونات تقبض الحدقة دون زيادة إلعاب؛ الأمفيتامين ومضادات الاكتئاب ثلاثية الحلقة تسبب توسع الحدقة."},{"f":"من سؤال حقيقي: أول العلامات الباكرة عند التسمم بالحديد عند الأطفال؟","b":"المرحلة الأولى (0–6 ساعات) هضمية: الحديد مادة أكّالة تسبب أذية مخاطية حادة (قياء، ألم بطني، إسهال مدمى/قرحة هضمية). السبات والصدمة من المراحل المتأخرة (بعد 6–24 ساعة)."},{"f":"فرّق: بعد رض الرأس عند الأطفال — أي عرض يوجّه لإصابة عصبية مهمة؟ وأي عرض لا يستدعي العودة؟","b":"النعاس غير الطبيعي (تغير مستوى الوعي) = علامة إصابة عصبية مهمة تستوجب التقييم العاجل. أما الإقياء لمرة واحدة فقط بعد رض رأس بفحص طبيعي فلا يستدعي العودة بحد ذاته."},{"f":"قاعدة ذهبية: أي الحروق عند الأطفال تحتاج التحويل لمركز متخصص بغض النظر عن المساحة؟","b":"تُحوَّل بغض النظر عن المساحة: حروق الأذنين، العينين (الوجه)، الأعضاء التناسلية/العجان، المفاصل الكبيرة (العابرة للمفاصل). حروق الماء المغلي (السلق) آلية للحرق وليست موقعًا يستدعي التحويل بحد ذاته."}]},{"t":"حماية الطفل","cards":[{"f":"من سؤال حقيقي: كل ما يلي من عوامل الخطورة لاضطهاد الطفل (إساءة معاملته) ما عدا؟","b":"عوامل الخطورة الأسرية: إدمان الأهل للكحول والمخدرات، الولادات القريبة المتعددة، صغر عمر الأهل — إضافة إلى: الطفل من ذوي الاحتياجات الخاصة. الاستثناء: الولادة العسيرة بحد ذاتها ليست عامل خطورة."},{"f":"نقطة ذهبية: هل الطفل من ذوي الاحتياجات الخاصة أكثر عرضة لاضطهاد الطفل؟","b":"نعم — الطفل من ذوي الاحتياجات الخاصة من عوامل الخطورة لاضطهاد الطفل، إلى جانب العوامل الأسرية (إدمان الأهل، الولادات القريبة المتعددة، صغر عمر الأهل)."},{"f":"فرّق: أي عامل مما يلي ليس من عوامل خطورة اضطهاد الطفل: إدمان الأهل، الولادة العسيرة، الولادات القريبة المتعددة؟","b":"الولادة العسيرة — ليست عامل خطورة لاضطهاد الطفل، على عكس إدمان الأهل والولادات القريبة المتعددة وصغر عمر الأهل والطفل ذي الاحتياجات الخاصة."}]},{"t":"علم الوراثة","cards":[{"f":"من سؤال حقيقي: الملامح السريرية لمتلازمة تيرنر (XO) — وما العبارة الخاطئة عنها؟","b":"قصر قامة، وذمة لمفاوية في يدي وقدمي الوليد، تأخر بلوغ (قصور/سوء تكون مبيضين)، الحالة العقلية سليمة عادة، التهاب أذن وسطى متكرر شائع. القلب: تضيق برزخ الأبهر (Coarctation) شائع لكنه ليس ثابتًا — تشوه الوسادة ليس شائعًا. هرمون النمو يُبدأ باكرًا (2–4 سنوات) لا بعد 10 سنوات."},{"f":"من سؤال حقيقي: متلازمة داون — فرط مقوية أم رخاوة مفصلية؟ وما أبرز المظاهر المرافقة؟","b":"متلازمة داون = رخاوة مفصلية (نقص مقوية) وليس فرط مقوية. المظاهر: قذال مسطح، طيات فوق المآق الداخلية، شقوق جفنية مائلة نحو الأعلى، ثلم راحي وحيد، عنق قصير. القلب: آفة أذينية بطينية (AV canal)؛ الهضم: رتق عفج (Duodenal atresia)."},{"f":"من سؤال حقيقي: ما علامات الصبغي X الهش (Fragile X) عند الأطفال؟","b":"الصبغي X الهش (Fragile X): انسدال الصمام التاجي (Mitral valve prolapse) + وجه طويل وأذنان كبيرتان بارزتان + تخلف عقلي + ضخامة الخصيتين بعد البلوغ (لا صغرهما)."}]},{"t":"الطب حول الولادة","cards":[{"f":"من سؤال حقيقي: وليد لأم سكرية، بعد 4 ساعات من الولادة حدث اختلاج معمم — السبب الأكثر احتمالًا؟ وما أشيع تشوه لديه؟","b":"نقص سكر الدم — فرط الأنسولين الجنيني (استجابة لفرط سكر الأم) وعند انقطاع وارد الغلوكوز بعد الولادة يحدث هبوط سكر يتظاهر باختلاج معمم في الساعات الأولى. وأشيع تشوه عند وليد الأم السكرية: التشوهات القلبية."},{"f":"نقطة ذهبية: تعريف الخداج؟ والفرق بينه وبين نقص وزن الولادة؟","b":"الخداج = الولادة قبل إتمام 37 أسبوعًا حمليًا (بغض النظر عن الوزن). الوزن أقل من 2500غ = نقص وزن الولادة. الولادة قبل 28 أسبوعًا = خداج شديد."},{"f":"فرّق: الحصبة الألمانية الخلقية مقابل CMV الخلقي — أيهما أشيع سببًا للساد؟ وأيهما أشيع سببًا للصمم؟","b":"الحصبة الألمانية الخلقية: أشيع سبب إنتاني للساد الخلقي + ثالوثها (ساد + تشوهات قلبية كالقناة الشريانية + صمم حسي عصبي)؛ الوليد المصاب قد يبقى معديًا حتى عمر سنة. الـCMV: أشيع سبب إنتاني خلقي للصمم الحسي العصبي + صغر رأس + تكلسات حول البطينات + التهاب شبكية ومشيمية؛ 90% من الحالات غير عرضية ولا لقاح له."},{"f":"من سؤال حقيقي: مظاهر التوكسوبلاسموز (المقوسات) الخلقي — وما المستثنى؟","b":"التوكسوبلاسموز الخلقي: استسقاء دماغ + تكلسات داخل الدماغ + التهاب مشيمية وشبكية حاد + ضخامة كبدية طحالية. الاستثناء: الإصابة القلبية والتهاب السحايا القيحي ليسا من مظاهره."},{"f":"فرّق: المظاهر الجلدية الطبيعية عند الوليد مقابل المرضية؟","b":"طبيعية وعابرة: الحمامى السمية، التملن البثري العابر، البقع المنغولية، لآلئ إبشتاين، العد، تبدل لون المهرج. مرضية: النخرة الشحمية تحت الجلد، استمرار زرقة النهايات بعد 48 ساعة، وظهور اليرقان في أول 24 ساعة من العمر."},{"f":"نقطة ذهبية: عناصر مشعر أبغار (Apgar) الخمسة؟","b":"5 عناصر (0–2 لكل عنصر) والمجموع من 10: النبض، الجهد التنفسي، المقوية العضلية، المنعكسات/التكشير، اللون. مثال: نبض 130 + بكاء شديد + مقوية جيدة + تكشير + زرقة أطراف = 8."},{"f":"فرّق: إنتان الحلأ البسيط حول الولادة مقابل الأخماج داخل الرحم — متى يتظاهر كل منهما؟","b":"الحلأ البسيط حول الولادة: اندفاعات حويصلية على قاعدة حمامية (وجه/عينان) بعمر 1–3 أسابيع مع حرارة وذات رئة شديدة. أما أخماج داخل الرحم (CMV، حصبة ألمانية، حماق) فتتظاهر منذ الولادة بوصمات خلقية (صغر رأس، ساد، طفح فرفري) — والحلأ البسيط لا يسبب تشوهات جنينية داخل الرحم بالمعنى الكلاسيكي."},{"f":"قاعدة ذهبية: تحدد النمو داخل الرحم يتظاهر بكل ما يلي ما عدا؟","b":"تحدد النمو داخل الرحم يتظاهر بـ: نقص حرارة، نقص سكر الدم، نقص النسيج الشحمي تحت الجلد، كثرة الحمر. الاستثناء: نقص تصنع الرئتين (يترافق مع قلة السائل الأمنيوسي لا مع تحدد النمو)."}]},{"t":"طب حديث الولادة","cards":[{"f":"قاعدة ذهبية: كل اختلاج باكر (الساعات الأولى) عند وليد أم سكرية هو نقص سكر الدم حتى يثبت العكس — وما الذي يتعرض له أيضًا (ما عدا)؟","b":"نقص سكر الدم — فرط الأنسولين الجنيني. وليد الأم السكرية معرض أيضًا لـ: نقص كلس الدم (وليس فرطه)، متلازمة التراجع الذيلي، تأخر النمو داخل الرحم، كثرة الحمر، الجنين العرطل، التشوهات القلبية."},{"f":"فرّق: أعراض نقص كلس الدم عند الوليد — وأي علامة نادرة عنده؟","b":"أهم عرض: الاختلاج؛ هياج ونرفزة؛ نوب زرقة (بسبب توقف التنفس)؛ قد يكون لا عرضيًا. أما علامة تشيفوستك (Chvostek) فمميزة لنقص الكلس عند البالغين لكنها نادرة المشاهدة عند الأطفال والولدان."},{"f":"فرّق: متلازمة العسرة التنفسية (RDS) مقابل الزلة التنفسية العابرة (TTN) — السبب، الصورة، المعالجة الأساسية؟","b":"RDS (الخدج — عوز سورفاكتانت): أعراض منذ الدقائق الأولى، زرقة لا تستجيب جيدًا على O2، صورة «الزجاج المغشى» (ارتشاحات شبكية عقيدية منتشرة)؛ المعالجة الأساسية: إعطاء سورفاكتانت داخل الرغامى. TTN (تمام حمل — غالبًا بعد قيصرية): تسرع تنفس دون عسرة شديدة، صورة فرط تهوية + شقوق ممتلئة بالسائل + احتقان رسغني؛ يزول خلال 48–72 ساعة."},{"f":"من سؤال حقيقي: وليد 37 أسبوعًا، تسرع تنفس 80/د بعد 4 ساعات من الولادة، إصغاء طبيعي، صورة فرط تهوية خفيف — التشخيص؟","b":"تسرع تنفس عابر TTN (رئة الوليد الرطبة) — تأخر ارتشاف السائل الرئوي الجنيني؛ أشيع بعد الولادة القيصرية وأشيع سبب للزلة عند الوليد الناضج."},{"f":"فرّق: استنشاق العقي عند الخدج أم الناضجين؟ وما مخاطر الخدج الشائعة؟","b":"استنشاق العقي يحدث عند الولدان الناضجين ومديدي الحمل (تعقي السائل الأمنيوسي) — نادر عند الخدج. مخاطر الخدج الشائعة: RDS، بقاء القناة الشريانية سالكة، النزف داخل البطينات، التهاب الكولون النخري، نوب توقف التنفس (أشيع تظاهر تنفسي عند الخدج)."},{"f":"من سؤال حقيقي: وليد 43 أسبوعًا، زلة تنفسية بعد 6 ساعات استمرت 5 أيام لم تستجب على الأكسجة، صورة صدر طبيعية — التشخيص الأرجح؟","b":"فرط التوتر الرئوي المستمر (PPHN) — نقص أكسجة لا يستجيب للأكسجة مع صورة صدر طبيعية نسبيًا عند وليد مديد الحمل."},{"f":"من سؤال حقيقي: استسقاء أمنيوسي + إلعاب + زلة تنفسية بعد الولادة عند وليد تمام الحمل — التشخيص والاستقصاء الأمثل؟","b":"رتق المريء (Esophageal atresia) — عدم بلع الجنين للسائل سبب الاستسقاء الأمنيوسي. الاستقصاء الأمثل: صورة صدر مع أنبوب أنفي معدي ظليل يُظهر التفاف الأنبوب في الجيب المريئي العلوي المسدود."},{"f":"فرّق: علامات التهاب الكولون النخري (NEC) — وما المستثنى؟ ومتى تكون الصدمة؟","b":"العلامات: ثمالة معدية صفراوية، توقف تنفس، دم بالبراز، تهوي جدار الأمعاء (Pneumatosis). اليرقان ليس من علاماته، والصدمة علامة متأخرة (انثقاب) لا باكرة. الوقاية: حليب الأم + بروبيوتيك (الحليب الصناعي المشتق من حليب البقر يزيد الخطر)."},{"f":"فرّق: أسباب اليرقان غير المقترن عند الوليد — وأيهما يسبب المقترن؟ ومتى يكون اليرقان مرضيًا؟","b":"غير المقترن: عوز G6PD، تكور الكريات الوراثي، انحلال ABO/Rh، اليرقان الفيزيولوجي، الإنتان البولي. رتق المسالك الصفراوية يسبب اليرقان المقترن (الانسدادي). اليرقان الظاهر في أول 24 ساعة = مرضي انحلالي دائمًا؛ اليرقان الفيزيولوجي الخفيف (يوم 4، أعلى الجذع، طفل سليم، لا تنافر) = مراقبة فقط."},{"f":"من سؤال حقيقي: أم O إيجابي وطفل B إيجابي + كومبس مباشر إيجابي ضعيف + يرقان منذ اليوم الأول — التشخيص؟","b":"تنافر ABO: أم O + طفل A أو B، كومبس مباشر إيجابي ضعيف، يرقان منذ اليوم الأول بارتفاع سريع في البيليروبين، والمعالجة الضوئية كافية غالبًا."},{"f":"من سؤال حقيقي: صفات شلل إرب — الجذور المصابة والوضعية؟","b":"شلل إرب (Erb's palsy): إصابة الجذور C5–C6، شلل رخو بوضعية «النادل» — كتف مدوَّر للداخل ومقرَّب، مرفق ممدود، ساعد في وضع الكب (Pronation). قد يترافق مع شلل العصب الحجابي."},{"f":"فرّق: الورم الدموي فوق السمحاق مقابل التورم المصلي الدموي بعد الولادة؟","b":"الورم الدموي فوق السمحاق (Cephalohematoma): يصيب عظمًا واحدًا لا يتجاوز الدروز، قد يترافق بكسر خطي، يتكلس بنهاية الأسبوع الثاني، ويزول خلال أسابيع إلى أشهر. أما الزوال خلال 24 ساعة فيميز التورم المصلي الدموي (Caput succedaneum)."},{"f":"فرّق: أسباب الاختلاج عند الوليد (ما عدا)؟ ومظاهر النزف داخل البطينات؟","b":"أسباب الاختلاج عند الوليد: نقص سكر الدم، نقص الكلس، النزف الدماغي، نقص الأكسجة — فقر الدم بحد ذاته لا يسبب اختلاجات ولادية. والنزف داخل البطينات عند الخديج يترافق مع: نوب توقف تنفس، اختلاج، بطء قلب (وليس تسرعه)، سبات، حماض استقلابي."}]},{"t":"التغذية","cards":[{"f":"من سؤال حقيقي: رضيع بإسهالات مزمنة + اندفاعات حول الفم + إكزيما حفاضية شديدة + طفح حمامي حطاطي — أي عوز؟","b":"عوز الزنك — التهاب الجلد النهاياتي المعوي (Acrodermatitis enteropathica): إسهالات مزمنة + اندفاعات حول الفم + إكزيما حفاضية شديدة + طفح حمامي حطاطي/حويصلي + فشل نمو + تساقط شعر."},{"f":"فرّق: الكواشيركور مقابل السغل (Marasmus) — العلامة المميزة لكل منهما؟","b":"الكواشيركور (عوز بروتيني): وذمات انطباعية + طفح جلدي تقشري + تهيج شديد + جفاف الجلد وفقدان لمعان الشعر + شهية ضعيفة (قهم). السغل (نقص سعرات): ضمور النسيج الشحمي خاصة الأليتين — «البنطال الفضفاض» — دون وذمات."},{"f":"فرّق: علامات الكساح (Rickets) — وما العلامة التي ليست منه؟ وما علاقة الإرضاع الوالدي به؟","b":"الكساح: السبحة الضلعية، التابس القحفي (علامة مبكرة مميزة)، تقوس الساقين، ضخامة المشاش، تأخر بزوغ الأسنان. بقع بيتو (Bitot spots) علامة نقص فيتامين A لا الكساح. والإرضاع الوالدي المطلق دون مكملات سبب رئيسي للكساح الغذائي — حليب الأم فقير بفيتامين D (~25 وحدة/لتر؛ الحاجة 400 وحدة/يوم)."},{"f":"نقطة ذهبية: نقص أي فيتامين يسبب مرض بري بري (Beriberi)؟","b":"نقص التيامين (فيتامين B1) — بري بري الرطب: قصور قلب احتقاني مع وذمات؛ والجاف: اعتلال أعصاب محيطية."},{"f":"فرّق: مضادات استطباب الإرضاع الوالدي (ما عدا)؟ وبم يتميز حليب الأم عن حليب البقر؟","b":"مضادات الاستطباب: الغالاكتوزيميا، عوز اللاكتاز الشديد، بيلة الفينيل كيتون (نسبي)، تعاطي الأم أدوية ممنوعة. يرقان حليب الثدي ليس مضاد استطباب — يُتابع الإرضاع. حليب الأم يتميز عن حليب البقر بـ: بروتين أقل، لاكتوز أعلى، عبء كلوي أقل."},{"f":"من سؤال حقيقي: قواعد التغذية التكميلية عند الرضع — ومتى يُعطى العسل؟","b":"تبدأ من الشهر السادس، أغذية قليلة الملح، نوع واحد كل مرة (لمراقبة التحسس)، العسل بعد السنة (خطر التسمم الوشيقي عند الرضع). الأغذية الغنية بالسكريات مستثناة — تفسد الشهية وتسبب التسوس والبدانة."},{"f":"فرّق: من اختلاطات البدانة عند الأطفال ما عدا؟","b":"السكري من النمط الثاني، انزلاق مشاش رأس الفخذ، فرط التوتر داخل القحف مجهول السبب، تشحم الكبد، فرط التوتر الشرياني. السكري من النمط الأول مرض مناعي ذاتي وليس من اختلاطات البدانة."}]},{"t":"أخطاء الاستقلاب الوراثية","cards":[{"f":"من سؤال حقيقي: الطريقة المفضلة للتشخيص المبكر لبيلة الفينيل كيتون (PKU) والتي حسّنت إنذار المرض عالميًا؟","b":"برامج النخل (المسح) الشامل عند الوليد بقياس الفينيل ألانين في الدم — تكشف المرض قبل ظهور التخلف العقلي، وبدء الحمية منخفضة الفينيل ألانين مبكرًا حسّن الإنذار جذريًا عالميًا."},{"f":"من سؤال حقيقي: علامة بقعة الكرز الحمراء في اللطخة الصفراء (Cherry-red spot) تُشاهد في أي مرض؟ وفرّقها عن علامات ويلسون والهوموسيستين والغالاكتوزيميا العينية.","b":"داء تاي-ساكس (تراكم الغانغليوزيد GM2 في الخلايا العقدية الشبكية حول النقرة). فرّق: داء ويلسون = حلقة كايزر-فلايشر القرنية؛ بيلة الهوموسيستين = خلع البلورة (تنزاح للأسفل والأنف — بعكس مارفان: للأعلى والصدغ)؛ الغالاكتوزيميا = ساد (عتامة) لا خلع للعدسة."},{"f":"فرّق: مظاهر عوز فيتامين E عند الأطفال (ما عدا)؟ وأي عوز يسبب اعتلال العضلة القلبية؟","b":"مظاهر عوز فيتامين E عند الأطفال: فقر دم انحلالي، رنح، اعتلال أعصاب محيطية، اعتلال شبكية (تنكس شبكية). اعتلال العضلة القلبية يميز عوز السيلينيوم (داء كيشان/Keshan) وليس عوز فيتامين E."}]}]},{"s":"الأطفال 2","topics":[{"t":"النمو والبلوغ","cards":[{"f":"نقطة ذهبية: متى أعلى سرعة نمو في حياة الإنسان؟ ومتى يتضاعف طول/وزن الولادة؟","b":"أعلى سرعة نمو في الحياة الجنينية. طول الولادة يتضاعف بعمر 4 سنوات؛ وزن الولادة يتضاعف بعمر 5–6 أشهر ويتثلث بعمر السنة؛ محيط الرأس يزداد ~12 سم في السنة الأولى وأعلاها في الربع الأول (~2 سم شهريًا)."},{"f":"فرّق: تعريف البلوغ الباكر عند الجنسين — وما دور الرنين المغناطيسي؟","b":"البلوغ الباكر = ظهور صفة جنسية ثانوية قبل 8 سنوات عند الإناث و9 سنوات عند الذكور. العمر العظمي متقدم (لا متأخر)، والرنين المغناطيسي للدماغ من وسائل التشخيص لنفي آفة تحت المهاد — خاصة عند الذكور."},{"f":"نقطة ذهبية: أي نواة عظمية يدل ظهورها على بدء البلوغ؟","b":"ظهور نواة العظم السمسماني في الإبهام (Adductor sesamoid) — دلالة شعاعية على بدء البلوغ، تظهر قبل مشاشات الزند والعضد."},{"f":"فرّق: قصر القامة متناسب الأجزاء مقابل غير متناسب الأجزاء — الأسباب؟","b":"متناسب الأجزاء: قصور الدرق المكتسب، عوز هرمون النمو، متلازمة كوشينغ. غير متناسب الأجزاء (قصر أطراف نسبة للجذع كما في الودانة): عسرات التنسج الهيكلية فقط — ومارفان تسبب طول قامة لا قصرها."},{"f":"من سؤال حقيقي: استقصاءات قصر القامة عند طفلة 5 سنوات — ما الضروري منها وما المستثنى؟","b":"الضرورية: IGF-1 (محور هرمون النمو)، TSH (نفي قصور الدرق)، صورة العمر العظمي لليد اليسرى، الصيغة الصبغية عند كل طفلة (نفي تيرنر)، أضداد الزلاقي، طول الوالدين (الطول الوراثي المستهدف). المستثناة: شوارد الدم، صورة الصدر، التنظير الهضمي السفلي."},{"f":"من سؤال حقيقي: قصر قامة مع ميل لزيادة الوزن — الأسباب ما عدا؟","b":"قصور الدرق المكتسب، عوز هرمون النمو، عوز عامل النمو IGF-1، زيادة الستيروئيدات (كوشينغ) — كلها قصر قامة مع ميل لزيادة الوزن. الاستثناء: البدانة الأساسية (تترافق بطول طبيعي أو متسارع لا قصر قامة)."},{"f":"قاعدة ذهبية: تأخر النمو والبلوغ البنيوي — ما الإنذار النهائي؟ وما العمر العظمي؟","b":"تأخر النمو والبلوغ البنيوي (Constitutional delay) حالة سليمة محدودة ذاتيًا: الطول النهائي طبيعي دون أي علاج، العمر العظمي متأخر عن الزمني، قصة عائلية إيجابية لتأخر البلوغ."},{"f":"نقطة ذهبية: متى ذروة النمو التعويضي عند صغار الوزن لعمرهم الحملي؟","b":"النمو التعويضي (Catch-up growth) عند المولودين بوزن أقل من الطبيعي لعمرهم الحملي (SGA): ذروة التسارع وأقصى معدل له خلال الأشهر الستة الأولى بعد الولادة."}]},{"t":"أمراض الجهاز الهضمي","cards":[{"f":"من سؤال حقيقي: الصورة السريرية والمخبرية لتضيق البواب الضخامي (Hypertrophic pyloric stenosis)؟","b":"إقياءات نافورية غير صفراوية تبدأ بعمر 2–3 أسابيع (ذروة 3–4 أسابيع) — وليس بعد الولادة مباشرة؛ رضيع جائع دومًا (شره للرضاعة)، جس الزيتونة (Olive) في الشرسوف، حركات حوية معدية ظاهرة، نقص وزن، إمساك. مخبريًا: قلاء استقلابي ناقص الكلور (نقص كلور + نقص بوتاسيوم) من فقدان HCl."},{"f":"فرّق: أشيع عرض للقلس المعدي المريئي واختلاطاته — ونوع فقر الدم المرتبط به؟","b":"أشيع عرض: إقياءات متكررة بعد الرضعات. الاختلاطات: فشل نمو، استنشاق متكرر/ذات رئة استنشاقية، وزيز، نوب توقف تنفس وموت مفاجئ عند الرضع، نوب بكاء متكرر، متلازمة سانديفر (قعس رقبي/Sandifer). فقر الدم المرتبط به صغير الكريات (عوز حديد من نزف مزمن) — وليس كبير الكريات."},{"f":"فرّق: داء كرون مقابل التهاب القولون التقرحي — الامتداد والآفات والنواسير؟","b":"داء كرون: يصيب أي جزء من الفم إلى الشرج مع ميل للدقاق الانتهائي، آفات متقطعة (Skip lesions)، نواسير، فشل نمو وفقر دم أشد. التهاب القولون التقرحي: محصور بالقولون والمستقيم، التهاب متصل مستمر، لا نواسير."},{"f":"من سؤال حقيقي: الصورة النموذجية للداء الزلاقي وتأكيد تشخيصه وعلاجه؟","b":"طفل كان طبيعيًا حتى إدخال الحبوب (الغلوتين) ثم إسهال مزمن + فشل نمو؛ ذروة التظاهر 8–24 شهرًا. التشخيص: أضداد الترانسغلوتاميناز النسيجي (tTG) ثم خزعة العفج — أضداد الغليادين اختبار قديم قليل النوعية. العلاج: حذف القمح والشعير والشوفان. يترافق مع السكري نمط 1 والدرق المناعي الذاتي."},{"f":"فرّق: انغلاف الأمعاء — العمر، الصورة، العلامة الشعاعية، ومتى يكون البراز المدمى؟","b":"الذروة 3 أشهر–سنتين؛ ألم مغصي نوبي شديد مع شحوب وهدوء؛ البراز الهلامي المدمى (مربى الكشمش) علامة متأخرة (احتشاء مخاطية) لا باكرة؛ علامة الهدف (Target sign) بالإيكو؛ الرد بالحقنة الشرجية المائية أو الغازية إذا لم يوجد انثقاب."},{"f":"فرّق: متى تُستطب الصادات في التهاب المعدة والأمعاء — ومتى تُمنع؟","b":"تُستطب الصادات في: الشيغلا (الزحار العصوي)، انتشار الخمج خارج الجهاز الهضمي (تجرثم الدم)، تثبيط المناعة، سوء التغذية الشديد — وليست روتينية دومًا. الاستثناء: الإشريكية القولونية (خاصة O157:H7 — الصادات تزيد خطر المتلازمة الانحلالية اليوريميائية)؛ والحرارة وحدها ليست استطبابًا."},{"f":"من سؤال حقيقي: العلامات المنذرة لسبب عضوي في الألم البطني المتكرر عند الأطفال (ما عدا)؟","b":"فقد الوزن، اليرقان، الإقياء الدموي، الإقياءات الصفراوية، الألم الشرسوفي الليلي، عسر التبول. أما الإمساك فشائع في الألم البطني الوظيفي وليس علامة منذرة بحد ذاته."},{"f":"نقطة ذهبية: أشيع سبب للإسهال الحاد عند الرضع؟ وفترة حضانة التهاب المعدة والأمعاء؟","b":"أشيع سبب للإسهال الحاد عند الرضع: فيروس الروتا (Rotavirus). فترة حضانة التهاب المعدة والأمعاء قصيرة جدًا: 24–48 ساعة."},{"f":"من سؤال حقيقي: مبادئ تدبير التهاب المعدة والأمعاء عند الأطفال؟","b":"الأساس: الإماهة الفموية + السوائل الوريدية في الحالات الشديدة + الزنك في الإسهال الحاد؛ تجنب مضادات الإسهال؛ الصادات ليست روتينية بل لاستطبابات محددة فقط."},{"f":"فرّق: علامات التجفاف المتوسط مقابل علامة التجفاف الشديد؟","b":"التجفاف المتوسط (5–10%): قلة تبول، فقدان مرونة الجلد، غؤور العينين واليوافيخ، تسرع تنفس. الوهط الدوراني (هبوط ضغط/صدمة) علامة التجفاف الشديد (>10%) ويستلزم إماهة وريدية إسعافية."},{"f":"فرّق: الرايات الحمراء للإقياء عند الأطفال — وأي إقياء فيزيولوجي؟","b":"الرايات الحمراء: الإقياءات القذفية، المضض البطني، انتباج اليوافيخ، الإقياء بنهاية سعال نوبي. أما الإقياءات القلسية البسيطة في الأسابيع الأولى ففيزيولوجية شائعة لا تستدعي القلق."},{"f":"من سؤال حقيقي: طفل 4 سنوات بطفح فرفري على السفليين + ألم مفصلي ثم ألم بطني مع براز هلامي — التشخيص؟","b":"فرفرية هينوخ-شونلاين (التهاب الأوعية بالغلوبولين المناعي A): طفح فرفري على الطرفين السفليين + ألم مفصلي، ثم ألم بطني مع براز هلامي = انغلاف أمعاء — من أشيع أسبابه فوق عمر السنتين خارج الذروة العمرية."}]},{"t":"الأمراض الخمجية والمناعة","cards":[{"f":"من سؤال حقيقي: استئصال الطحال لدى طفل 3 سنوات — ما اللقاح الواجب؟ ولماذا؟","b":"لقاح المكورات الرئوية (Pneumococcal) — للوقاية من الإنتان الماحق بعد استئصال الطحال (OPSI) الذي أشيع مسبباته العقديات الرئوية (الجراثيم المغلفة)."},{"f":"من سؤال حقيقي: التهاب لوزات قيحي مع ضخامة طحال عند طفل — التشخيص والعامل الممرض؟ وما الدواء الممنوع؟","b":"الصورة الكلاسيكية: التهاب لوزات قيحي + ضخامة طحال + نمشات على الحنك الرخو + اعتلال عقد رقبية + حرارة ممتدة. العامل: فيروس إبشتاين-بار (EBV). تنبيه: تجنب الأموكسيسيلين فيه — يسبب طفحًا جلديًا شبه مؤكد."},{"f":"فرّق: ما الذي يميز طفح الحماق (جدري الماء)؟ وما فترة حضانته الحقيقية؟","b":"طفح حطاطي حويصلي يظهر بدفعات متعاقبة (Crops) — في المنطقة الواحدة آفات بأعمار وصفات مختلفة (حطاطات وحويصلات وقشور معًا)؛ حاكّ يبدأ على الجذع والوجه. فترة الحضانة 10–21 يومًا (لا 6–8)."},{"f":"فرّق: متى يظهر طفح وردية الرضيع بالنسبة للحرارة؟ وما حالة الطفل العامة؟","b":"وردية الرضيع (Roseola — HHV-6): حرارة مرتفعة 3–4 أيام ثم يظهر الطفح الحمامي البقعي المعمم بعد هبوط الحرارة المفاجئ (لا يتزامن معها)؛ الحالة العامة جيدة رغم الحرارة؛ المعالجة عرضية والإنذار ممتاز."},{"f":"قاعدة ذهبية: التهاب السحايا الجرثومي عند الأطفال — هل يُعالج منزليًا؟ وما أشيع عقابيله؟","b":"حالة إسعافية: قبول مشفوي + صادات وريدية — لا يُعالج في المنزل أبدًا. أشيع عقابيله: نقص السمع الحسي العصبي (يُوصى بتخطيط السمع لكل ناجٍ). نسبة الوفيات 5–10%."},{"f":"فرّق: موجودات السائل الدماغي الشوكي في التهاب السحايا القيحي مقابل الدرني؟","b":"القيحي: سائل عكر + عدلات + ارتفاع البروتين (وليس انخفاضه) + نقص السكر + تلوين إيجابي. الدرني: سير مزمن (أسابيع من حرارة وصداع) + لمفاويات + بروتين مرتفع جدًا + سكر منخفض."},{"f":"قاعدة ذهبية: فرفرية مرافقة للحرارة عند طفل بأي عمر = الشك الفوري بأي عامل ممرض؟","b":"النيسريات السحائية (المكورات السحائية) — شك إسعافي فوري. والطفح الفرفري سمة التهاب السحايا بالمكورات السحائية (التهاب أوعية وتخثر منتشر) وليس من موجودات التهاب السحايا بالمكورات الرئوية."},{"f":"من سؤال حقيقي: معايير داء كاوازاكي وعلاجه — وما الدواء الذي لا يُعطى؟","b":"حمى مستمرة 5 أيام أو أكثر + 4 من 5: التهاب ملتحمة غير قيحي (مع تجنيب الحوف)، تغيرات شفوية فموية (تشقق شفاه)، تغيرات الأطراف (احمرار ووذمة الراحتين والأخمصين ثم تقشر)، طفح، اعتلال عقد رقبية وحيدة الجانب. العلاج: غلوبولين مناعي وريدي + أسبرين بجرعة عالية + إيكو قلب — لا بنسلين."},{"f":"فرّق: الحصبة — الحضانة، العلامة الواسمة، نوع الطفح، أشيع اختلاط، وهل هي مشوهة؟","b":"فترة الحضانة 8–12 يومًا؛ الطور البادري: سعال وزكام والتهاب ملتحمة؛ بقع كوبليك (Koplik) العلامة الواسمة؛ الطفح بقعي حطاطي (ليس حويصليًا) والحرارة تبلغ ذروتها مع ظهوره؛ أشيع اختلاط: التهاب الأذن الوسطى. الحصبة ليست مشوهة للأجنة (بعكس الحصبة الألمانية)."},{"f":"فرّق: الحمى القرمزية — المسبب، صفة الطفح، العلاج، وهل المناعة دائمة؟","b":"المسبب: العقديات من المجموعة A + الذيفان المحمر؛ الطفح كورق الصنفرة أشد في الثنيات (خطوط باستيا) مع توهج الوجنتين؛ العلاج: بنسلين 10 أيام. المناعة نوعية للسلالة المسببة وليست دائمة مطلقًا — قد تتكرر بسلالات أخرى."},{"f":"نقطة ذهبية: مكونات اللقاح الخماسي (ما عدا)؟ وأي لقاح غير مشمول في البرنامج الوطني السوري؟","b":"اللقاح الخماسي = الدفتريا + الكزاز + السعال الديكي (DPT) + التهاب الكبد B + المستدمية النزلية B — ولا يشمل الحصبة الألمانية (تُعطى ضمن MMR). لقاح الحماق غير مشمول في برنامج التلقيح الوطني السوري."},{"f":"فرّق: اللقاحات عند الطفل المثبط مناعيًا — ما الممنوع وما المسموح؟ وأين تُبحث ندبة BCG؟","b":"اللقاحات الحية المضعفة (MMR، الشلل الفموي، BCG) ممنوعة عند المثبط مناعيًا (مثل كورتيزون 2 مغ/كغ لأكثر من شهر) — تُعطى اللقاحات المقتولة/المعطلة فقط. MMR لقاح حي مضعف يُعطى بجرعتين؛ وBCG يُعطى داخل الأدمة في الثلث العلوي من الذراع الأيسر (موضع ندبة اللقاح)."},{"f":"من سؤال حقيقي: علامة الخد المصفوع (Slapped cheek) تُشاهد في أي مرض؟","b":"الداء الخامس (الحمامى الإنتانية — Erythema infectiosum) الناجم عن الفيروس الصغير B19 (Parvovirus B19)."},{"f":"فرّق: النكاف — نوع لقاحه، مدة العدوى، وهل التهاب الخصية من اختلاطاته أم من اختلاطات EBV؟","b":"لقاح النكاف حي مضعف ضمن MMR (وليس فيروسًا معطلًا)؛ المريض معدٍ 5 أيام بعد تورم النكفة؛ التهاب السحايا العقيم اختلاط شائع لكنه سليم المسار. التهاب الخصية والبربخ اختلاط النكاف — وليس داء وحيدات النوى الخمجي (EBV)."},{"f":"من سؤال حقيقي: الحمى التيفية — ما علامة النبض المميزة؟","b":"الحمى التيفية: صداع + ألم بطني + ضخامة طحال + اندفاعات وردية حول الجذع — مع بطء نبض نسبي (Relative bradycardia) لا تسرع نبض."},{"f":"نقطة ذهبية: الخط الأول في علاج حمى البحر الأبيض المتوسط (FMF) عند الأطفال؟","b":"الكولشيسين (Colchicine) — الخط الأول والعلاج الوقائي الدائم المعتمد لحمى البحر الأبيض المتوسط (FMF) عند الأطفال."},{"f":"فرّق: مكونات المسح الخمجي الروتيني — وما الذي ليس روتينيًا؟","b":"المسح الخمجي الروتيني: زرع دم + تعداد دم وصيغة + CRP + فحص بول وراسب. البزل القطني ليس روتينيًا — عند الاشتباه بالتهاب سحايا فقط؛ وفحص البراز يُطلب عند وجود أعراض هضمية فقط."},{"f":"نقطة ذهبية: ما التظاهر الأشيع للإصابة بفيروس شلل الأطفال؟","b":"الإصابة تحت السريرية (غير العرضية) — 90–95% من الإصابات بفيروس شلل الأطفال."},{"f":"فرّق: فيروسات عائلة الحلأ — وأي فيروس مذكور ليس منها؟","b":"عائلة فيروسات الحلأ (Herpesviridae): الحلأ البسيط (HSV)، الحماق النطاقي (VZV)، المضخم للخلايا (CMV)، إبشتاين-بار (EBV)، الحلأ الإنساني (HHV). الأدينوفيروس (Adenovirus) ليس منها."},{"f":"فرّق: التهاب البلعوم مع توضع أغشية على اللوزتين — أي عامل ممرض لا يشكل أغشية؟","b":"الإنتان بالأدينوفيروس (الحمات الراشحة الغدية) — التهاب بلعوم حموي دون تشكل أغشية نموذجية. أما الدفتريا (غشاء كاذب)، وداء وحيدات النوى، والتهاب البلعوم العقدي، والهربسي فتشكل أغشية."}]},{"t":"التحسس","cards":[{"f":"من سؤال حقيقي: طفل 3 سنوات بالتهاب أنف وملتحمة تحسسي — ما المرض المتوقع إصابته به مستقبلًا؟","b":"المسيرة التأتبية (Atopic march): إكزيما → حساسية طعام → التهاب أنف تحسسي → ربو. الطفل الأتوبي بالتهاب أنف وملتحمة تحسسي معرض أكثر لتطور الربو لاحقًا (وحدة المجرى الهوائي والآلية الالتهابية المشتركة بوساطة IgE)."},{"f":"فرّق: مظاهر التهاب الأنف التحسسي عند الأطفال (ما عدا)؟","b":"المظاهر: عطاس ونزّ أنفي وحكة أنفية وعينية وسيلان دمعي، تنفس فموي، سحنة تحسسية (هالات داكنة تحت العينين وخطوط ديني)، سعال من التنقيط الأنفي الخلفي، اضطراب نوم وضعف تركيز نهاري. المستثنى: الترفع الحروري (يوجه لسبب خمجي) والسعال النوبي الاشتدادي (يوحي بالسعال الديكي أو الربو)."},{"f":"فرّق: من تظاهرات العوز المناعي عند الأطفال ما عدا؟","b":"تظاهرات العوز المناعي: ذات رئة متكررة، خراجات جلدية متكررة، داء مبيضات شديد، مليساء سارية متكررة. السلس البولي الليلي ليس منها."}]},{"t":"الاضطرابات التنفسية","cards":[{"f":"فرّق: الصورة السريرية للكروب (Croup) والخط الأول لعلاجه؟","b":"الكروب (التهاب حنجرة ورغامى فيروسي — بارا إنفلونزا): سن 6 أشهر–6 سنوات، استيقاظ ليلي مفاجئ بسعال نباحي + بحة صوت + صرير شهيقي خشن، حالة عامة جيدة، حمى خفيفة. العلاج: الستيروئيدات (ديكساميتازون) خط أول — لا صادات (خمج فيروسي بحت)."},{"f":"فرّق: التهاب لسان المزمار مقابل الكروب — ما العلامة الفارقة؟","b":"التهاب لسان المزمار (Epiglottitis): ألم حلق شديد + إلعاب (سيلان لعاب) وصعوبة بلع + حرارة شديدة + حالة عامة سيئة مع عسرة تنفسية مترقية. الكروب: لا إلعاب فيه — الإلعاب يوجه للسان المزمار."},{"f":"من سؤال حقيقي: رضيع 10 أشهر بزلة تنفسية مفاجئة + خفوت بالجهة اليمنى — التشخيص والاستقصاء الأول؟","b":"البداية المفاجئة عند رضيع سليم سابقًا (سن الاستكشاف الفموي) + خفوت إصغاء وحيد الجانب. الجسم الأجنبي غير الظليل (كالفستق) يعمل كصمام: يدخل الهواء ولا يخرج (Air trapping) — الاستقصاء الأول: صورة صدر بسيطة في وضعية الزفير تُظهر انحباس الهواء."},{"f":"فرّق: صورة التهاب القصيبات واستطبابات قبوله المشفوي (ما عدا)؟","b":"رضيع دون السنتين بعد رشح علوي بأيام: عسرة تنفسية + تطاول زفير + وزيز معمم + خراخر ناعمة بالساحتين. استطبابات القبول: نوب توقف تنفس، إشباع أكسجين <90%، وارد فموي ناقص، خمول/ضعف رضاعة، عسرة شديدة — الوزيز المنتشر وحده لا يستوجب القبول."},{"f":"فرّق: علامة شدة النوبة الربوية وحجر أساس تدبيرها — وما الذي لا يُستخدم في الهجمة؟","b":"صعوبة الكلام (عدم إتمام الجمل) = علامة النوبة الشديدة. حجر الأساس: إرذاذ السالبوتامول (منبه بيتا2 قصير). لا سالميترول (طويل المفعول — للضبط المزمن لا الهجمة)، ولا أدرينالين عضلي (علاج التأق لا الربو). الربو الخفيف المتقطع: منبه بيتا إنشاقي قصير عند الحاجة فقط."},{"f":"فرّق: الداء الليفي الكيسي — الوراثة، الطفرة الأشيع، التظاهر الولادي، والثلاثية؟","b":"يورث بصفة جسدية مقهورة؛ طفرة F508 الأشيع. التظاهر الولادي: العلوص بالعقي (Meconium ileus). الثلاثية: إنتانات رئوية متكررة + فشل نمو + براز دهني كبير كريه. زيادة إطراح الصوديوم بالعرق؛ العقم عند الذكور (غياب الأسهرين الخلقي)؛ السعال مزمن منتج (رطب) منذ الرضاعة — وليس جافًا."},{"f":"فرّق: السعال الديكي — المستودع، الصورة الدموية، الحمى، ودور الماكروليدات؟","b":"الإنسان المستودع الوحيد؛ سعال نوبي اشتدادي يزداد ليلًا؛ كثرة لمفاويات؛ غياب الحمى أو خفوتها (الحمى المرتفعة توجه لتشخيص آخر)؛ تغيب صيحة الديك عند الرضع الصغار. الماكروليدات تقلل العدوى وتخفف الأعراض إذا أُعطيت في المرحلة النزلية — لا تُحسّن السير إذا تأخرت."},{"f":"من سؤال حقيقي: التهاب الأذن الوسطى الحاد — العمر، أشيع مسبب، ونوع نقص السمع؟","b":"ذروة الحدوث 6–12 شهرًا (سوء وظيفة نفير أوستاش)؛ أشيع مسبب: العقديات الرئوية ثم المستدمية النزلية؛ نقص السمع المرافق توصيلي (انصباب) لا حسي عصبي؛ معظم الحالات تشفى عفويًا."},{"f":"من سؤال حقيقي: ذات رئة عند طفلة 7 سنوات بحالة عامة حسنة ونمط قصبي — العامل الأكثر احتمالًا؟","b":"الميكوبلازما (Mycoplasma) — طفل بعمر المدرسة بسعال مستمر وحرارة خفيفة وخراخر منتشرة مع وزيز خفيف وصورة بنمط ذات رئة وقصبات وحالة عامة حسنة."},{"f":"فرّق: أسباب الصرير المزمن (ما عدا)؟","b":"تلين الحنجرة، تضيق تحت المزمار، الحلقة الوعائية، العقد اللمفية الضاغطة — أما الكروب فسبب حاد للصرير لا مزمن."},{"f":"فرّق: أسباب انسداد الطرق التنفسية العلوية (ما عدا)؟","b":"جسم أجنبي، التهاب لسان المزمار، كروب، تضيق حنجرة — كلها علوية (صرير شهيقي). الربو مرض الطرق السفلية (تضيق قصبي قابل للعكس — وزيز زفيري) وليس من أسباب انسداد الطرق العلوية."},{"f":"فرّق: علامات الشدة التنفسية المتوسطة مقابل الشديدة عند الأطفال؟","b":"المتوسطة: تسرع تنفس وقلب + رقص خنابتي الأنف + سحب وربي. الشديدة: زرقة + إنهاك + تعب من زيادة الجهد التنفسي + انخفاض مستوى الوعي. السحب الوربي وحده علامة متوسطة لا شديدة."},{"f":"فرّق: أي دواء مما يلي ليس موسعًا قصبيًا: سالبوتامول، سالميترول، ثيوفيليين، كرومولين، إبراتروبيوم؟","b":"كرومولين الصوديوم (Cromolyn) مثبت للخلايا البدينة وقائي — ليس موسعًا قصبيًا. الموسعات: سالبوتامول وسالميترول (محاكيا بيتا)، ثيوفيليين، إبراتروبيوم برومايد (مضاد كولين)."},{"f":"من سؤال حقيقي: أسباب التهاب الرئة المتكرر عند الأطفال (ما عدا)؟","b":"الداء الليفي الكيسي، نقص المناعة، استنشاق جسم أجنبي، المعالجة بالستيروئيدات — أما التهاب الأنف التحسسي فلا يسبب ذات رئة متكررة."},{"f":"من سؤال حقيقي: توقف التنفس الانسدادي أثناء النوم — ارتفاع أم هبوط الضغوط الرئوية؟","b":"متلازمة توقف التنفس الانسدادي أثناء النوم تسبب ارتفاع الضغوط الرئوية (فرط التوتر الرئوي من نقص الأكسجة الليلي المتكرر) لا هبوطها — مع اضطرابات تعلم وسلوك ونوم نهاري مفرط وفشل نمو."},{"f":"قاعدة ذهبية: هل يظهر تبقرط الأصابع في مرض تنفسي حاد منذ 3 أيام؟","b":"التبقرط (Clubbing) علامة مزمنة تحتاج أسابيع إلى أشهر لتتطور (أمراض رئوية مزمنة كالتليف الكيسي وتوسع القصبات، وقلبية مزرقة) — ولا يظهر في مرض حاد منذ 3 أيام."},{"f":"من سؤال حقيقي: أسباب الوزيز المتكرر بعمر 4 سنوات (ما عدا)؟","b":"الربو، الوزيز الفيروسي، الداء الليفي الكيسي، الاستنشاق المتكرر — أما التهاب القصيبات الحاد فمرض الرضع دون السنتين (النوبة الأولى غالبًا بالفيروس التنفسي المخلوي)."},{"f":"من سؤال حقيقي: استطبابات استئصال اللوزات عند الأطفال (ما عدا)؟","b":"التهاب لوزات شديد متكرر، خراج حول اللوزة، نوب نقص التنفس الانسدادي أثناء النوم، الشك بالخباثة — وليس التهاب الأذن الوسطى الحاد المتكرر."},{"f":"من سؤال حقيقي: عوامل خطورة التهاب القصيبات الحاد الشديد (ما عدا)؟","b":"الخداجة، عسر التصنع القصبي الرئوي، المرض القلبي الخلقي، الداء الكيسي الليفي — أما قصور الدرق الخلقي فليس من عوامل خطورة التهاب القصيبات الشديد."},{"f":"فرّق: مسببات الرشح الشائع — وأي عامل جرثومي ليس منها؟","b":"الرشح الشائع خمج فيروسي: الرينوفيروس، الفيروسات التاجية، البارا إنفلونزا، الأدينوفيروس — أما العقديات الحالة للدم بيتا زمرة A فتسبب التهاب البلعوم الجرثومي لا الرشح الشائع."}]},{"t":"الاضطرابات القلبية","cards":[{"f":"فرّق: مكونات رباعي فالو الأربعة ومنظره الشعاعي — وما الذي ليس منها؟","b":"المكونات الأربعة: فتحة بين البطينين كبيرة (VSD) + تراكب الأبهر على الحاجز + تضيق مخرج البطين الأيمن (تحت الصمام الرئوي) + ضخامة البطين الأيمن — مع نقص التوعية الرئوية (وليس زيادتها). الصورة الشعاعية: منظر الحذاء (Coeur en sabot). ليست من مكوناته: ASD ولا بقاء القناة الشريانية."},{"f":"من سؤال حقيقي: الصورة الاصغائية لتضيق الصمام الأبهري — وأي آفة قلبية تترافق بنوب غشي؟","b":"النفخة الانقباضية الدفعية على الورب الثاني أيمن القص المنتشرة للعنق + هرير سباتي + نبض محيطي ضعيف. نوب الغشي من سمات تضيق الأبهر الشديد (عجز القلب عن زيادة النتاج مع الجهد → نقص تروية دماغية عابر)."},{"f":"فرّق: العلامة الاصغائية المميزة لعيب الحاجز الأذيني (ASD) — وما الذي ليس من سماته؟","b":"العلامة المميزة: انقسام ثابت للصوت الثاني (لا يتغير مع التنفس — لزيادة ثابتة في العود الوريدي للبطين الأيمن) + نفخة انقباضية قذفية على الحافة اليسرى للقص. النفخة المستمرة (الآلية) سمة PDA لا ASD. والـASD الثانوية المعزولة لا ترفع خطر التهاب الشغاف بشكل يُعتد به (استثناء الوقاية)."},{"f":"فرّق: عيب الحاجز البطيني (VSD) — نوع النفخة والعلاقة بين شدتها وقطر الفتحة؟","b":"أشيع آفة قلبية ولادية؛ نفختها انقباضية شاملة (Holosystolic) لا دفعية؛ العلاقة عكسية: الفتحة الصغيرة نفختها أعلى (فرق ضغط أكبر)؛ تسبب زيادة التوعية الرئوية وقد تتعقد بقصور أبهري."},{"f":"نقطة ذهبية: الدواء الذي يساهم في إغلاق القناة الشريانية عند حديث الولادة؟","b":"الإيبوبروفين (والإندوميتاسين) — مضادات الالتهاب غير الستيروئيدية تثبط تصنيع البروستاغلاندينات فينغلق العامل المُبقي على القناة مفتوحة."},{"f":"من سؤال حقيقي: الخطر الأساسي على وليد الأم المصابة بالذأب الحمامي الجهازي؟","b":"الحصار القلبي التام الخلقي — عبور الأضداد anti-Ro/SSA وanti-La/SSB عبر المشيمة وإصابة جهاز التوصيل."},{"f":"فرّق: الزرقة المركزية القلبية — هل تزول بالأكسجين؟ ومتى يرجح تحسنها سببًا رئويًا؟","b":"الزرقة المركزية القلبية ناتجة عن تحويلة يمين–يسار (دم غير مؤكسج يتجاوز الرئتين) فلا تزول بإعطاء الأكسجين — بعكس الزرقة المحيطية. تزداد بالجهد والرضاعة وتُشاهد في الأغشية المخاطية واللسان. تحسنها الواضح بالأكسجين (اختبار فرط الأكسجة) يرجح سببًا رئويًا."},{"f":"من سؤال حقيقي: التشخيص الأرجح لزرقة مركزية منذ اليوم الأول للولادة دون زلة شديدة؟","b":"تبادل منشأ الأوعية الكبيرة (TGA) — الدورانان الجهازي والرئوي على التوازي بدل التعاقب فيصل الدم غير المؤكسج إلى الأبهر مباشرة؛ زرقة مركزية منذ اليوم الأول دون زلة تنفسية شديدة."},{"f":"من سؤال حقيقي: الإصابة القلبية الأكثر شيوعًا في متلازمة داون؟","b":"تشوه الوسادة (عيب الحاجز الأذيني البطيني — AV canal) — يصيب نحو نصف الأطفال الداونيين المصابين بتشوه قلبي."},{"f":"فرّق: الآفات القلبية المعتمدة على القناة الشريانية (ما عدا)؟","b":"تبادل منشأ الأوعية، نقص تصنع البطين الأيسر، انقطاع قوس الأبهر، تضيق برزخ الأبهر الحرج، تضيق الصمام الأبهري الحرج. الاستثناء: الجذع الشرياني المشترك (جذع واحد يغذي الدورانين معًا فلا يعتمد على القناة)."},{"f":"فرّق: معايير جونز الكبرى للحمى الرثوية — وما المعيار الصغير؟","b":"الكبرى: التهاب القلب، التهاب المفاصل (لا الألم المفصلي وحده)، رقص سيدنهام (علامة متأخرة)، الحمامى الهامشية (على الجذع والأطراف الدانية وتجتنب الوجه)، العقيدات تحت الجلد (على السطوح الباسطة). الصغرى: CRP وASLO والحرارة. الحمى الرثوية تتلو الإنتان بالعقديات المقيحة زمرة A (غير مقيحة)."},{"f":"فرّق: صفات النفخة البريئة — وما الذي يستبعد كونها بريئة؟","b":"ناعمة انقباضية دفعية (درجة 1–2/6) بأصوات قلب طبيعية، لا عرضية، تُسمع على الحافة اليسرى للقص — دون هرير مجسوس. وجود الهرير (Thrill) يدل على نفخة مرضية ويستبعد كونها بريئة."},{"f":"فرّق: من أسباب أمراض القلب الولادية (ما عدا)؟","b":"الحصبة الألمانية عند الحامل، الذئبة الحمامية الجهازية، تناول الوارفارين، الشذوذات الصبغية. الهيبارين لا يعبر المشيمة إطلاقًا فلا يسبب تشوهات قلبية ولادية."},{"f":"نقطة ذهبية: المضاد الحيوي الأنسب للوقاية من التهاب الشغاف عند المعرضين؟","b":"الأموكسيسيلين فمويًا (50 مغ/كغ قبل الإجراء بساعة) — الخط الأول للوقاية من التهاب الشغاف الخمجي عند الأطفال المعرضين لخطر كبير."},{"f":"فرّق: الآفات القلبية المزرقة (ما عدا)؟","b":"المزرقة: رباعي فالو، تبادل منشأ الأوعية، متلازمة آيزنمنغر، رتق مثلث الشرف، شذوذ العود الوريدي الرئوي التام. غير المزرقة: تضيق الصمام الرئوي المعزول، تضيق برزخ الأبهر (فرق ضغط بين العلوي والسفلي)."},{"f":"من سؤال حقيقي: تدبير نوبة الزرقة الشديدة في رباعي فالو (ما عدا)؟","b":"نوبة الزرقة الشديدة (Tet spell): وضعية الركبة–الصدر، الأكسجين، تسريب السوائل الوريدية، المورفين (يهدئ ويقلل التحويلة)، بروبرانولول وريدي، بيكربونات — ولا مكان للصادات الحيوية."},{"f":"نقطة ذهبية: في الآفات القلبية غير المزرقة — الوزن أم الطول يتأثر أولًا؟","b":"في الآفات غير المزرقة (تحويلات يسار–يمين كالـVSD): فشل النمو يتظاهر أولًا وأشدّ بتأثر الوزن أكثر من الطول (سوء تغذية من زيادة الاستقلاب)."},{"f":"فرّق: التضيق الرئوي الدسامي — وما صفة الصوت الثاني الرئوي فيه؟","b":"نفخة انقباضية دفعية + ضخامة بطين أيمن + معظم الحالات لا عرضية + العلاج بالتوسيع بالبالون — لكن الصوت الثاني الرئوي منقسم متأخر لا محتد (الاحتدام يدل على فرط التوتر الرئوي)."}]},{"t":"اضطرابات الكلية والمسالك البولية","cards":[{"f":"فرّق: صورة التهاب الكبب والكلية الحاد التالي للعقديات — والواسم المخبري؟","b":"بعد إنتان بالعقديات الحالة للدم زمرة A: شح بول + بيلة دموية + ارتفاع توتر شرياني + وذمات خفيفة حول الحجاج (وليست شديدة معممة — تلك صفة النفروزي). الواسم المخبري: نقص متممة C3 (تُستهلك بالمسلك البديل). تشريحيًا: الحدب (Humps) تحت الظهارية."},{"f":"فرّق: رباعية التناذر النفروزي وملامح الإنذار الجيد — وما العمر السيئ؟","b":"الرباعية: بيلة بروتينية + نقص ألبومين المصل + وذمات شديدة معممة + فرط شحوم الدم — مع ضغط شرياني طبيعي وC3 طبيعية ووظيفة كلوية طبيعية. النموذج (التبدلات الدنيا): عمر 1–10 سنوات (نموذجي 2–6). ملامح الإنذار الجيد: ضغط طبيعي + متممة طبيعية + وظيفة طبيعية + غياب البيلة الدموية العيانية — البدء قبل عمر السنة إنذار سيئ."},{"f":"فرّق: المتلازمة الانحلالية اليوريميائية (HUS) — الثلاثي والمسبب والنمط اللانموذجي؟","b":"الثلاثي: فقر دم انحلالي + نقص صفيحات + قصور كلوي حاد (ارتفاع بولة وكرياتينين) — بعد أيام من إنتان معوي (أشيعها E. coli O157:H7 المنتجة لذيفان شيغا). مرض مكتسب لا وراثي؛ النمط النموذجي إنذاره جيد عمومًا. اللانموذجية (aHUS): خلل تنظيم المتممة ولا يسبقها إسهال."},{"f":"نقطة ذهبية: أي موجود في فحص البول يشير لإنتان بولي جرثومي؟","b":"النتريت (Nitrite) في فحص البول — جراثيم سلبية الغرام (كالإشريكية القولونية) تختزل النترات إلى نتريت؛ واسِم نوعي للإنتان الجرثومي البولي. أما أسطوانات الكريات الحمر فتدل على منشأ كبيبي."},{"f":"فرّق: تظاهرات إنتان المجاري البولية العلوية مقابل السفلية — وكيف يتظاهر عند الرضع؟","b":"العلوي (التهاب الحويضة والكلية): ترفع حروري + ألم بطني + عرواءات + إقياءات — الإلحاح البولي صفة الإنتان السفلي. عند الرضع: أعراض عامة غير نوعية (قد يسبب يرقان ونقص وزن) — عسر التبول ليس تظاهرًا وحيدًا عندهم."},{"f":"من سؤال حقيقي: رضيع 7 أشهر بحرارة 4 أيام دون بؤرة — ما التشخيص المرجح الذي يُبحث عنه أولًا؟","b":"خمج السبيل البولي — أشيع خمج جرثومي خطير عند الرضع بحرارة دون بؤرة سريرية؛ يُبحث عنه أولًا بفحص البول وزرعه."},{"f":"فرّق: فرفرية هينوخ-شونلاين — توضع الطفح ودور الستيروئيدات؟","b":"التهاب الأوعية بالغلوبولين المناعي A: فرفريات مجسوسة على الأطراف السفلية والإليتين (لا الجذع) + ألم بطني تشنجي + ألم/تورم مفصلي + التهاب كبب وكلية (بيلة دموية). مرض محدود ذاتيًا غالبًا — الستيروئيدات ليست لكل المرضى ولا تغير سير الإصابة الكلوية."},{"f":"فرّق: داء برغر (اعتلال الكلية بـIgA) مقابل التهاب الكبب التالي للعقديات — توقيت البيلة الدموية؟","b":"بيلة دموية عيانية (اغمقاق البول) متزامنة مع التهاب البلعوم (بعد 1–3 أيام فقط) بحالة عامة جيدة دون وذمات وضغط طبيعي — بعكس التهاب الكبب التالي للعقديات الذي يلي الإنتان بفاصل زمني. المتممة C3 طبيعية."},{"f":"من سؤال حقيقي: السبب الأكثر شيوعًا للمرض الكلوي المزمن عند الأطفال؟","b":"التشوهات البنيوية الخلقية في الكلى والمسالك البولية (CAKUT) — كالجذر المثاني الحالبي وصمامات الإحليل الخلفية — لا ارتفاع الضغط أو السكري (سببا البالغين)."},{"f":"فرّق: استطبابات التحال عند الطفل (ما عدا)؟","b":"وذمة الرئة، فرط البوتاسيوم المعند، الحماض الاستقلابي الشديد، نقص الصوديوم الشديد، فشل الأجهزة المتعدد. ليست استطبابًا: القلاء الاستقلابي، وفرط الفوسفور وحده (يُعالج دوائيًا بقابضات الفوسفور)."},{"f":"فرّق: اختلاطات التهاب الكبب والكلية بالعقديات (ما عدا)؟","b":"قصور القلب، اعتلال الدماغ والاختلاج، القصور الكلوي الحاد. الداء الخثاري (فرط التخثر) من اختلاطات التناذر النفروزي لا التهاب الكبب الحاد."},{"f":"من سؤال حقيقي: بيلة بروتينية 2+ بعد إنتان فيروسي دون وذمة ودون بيلة دموية — التشخيص؟","b":"بيلة بروتينية عابرة حميدة — خفيفة بعد إنتان فيروسي دون وذمة ودون بيلة دموية؛ تزول بشفاء الإنتان ولا تحتاج إلا للمراقبة."},{"f":"قاعدة ذهبية: فشل الرد اليدوي للفتق الإربي المختنق — هل ننتظر زوال الوذمة؟","b":"الفتق الإربي المختنق حالة إسعافية — فشل الرد اليدوي يستوجب استشارة جراحية عاجلة ولا يُنتظر زوال الوذمة."},{"f":"فرّق: الإحليل التحتي — نادر أم شائع؟ وما سببه؟","b":"من أشيع التشوهات الولادية عند الذكور (نحو 1 من كل 200–300 مولود ذكر) — ليس نادرًا؛ ناتج عن التحام ناقص للطيات الإحليلية، قد يرافقه انحناء بالوجه البطني للقضيب وتشوهات بولية/تناسلية مرافقة."},{"f":"من سؤال حقيقي: عوامل تكرار الخمج البولي عند الأطفال (ما عدا)؟","b":"المثانة العصبية، الثمالة البولية بعد التبول، الإمساك، الجذر المثاني الحالبي — أما السلس البولي الثانوي وحده فليس عامل خطورة مستقلًا لتكرار الإنتان."},{"f":"قاعدة ذهبية: خزعة الكلية عند بدء التناذر النفروزي النموذجي — تُجرى أم لا؟","b":"لا تُجرى عند بدء النفروز النموذجي المستجيب للكورتيزون — تُحفظ للحالات المقاومة أو اللانموذجية. الاستقصاءات البدئية: المتممة، مسح التهاب الكبد B وC، فحص بول وزرع، وظائف كلوية وشوارد وألبومين."},{"f":"من سؤال حقيقي: ارتفاع الضغط عند طفل بتناذر نفروزي يعالج بالستيروئيدات — ما دلالته الإنذارية؟","b":"ارتفاع الضغط الشرياني في سياق تناذر نفروزي يشير لآفة كبية غير الداء بأقل التبدلات (كالتصلب البؤري القطعي) أو لمقاومة ستيروئيدية — أي إنذار سيئ."},{"f":"من سؤال حقيقي: سلس بولي ليلي ثانوي عند طفلة 7 سنوات — ما الخطوة التالية الأفضل؟","b":"فحص بول وراسب — الخطوة الأولى لنفي الأسباب العضوية البسيطة (خمج بولي، بيلة سكرية) قبل اللجوء للاستقصاءات الشعاعية."},{"f":"فرّق: مضاعفات التناذر النفروزي — حجم الحيز داخل الأوعية يزيد أم ينقص؟","b":"فرط التخثر (الخثار)، فرط شحوم الدم، الإنتانات، نقص حجم الحيز داخل الأوعية (لا زيادته — بسبب تسرب الألبومين)، احتباس الصوديوم."}]},{"t":"اضطرابات الأعضاء التناسلية","cards":[{"f":"فرّق: الفتق الإربي عند الأطفال — عند أي عمر أشيع؟ ومتى يكون الاختناق أشيع؟","b":"أشيع عند الخدج (بقاء الناتئ الغمدي)، عادة غير عرضي، ومعظم الفتوق ترد يدويًا — لكن الاختناق أشيع عند الرضع الصغار لا عند الأطفال الكبار."},{"f":"فرّق: جراحة الإحليل التحتي — إسعافية أم انتخابية؟ وهل يُجرى الختان؟","b":"جراحة انتخابية تُجرى بعمر 6–18 شهرًا — ليست إسعافية إطلاقًا. يُمنع إجراء الختان لأن القلفة تُستخدم في الترميم الجراحي. الهدف: تبول مستقيم بمظهر طبيعي وانتصاب سوي مستقبلًا."},{"f":"فرّق: أسباب الصفن الحاد المؤلم عند الأطفال (ما عدا)؟","b":"الأسباب: انفتال الخصية، انفتال الزوائد الخصوية، الفتق الإربي المختنق، التهاب الخصية والبربخ. ليست من أسبابه: القيلة الدوالية (توسع وريدي مزمن غير مؤلم — ككيس الديدان — عند المراهقين) والقيلة المائية (تورم غير مؤلم عادة)."}]},{"t":"اضطرابات الكبد","cards":[{"f":"فرّق: أسباب المرض الكبدي المزمن عند الأطفال (ما عدا)؟","b":"التهاب الكبد المناعي الذاتي، الداء الليفي الكيسي (ركودة صفراوية)، داء ويلسون (ترسب النحاس)، عوز ألفا1 أنتي تربسين. الاستثناء: التهاب الكبد الفيروسي A — مرض حاد محدود ذاتيًا لا يتحول إلى مزمن أبدًا ولا توجد حالة حاملة مزمنة له."},{"f":"من سؤال حقيقي: داء ويلسون — العلامة العينية والعلاج النوعي؟","b":"ترسب النحاس في الكبد والدماغ؛ العلامة العينية: حلقة كايزر-فلايشر القرنية. العلاج النوعي: البنسيلامين (Penicillamine) — خالب النحاس الأقوى يحرض إطراحه بالبول؛ والزنك علاج مساعد يقلل الامتصاص المعوي. لا يسبب قصور كبد حاد تحت السنتين (يظهر عادة بعد 5 سنوات)."},{"f":"من سؤال حقيقي: رضيع 6 أسابيع بيرقان مديد + براز حواري + بول داكن + ضخامة كبدية — التشخيص؟","b":"رتق المسالك الصفراوية خارج الكبد — الرباعية: يرقان مديد بعمر 6 أسابيع + براز شاحب حواري + بول داكن يصبغ الحفاض + ضخامة كبدية (ركودة صفراوية = يرقان مقترن/مباشر)."}]},{"t":"الأمراض الخبيثة","cards":[{"f":"فرّق: الابيضاض اللمفاوي الحاد (ALL) — الذروة العمرية والتظاهرات (ما عدا)؟","b":"ذروة الحدوث 2–5 سنوات؛ أشيع ابيضاضات الدم عند الأطفال. التظاهرات: شحوب (فقر دم)، فرفريات وكدمات (نقص صفيحات)، ألم ساقين (ارتشاح النقي)، ضخامة عقد لمفاوية وكبدية، تضخم خصوي (ارتشاح)، شلول أعصاب قحفية — الكتلة البطنية ليست من مشاهداته؛ والشبكيات منخفضة (ارتفاعها يدل على انحلال أو نزف حاد)."},{"f":"فرّق: عوامل سوء الإنذار في الابيضاض اللمفاوي الحاد (ما عدا)؟","b":"العمر دون سنة أو فوق 10 سنوات، ارتفاع الكريات البيض عند التشخيص، الشذوذات الجزيئية/الخلوية، استمرار الأرومات بعد العلاج، النمط التائي. نقص الكريات البيض عند التشخيص ليس عامل سوء إنذار."},{"f":"فرّق: صفات العقد اللمفاوية في لمفوما هودجكن عند الأطفال (ما عدا)؟","b":"عقد لمفاوية غير مؤلمة مطاطية القوام بطيئة النمو والتضخم — غالبًا في العنق وفوق الترقوة (نادرة في العقد الإربية) — مع ضخامة كبدية طحالية."},{"f":"فرّق: التظاهر الأشيع لورم ويلمز (النفروبلاستوما)؟","b":"أشيع تظاهر: كتلة بطنية غير مؤلمة يكتشفها الأهل صدفة عند طفل لا عرضي (بعمر 2–5 سنوات). قد تترافق مع فرط توتر شرياني وتشوهات بولية؛ والألم البطني ليس نادرًا (نزف داخل الورم أو انضغاط)."},{"f":"فرّق: النوروبلاستوما مقابل ورم ويلمز — أيهما أشيع عند حديث الولادة؟ وما الذي يوجه للأولى عند طفل 4 سنوات؟","b":"النوروبلاستوما = أشيع سبب لكتلة بطنية عند حديث الولادة. كتلة بطنية غير نموذجية + ارتفاع توتر شرياني (إفراز الكاتيكولامينات) عند طفل 4 سنوات توجه للنوروبلاستوما لا لورم ويلمز."},{"f":"نقطة ذهبية: ألفا-فيتوبروتين (AFP) يرتفع في أي أورام عند الأطفال؟","b":"ألفا-فيتوبروتين (AFP) — يرتفع في أورام الكبد الخبيثة عند الأطفال كالورم الأرومي الكبدي (Hepatoblastoma) وسرطان الخلايا الكبدية."},{"f":"فرّق: التأثيرات الجانبية للعلاج الكيماوي (ما عدا)؟","b":"نزف، إنتان، فقر دم، نقص صفيحات، تساقط شعر، قرحات فموية، إقياء وقهم. قصور الدرق تأثير متأخر للمعالجة الشعاعية على الرقبة — وليس من تأثيرات الكيماوي."},{"f":"من سؤال حقيقي: طفل بضخامة عقدية في العنق 4 سم قاسية غير مؤلمة بطيئة التطور دون أعراض أخرى — التشخيص الأرجح؟","b":"لمفوما هودجكن — الضخامة العقدية الرقبية غير المؤلمة القاسية بطيئة التطور (خاصة >2 سم) من العلامات النموذجية لها عند الأطفال."}]},{"t":"الاضطرابات الدموية","cards":[{"f":"فرّق: العلامة النوعية لفقر الدم بعوز الحديد — والشحوب أبكر أم متأخر؟ وماذا عن TIBC؟","b":"العلامة السريرية النوعية: شهوة الطين/انحراف الشهية (Pica) — تناول مواد غير غذائية (طين، ثلج، نشا). الشحوب علامة متأخرة؛ الأبكر: نقص شهية وشهية ضالة وضعف القدرات العقلية. مخبريًا: صغير الخلايا ناقص الصباغ + نقص الفيريتين + زيادة السعة الرابطة الكلية للحديد (TIBC) وارتفاع الترانسفيرين."},{"f":"من سؤال حقيقي: وليد 4 أيام بنزف سري وكدمات وتطاول PT/PTT بعد ولادة منزلية وإرضاع والدي — التشخيص؟ وهل تتأثر الصفيحات؟","b":"الصورة: وليد بعمر 2–7 أيام، ولادة منزلية دون فيتامين K وقائي، إرضاع والدي (حليب الأم فقير بفيتامين K) — نزف من السرة/المستقيم مع كدمات، تطاول PT وPTT. عوز فيتامين K يؤثر على عوامل التخثر (2، 7، 9، 10) ولا يؤثر إطلاقًا على تعداد الصفيحات."},{"f":"فرّق: الناعور A — العامل الناقص، نمط الوراثة، والنزف المميز؟","b":"عوز العامل الثامن؛ وراثة مرتبطة بالجنس مقهورة (X-linked) — تصيب الذكور وتنقله الإناث — وليست جسمية مقهورة. النزوف المفصلية والعضلية العفوية مميزة له (في العوز الشديد). تجنب الأسبرين والحقن العضلية. علاج تدمي المفصل: ركازة العامل الثامن + راحة تامة للمفصل — لا ستيروئيدات."},{"f":"فرّق: داء فون ويلبراند مقابل الناعور — نمط الوراثة والنزف المميز لكل منهما؟","b":"وراثة جسدية سائدة غالبًا؛ يصيب وظيفة الصفيحات والعامل الثامن — نزوف مخاطية جلدية: رعاف، نزف طمثي، نزف تالٍ للجراحة. النزوف المفصلية (Hemarthrosis) مميزة للناعور لا لفون ويلبراند."},{"f":"فرّق: نقص الصفيحات المناعي (ITP) — وما الذي يميزه عن الابيضاضات؟","b":"كدمات وفرفريات صغيرة غير متناظرة دون حرارة عادة، والصفيحات أقل من 20 ألف غالبًا — مع غياب الضخامات الحشوية (غياب ضخامة كبدية طحالية مميز لـITP)."},{"f":"فرّق: تكور الكريات الوراثي — كومبس؟ وحجم ضخامة الطحال؟","b":"انحلال غير مناعي بتفاعل كومبس سلبي (إيجابيته تنفيه)؛ وراثة جسدية سائدة غالبًا؛ ضخامة طحال خفيفة إلى متوسطة (العرطلة توحي بأمراض أخرى)؛ حصيات مرارية؛ نوب نقص تصنع بالكريات الحمر تالية للبارفوفيروس B19؛ قد ينحل في عمر الوليد."},{"f":"فرّق: التلاسيميا الكبرى (بيتا) — متى تبدأ الأعراض؟ ومتى تظهر التبدلات العظمية؟","b":"لا تتظاهر عند الولادة — الخضاب الجنيني (HbF) يحمي الوليد؛ تبدأ الأعراض بعد 3–6 أشهر مع تراجع HbF. التبدلات العظمية (وجه السنجاب، توسع العظام المسطحة) ناتجة عن فرط تنسج النقي المزمن وتظهر متأخرة لا منذ البداية."},{"f":"فرّق: عوز G6PD — المحرضات، وهل كل المرضى تنتابهم نوبات؟ وما المسكن الآمن؟","b":"مرض مرتبط بالجنس؛ نوب الانحلال تتحرض بتناول الفول وبعض الأدوية (السلفا، الكلوروكين، النفتالين) والإنتانات — لكن ليس كل المرضى تصيبهم نوبات (كثيرون لا عرضيون). الباراسيتامول بالجرعات العلاجية آمن ومفضل كمسكن وخافض حرارة."},{"f":"فرّق: الداء المنجلي عند الأطفال — التظاهرات والمحرضات (ما عدا)؟","b":"التظاهرات عند الأطفال: نوب ألمية، تشظي طحالي متكرر في السنوات الأولى (يؤدي لضمور ذاتي فلا تستمر الضخامة حتى البلوغ)، إنتانات، متلازمة الصدر الحاد — قرحة الساق اختلاط البالغين. محرضات النوب: البرد والجفاف والإنتانات وفرط النشاط وبعض الأدوية — الإماهة الجيدة تقي من النوب لا تحرضها."},{"f":"فرّق: ما الذي يؤكد فقر الدم الانحلالي — وما الذي ينفيه؟","b":"ارتفاع الشبكيات + فرط تصنع سلسلة الحمر في النقي (تعويضًا) + ارتفاع البيليروبين اللامباشر + إيجابية كومبس (في المناعي). نقص طلائع الكريات الحمر في النقي ينفي الانحلال ويوجه لنقص التصنيع. ضخامة الطحال ليست موجودة دومًا."},{"f":"فرّق: تظاهرات نقص الصفيحات من الأشيع للأقل — وأين النزف المفصلي؟","b":"الأشيع: النمشات (Petechiae) والرعاف، ثم النزف الهضمي والبيلة الدموية. النزف داخل المفصلي نادر جدًا في نقص الصفيحات ومميز للناعور؛ والنزف الدماغي أخطر التظاهرات لكنه الأقل شيوعًا."},{"f":"نقطة ذهبية: اختبار PT يقيم أي عامل تخثر؟","b":"زمن البروثرومبين (PT) يقيم الطريق الخارجي للتخثر — عامله الوحيد هو العامل السابع (VII) إضافة إلى عوامل الطريق المشترك."},{"f":"نقطة ذهبية: فقر الدم الفيزيولوجي — متى ذروته؟ وكيف هو عند الخدج؟","b":"يبلغ ذروته (أدنى هبوط في الخضاب) بعمر 8–12 أسبوعًا عند ولدان تمام الحمل؛ عند الخدج يظهر أبكر ويكون أشد؛ غالبًا لا يحتاج علاجًا؛ الكريات الحمر سوية الحجم وسوية الصباغ."},{"f":"فرّق: تكور الكريات الوراثي وفرط الطحالية — هل هما من أسباب فقر الدم بنقص التصنيع؟","b":"تكور الكريات الوراثي = انحلال (تصنع تعويضي زائد في النقي) وليس نقص تصنع. فرط الطحالية = تدمير واحتجاز محيطي للكريات في الطحال المتضخم (آلية خارج النقي) وليس نقص تصنيع."},{"f":"من سؤال حقيقي: طفل سنتان بفقر دم ويرقان وارتفاع شبكيات منذ يومين — التشخيص الأرجح؟","b":"هجمة الفوال — اجتماع فقر الدم واليرقان مع ارتفاع الشبكيات منذ يومين يشير لفقر دم انحلالي حاد (عوز G6PD بعد محرض كالفول)."}]},{"t":"الداء السكري واضطرابات الغدد الصم","cards":[{"f":"من سؤال حقيقي: مولود 10 أيام بأعضاء تناسلية مبهمة + نقص صوديوم + فرط بوتاسيوم — التشخيص والعلاج الدائم؟","b":"عوز 21-هيدروكسيلاز بالشكل المُضيِّع للملح: أعضاء تناسلية مبهمة (أو ضخامة بظر) + نقص صوديوم + فرط بوتاسيوم + نقص سكر الدم. العلاج الدائم: الهيدروكورتيزون (تعويض الكورتيزول)."},{"f":"فرّق: قصور الكظر الأولي (أديسون) مقابل الثانوي — ما العلامة الجلدية الفارقة؟","b":"القصور الأولي (أديسون): فرط تصبغ جلدي — اسمرار اللحف وتصبغ الثنيات — ناجم عن ارتفاع ACTH، مع نقص سكر متكرر. القصور الثانوي (نقص ACTH): دون تصبغات جلدية."},{"f":"فرّق: قصور الدرق الخلقي — القاعدة الذهبية للتشخيص والعلامات الباكرة؟","b":"القاعدة الذهبية للتشخيص: برامج المسح (الغربلة) الوليدي الشامل — لأن معظم الأطفال لا يكونون عرضيين عند الولادة. العلامات الباكرة الموجهة: بطء الرضاعة والخمول، الإمساك، اليرقان المديد. الأسباب: خلل تكون الغدة (انعدام الدرق، درق هاجر)، عوز اليود، عبور مضادات الدرق — رضوض الولادة ليست منها."},{"f":"فرّق: داء غريفز مقابل داء هاشيموتو عند الأطفال — الصورة والواسم والعرض الأبكر؟","b":"داء غريفز: نشاط زائد + نقص وزن رغم زيادة الشهية + جحوظ + سلعة درقية + تسرع قلب + عدم تحمل الحرارة + تعرق + اضطراب خط اليد؛ الواسم: إيجابية أضداد مستقبل TSH. داء هاشيموتو (قصور مكتسب): العرض الرئيسي الأبكر = تباطؤ سرعة النمو الخطي."},{"f":"نقطة ذهبية: العلامة الثابتة في متلازمة كوشينغ عند الأطفال؟ وبم يُشخَّص؟","b":"العلامة الثابتة: البدانة — خاصة المركزية/الجذعية مع الوجه القمري — توجد عمليًا في كل الحالات وتسبق بقية العلامات؛ عند الأطفال تترافق مع توقف كسب الطول. تشخيصه: اختبار التثبيط بالديكساميتازون."},{"f":"فرّق: اختبارات تشخيص داء أديسون (ما عدا)؟","b":"كورتيزول الصباح (8 صباحًا) المنخفض + معايرة ACTH المرتفعة + اختبار التحريض بـACTH + الأضداد الذاتية لقشر الكظر. اختبار التثبيط بالديكساميتازون يُستخدم لتشخيص كوشينغ لا أديسون."},{"f":"فرّق: متى يُشتبه بالسكري نمط 2 عند الأطفال (ما عدا)؟","b":"بدانة شديدة مرافقة + الشواك الأسود (Acanthosis nigricans) + قصة عائلية قوية + مبيض متعدد الكيسات. الترافق مع داء هاشيموتو (مناعي ذاتي) يوجه للنمط الأول لا الثاني."},{"f":"فرّق: الأعراض الباكرة للسكري عند الأطفال مقابل علامات الحماض الكيتوني؟","b":"الباكرة: بوال وسهاف ونقص وزن وسلس بولي ثانوي — أما الألم البطني والتنفس الحامضي العميق (كوسماول) فعلامات الحماض الكيتوني المتأخرة الإسعافية. التظاهرات تشمل الانتانات الفطرية؛ زيادة الوزن توجه للنمط الثاني."},{"f":"فرّق: تظاهرات الحماض الكيتوني السكري (ما عدا)؟","b":"ألم بطني + تجفاف + تنفس حامضي عميق (تنفس كوسماول) + قد يصل لصدمة نقص الحجم — ولا يوجد طفح جلدي في صورته السريرية."},{"f":"فرّق: عوز هرمون النمو عند الوليد — وهل يسبب تأخرًا عقليًا؟","b":"عند الوليد: طول الولادة طبيعي + نقص سكر الدم + صغر حجم القضيب. قصور الفص الأمامي النخامي: تأخر بلوغ ونضج عظمي وبزوغ أسنان ونقص ثابت في سرعة النمو — دون تأخر عقلي (القدرات الذهنية طبيعية)."},{"f":"من سؤال حقيقي: اختلاجات + تراجع فك سفلي + غياب التيموس شعاعيًا — المتلازمة والاستقصاء الموجه؟","b":"متلازمة دي جورج (حذف 22q11.2): اختلاجات + تراجع الفك السفلي + غياب التيموس في صورة الصدر = نقص تصنع جارات الدرق → نقص كلس الدم — الاستقصاء الموجه للعلاج: كلس الدم."},{"f":"نقطة ذهبية: أحد استطبابات العلاج بهرمون النمو؟","b":"قصر القامة مجهول السبب (Idiopathic short stature) — استطباب معتمد لهرمون النمو."}]},{"t":"الاضطرابات العضلية الهيكلية","cards":[{"f":"من سؤال حقيقي: مفتاح تشخيص ذات العظم والنقي عند طفل محموم؟","b":"رفض تحريك الطرف المصاب (الشلل الكاذب — Pseudoparalysis) مع ألم موضعي بالجس — العلامة الموجهة نحو العظم المصاب. الحرارة والتعب والآلام المعممة غير نوعية."},{"f":"فرّق: آلام النمو عند الأطفال — متى تحدث؟ وما العلامة الحمراء التي تنفيها؟","b":"آلام ليلية نموذجية تحدث مساءً وقد توقظ الطفل من نومه ثم تختفي تمامًا صباحًا؛ في عضلات الطرفين السفليين (الفخذين والساقين) ثنائية الجانب؛ دون عرج ودون إصابة مفصلية والفحص السريري سوي. العرج المرافق علامة حمراء تنفي التشخيص؛ ولا علاقة لها بذروة النمو فعلًا."},{"f":"فرّق: التهاب المفصل الانتاني مقابل الارتكاسي عند الأطفال؟","b":"الانتاني (القيحي): وحيد المفصل غالبًا — مفصل كبير واحد (ركبة/ورك) — أشيع تحت عمر سنتين، الجرثوم الأشيع العنقوديات المذهبة، وقد يسبب تخربًا في العظم والغضروف. الارتكاسي: تالٍ لإنتان خارج مفصلي (بولي أو معوي)، يصيب مفاصل الأطراف السفلية الكبيرة (ركبتين/كاحلين) بشكل غير متناظر."}]},{"t":"الاضطرابات العصبية","cards":[{"f":"فرّق: الاختلاج الحروري البسيط — المواصفات، وما الذي يستبعده؟ وهل يقي خافض الحرارة من تكرره؟","b":"البسيط: عمر 6 أشهر–5/6 سنوات، اختلاج معمم قصير (<15 دقيقة) مرة واحدة في اليوم، لا خزل موضعي تالٍ — الاختلاج البؤري/الموضعي يستبعد البسيط. لا يزيد خطر الصرع لاحقًا؛ الزرقة العابرة حميدة لا تسبب أذية دماغية؛ لا وقاية بالفينوباربيتال المطول ولا بخافضات الحرارة. إذا استمرت الهجمة >5 دقائق: ميدازولام (أو ديازيبام). عوامل تكرره: العمر الصغير (<18 شهرًا) والقصة العائلية الإيجابية."},{"f":"فرّق: متلازمة غيلان باريه مقابل شلل الأطفال — الصورة والبزل والعلاج؟","b":"شلل رخو صاعد متناظر مع غياب المنعكسات الوترية العميقة؛ الافتراق الألبوميني الخلوي في السائل الدماغي (بروتين مرتفع مع خلايا طبيعية) يميزه عن شلل الأطفال؛ المصرات سليمة عادة؛ التحسن العفوي هو القاعدة (مرض أحادي الطور). العلاج: الغلوبولين المناعي الوريدي — الستيروئيدات لا تسرّع الشفاء. شلل الأطفال: شلل رخو حاد غير متناظر غير مؤلم (إصابة العصبون الحركي السفلي)."},{"f":"فرّق: داء وردنغ-هوفمان — العلامة اللسانية المميزة ونمط التنفس؟","b":"الضمور العضلي الشوكي نمط 1 (SMA): وراثة جسدية متنحية؛ تنكس العصبونات الحركية السفلية — رخاوة عضلية + غياب منعكسات وترية + تقلصات حزمية باللسان؛ الذكاء سليم (لا تأخر روحي حركي). التنفس عجائبي (إصابة العضلات الوربية مع سلامة نسبية للحجاب الحاجز باكرًا)؛ الوفاة غالبًا أول سنتين؛ لا علاج نوعي."},{"f":"نقطة ذهبية: علامة التسلق (Gower) تدل على أي مرض؟","b":"علامة التسلق (Gower's sign) — يتسلق الطفل على فخذيه بيديه للنهوض من الجلوس — تدل على ضعف عضلات الحزام الحوضي وهي مميزة لحثل دوشين العضلي."},{"f":"من سؤال حقيقي: علامة غروب الشمس عند الرضع تدل على أي مرض؟","b":"علامة «عيني الغروب» — عدم القدرة على النظر للأعلى مع ظهور بياض الصلبة فوق القزحية — من العلامات الكلاسيكية لاستسقاء الدماغ عند الرضع (ضغط البطينين المتوسعة)."},{"f":"من سؤال حقيقي: طفل 4 سنوات برنح حاد بعد أسبوع من طفح حويصلي حاك — التشخيص؟ وما أشيع اختلاط عصبي للحماق؟","b":"التهاب المخيخ الحاد — أشيع اختلاط عصبي للحماق عند الأطفال: رنح حاد واضطراب مشية بعد أيام من بدء الطفح الحويصلي الحاك، وغالبًا الشفاء تام."},{"f":"فرّق: الصرع الرولاندي — السن والتوقيت والإنذار؟","b":"صرع الطفولة السليم: سن 4–12 سنة، نوب ليلية بعلامات فموية-وجهية (سيلان لعاب، تشنج وجه، عسر كلام)، موجات ذروية في المنطقة الرولاندية — محدود ذاتيًا يشفى في المراهقة؛ لا يجب البدء بالعلاج بعد أول نوبة."},{"f":"فرّق: نوب الغياب — مدتها وما الذي يحرضها؟","b":"النموذجية تدوم ثوانٍ (5–30 ثانية) لا 1–2 دقيقة؛ تتكرر مرارًا في الجلسة الواحدة مع نسيان المريض ما حدث؛ تُحرض بفرط التهوية."},{"f":"فرّق: أعراض الصداع المنذرة لآفة شاغلة للحيز (ما عدا)؟","b":"إقياء صباحي، صداع يوقظ من النوم، يزداد بالسعال، تبدلات بالشخصية، اضطراب رؤيا/حول/صعر/رنح. رهاب الضوء صفة الشقيقة لا الآفة الشاغلة؛ والكدمات والفرفريات توجه لاضطراب نزفي أو ابيضاض لا لورم دماغي."},{"f":"فرّق: مضادات استطباب البزل القطني (ما عدا)؟","b":"وذمة حليمة العصب البصري، الورم السحائي، خراج الدماغ، النزف تحت الجافية (خطر الانفتاق). أما ارتفاع التوتر داخل القحف مجهول السبب فالبزل إجراء تشخيصي علاجي فيه — ليس مضاد استطباب."},{"f":"من سؤال حقيقي: علامات داء ريكلينغ هاوزن (الورم الليفي العصبي نمط 1)؟","b":"بقع قهوة بحليب (Café-au-lait) + أورام ليفية عصبية + نمشات إبطية + عقيدات ليش على القزحية — وقد يترافق بكبر الرأس لا صغره."},{"f":"من سؤال حقيقي: أشيع سبب يُبحث عنه عند تشخيص التشنجات الطفلية؟","b":"التصلب الحديبي (Tuberous sclerosis) — أشيع سبب نوعي يجب البحث عنه عند تشخيص التشنجات الطفلية (متلازمة ويست)."},{"f":"من سؤال حقيقي: رضيع 10 أشهر بنوب رمعية متكررة وتطور طبيعي وفحوص طبيعية — التشخيص؟","b":"الصرع الرمعي العضلي السليم عند الرضع — نوب رمعية عضلية متكررة (حتى 8/اليوم) مع تطور روحي حركي طبيعي وفحوص كلها طبيعية."},{"f":"فرّق: استقصاءات الطفل المختلج (ما عدا)؟","b":"سكر الدم (نقصه سبب اختلاج)، كالسيوم الدم، المسح الانتاني، البزل القطني لنفي التهاب السحايا — بوتاسيوم الدم ليس من استقصاءات الطفل المختلج."}]}]}];